local Players = game:GetService("Players")

-- WaitForChild TANPA timeout yield selamanya. pcall TIDAK memotong yield,
-- jadi 1 module yang nunggu child = seluruh sequential boot (termasuk UI) macet.
local function waitChild(parent, name, timeout)
    if typeof(parent) ~= "Instance" then
        return nil
    end
    timeout = tonumber(timeout) or 15
    local existing = parent:FindFirstChild(name)
    if existing then
        return existing
    end
    return parent:WaitForChild(name, timeout)
end

if not game:IsLoaded() then
    local loaded = false
    local conn
    conn = game.Loaded:Connect(function()
        loaded = true
    end)
    local t0 = os.clock()
    while not game:IsLoaded() and not loaded and (os.clock() - t0) < 30 do
        task.wait()
    end
    if conn then
        conn:Disconnect()
    end
end

local LP = Players.LocalPlayer
if not LP then
    local t0 = os.clock()
    while not Players.LocalPlayer and (os.clock() - t0) < 15 do
        task.wait()
    end
    LP = Players.LocalPlayer
end
if LP then
    waitChild(LP, "PlayerGui", 15)
end
task.wait()

local ENV = (getgenv and getgenv()) or _G

local BOOT_NAME = "NodeHub Market"

local BOOT_RETRY = 5
local RETRY_DELAY = 2
local STATE_RETRY = 10
