local GAME_DATA_WAIT = 20

local DEBUG = ENV.__NODEHUB_MARKET_DEBUG == true or _G.__NODEHUB_MARKET_DEBUG == true

local function dprint(...)
    if DEBUG then
        warn("[" .. BOOT_NAME .. "][DEBUG]", ...)
    end
end

local function warnlog(...)
    warn("[" .. BOOT_NAME .. "]", ...)
end

local function failBoot(msg)
    ENV.__NODEHUB_MARKET_RUNNING = false
    ENV.__NODEHUB_MARKET_READY = false
    _G.__NODEHUB_MARKET_READY = false

    error("[" .. BOOT_NAME .. "] " .. tostring(msg), 0)
end

if ENV.__NODEHUB_MARKET_RUNNING and ENV.__NODEHUB_MARKET_READY then
    -- UI sudah loaded: tetap kick skip kalau LoadingGui masih nempel
    local stillLoading = false
    pcall(function()
        local pg = LP and LP:FindFirstChild("PlayerGui")
        local gui = pg and pg:FindFirstChild("LoadingGui")
        stillLoading = gui ~= nil and gui.Enabled == true
    end)
    if stillLoading then
        local AF = ENV.AntiAFK or ENV.antiafk or _G.AntiAFK
        if type(AF) == "table" then
            AF._skipWatcher = false
            if type(AF.AutoSkipLoading) == "function" then
                pcall(function()
                    AF.AutoSkipLoading("reexec")
                end)
            end
        end
    end
    return true
end

-- Load dobel (auto exec + queue teleport) bisa datang saat boot pertama belum READY.
-- Tahan duplikat selama boot di server yang sama masih wajar berjalan.
local BOOT_LOCK_SEC = 90
local BOOT_JOB = tostring(game.JobId or "")
if ENV.__NODEHUB_MARKET_RUNNING == true
    and ENV.__NODEHUB_MARKET_BOOT_JOB == BOOT_JOB
    and (os.clock() - (tonumber(ENV.__NODEHUB_MARKET_BOOT_AT) or 0)) < BOOT_LOCK_SEC
then
    warnlog("boot lain masih berjalan, skip load duplikat")
    return true
end

