-- Outer loader UI: progress bar saja, teks state/info tidak ditampilkan
-- IMPORTANT: tutup outer loader segera setelah Market UI terlihat.
-- Kalau nunggu sampai akhir boot, popup "Almost done..." sering nempel
-- (UI sudah kebuka, tabs/modules masih load).
local OUTER = ENV.__NODEHUB_OUTER_LOADER or _G.__NODEHUB_OUTER_LOADER or ENV.LOADER or _G.LOADER or {}

local LOADER = {}
local outerClosed = false

function LOADER.SetProgress(p, _text)
    if outerClosed then
        return
    end
    dprint("PROGRESS:", _text or "")
    if type(OUTER.SetProgress) == "function" then
        pcall(OUTER.SetProgress, p, nil)
    end
end

function LOADER.SetInfo(_text)
    dprint("INFO:", _text or "")
end

function LOADER.Destroy()
    if outerClosed then
        return
    end
    outerClosed = true
    dprint("LOADER DESTROY")
    if type(OUTER.Destroy) == "function" then
        pcall(OUTER.Destroy)
    elseif type(OUTER.Done) == "function" then
        pcall(OUTER.Done)
    end
end

