function MainUI:CreateRowToggle(parent, labelText, initial, onChanged, order, opts)
    opts = opts or {}
    local momentary = (opts.momentary == true) -- ✅ NEW

    local row = Instance.new("Frame")
    row.Name = "RowToggle"
    row.BackgroundTransparency = 1
    row.Size = UDim2.new(1, 0, 0, 26)
