local function autoSave()
    task.defer(function()

        local MAIN = rawget(_G, "MAIN") or rawget((getgenv and getgenv()) or _G, "MAIN")
        local saveFn = MAIN and (MAIN.save or MAIN.Save)
        if type(saveFn) == "function" then
            local ok2, err2 = pcall(function()
                saveFn(MAIN)
            end)
            if ok2 then
                --warn("[auto_market] MAIN.Save OK")
            else
                --warn("[auto_market] MAIN.Save FAIL:", err2)
            end
        else
            --warn("[auto_market] MAIN.Save tidak ada")
        end
    end)
end


    local function cleanSelectedMap(m)
        local out = {}
        if type(m) == "table" then
            for k, v in pairs(m) do
                if v == true then out[tostring(k)] = true end
            end
        end
        return out
    end

    local function toNumFloat(text)
        text = tostring(text or ""):gsub("%s+", "")
        if text == "" then return nil end
        text = text:gsub(",", ".")
        return tonumber(text)
    end

    local function round1(x)
        x = tonumber(x) or 0
        return math.floor(x * 10 + 0.5) / 10
    end
    


local function fmt1(n)
    n = tonumber(n) or 0
    return string.format("%.1f", n)
end

local function titleCaseWords(s)
    s = tostring(s or ""):lower()
    -- ubah tiap awal kata jadi kapital
    return (s:gsub("(%a)([%w_']*)", function(a,b)
        return a:upper() .. b
    end))
end

-- ✅ UI LIST HINT: cuma arah (tanpa angka)
local function kgHintSimple(kgSigned)
    kgSigned = tonumber(kgSigned) or 0
    if kgSigned == 0 then return "" end
    if kgSigned < 0 then
        return "Below"
    else
        return "Above"
    end
end

local function kgTextForPopup(kgSigned)
    kgSigned = tonumber(kgSigned) or 0
    if kgSigned == 0 then return "Any" end -- atau "-" kalau mau
    local abs = math.abs(kgSigned)
    if kgSigned < 0 then
        return ("Below %s"):format(abs)
    else
        return ("Above %s"):format(abs)
    end
end

    -- shared listing + MyBooth helpers (harus di scope Register, bukan cuma tab Listing)
    local function parseKgBox(text)
        local s = tostring(text or "")
        s = s:gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then return nil end
        local n = toNumFloat(s)
        if n == nil then return nil end
        return round1(n)
    end

    local function parseAgeBox(text)
        local s = tostring(text or "")
        s = s:gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then return 0 end
        if s:lower() == "inf" then return nil end
        local n = tonumber(s)
        if n == nil then return 0 end
        return math.floor(n + 0.5)
    end

    local function ageRangeText(minAge, maxAge)
        minAge = math.floor(tonumber(minAge) or 0)
        maxAge = tonumber(maxAge)
        if maxAge == nil then
            if minAge <= 0 then return "Age: any" end
            return ("Age >= %d"):format(minAge)
        end
        maxAge = math.floor(maxAge)
        if minAge == maxAge then return ("Age %d"):format(minAge) end
        return ("Age %d-%d"):format(minAge, maxAge)
    end

    local function kgRangeText(minKg, maxKg)
        minKg = tonumber(minKg) or 0
        maxKg = tonumber(maxKg)
        if maxKg == nil then return ("KG >= %s"):format(fmt1(minKg)) end
        return ("KG %s - %s"):format(fmt1(minKg), fmt1(maxKg))
    end

    local MODE_B_AGE_BLOCK = 100
    local MODE_B_AGE_MAX = 500

    local function buildModeBListAgePresets()
        local presets = {}
        local ageIdx = 0
        while true do
            local maxAge = (ageIdx + 1) * MODE_B_AGE_BLOCK
            if maxAge > MODE_B_AGE_MAX then
                if ageIdx * MODE_B_AGE_BLOCK >= MODE_B_AGE_MAX then break end
                maxAge = MODE_B_AGE_MAX
            end
            local minAge = (ageIdx == 0) and 0 or (ageIdx * MODE_B_AGE_BLOCK + 1)
            presets[#presets + 1] = {
                label = ("%d-%d"):format(minAge, maxAge),
                minAge = minAge,
                maxAge = maxAge,
            }
            if maxAge >= MODE_B_AGE_MAX then break end
            ageIdx = ageIdx + 1
        end
        return presets
    end

    local MODE_B_LIST_AGE = buildModeBListAgePresets()

    local function clampModeBAge(n)
        n = math.floor(tonumber(n) or 0)
        if n < 0 then n = 0 end
        if n > MODE_B_AGE_MAX then n = MODE_B_AGE_MAX end
        return n
    end

    local function modeBListAgePresetIndex(minAge, maxAge)
        minAge = math.floor(tonumber(minAge) or 0)
        maxAge = math.floor(tonumber(maxAge) or 0)

        for i, pr in ipairs(MODE_B_LIST_AGE) do
            if pr.minAge == minAge and pr.maxAge == maxAge then
                return i
            end
        end

        for i, pr in ipairs(MODE_B_LIST_AGE) do
            if minAge >= pr.minAge and minAge <= pr.maxAge then
                return i
            end
        end

        for i, pr in ipairs(MODE_B_LIST_AGE) do
            if maxAge >= pr.minAge and maxAge <= pr.maxAge then
                return i
            end
        end

        return 1
    end

    local function snapModeBAgeToPreset(minAge, maxAge)
        local idx = modeBListAgePresetIndex(minAge, maxAge)
        local pr = MODE_B_LIST_AGE[idx] or MODE_B_LIST_AGE[1]
        return pr.minAge, pr.maxAge, pr.label, idx
    end

    local function modeBListAgeButtonText(minAge, maxAge)
        minAge = clampModeBAge(minAge)
        maxAge = clampModeBAge(maxAge)
        if maxAge < minAge then
            local tmp = minAge
            minAge = maxAge
            maxAge = tmp
        end
        if minAge == maxAge then
            return tostring(minAge)
        end
        return ("%d-%d"):format(minAge, maxAge)
    end

    local MUT_NO  = "__NONE__"
    local MUT_ALL = "__ALL__"

    local function mutUiToStore(k)
        k = tostring(k or "")
        if k == MUT_NO then return "" end
        if k == MUT_ALL or k == "" then return "*" end
        return k
    end

    local function mutStoreToUi(v)
        v = tostring(v or "*")
        if v == "" then return MUT_NO end
        if v == "*" then return MUT_ALL end
        return v
    end

    local function normMutationStore(v)
        v = tostring(v == nil and "*" or v)
        if v == MUT_ALL or v == "ALL" or string.lower(v) == "all" then return "*" end
        if v == MUT_NO or v == "NONE" then return "" end
        return v
    end

    local function mutStoreToRuleToken(mut)
        mut = normMutationStore(mut)
        if mut == "*" then return "ALL" end
        if mut == "" then return "NONE" end
        return tostring(mut):gsub("|", "_")
    end

    local function mutRuleTokenToStore(tok)
        tok = tostring(tok or "ALL")
        if tok == "ALL" or tok == "*" then return "*" end
        if tok == "NONE" then return "" end
        return tok
    end

    local function mutLabel(mut)
        mut = normMutationStore(mut)
        if mut == "*" then return "All" end
        if mut == "" then return "None" end
        return tostring(mut)
    end

    local function mutationOverlaps(a, b)
        a = normMutationStore(a)
        b = normMutationStore(b)
        if a == "*" or b == "*" then return true end
        return a == b
    end

    local function prependMutationSpecial(items)
        items = items or {}
        local hasNo, hasAll = false, false
        for _, it in ipairs(items) do
            local k = tostring(type(it) == "table" and it.key or it)
            if k == MUT_NO then hasNo = true end
            if k == MUT_ALL then hasAll = true end
        end
        if not hasAll then
            table.insert(items, 1, { key = MUT_ALL, name = "(All mutation)" })
        end
        if not hasNo then
            table.insert(items, 1, { key = MUT_NO, name = "(No mutation)" })
        end
        return items
    end

    local function buildMutationItems()
        if PetListView and type(PetListView.listAllMutations) == "function" then
            local items = PetListView.listAllMutations() or {}
            if #items > 0 then
                if type(items[1]) == "string" then
                    local out = {}
                    for _, s in ipairs(items) do
                        out[#out + 1] = { key = s, name = s }
                    end
                    return prependMutationSpecial(out)
                end
                return prependMutationSpecial(items)
            end
        end
        local RS = game:GetService("ReplicatedStorage")
        local ok, reg = pcall(function()
            return require(RS.Data.PetRegistry.PetMutationRegistry)
        end)
        local items = {}
        if ok and type(reg) == "table" then
            local list = reg.PetMutationRegistry or reg.List or reg.Mutations or reg.All or reg
            if type(list) == "table" then
                for k, v in pairs(list) do
                    if type(v) == "table" or type(k) == "string" then
                        local nm = tostring((type(v) == "table" and (v.name or v.Name)) or k)
                        if nm ~= "" and nm ~= "PetMutationRegistry" then
                            items[#items + 1] = { key = nm, name = nm }
                        end
                    end
                end
            end
        end
        table.sort(items, function(a, b)
            return tostring(a.name) < tostring(b.name)
        end)
        return prependMutationSpecial(items)
    end

    local function makeRuleIdB(petType, minKg, maxKg, minAge, maxAge, mutation)
        petType = tostring(petType or "")
        minKg = tonumber(minKg) or 0
        local maxPart = (maxKg == nil) and "INF" or tostring(tonumber(maxKg) or 0)
        local minPart = tostring(round1(minKg))
        if maxKg ~= nil then maxPart = tostring(round1(maxKg)) end
        minAge = math.floor(tonumber(minAge) or 0)
        local maxAgePart = (maxAge == nil) and "INF" or tostring(math.floor(tonumber(maxAge) or 0))
        local mutPart = mutStoreToRuleToken(mutation)
        return ("B|%s|%s|%s|%d|%s|%s"):format(petType, minPart, maxPart, minAge, maxAgePart, mutPart)
    end

    local function normalizeModeBListAges()
        local migrated = false
        for key, rec in pairs(MK.list or {}) do
            if rec and tostring(rec.mode or "") == "B" then
                if rec.mutation == nil then
                    rec.mutation = "*"
                    migrated = true
                else
                    rec.mutation = normMutationStore(rec.mutation)
                end
                rec.minAge = clampModeBAge(rec.minAge)
                rec.maxAge = clampModeBAge(rec.maxAge)
                if rec.maxAge < rec.minAge then
                    local tmp = rec.minAge
                    rec.minAge = rec.maxAge
                    rec.maxAge = tmp
                    migrated = true
                end
            end
        end
        if migrated and type(autoSave) == "function" then autoSave() end
    end

    local function attachModeBListRowControls(opts)
        local item = opts.item
        local rec = opts.rec
        local key = tostring(opts.key or "")
        local xRight = tonumber(opts.xRight) or 22
        local gap2 = 4
        local makeMiniBox = opts.makeMiniBox
        local kgW, priceW, ageW = 30, 50, 58

        local function uiCorner(p)
            local c = Instance.new("UICorner")
            c.CornerRadius = UDim.new(0, 4)
            c.Parent = p
        end

        local function commitAll()
            local oldKey = key
            MK.list[oldKey] = MK.list[oldKey] or rec
            local row = MK.list[oldKey]

            local n = toNumFloat(opts.priceBox and opts.priceBox.Text)
            if not n or n < 0 then n = 0 end
            row.price = n
            if opts.priceBox then opts.priceBox.Text = tostring(n) end

            local minV = parseKgBox(opts.minBox and opts.minBox.Text)
            if minV == nil then minV = 0 end
            local maxV = parseKgBox(opts.maxBox and opts.maxBox.Text)
            if maxV ~= nil and maxV < minV then
                local tmp = minV; minV = maxV; maxV = tmp
            end
            row.minKg = minV
            row.maxKg = maxV

            row.minAge = clampModeBAge(row.minAge)
            row.maxAge = clampModeBAge(row.maxAge)
            if row.maxAge < row.minAge then
                local tmp = row.minAge
                row.minAge = row.maxAge
                row.maxAge = tmp
            end
            row.mutation = normMutationStore(row.mutation or rec.mutation)

            local petType = tostring(row.petType or rec.petType or "")
            local newKey = makeRuleIdB(petType, minV, maxV, row.minAge, row.maxAge, row.mutation)
            if newKey ~= oldKey then
                MK.list[newKey] = row
                MK.list[oldKey] = nil
            end

            if opts.minBox then opts.minBox.Text = fmt1(minV) end
            if opts.maxBox then opts.maxBox.Text = (maxV ~= nil) and fmt1(maxV) or "" end
            if opts.ageBtn then
                opts.ageBtn.Text = modeBListAgeButtonText(row.minAge, row.maxAge)
            end

            if type(autoSave) == "function" then autoSave() end
            if type(MK._refreshSavedList) == "function" then MK._refreshSavedList() end
            if type(MK._refreshListTab) == "function" then MK._refreshListTab() end
        end

        local priceBox = makeMiniBox(priceW, rec.price or 0, "price")
        priceBox.Parent = item
        priceBox.Position = UDim2.new(1, -(xRight + priceW), 0.5, -11)
        xRight = xRight + priceW + gap2

        local curMin = tonumber(rec.minKg) or 0
        local curMax = (rec.maxKg ~= nil) and tonumber(rec.maxKg) or nil

        local maxBox = makeMiniBox(kgW, (curMax ~= nil and fmt1(curMax) or ""), "max")
        maxBox.Parent = item
        maxBox.Position = UDim2.new(1, -(xRight + kgW), 0.5, -11)
        xRight = xRight + kgW + gap2

        local minBox = makeMiniBox(kgW, fmt1(curMin), "min")
        minBox.Parent = item
        minBox.Position = UDim2.new(1, -(xRight + kgW), 0.5, -11)
        xRight = xRight + kgW + gap2

        local ageBtn = Instance.new("TextButton")
        ageBtn.BackgroundColor3 = Color3.fromRGB(28, 28, 38)
        ageBtn.BorderSizePixel = 0
        ageBtn.Size = UDim2.new(0, ageW, 0, 22)
        ageBtn.Position = UDim2.new(1, -(xRight + ageW), 0.5, -11)
        ageBtn.Font = Enum.Font.Gotham
        ageBtn.TextSize = 10
        ageBtn.TextColor3 = Color3.fromRGB(235, 235, 235)
        ageBtn.Text = modeBListAgeButtonText(rec.minAge, rec.maxAge)
        ageBtn.AutoButtonColor = true
        ageBtn.Parent = item
        uiCorner(ageBtn)
        xRight = xRight + ageW + gap2

        opts.priceBox = priceBox
        opts.minBox = minBox
        opts.maxBox = maxBox
        opts.ageBtn = ageBtn

        priceBox.FocusLost:Connect(commitAll)
        minBox.FocusLost:Connect(commitAll)
        maxBox.FocusLost:Connect(commitAll)
        ageBtn.MouseButton1Click:Connect(function()
            local row = MK.list[key] or rec
            local curMin = clampModeBAge(row.minAge)
            local curMax = clampModeBAge(row.maxAge)
            local snapMin, snapMax, _, pidx = snapModeBAgeToPreset(curMin, curMax)
            local nextIdx
            if curMin == snapMin and curMax == snapMax then
                nextIdx = (pidx % #MODE_B_LIST_AGE) + 1
            else
                -- range custom (mis. 0-500): klik = bucket berikutnya, jangan paksa 0-100
                nextIdx = (pidx % #MODE_B_LIST_AGE) + 1
            end
            local next = MODE_B_LIST_AGE[nextIdx]
            if next then
                row.minAge = next.minAge
                row.maxAge = next.maxAge
            end
            MK.list[key] = row
            commitAll()
        end)

        return xRight, priceBox
    end

    -- Urutan list: Harga → Age → KG (Mode A / booth); Mode B: harga → min age → min KG → jenis pet
    local function cmpNumAsc(a, b)
        a = tonumber(a) or 0
        b = tonumber(b) or 0
        if a ~= b then return a < b end
        return nil
    end

    local function cmpStrAsc(a, b)
        a = tostring(a or "")
        b = tostring(b or "")
        if a ~= b then return a < b end
        return nil
    end

    local function cmpPriceAgeKg(a, b)
        local c = cmpNumAsc(a.price, b.price)
        if c ~= nil then return c end
        c = cmpNumAsc(a.age, b.age)
        if c ~= nil then return c end
        c = cmpNumAsc(a.kg, b.kg)
        if c ~= nil then return c end
        return cmpStrAsc(a.key, b.key)
    end

    local function cmpModeBRule(a, b)
        local c = cmpNumAsc(a.price, b.price)
        if c ~= nil then return c end
        c = cmpNumAsc(a.minAge, b.minAge)
        if c ~= nil then return c end
        c = cmpNumAsc(a.minKg, b.minKg)
        if c ~= nil then return c end
        c = cmpStrAsc(a.petType, b.petType)
        if c ~= nil then return c end
        return cmpStrAsc(a.key, b.key)
    end

    local function buildNotFavUuidMap()
        local m = {}
        if PetListView and type(PetListView.listPetsNotFav) == "function" then
            for _, p in ipairs(PetListView.listPetsNotFav() or {}) do
                if p and p.uuid then
                    m[tostring(p.uuid)] = p
                end
            end
        end
        return m
    end

    local function sortMkListRows(rows, notFavByUuid, modeFilter)
        modeFilter = modeFilter and tostring(modeFilter):upper() or nil
        table.sort(rows, function(a, b)
            local ma = tostring(a.rec.mode or "A"):upper()
            local mb = tostring(b.rec.mode or "A"):upper()
            if modeFilter then
                ma = modeFilter
                mb = modeFilter
            elseif ma ~= mb then
                return ma < mb
            end
            if ma == "B" then
                return cmpModeBRule({
                    petType = a.rec.petType,
                    price = a.rec.price,
                    minKg = a.rec.minKg,
                    minAge = a.rec.minAge,
                    key = a.key,
                }, {
                    petType = b.rec.petType,
                    price = b.rec.price,
                    minKg = b.rec.minKg,
                    minAge = b.rec.minAge,
                    key = b.key,
                })
            end
            local pa = notFavByUuid[tostring(a.key)] or {}
            local pb = notFavByUuid[tostring(b.key)] or {}
            return cmpPriceAgeKg({
                price = a.rec.price,
                age = pa.age,
                kg = pa.kg or pa.baseKg,
                key = a.key,
            }, {
                price = b.rec.price,
                age = pb.age,
                kg = pb.kg or pb.baseKg,
                key = b.key,
            })
        end)
    end

