local MODE_C_AGE_BLOCK = 100
local MODE_C_AGE_MAX   = 500

local function ageBracketFromIndex(ageIdx)
    ageIdx = math.floor(tonumber(ageIdx) or 0)
    if ageIdx < 0 then return nil end

    local maxAge = (ageIdx + 1) * MODE_C_AGE_BLOCK
    if maxAge > MODE_C_AGE_MAX then
        if ageIdx * MODE_C_AGE_BLOCK >= MODE_C_AGE_MAX then
            return nil
        end
        maxAge = MODE_C_AGE_MAX
    end

    local minAge = (ageIdx == 0) and 0 or (ageIdx * MODE_C_AGE_BLOCK + 1)
    local label = ("%d-%d"):format(minAge, maxAge)
    return minAge, maxAge, label
end

local function ageBracketIndexFromPet(age)
    age = math.floor(tonumber(age) or 0)
    if age < 0 then age = 0 end
    if age > MODE_C_AGE_MAX then return nil end
    if age <= MODE_C_AGE_BLOCK then return 0 end
    return math.floor((age - 1) / MODE_C_AGE_BLOCK)
end

local function normPetKey(s)
    s = tostring(s or ""):lower()
    s = s:gsub("[%s_%-]+", "")
    return s
end

local function bucketAlreadyInSavedList(petType, minKg, maxKg, minAge, maxAge, mutation)
    local wantPt = normPetKey(petType)
    local wantMin = round1(minKg)
    local wantMax = round1(maxKg)
    local wantMinA = math.floor(tonumber(minAge) or 0)
    local wantMaxA = math.floor(tonumber(maxAge) or 100)
    local wantMut = normMutationStore(mutation)

    if type(makeRuleIdB) == "function" then
        local ruleId = makeRuleIdB(petType, minKg, maxKg, minAge, maxAge, wantMut)
        local rec = MK.list and MK.list[ruleId]
        if type(rec) == "table" and tostring(rec.mode or "A"):upper() == "B" then
            return true
        end
    end

    for _, rec in pairs(MK.list or {}) do
        if type(rec) == "table" and tostring(rec.mode or "A"):upper() == "B" then
            local gotPt = normPetKey(rec.petType)
            if gotPt ~= "" and gotPt == wantPt and mutationOverlaps(wantMut, rec.mutation) then
                local rMin = round1(tonumber(rec.minKg) or 0)
                local rMax = (rec.maxKg == nil) and wantMax or round1(rec.maxKg)
                if rMin == wantMin and rMax == wantMax then
                    local rMinA = math.floor(tonumber(rec.minAge) or 0)
                    local rMaxA = math.floor(tonumber(rec.maxAge) or wantMaxA)
                    if rMinA == wantMinA and rMaxA == wantMaxA then
                        return true
                    end
                end
            end
        end
    end
    return false
end

local function buildBucketItemsForDropdown(step)
    step = tonumber(step) or 0.1
    if step <= 0 then step = 0.1 end

    local raw = _getNotFav()
    -- pt -> kgIdx -> { ageIdx=count, minAgeIdx, maxAgeIdx, minKgIdx, maxKgIdx }
    local byType = {}

    for _, p in ipairs(raw) do
        local pt = tostring(p and p.ptype or "")
        if pt ~= "" then
            local kg = tonumber(p.baseKg)
            if not kg or kg <= 0 then kg = tonumber(p.kg) end
            if kg and kg > 0 then
                local kgIdx = math.floor((kg / step) + 1e-9)
                local ageIdx = ageBracketIndexFromPet(p.age)
                if ageIdx ~= nil then
                    local ptR = byType[pt]
                    if not ptR then
                        ptR = { kg = {}, minKgIdx = kgIdx, maxKgIdx = kgIdx }
                        byType[pt] = ptR
                    end
                    if kgIdx < ptR.minKgIdx then ptR.minKgIdx = kgIdx end
                    if kgIdx > ptR.maxKgIdx then ptR.maxKgIdx = kgIdx end

                    local kgR = ptR.kg[kgIdx]
                    if not kgR then
                        kgR = { age = {}, minAgeIdx = ageIdx, maxAgeIdx = ageIdx }
                        ptR.kg[kgIdx] = kgR
                    end
                    kgR.age[ageIdx] = (kgR.age[ageIdx] or 0) + 1
                    if ageIdx < kgR.minAgeIdx then kgR.minAgeIdx = ageIdx end
                    if ageIdx > kgR.maxAgeIdx then kgR.maxAgeIdx = ageIdx end
                end
            end
        end
    end

    local items = {}
    for pt, ptR in pairs(byType) do
        local pretty = titleCaseWords(pt)
        for kgIdx = ptR.minKgIdx, ptR.maxKgIdx do
            local kgR = ptR.kg[kgIdx]
            if kgR then
                for ageIdx = kgR.minAgeIdx, kgR.maxAgeIdx do
                    local c = kgR.age[ageIdx]
                    if c and c > 0 then
                        local minKg = kgIdx * step
                        local maxKg = (kgIdx + 1) * step
                        local minAge, maxAge, ageLabel = ageBracketFromIndex(ageIdx)
                        if minAge then
                            local key = ("C|%s|%s|%s|%d|%d"):format(
            tostring(pt),
            tostring(round1(minKg)),
                                tostring(round1(maxKg)),
                                minAge,
                                maxAge
        )

        local name = ("%s | T %d | %s < %s | Age %s"):format(
                                    pretty, c, fmt1(minKg), fmt1(maxKg), ageLabel)
                            local inList = bucketAlreadyInSavedList(pt, minKg, maxKg, minAge, maxAge, MK.modeC and MK.modeC.mutation)
                            if inList then
                                name = "\194\183 " .. name
                            end
        items[#items+1] = {
                                key     = key,
                                name    = name,
                                _pt     = pt,
                                _min    = minKg,
                                _max    = maxKg,
                                _ageMin = minAge,
                                _n      = c,
                                _inList = inList,
                                _order  = inList and 0 or 1,
                            }
                        end
                    end
                end
    end
end
    end

    table.sort(items, function(a, b)
        local aIn = a._inList == true
        local bIn = b._inList == true
        if aIn ~= bIn then
            return aIn
        end
        if tostring(a._pt) ~= tostring(b._pt) then
            return tostring(a._pt) < tostring(b._pt)
        end
        if (tonumber(a._min) or 0) ~= (tonumber(b._min) or 0) then
            return (tonumber(a._min) or 0) < (tonumber(b._min) or 0)
        end
        return (tonumber(a._ageMin) or 0) < (tonumber(b._ageMin) or 0)
    end)

    return items
end

local function parseBucketKey(key)
    -- "C|petType|minKg|maxKg|minAge|maxAge" (6 bagian) atau legacy 4 bagian
    local parts = {}
    for s in tostring(key or ""):gmatch("[^|]+") do
        parts[#parts+1] = s
    end
    if parts[1] ~= "C" or #parts < 4 then return nil end

    local pt = parts[2]
    local minKg = tonumber(parts[3])
    local maxKg = tonumber(parts[4])
    if not pt or not minKg or not maxKg then return nil end

    local minAge, maxAge = 0, 100
    if #parts >= 6 then
        minAge = math.floor(tonumber(parts[5]) or 0)
        maxAge = math.floor(tonumber(parts[6]) or 100)
    end
    return pt, minKg, maxKg, minAge, maxAge
end

            local function buildLabelMapFromItems(items)
