            local function fmtNum(n)
    n = tonumber(n) or 0
    if n % 1 == 0 then return tostring(math.floor(n)) end
    return tostring(n)
end

-- map key->label (biar yang tampil bukan UUID doang)
local function getLabelForKey(labelMap, key)
    key = tostring(key)
    return tostring(labelMap and labelMap[key] or key)
end

local function _asMax(v)
    v = tonumber(v)
    if v == nil then return math.huge end
    return v
end

local function _overlapHalfOpen(aMin, aMax, bMin, bMax)
    aMin = tonumber(aMin) or 0
    bMin = tonumber(bMin) or 0
    aMax = _asMax(aMax)
    bMax = _asMax(bMax)
    -- overlap if [aMin,aMax) intersects [bMin,bMax)
    return (aMin < bMax) and (bMin < aMax)
end

local function _overlapInclusiveAge(aMin, aMax, bMin, bMax)
    aMin = math.floor(tonumber(aMin) or 0)
    bMin = math.floor(tonumber(bMin) or 0)
    aMax = tonumber(aMax)
    bMax = tonumber(bMax)
    if aMax == nil then aMax = math.huge else aMax = math.floor(aMax) end
    if bMax == nil then bMax = math.huge else bMax = math.floor(bMax) end
    return aMin <= bMax and bMin <= aMax
end

local function findConflictsForPetType(petType, newMin, newMax, newMinAge, newMaxAge, mutation)
    local hits = {}
    local wantMut = normMutationStore(mutation)
    for _, rec in pairs(MK.list or {}) do
        if type(rec) == "table" and tostring(rec.mode or "A"):upper() == "B" then
            if tostring(rec.petType or "") == tostring(petType)
                and mutationOverlaps(wantMut, rec.mutation) then
                local oldMin = tonumber(rec.minKg) or 0
                local oldMax = rec.maxKg
                local oldMinAge = math.floor(tonumber(rec.minAge) or 0)
                local oldMaxAge = rec.maxAge
                if oldMaxAge ~= nil then oldMaxAge = math.floor(tonumber(oldMaxAge) or 0) end
                if _overlapHalfOpen(newMin, newMax, oldMin, oldMax)
                    and _overlapInclusiveAge(newMinAge, newMaxAge, oldMinAge, oldMaxAge) then
                    hits[#hits+1] = {
                        minKg = oldMin,
                        maxKg = oldMax,
                        minAge = oldMinAge,
                        maxAge = oldMaxAge,
                        price = tonumber(rec.price) or 0,
                        mutation = normMutationStore(rec.mutation),
                    }
                end
            end
        end
    end
    return hits
end

local function buildConflictLines(petType, newMin, newMax, newMinAge, newMaxAge, conflicts, mutation)
    local lines = {}
    lines[#lines+1] = ("PetType: %s | Mut: %s"):format(tostring(petType), mutLabel(mutation))
    lines[#lines+1] = ("New KG: [%s, %s) | %s"):format(
        fmt1(newMin), (newMax==nil and "∞" or fmt1(newMax)), ageRangeText(newMinAge, newMaxAge))
    lines[#lines+1] = "Sama dengan:"
    local maxShow = 6
    for i = 1, math.min(#conflicts, maxShow) do
        local c = conflicts[i]
        lines[#lines+1] = ("• [%s, %s) | %s | Mut %s | Price %s"):format(
            fmt1(c.minKg),
            (c.maxKg==nil and "∞" or fmt1(c.maxKg)),
            ageRangeText(c.minAge, c.maxAge),
            mutLabel(c.mutation),
            fmtNum(c.price)
        )
    end
    if #conflicts > maxShow then
        lines[#lines+1] = ("• +%d lainnya..."):format(#conflicts - maxShow)
    end
    return lines
end

local function buildConfirmLines_ModeA(pickedUUIDs, price, notFavLabelMap)
    local lines = {}
    lines[#lines+1] = ("Mode A  |  Price: %s"):format(fmtNum(price))
    lines[#lines+1] = ("Items (%d):"):format(#pickedUUIDs)

    local maxShow = 14
    for i = 1, math.min(#pickedUUIDs, maxShow) do
        local uuid = tostring(pickedUUIDs[i])
        local nm = getLabelForKey(notFavLabelMap, uuid)
        lines[#lines+1] = ("• %s  |  %s"):format(nm, uuid)
    end
    if #pickedUUIDs > maxShow then
        lines[#lines+1] = ("• +%d lainnya..."):format(#pickedUUIDs - maxShow)
    end
    return lines
end

local function buildConfirmLines_ModeB(picked, price, minKg, maxKg, minAge, maxAge, petTypeLabel, mutation)
    local lines = {}

    lines[#lines+1] = ("Mode B | Price: %s | Mut: %s | %s | %s"):format(
        tostring(price), mutLabel(mutation), kgRangeText(minKg, maxKg), ageRangeText(minAge, maxAge))
    lines[#lines+1] = ("Types (%d):"):format(#picked)

    for _, k in ipairs(picked) do
        local nm = (petTypeLabel and petTypeLabel[tostring(k)]) or tostring(k)
        lines[#lines+1] = "- " .. nm
    end

    return lines
end


