            searchWrap.Size = UDim2.new(1, 0, 0, 26)
            searchWrap.LayoutOrder = 2
            mkCorner(searchWrap, 4)
            mkStroke(searchWrap, Color3.fromRGB(40,40,40), 1, 0.5)
            mkPad(searchWrap, 6, 6, 0, 0)

            local searchBox = Instance.new("TextBox")
            searchBox.Name = "Search"
            searchBox.Parent = searchWrap
            searchBox.BackgroundTransparency = 1
            searchBox.Size = UDim2.new(1, 0, 1, 0)
            searchBox.Font = Enum.Font.Gotham
            searchBox.TextSize = 12
            searchBox.TextColor3 = Color3.fromRGB(235,235,235)
            searchBox.TextXAlignment = Enum.TextXAlignment.Center
            searchBox.ClearTextOnFocus = false
            searchBox.Text = ""

            local hint = Instance.new("TextLabel")
            hint.Name = "Hint"
            hint.Parent = searchWrap
            hint.BackgroundTransparency = 1
            hint.Size = UDim2.new(1, 0, 1, 0)
            hint.Font = Enum.Font.Gotham
            hint.TextSize = 12
            hint.TextColor3 = Color3.fromRGB(150,150,150)
            hint.TextXAlignment = Enum.TextXAlignment.Center
            hint.Text = "Search"
            hint.ZIndex = searchBox.ZIndex + 1

            local function updateHint()
                local txt = tostring(searchBox.Text or ""):gsub("%s+", "")
                hint.Visible = (txt == "") and (not searchBox:IsFocused())
            end
            updateHint()
            searchBox.Focused:Connect(updateHint)
            searchBox.FocusLost:Connect(function()
                local t = tostring(searchBox.Text or "")
                t = t:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
                searchBox.Text = t
                updateHint()
                if MK._refreshSavedList then MK._refreshSavedList() end
            end)

            local ROW_H = 26
            local ROW_PAD = 4
            local VISIBLE_ROWS = 6
            local LIST_PAD_TOP = 8
            local LIST_PAD_BOT = 8

            local function calcListHeight(count)
                local rows = math.min(count or 0, VISIBLE_ROWS)
                if rows <= 0 then rows = 1 end
                return (rows * ROW_H) + ((rows - 1) * ROW_PAD) + LIST_PAD_TOP + LIST_PAD_BOT
            end

            local sf = Instance.new("ScrollingFrame")
            sf.Name = "SavedList"
            sf.Parent = listRow
            sf.BackgroundColor3 = Color3.fromRGB(15,15,15)
            sf.BorderSizePixel = 0
            sf.LayoutOrder = 3
            sf.Size = UDim2.new(1, 0, 0, calcListHeight(0))
            sf.CanvasSize = UDim2.new(0, 0, 0, 0)
            sf.ScrollBarThickness = 0
            sf.ScrollBarImageTransparency = 1
            sf.ScrollingDirection = Enum.ScrollingDirection.Y
            sf.AutomaticCanvasSize = Enum.AutomaticSize.Y
            sf.ClipsDescendants = true
            mkCorner(sf, 6)
            mkStroke(sf, Color3.fromRGB(40,40,40), 1, 0.5)
            mkPad(sf, 4, 4, LIST_PAD_TOP, LIST_PAD_BOT)

            local layout = Instance.new("UIListLayout")
            layout.FillDirection = Enum.FillDirection.Vertical
            layout.SortOrder = Enum.SortOrder.LayoutOrder
            layout.Padding = UDim.new(0, ROW_PAD)
            layout.Parent = sf

            local function clearRows()
                for _, ch in ipairs(sf:GetChildren()) do
                    if ch:IsA("Frame") and ch.Name:sub(1,5) == "Item_" then
                        ch:Destroy()
                    end
                    if ch:IsA("TextLabel") and ch.Name == "EmptyHint" then
                        ch:Destroy()
                    end
                end
            end

            local function deleteKey(key)
                key = tostring(key or "")
                if key == "" then return end
                MK.list[key] = nil
                autoSave()
            end

            local function buildRow(i, key, titleText, rec)
                rec = rec or {}
                local mode = tostring(rec.mode or "A")

                local item = Instance.new("Frame")
                item.Name = "Item_" .. tostring(key)
                item.BackgroundColor3 = Color3.fromRGB(22,22,22)
                local rowH = (mode == "B") and 28 or ROW_H
                item.Size = UDim2.new(1, 0, 0, rowH)
                item.LayoutOrder = i
                item.Parent = sf
                mkCorner(item, 4)

                local ip = Instance.new("UIPadding")
                ip.PaddingLeft = UDim.new(0, 6)
                ip.PaddingRight = UDim.new(0, 6)
                ip.Parent = item

                local function makeMiniLabel(txt, w)
                    local lb = Instance.new("TextLabel")
                    lb.BackgroundTransparency = 1
                    lb.Size = UDim2.new(0, w or 34, 1, 0)
                    lb.Font = Enum.Font.Gotham
                    lb.TextSize = 11
                    lb.TextColor3 = Color3.fromRGB(190,190,190)
                    lb.TextXAlignment = Enum.TextXAlignment.Left
                    lb.Text = tostring(txt or "")
                    return lb
                end

                local function makeMiniBox(w, text, placeholder)
                    local box = Instance.new("TextBox")
                    box.BackgroundColor3 = Color3.fromRGB(18,18,18)
                    box.BorderSizePixel = 0
                    box.Size = UDim2.new(0, w, 0, 22)
                    box.Font = Enum.Font.Gotham
                    box.TextSize = 12
                    box.TextColor3 = Color3.fromRGB(235,235,235)
                    box.PlaceholderColor3 = Color3.fromRGB(140,140,140)
                    box.PlaceholderText = placeholder or ""
                    box.ClearTextOnFocus = false
                    box.TextXAlignment = Enum.TextXAlignment.Center
                    box.Text = tostring(text or "")
                    mkCorner(box, 4)
                    mkStroke(box, Color3.fromRGB(40,40,40), 1, 0.6)
                    return box
                end

                local del = Instance.new("TextButton")
                del.Name = "BtnDelete"
                del.Parent = item
                del.BackgroundColor3 = Color3.fromRGB(160, 40, 40)
                del.Size = UDim2.new(0, 22, 0, 22)
                del.Position = UDim2.new(1, -22, 0.5, -11)
                del.AutoButtonColor = true
                del.Font = Enum.Font.GothamBold
                del.TextSize = 14
                del.TextColor3 = Color3.fromRGB(255,255,255)
                del.Text = "-"
                del.BorderSizePixel = 0
                mkCorner(del, 4)
                mkStroke(del, Color3.fromRGB(40,40,40), 1, 0.6)

                del.MouseButton1Click:Connect(function()
                    deleteKey(key)
                    if MK._refreshSavedList then MK._refreshSavedList() end
                end)

                local xRight = 22
                local gap = 6
                local priceBox

                if mode == "B" then
                    xRight = attachModeBListRowControls({
                        item = item,
                        rec = rec,
                        key = key,
                        xRight = xRight,
                        makeMiniBox = makeMiniBox,
                    })
                else
                    local priceBoxW = 56
                    priceBox = makeMiniBox(priceBoxW, rec.price or 0, "price")
                priceBox.Parent = item
                priceBox.Position = UDim2.new(1, -(xRight + priceBoxW), 0.5, -11)
                    xRight = xRight + priceBoxW + gap
                end

                local nameLbl = Instance.new("TextLabel")
                nameLbl.BackgroundTransparency = 1
                nameLbl.Position = UDim2.new(0, 0, 0, 0)
                nameLbl.Size = UDim2.new(1, -(xRight + gap), 1, 0)
                nameLbl.Font = Enum.Font.Gotham
                nameLbl.TextSize = 11
                nameLbl.TextXAlignment = Enum.TextXAlignment.Left
                nameLbl.TextColor3 = Color3.fromRGB(235,235,235)
                nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
                nameLbl.Text = tostring(titleText or key)
                nameLbl.Parent = item

                if mode ~= "B" and priceBox then
                priceBox.FocusLost:Connect(function()
                    local n = toNumFloat(priceBox.Text)
                    if not n or n < 0 then n = 0 end
                    local k = tostring(key)
                    MK.list[k] = MK.list[k] or rec
                    MK.list[k].price = n
                    priceBox.Text = tostring(n)
                    autoSave()
                end)
                end

            end

            local function refreshSavedList()
                normalizeModeBListAges()
                clearRows()
                updateHint()

                local q = norm(searchBox.Text)
                local shown = 0

                local notFavLabel = buildLabelMapFromItems(buildNotFavItems())
                local petTypeLabel = buildLabelMapFromItems(buildPetTypeItems())
                local notFavByUuid = buildNotFavUuidMap()
                local rows = {}

                for key, rec in pairs(MK.list or {}) do
                    if rec then
                        local mode = tostring(rec.mode or "A")
                        local title

if mode == "A" then
    title = notFavLabel[tostring(key)] or ("UUID: " .. tostring(key))
else
local pt = tostring(rec.petType or key)
local nm = petTypeLabel[pt] or pt
                            nm = titleCaseWords(nm)
local rmin = tonumber(rec.minKg) or 0
local rmax = rec.maxKg ~= nil and tonumber(rec.maxKg) or nil
                            title = ("%s | %s | %s | %s"):format(
                                nm, mutLabel(rec.mutation), kgRangeText(rmin, rmax), ageRangeText(rec.minAge, rec.maxAge))
end

                        if q == "" or norm(title):find(q, 1, true) then
                            rows[#rows + 1] = { key = key, rec = rec, title = title }
                        end
                    end
                end

                sortMkListRows(rows, notFavByUuid, nil)
                for i, row in ipairs(rows) do
                    shown += 1
                    buildRow(shown, row.key, row.title, row.rec)
                end

                if shown == 0 then
                    local t = Instance.new("TextLabel")
                    t.Name = "EmptyHint"
                    t.Parent = sf
                    t.BackgroundTransparency = 1
                    t.Size = UDim2.new(1, -10, 0, 40)
                    t.Position = UDim2.new(0, 5, 0, 0)
                    t.Font = Enum.Font.Gotham
                    t.TextSize = 12
                    t.TextXAlignment = Enum.TextXAlignment.Left
                    t.TextYAlignment = Enum.TextYAlignment.Top
                    t.TextColor3 = Color3.fromRGB(170,170,170)
                    t.RichText = true
                    t.TextWrapped = true
                    t.Text = (q ~= "")
                        and '<font color="#FFD76A"><b>Tidak ditemukan.</b></font>\n<b>Hapus kata pencarian untuk menampilkan semua.</b>'
                        or  '<font color="#FFD76A"><b>List masih kosong.</b></font>\n<b>Pilih Mode lalu klik APPLY.</b>'
                end

                local baseH = calcListHeight(shown)
                if shown == 0 then baseH = math.max(baseH, 44) end
                sf.Size = UDim2.new(1, 0, 0, baseH)

                if shown > VISIBLE_ROWS then
                    sf.ScrollBarThickness = 6
                    sf.ScrollBarImageTransparency = 0
                else
                    sf.ScrollBarThickness = 0
                    sf.ScrollBarImageTransparency = 1
                    sf.CanvasPosition = Vector2.new(0, 0)
                end
                if MK.mode == "C" and type(MK._refreshModeCDropdown) == "function" then
                    MK._refreshModeCDropdown()
                end
                if type(MK._refreshListingConfig) == "function" then
                    MK._refreshListingConfig()
                elseif type(MK._refreshListingPetConfig) == "function" then
                    MK._refreshListingPetConfig()
                end
            end
            MK._refreshSavedList = refreshSavedList

            do
                local sp = false
                searchBox:GetPropertyChangedSignal("Text"):Connect(function()
                    updateHint()
                    if sp then return end
                    sp = true
                    task.defer(function()
                        sp = false
                        if MK._refreshSavedList then MK._refreshSavedList() end
                    end)
                end)
            end


local modeItems = {
    { key = "A", name = "A · NotFav" },
    { key = "B", name = "B · Manual" },
    { key = "C", name = "C · Bucket" },
}

