-- ambil data input (max boleh nil)
local price = tonumber(MK.modeB.price) or 0
local minKg = tonumber(MK.modeB.minKg) or 0
local maxKg = tonumber(MK.modeB.maxKg) or 0
local minAge = clampModeBAge(MK.modeB.minAge)
local maxAge = clampModeBAge(MK.modeB.maxAge)

-- normalize: kalau max ada dan < min swap
if maxKg ~= nil and maxKg < minKg then
    local tmp = minKg; minKg = maxKg; maxKg = tmp
end
if maxAge < minAge then
    local tmp = minAge; minAge = maxAge; maxAge = tmp
end

-- cek bentrok untuk semua petType yang dipilih
local anyConflict = false
local conflictLinesAll = {}
for _, petType in ipairs(picked) do
    local conflicts = findConflictsForPetType(petType, minKg, maxKg, minAge, maxAge, mutation)
    if #conflicts > 0 then
        anyConflict = true
        -- gabung lines (dipisah biar jelas)
        conflictLinesAll[#conflictLinesAll+1] = ("<b>%s</b>"):format(tostring(petType))
        local lines = buildConflictLines(petType, minKg, maxKg, minAge, maxAge, conflicts, mutation)
        for _, ln in ipairs(lines) do conflictLinesAll[#conflictLinesAll+1] = ln end
        conflictLinesAll[#conflictLinesAll+1] = " " -- spacer
    end
end

if anyConflict then
    ui:Confirm({
        title = "RANGE BENTROK",
        badge = "MODE B",
        meta  = "Tidak disimpan. Silakan ubah range dulu.",
        lines = conflictLinesAll,
        onYes = function() end, -- biar bisa ditutup
    })
    return -- ✅ STOP. jangan simpan, jangan reset
end

    ui:Confirm({
        title = "ADD TO LIST",
        badge = "MODE B",
        meta  = ("Price: %s  |  Mut: %s  |  %s  |  %s  |  Types: %d"):format(
            tostring(price), mutLabel(mutation), kgRangeText(minKg, maxKg), ageRangeText(minAge, maxAge), #picked),
        lines = buildConfirmLines_ModeB(picked, price, minKg, maxKg, minAge, maxAge, petTypeLabel, mutation),

        onYes = function()
            for _, petType in ipairs(picked) do
                local ruleId = makeRuleIdB(petType, minKg, maxKg, minAge, maxAge, mutation)
                MK.list[ruleId] = MK.list[ruleId] or { mode = "B" }

                MK.list[ruleId].mode   = "B"
                MK.list[ruleId].petType= tostring(petType)
                MK.list[ruleId].price  = price
                MK.list[ruleId].minKg  = minKg
                MK.list[ruleId].maxKg  = maxKg
                MK.list[ruleId].minAge = minAge
                MK.list[ruleId].maxAge = maxAge
                MK.list[ruleId].mutation = mutation
            end

            MK.modeB.selected = {}
            if ddPetTypeApi and ddPetTypeApi.setSelected then
                ddPetTypeApi.setSelected({})
                if ddPetTypeApi.refreshLabel then ddPetTypeApi.refreshLabel() end
            end

            MK.modeB.price = 0
            MK.modeB.minKg = 0
            MK.modeB.maxKg = 0
            MK.modeB.minAge = 0
            MK.modeB.maxAge = 0
            MK.modeB.mutation = "*"
            if ddMutApi and ddMutApi.setSelected then
