                if ddMutApi.refreshLabel then ddMutApi.refreshLabel() end
            end

            if setPriceB then setPriceB("0") end
            if setMinB then setMinB("0") end
            if setMaxB then setMaxB("0") end
            if setMinAgeB then setMinAgeB("0") end
            if setMaxAgeB then setMaxAgeB("0") end

            autoSave()
            if MK._refreshSavedList then MK._refreshSavedList() end
        end,
    })
end, nil, { momentary = true })

