            local pt, minKg, maxKg, bMinAge, bMaxAge = parseBucketKey(key)
            if pt then
                previewLines[#previewLines+1] = ("• %s | [%s, %s) | Age %d-%d"):format(
                    pt, fmt1(minKg), fmt1(maxKg), bMinAge, bMaxAge)
            end
        end

        -- conflict check
        local anyConflict = false
        local conflictLinesAll = {}
        for _, key in ipairs(pickedBuckets) do
            local pt, minKg, maxKg, bMinAge, bMaxAge = parseBucketKey(key)
            if pt then
                local conflicts = findConflictsForPetType(pt, minKg, maxKg, bMinAge, bMaxAge, mutation)
                if #conflicts > 0 then
                    anyConflict = true
                    conflictLinesAll[#conflictLinesAll+1] = ("<b>%s</b> [%s,%s) Age %d-%d"):format(
                        pt, fmt1(minKg), fmt1(maxKg), bMinAge, bMaxAge)
                    local lines = buildConflictLines(pt, minKg, maxKg, bMinAge, bMaxAge, conflicts, mutation)
                    for _, ln in ipairs(lines) do conflictLinesAll[#conflictLinesAll+1] = ln end
                    conflictLinesAll[#conflictLinesAll+1] = " "
                end
            end
        end

        if anyConflict then
            ui:Confirm({
                title = "RANGE BENTROK",
                badge = "MODE C",
                meta  = "Tidak disimpan. Hapus rule bentrok / ubah step / ubah list.",
                lines = conflictLinesAll,
                onYes = function() end,
            })
            return
        end

        ui:Confirm({
            title = "ADD TO LIST",
            badge = "MODE C",
            meta  = ("Price: %s | Mut: %s | Buckets: %d | Age per 100 level (max 500)"):format(
                tostring(price), mutLabel(mutation), #pickedBuckets),
            lines = previewLines,
            onYes = function()
                for _, key in ipairs(pickedBuckets) do
                    local pt, minKg, maxKg, bMinAge, bMaxAge = parseBucketKey(key)
                    if pt then
                        local ruleId = makeRuleIdB(pt, minKg, maxKg, bMinAge, bMaxAge, mutation)
                        MK.list[ruleId] = MK.list[ruleId] or { mode = "B" }
                        MK.list[ruleId].mode    = "B"
                        MK.list[ruleId].petType = tostring(pt)
                        MK.list[ruleId].price   = price
                        MK.list[ruleId].minKg   = minKg
                        MK.list[ruleId].maxKg   = maxKg
                        MK.list[ruleId].minAge  = bMinAge
                        MK.list[ruleId].maxAge  = bMaxAge
                        MK.list[ruleId].mutation = mutation
                    end
                end

                MK.modeC.selected = {}
                if ddBucketApi and ddBucketApi.setSelected then
                    ddBucketApi.setSelected({})
                    if ddBucketApi.refreshLabel then ddBucketApi.refreshLabel() end
                end

                MK.modeC.price = 0
                MK.modeC.mutation = "*"
                if setPriceC then setPriceC("0") end
                if ddMutApi and ddMutApi.setSelected then
                    ddMutApi.setSelected(MUT_ALL)
                    if ddMutApi.refreshLabel then ddMutApi.refreshLabel() end
                end

                autoSave()
                if MK._refreshSavedList then MK._refreshSavedList() end
                if MK._refreshModeCDropdown then MK._refreshModeCDropdown() end
            end,
        })
    end, nil, { momentary = true })
end

            if MK.mode == "B" then
    showModeB()
elseif MK.mode == "C" then
    showModeC()
else
    showModeA()
end

            refreshSavedList()

            ----------------------------------------------------------------
            -- LISTING FRUIT
            ----------------------------------------------------------------
            local bodyFruit = createSection("Listing Fruit", false)

            local function buildFruitItems()
                if FruitListView and type(FruitListView.buildEntriesFruits) == "function" then
                    return FruitListView.buildEntriesFruits(MK.modeF.selected) or {}
                end
                if FruitListView and type(FruitListView.listFruitsNotFav) == "function" then
                    local raw = FruitListView.listFruitsNotFav() or {}
                    local items = {}
                    for _, f in ipairs(raw) do
                        items[#items + 1] = { key = f.uuid, name = f.name }
                    end
                    return items
                end
                return {}
            end

            local function buildFruitLabelMap()
                local m = {}
                if FruitListView and type(FruitListView.listFruitsNotFav) == "function" then
                    for _, f in ipairs(FruitListView.listFruitsNotFav() or {}) do
                        if f then
                            local label = f.name
                            if f.listingId then m[tostring(f.listingId)] = label end
                            if f.key then m[tostring(f.key)] = label end
                            if f.uuid then m[tostring(f.uuid)] = label end
                        end
                    end
                end
                return m
            end

            local fruitListRow = Instance.new("Frame")
            fruitListRow.Name = "FruitListRow"
            fruitListRow.BackgroundTransparency = 1
            fruitListRow.Size = UDim2.new(1, 0, 0, 0)
            fruitListRow.AutomaticSize = Enum.AutomaticSize.Y
            fruitListRow.LayoutOrder = 1
            fruitListRow.Parent = bodyFruit

            local fruitRowLayout = Instance.new("UIListLayout")
            fruitRowLayout.Parent = fruitListRow
            fruitRowLayout.FillDirection = Enum.FillDirection.Vertical
            fruitRowLayout.SortOrder = Enum.SortOrder.LayoutOrder
            fruitRowLayout.Padding = UDim.new(0, 8)

            local fruitInfoWrap = Instance.new("Frame")
            fruitInfoWrap.Name = "FruitInfoWrap"
            fruitInfoWrap.Parent = fruitListRow
            fruitInfoWrap.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            fruitInfoWrap.BorderSizePixel = 0
            fruitInfoWrap.Size = UDim2.new(1, 0, 0, 0)
            fruitInfoWrap.AutomaticSize = Enum.AutomaticSize.Y
