            local fruitInfoLbl = Instance.new("TextLabel")
            fruitInfoLbl.Parent = fruitInfoWrap
            fruitInfoLbl.BackgroundTransparency = 1
            fruitInfoLbl.Size = UDim2.new(1, 0, 0, 0)
            fruitInfoLbl.AutomaticSize = Enum.AutomaticSize.Y
            fruitInfoLbl.Font = Enum.Font.Gotham
            fruitInfoLbl.TextSize = 11
            fruitInfoLbl.TextXAlignment = Enum.TextXAlignment.Left
            fruitInfoLbl.TextYAlignment = Enum.TextYAlignment.Top
            fruitInfoLbl.TextWrapped = true
            fruitInfoLbl.TextColor3 = Color3.fromRGB(235, 235, 235)
            fruitInfoLbl.RichText = true
            fruitInfoLbl.Text =
                '<font color="#7FD6FF"><b>PETUNJUK FRUIT</b></font>\n' ..
                '• Pilih <b>Fruit Mode</b> di bawah list (A = KG, B = NPC Price + Token).\n' ..
                '• <b>Mode A (KG)</b> = pilih jenis fruit + filter KG (<b>-10</b> = di bawah 10kg, <b>10</b> = di atas 10kg).\n' ..
                '• <b>Mode B (Price)</b> = NPC Price (<b>1SX</b>, <b>-12M</b>) + Price Token booth.\n' ..
                '• <b>0</b> = disable rule. Edit harga di list bawah.'

            local fruitSearchWrap = Instance.new("Frame")
            fruitSearchWrap.Name = "FruitSearchWrap"
            fruitSearchWrap.Parent = fruitListRow
            fruitSearchWrap.BackgroundColor3 = Color3.fromRGB(22, 22, 22)
            fruitSearchWrap.BorderSizePixel = 0
            fruitSearchWrap.Size = UDim2.new(1, 0, 0, 26)
            fruitSearchWrap.LayoutOrder = 2
            mkCorner(fruitSearchWrap, 4)
            mkStroke(fruitSearchWrap, Color3.fromRGB(40, 40, 40), 1, 0.5)
            mkPad(fruitSearchWrap, 6, 6, 0, 0)

            local fruitSearchBox = Instance.new("TextBox")
            fruitSearchBox.Name = "FruitSearch"
            fruitSearchBox.Parent = fruitSearchWrap
            fruitSearchBox.BackgroundTransparency = 1
            fruitSearchBox.Size = UDim2.new(1, 0, 1, 0)
            fruitSearchBox.Font = Enum.Font.Gotham
            fruitSearchBox.TextSize = 12
            fruitSearchBox.TextColor3 = Color3.fromRGB(235, 235, 235)
            fruitSearchBox.PlaceholderText = "Cari fruit list..."
            fruitSearchBox.PlaceholderColor3 = Color3.fromRGB(140, 140, 140)
            fruitSearchBox.Text = ""
            fruitSearchBox.ClearTextOnFocus = false

            local fruitSf = Instance.new("ScrollingFrame")
            fruitSf.Name = "FruitSavedList"
            fruitSf.Parent = fruitListRow
            fruitSf.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
            fruitSf.BorderSizePixel = 0
            fruitSf.LayoutOrder = 3
            fruitSf.Size = UDim2.new(1, 0, 0, calcListHeight(0))
            fruitSf.CanvasSize = UDim2.new(0, 0, 0, 0)
            fruitSf.ScrollBarThickness = 0
            fruitSf.ScrollBarImageTransparency = 1
            fruitSf.ScrollingDirection = Enum.ScrollingDirection.Y
            fruitSf.AutomaticCanvasSize = Enum.AutomaticSize.Y
            fruitSf.ClipsDescendants = true
            mkCorner(fruitSf, 6)
            mkStroke(fruitSf, Color3.fromRGB(40, 40, 40), 1, 0.5)
            mkPad(fruitSf, 4, 4, LIST_PAD_TOP, LIST_PAD_BOT)

            local fruitLayout = Instance.new("UIListLayout")
            fruitLayout.FillDirection = Enum.FillDirection.Vertical
            fruitLayout.SortOrder = Enum.SortOrder.LayoutOrder
            fruitLayout.Padding = UDim.new(0, ROW_PAD)
            fruitLayout.Parent = fruitSf

            local function clearFruitRows()
                for _, ch in ipairs(fruitSf:GetChildren()) do
                    if ch:IsA("Frame") and ch.Name:sub(1, 6) == "Fruit_" then
                        ch:Destroy()
                    end
                    if ch:IsA("TextLabel") and ch.Name == "FruitEmptyHint" then
                        ch:Destroy()
                    end
                end
            end

            local function deleteFruitKey(key)
                key = tostring(key or "")
                if key == "" then return end
                MK.fruitList[key] = nil
                autoSave()
            end

            local function parseFruitKgSigned(text)
                if FruitListView and type(FruitListView.parseKgSigned) == "function" then
                    return FruitListView.parseKgSigned(text)
                end
                return tonumber(text) or 0
            end

            local function parseFruitCompactPrice(text)
                if FruitListView and type(FruitListView.parseCompactPrice) == "function" then
                    return FruitListView.parseCompactPrice(text)
                end
                return tonumber(text) or 0
            end

            local function parseFruitSignedNpcPrice(text)
                if FruitListView and type(FruitListView.parseSignedCompactPrice) == "function" then
                    return FruitListView.parseSignedCompactPrice(text)
                end
                return tonumber(text) or 0
            end

            local function fruitNpcPriceSignedText(npcPriceSigned)
                if FruitListView and type(FruitListView.npcPriceSignedText) == "function" then
                    return FruitListView.npcPriceSignedText(npcPriceSigned)
                end
                npcPriceSigned = tonumber(npcPriceSigned) or 0
                if npcPriceSigned == 0 then return "Any NPC" end
                if npcPriceSigned < 0 then return ("<= %s"):format(math.abs(npcPriceSigned)) end
                return (">= %s"):format(npcPriceSigned)
            end

            local function fruitKgSignedText(kgSigned)
                if FruitListView and type(FruitListView.kgSignedText) == "function" then
                    return FruitListView.kgSignedText(kgSigned)
                end
                kgSigned = tonumber(kgSigned) or 0
                if kgSigned == 0 then return "Any KG" end
                if kgSigned < 0 then return ("<= %s kg"):format(math.abs(kgSigned)) end
                return (">= %s kg"):format(kgSigned)
            end

            local function buildFruitNameItems(selectedMap)
                if FruitListView and type(FruitListView.buildEntriesFruitNames) == "function" then
                    local ok, items = pcall(function()
                        return FruitListView.buildEntriesFruitNames(selectedMap)
                    end)
                    if ok and type(items) == "table" then
                        return items
                    end
                    warn("[fruit] buildFruitNameItems error:", items)
                end
                return {}
            end

            local function fruitRowTitle(key, rec, fruitLabel)
                local mode = tostring(rec.mode or "F"):upper()
                if mode == "FA" then
                    return string.format("[A] %s | %s | %s",
                        tostring(rec.fruitName or key),
                        fruitKgSignedText(rec.kg),
                        tostring(rec.price or 0))
                elseif mode == "FB" then
                    return string.format("[B] %s | NPC %s | Token %s",
                        tostring(rec.fruitName or key),
                        fruitNpcPriceSignedText(rec.npcPrice),
                        tostring(rec.price or 0))
                end
                return fruitLabel[tostring(key)] or ("UUID: " .. tostring(key))
            end

            local function refreshFruitSavedList()
                clearFruitRows()

                local q = norm(fruitSearchBox.Text)
                local shown = 0
                local fruitLabel = buildFruitLabelMap()
                local rows = {}

                for key, rec in pairs(MK.fruitList or {}) do
                    if type(rec) == "table" then
                        local title = fruitRowTitle(key, rec, fruitLabel)
                        if q == "" or norm(title):find(q, 1, true) then
                            rows[#rows + 1] = { key = key, rec = rec, title = title }
                        end
                    end
                end

                table.sort(rows, function(a, b)
                    local pa = tonumber(a.rec.price) or 0
                    local pb = tonumber(b.rec.price) or 0
                    if pa ~= pb then return pa < pb end
                    return tostring(a.title) < tostring(b.title)
                end)

                for i, row in ipairs(rows) do
                    shown += 1
                    local key = row.key
                    local rec = row.rec

                    local item = Instance.new("Frame")
                    item.Name = "Fruit_" .. tostring(key)
                    item.BackgroundColor3 = Color3.fromRGB(22, 22, 22)
                    item.Size = UDim2.new(1, 0, 0, ROW_H)
                    item.LayoutOrder = i
                    item.Parent = fruitSf
                    mkCorner(item, 4)

                    local ip = Instance.new("UIPadding")
                    ip.PaddingLeft = UDim.new(0, 6)
                    ip.PaddingRight = UDim.new(0, 6)
                    ip.Parent = item

                    local del = Instance.new("TextButton")
                    del.Name = "Del"
                    del.Parent = item
                    del.BackgroundColor3 = Color3.fromRGB(180, 50, 50)
                    del.Size = UDim2.new(0, 22, 0, 22)
                    del.Position = UDim2.new(1, -22, 0.5, -11)
                    del.AutoButtonColor = true
                    del.Font = Enum.Font.GothamBold
                    del.TextSize = 14
                    del.TextColor3 = Color3.fromRGB(255, 255, 255)
                    del.Text = "-"
                    del.BorderSizePixel = 0
                    mkCorner(del, 4)
                    mkStroke(del, Color3.fromRGB(40, 40, 40), 1, 0.6)
                    del.MouseButton1Click:Connect(function()
                        deleteFruitKey(key)
                        refreshFruitSavedList()
                    end)

                    local priceBoxW = 56
                    local priceBox = Instance.new("TextBox")
                    priceBox.Name = "Price"
                    priceBox.Parent = item
                    priceBox.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
                    priceBox.Size = UDim2.new(0, priceBoxW, 0, 22)
                    priceBox.Position = UDim2.new(1, -(22 + 6 + priceBoxW), 0.5, -11)
                    priceBox.Font = Enum.Font.Gotham
                    priceBox.TextSize = 11
                    priceBox.TextColor3 = Color3.fromRGB(235, 235, 235)
                    priceBox.Text = tostring(rec.price or 0)
                    priceBox.ClearTextOnFocus = false
                    mkCorner(priceBox, 4)
                    mkStroke(priceBox, Color3.fromRGB(40, 40, 40), 1, 0.6)

                    local nameLbl = Instance.new("TextLabel")
                    nameLbl.BackgroundTransparency = 1
                    nameLbl.Position = UDim2.new(0, 0, 0, 0)
                    nameLbl.Size = UDim2.new(1, -(22 + 6 + priceBoxW + 6), 1, 0)
                    nameLbl.Font = Enum.Font.Gotham
                    nameLbl.TextSize = 11
                    nameLbl.TextXAlignment = Enum.TextXAlignment.Left
                    nameLbl.TextColor3 = Color3.fromRGB(235, 235, 235)
                    nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
                    nameLbl.Text = tostring(row.title or key)
                    nameLbl.Parent = item

                    priceBox.FocusLost:Connect(function()
                        local mode = tostring(rec.mode or "F"):upper()
                        local n
                        if mode == "FB" then
                            n = parseFruitCompactPrice(priceBox.Text)
                        else
                            n = toNumFloat(priceBox.Text)
                            if not n or n < 0 then n = 0 end
                        end
                        local k = tostring(key)
                        MK.fruitList[k] = MK.fruitList[k] or rec
                        MK.fruitList[k].price = n
                        priceBox.Text = tostring(n)
                        autoSave()
                    end)
                end

                if shown == 0 then
                    local t = Instance.new("TextLabel")
                    t.Name = "FruitEmptyHint"
                    t.Parent = fruitSf
                    t.BackgroundTransparency = 1
                    t.Size = UDim2.new(1, -10, 0, 40)
                    t.Position = UDim2.new(0, 5, 0, 0)
                    t.Font = Enum.Font.Gotham
                    t.TextSize = 12
                    t.TextXAlignment = Enum.TextXAlignment.Left
                    t.TextYAlignment = Enum.TextYAlignment.Top
                    t.TextColor3 = Color3.fromRGB(170, 170, 170)
                    t.RichText = true
                    t.TextWrapped = true
                    t.Text = (q ~= "")
                        and '<font color="#7FD6FF"><b>Tidak ditemukan.</b></font>'
                        or  '<font color="#7FD6FF"><b>Fruit list kosong.</b></font>\n<b>Pilih fruit lalu Apply Mode A / B.</b>'
                end

                local baseH = calcListHeight(shown)
                if shown == 0 then baseH = math.max(baseH, 44) end
                fruitSf.Size = UDim2.new(1, 0, 0, baseH)

                if shown > VISIBLE_ROWS then
                    fruitSf.ScrollBarThickness = 6
                    fruitSf.ScrollBarImageTransparency = 0
                else
                    fruitSf.ScrollBarThickness = 0
                    fruitSf.ScrollBarImageTransparency = 1
                    fruitSf.CanvasPosition = Vector2.new(0, 0)
                end
                if type(MK._refreshListingConfig) == "function" then
                    MK._refreshListingConfig()
                end
            end
            MK._refreshFruitSavedList = refreshFruitSavedList

            do
                local sp = false
                fruitSearchBox:GetPropertyChangedSignal("Text"):Connect(function()
                    if sp then return end
                    sp = true
                    task.defer(function()
                        sp = false
                        refreshFruitSavedList()
                    end)
                end)
            end

            local fruitModeItems = {
                { key = "FA", name = "A · KG Rule" },
                { key = "FB", name = "B · Price Rule" },
            }

            local refreshFruitModePanel

            local fruitModeRow = select(1, ui:CreateRowDropdown(bodyFruit, {
                label       = "Fruit Mode",
                placeholder = "Select Mode...",
                mode        = "single",
                getItems    = function() return fruitModeItems end,
                initial     = MK.fruitMode or "FA",
                onChanged   = function(_, picked)
                    local v = (type(picked) == "table" and picked.key) or picked
                    v = tostring(v or ""):upper()
                    if v ~= "FB" then v = "FA" end
                    if MK.fruitMode ~= v then
                        MK.fruitMode = v
                        autoSave()
                        task.defer(function()
                            if refreshFruitModePanel then
                                refreshFruitModePanel()
                            end
                        end)
                    end
                end,
            }))
            if fruitModeRow then
                fruitModeRow.LayoutOrder = 10
            end

            local fruitModeWrap = Instance.new("Frame")
            fruitModeWrap.Name = "FruitModeWrap"
            fruitModeWrap.BackgroundTransparency = 1
            fruitModeWrap.Size = UDim2.new(1, 0, 0, 0)
            fruitModeWrap.AutomaticSize = Enum.AutomaticSize.Y
            fruitModeWrap.LayoutOrder = 11
            fruitModeWrap.Parent = bodyFruit

            local fruitModeLayout = Instance.new("UIListLayout")
            fruitModeLayout.FillDirection = Enum.FillDirection.Vertical
            fruitModeLayout.SortOrder = Enum.SortOrder.LayoutOrder
            fruitModeLayout.Padding = UDim.new(0, 4)
            fruitModeLayout.Parent = fruitModeWrap

            local function clearFruitModeWrap()
                for _, ch in ipairs(fruitModeWrap:GetChildren()) do
                    if not ch:IsA("UIListLayout") then
                        ch:Destroy()
                    end
                end
            end

            local function showFruitModeA()
                local ddFruitApi
                local setKgFA
                local setPriceFA

                ddFruitApi = select(2, ui:CreateRowDropdown(fruitModeWrap, {
                    label       = "Select Fruit",
                    placeholder = "Select Fruit...",
                    mode        = "multi",
                    getItems    = function()
                        return buildFruitNameItems(MK.modeFA.selected) or {}
                    end,
                    initial     = MK.modeFA.selected,
                    onChanged   = function(_, selectedMap)
                        MK.modeFA.selected = cleanSelectedMap(selectedMap)
                        autoSave()
                    end,
                }))

                local _, setterKg = ui:CreateRowInput(fruitModeWrap, "KG (- = below)", tostring(MK.modeFA.kg or 0), function(text)
                    MK.modeFA.kg = parseFruitKgSigned(text)
                    autoSave()
                end)
                setKgFA = setterKg

                local _, setterPrice = ui:CreateRowInput(fruitModeWrap, "Price Token", tostring(MK.modeFA.price or 0), function(text)
                    local n = toNumFloat(text)
                    if not n or n < 0 then n = 0 end
                    MK.modeFA.price = n
                    autoSave()
                end)
                setPriceFA = setterPrice

                ui:CreateRowToggle(fruitModeWrap, "Apply Fruit Mode A", false, function(isOn)
                    if not isOn then return end

                    local kgSigned = parseFruitKgSigned(MK.modeFA.kg)
                    local price = tonumber(MK.modeFA.price) or 0
                    local picked = {}
                    for name, on in pairs(MK.modeFA.selected or {}) do
                        if on then table.insert(picked, tostring(name)) end
                    end
                    if #picked == 0 or price <= 0 then return end

                    local lines = {}
                    for _, name in ipairs(picked) do
                        lines[#lines + 1] = ("%s | %s | %s"):format(name, fruitKgSignedText(kgSigned), tostring(price))
                    end

                    ui:Confirm({
                        title = "ADD FRUIT KG RULE",
                        badge = "FA",
                        meta  = ("Items: %d"):format(#picked),
                        lines = lines,
                        onYes = function()
                            for _, fruitName in ipairs(picked) do
                                local ruleId = (FruitListView and FruitListView.makeRuleIdFA)
                                    and FruitListView.makeRuleIdFA(fruitName, kgSigned)
                                    or ("FA|%s|%s"):format(fruitName, tostring(kgSigned))
                                MK.fruitList[ruleId] = {
                                    mode      = "FA",
                                    fruitName = fruitName,
                                    kg        = kgSigned,
                                    price     = price,
                                    itemType  = "Holdable",
                                }
                            end

                            MK.modeFA.selected = {}
                            if ddFruitApi and ddFruitApi.setSelected then
                                ddFruitApi.setSelected({})
                                if ddFruitApi.refreshLabel then ddFruitApi.refreshLabel() end
                            end
                            MK.modeFA.kg = 0
                            MK.modeFA.price = 0
                            if setKgFA then setKgFA("0") end
                            if setPriceFA then setPriceFA("0") end

                            autoSave()
                            refreshFruitSavedList()
                        end,
                    })
                end, nil, { momentary = true })
            end

            local function showFruitModeB()
                local ddFruitApi
                local setNpcPriceFB
                local setPriceFB

                ddFruitApi = select(2, ui:CreateRowDropdown(fruitModeWrap, {
                    label       = "Select Fruit",
                    placeholder = "Select Fruit...",
                    mode        = "multi",
                    getItems    = function()
                        return buildFruitNameItems(MK.modeFB.selected) or {}
                    end,
                    initial     = MK.modeFB.selected,
                    onChanged   = function(_, selectedMap)
                        MK.modeFB.selected = cleanSelectedMap(selectedMap)
                        autoSave()
                    end,
                }))

                local _, setterNpcPrice = ui:CreateRowInput(fruitModeWrap, "NPC Price (- = below)", tostring(MK.modeFB.npcPrice or ""), function(text)
                    MK.modeFB.npcPrice = tostring(text or "")
                    autoSave()
                end)
                setNpcPriceFB = setterNpcPrice

                local _, setterPrice = ui:CreateRowInput(fruitModeWrap, "Price Token", tostring(MK.modeFB.price or ""), function(text)
                    MK.modeFB.price = tostring(text or "")
                    autoSave()
                end)
                setPriceFB = setterPrice

                ui:CreateRowToggle(fruitModeWrap, "Apply Fruit Mode B", false, function(isOn)
                    if not isOn then return end

                    local npcPriceSigned = parseFruitSignedNpcPrice(MK.modeFB.npcPrice)
                    local price = parseFruitCompactPrice(MK.modeFB.price)
                    local picked = {}
                    for name, on in pairs(MK.modeFB.selected or {}) do
                        if on then table.insert(picked, tostring(name)) end
                    end
                    if #picked == 0 or price <= 0 then return end

                    local lines = {}
                    for _, name in ipairs(picked) do
                        lines[#lines + 1] = ("%s | NPC %s | Token %s"):format(
                            name,
                            fruitNpcPriceSignedText(npcPriceSigned),
                            tostring(price)
                        )
                    end

                    ui:Confirm({
                        title = "ADD FRUIT PRICE RULE",
                        badge = "FB",
                        meta  = ("Items: %d"):format(#picked),
                        lines = lines,
                        onYes = function()
                            for _, fruitName in ipairs(picked) do
                                local ruleId = (FruitListView and FruitListView.makeRuleIdFB)
                                    and FruitListView.makeRuleIdFB(fruitName)
                                    or ("FB|%s"):format(fruitName)
                                MK.fruitList[ruleId] = {
                                    mode      = "FB",
                                    fruitName = fruitName,
                                    npcPrice  = npcPriceSigned,
                                    price     = price,
                                    itemType  = "Holdable",
                                }
                            end

                            MK.modeFB.selected = {}
                            if ddFruitApi and ddFruitApi.setSelected then
                                ddFruitApi.setSelected({})
                                if ddFruitApi.refreshLabel then ddFruitApi.refreshLabel() end
                            end
                            MK.modeFB.npcPrice = ""
                            MK.modeFB.price = ""
                            if setNpcPriceFB then setNpcPriceFB("") end
                            if setPriceFB then setPriceFB("") end

                            autoSave()
                            refreshFruitSavedList()
                        end,
                    })
                end, nil, { momentary = true })
            end

            refreshFruitModePanel = function()
                clearFruitModeWrap()
                if MK.fruitMode == "FB" then
                    showFruitModeB()
                else
                    showFruitModeA()
                end
                task.defer(function()
                    if ui.RelayoutContent then
                        ui:RelayoutContent()
                    end
                end)
            end

            refreshFruitModePanel()

            refreshFruitSavedList()

            ----------------------------------------------------------------
            -- LISTING BOOTH SKIN
            ----------------------------------------------------------------
            local bodySkin = createSection("Listing Booth Skin", false)

            local function buildBoothSkinItems()
                local items = {}
                local ok, reg = pcall(function()
                    return require(game:GetService("ReplicatedStorage").Data.TradeBoothSkinRegistry)
                end)
                if ok and type(reg) == "table" then
                    for key, v in pairs(reg) do
                        local id = tostring(key or "")
                        if id ~= "" and id ~= "Default" and type(v) == "table" then
                            items[#items + 1] = {
                                key = id,
                                name = tostring(v.DisplayName or id),
                            }
                        end
                    end
                end
                table.sort(items, function(a, b)
                    return tostring(a.name) < tostring(b.name)
                end)
                return items
            end

            local function boothSkinDisplayName(skinId)
                skinId = tostring(skinId or "")
                local ok, reg = pcall(function()
                    return require(game:GetService("ReplicatedStorage").Data.TradeBoothSkinRegistry)
                end)
                if ok and type(reg) == "table" and type(reg[skinId]) == "table" then
                    return tostring(reg[skinId].DisplayName or skinId)
                end
                return skinId
            end

            local skinListRow = Instance.new("Frame")
            skinListRow.Name = "SkinListRow"
            skinListRow.BackgroundTransparency = 1
            skinListRow.Size = UDim2.new(1, 0, 0, 0)
            skinListRow.AutomaticSize = Enum.AutomaticSize.Y
            skinListRow.LayoutOrder = 1
            skinListRow.Parent = bodySkin

            local skinRowLayout = Instance.new("UIListLayout")
            skinRowLayout.Parent = skinListRow
            skinRowLayout.FillDirection = Enum.FillDirection.Vertical
            skinRowLayout.SortOrder = Enum.SortOrder.LayoutOrder
            skinRowLayout.Padding = UDim.new(0, 8)

            local skinInfoWrap = Instance.new("Frame")
            skinInfoWrap.Name = "SkinInfoWrap"
            skinInfoWrap.Parent = skinListRow
            skinInfoWrap.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            skinInfoWrap.BorderSizePixel = 0
            skinInfoWrap.Size = UDim2.new(1, 0, 0, 0)
            skinInfoWrap.AutomaticSize = Enum.AutomaticSize.Y
            skinInfoWrap.LayoutOrder = 1
            mkCorner(skinInfoWrap, 6)
            mkStroke(skinInfoWrap, Color3.fromRGB(40, 40, 40), 1, 0.5)
            mkPad(skinInfoWrap, 8, 8, 8, 8)

            local skinInfoLbl = Instance.new("TextLabel")
            skinInfoLbl.Parent = skinInfoWrap
            skinInfoLbl.BackgroundTransparency = 1
            skinInfoLbl.Size = UDim2.new(1, 0, 0, 0)
            skinInfoLbl.AutomaticSize = Enum.AutomaticSize.Y
            skinInfoLbl.Font = Enum.Font.Gotham
            skinInfoLbl.TextSize = 11
            skinInfoLbl.TextXAlignment = Enum.TextXAlignment.Left
            skinInfoLbl.TextYAlignment = Enum.TextYAlignment.Top
            skinInfoLbl.TextWrapped = true
            skinInfoLbl.TextColor3 = Color3.fromRGB(235, 235, 235)
            skinInfoLbl.RichText = true
            skinInfoLbl.Text =
                '<font color="#7FD6FF"><b>PETUNJUK BOOTH SKIN</b></font>\n' ..
                '• Pilih <b>Booth Skin</b> yang owned (bukan Default / yang sedang dipakai).\n' ..
                '• Isi <b>Price Token</b> lalu toggle <b>Apply Skin Rule</b>.\n' ..
                '• Edit harga di list bawah. Price <b>0</b> = disable rule.'

            local skinSf = Instance.new("ScrollingFrame")
            skinSf.Name = "SkinSavedList"
            skinSf.Parent = skinListRow
            skinSf.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
            skinSf.BorderSizePixel = 0
            skinSf.LayoutOrder = 2
            skinSf.Size = UDim2.new(1, 0, 0, calcListHeight(0))
            skinSf.CanvasSize = UDim2.new(0, 0, 0, 0)
            skinSf.ScrollBarThickness = 0
            skinSf.ScrollBarImageTransparency = 1
            skinSf.ScrollingDirection = Enum.ScrollingDirection.Y
            skinSf.AutomaticCanvasSize = Enum.AutomaticSize.Y
            skinSf.ClipsDescendants = true
            mkCorner(skinSf, 6)
            mkStroke(skinSf, Color3.fromRGB(40, 40, 40), 1, 0.5)
            mkPad(skinSf, 4, 4, LIST_PAD_TOP, LIST_PAD_BOT)

            local skinLayout = Instance.new("UIListLayout")
            skinLayout.FillDirection = Enum.FillDirection.Vertical
            skinLayout.SortOrder = Enum.SortOrder.LayoutOrder
            skinLayout.Padding = UDim.new(0, ROW_PAD)
            skinLayout.Parent = skinSf

            local function clearSkinRows()
                for _, ch in ipairs(skinSf:GetChildren()) do
                    if ch:IsA("Frame") and ch.Name:sub(1, 5) == "Skin_" then
                        ch:Destroy()
                    end
                    if ch:IsA("TextLabel") and ch.Name == "SkinEmptyHint" then
                        ch:Destroy()
                    end
                end
            end

            local function deleteSkinKey(key)
                key = tostring(key or "")
                if key == "" then return end
                MK.skinList[key] = nil
                autoSave()
            end

            local function refreshSkinSavedList()
                clearSkinRows()

                local shown = 0
                local rows = {}
                for key, rec in pairs(MK.skinList or {}) do
                    if type(rec) == "table" then
                        local skinId = tostring(rec.skinId or key)
                        rows[#rows + 1] = {
                            key = key,
                            rec = rec,
                            title = ("[S] %s | %s"):format(boothSkinDisplayName(skinId), tostring(rec.price or 0)),
                        }
                    end
                end

                table.sort(rows, function(a, b)
                    local pa = tonumber(a.rec.price) or 0
                    local pb = tonumber(b.rec.price) or 0
                    if pa ~= pb then return pa < pb end
                    return tostring(a.title) < tostring(b.title)
                end)

                for i, row in ipairs(rows) do
                    shown += 1
                    local key = row.key
                    local rec = row.rec

                    local item = Instance.new("Frame")
                    item.Name = "Skin_" .. tostring(key)
                    item.BackgroundColor3 = Color3.fromRGB(22, 22, 22)
                    item.Size = UDim2.new(1, 0, 0, ROW_H)
                    item.LayoutOrder = i
                    item.Parent = skinSf
                    mkCorner(item, 4)

                    local ip = Instance.new("UIPadding")
                    ip.PaddingLeft = UDim.new(0, 6)
                    ip.PaddingRight = UDim.new(0, 6)
                    ip.Parent = item

                    local del = Instance.new("TextButton")
                    del.Name = "Del"
                    del.Parent = item
                    del.BackgroundColor3 = Color3.fromRGB(180, 50, 50)
                    del.Size = UDim2.new(0, 22, 0, 22)
                    del.Position = UDim2.new(1, -22, 0.5, -11)
                    del.AutoButtonColor = true
                    del.Font = Enum.Font.GothamBold
                    del.TextSize = 14
                    del.TextColor3 = Color3.fromRGB(255, 255, 255)
                    del.Text = "-"
                    del.BorderSizePixel = 0
                    mkCorner(del, 4)
                    mkStroke(del, Color3.fromRGB(40, 40, 40), 1, 0.6)
                    del.MouseButton1Click:Connect(function()
                        deleteSkinKey(key)
                        refreshSkinSavedList()
                    end)

                    local priceBoxW = 56
                    local priceBox = Instance.new("TextBox")
                    priceBox.Name = "Price"
                    priceBox.Parent = item
                    priceBox.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
                    priceBox.Size = UDim2.new(0, priceBoxW, 0, 22)
                    priceBox.Position = UDim2.new(1, -(22 + 6 + priceBoxW), 0.5, -11)
                    priceBox.Font = Enum.Font.Gotham
                    priceBox.TextSize = 11
                    priceBox.TextColor3 = Color3.fromRGB(235, 235, 235)
                    priceBox.Text = tostring(rec.price or 0)
                    priceBox.ClearTextOnFocus = false
                    mkCorner(priceBox, 4)
                    mkStroke(priceBox, Color3.fromRGB(40, 40, 40), 1, 0.6)

                    local nameLbl = Instance.new("TextLabel")
                    nameLbl.BackgroundTransparency = 1
                    nameLbl.Position = UDim2.new(0, 0, 0, 0)
                    nameLbl.Size = UDim2.new(1, -(22 + 6 + priceBoxW + 6), 1, 0)
                    nameLbl.Font = Enum.Font.Gotham
                    nameLbl.TextSize = 11
                    nameLbl.TextXAlignment = Enum.TextXAlignment.Left
                    nameLbl.TextColor3 = Color3.fromRGB(235, 235, 235)
                    nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
                    nameLbl.Text = tostring(row.title or key)
                    nameLbl.Parent = item

                    priceBox.FocusLost:Connect(function()
                        local n = toNumFloat(priceBox.Text)
                        if not n or n < 0 then n = 0 end
                        local k = tostring(key)
                        MK.skinList[k] = MK.skinList[k] or rec
                        MK.skinList[k].price = n
                        priceBox.Text = tostring(n)
                        autoSave()
                    end)
                end

                if shown == 0 then
                    local t = Instance.new("TextLabel")
                    t.Name = "SkinEmptyHint"
                    t.Parent = skinSf
                    t.BackgroundTransparency = 1
                    t.Size = UDim2.new(1, -10, 0, 40)
                    t.Position = UDim2.new(0, 5, 0, 0)
                    t.Font = Enum.Font.Gotham
                    t.TextSize = 12
                    t.TextXAlignment = Enum.TextXAlignment.Left
                    t.TextYAlignment = Enum.TextYAlignment.Top
                    t.TextColor3 = Color3.fromRGB(170, 170, 170)
                    t.RichText = true
                    t.TextWrapped = true
                    t.Text = '<font color="#7FD6FF"><b>Skin list kosong.</b></font>\n<b>Pilih booth skin lalu Apply Skin Rule.</b>'
                end

                local baseH = calcListHeight(shown)
                skinSf.Size = UDim2.new(1, 0, 0, baseH)

                if shown > VISIBLE_ROWS then
                    skinSf.ScrollBarThickness = 6
                    skinSf.ScrollBarImageTransparency = 0
                else
                    skinSf.ScrollBarThickness = 0
                    skinSf.ScrollBarImageTransparency = 1
                    skinSf.CanvasPosition = Vector2.new(0, 0)
                end
                if type(MK._refreshListingConfig) == "function" then
                    MK._refreshListingConfig()
                end
            end
            MK._refreshSkinSavedList = refreshSkinSavedList

            local ddSkinApi
            local setPriceS

            ddSkinApi = select(2, ui:CreateRowDropdown(bodySkin, {
                label       = "Select Booth Skin",
                placeholder = "Select Skin...",
                mode        = "multi",
                getItems    = function()
                    return buildBoothSkinItems()
                end,
                initial     = MK.modeS.selected,
                onChanged   = function(_, selectedMap)
                    MK.modeS.selected = cleanSelectedMap(selectedMap)
                    autoSave()
                end,
            }))

            local _, setterPriceS = ui:CreateRowInput(bodySkin, "Price Token", tostring(MK.modeS.price or 0), function(text)
                local n = toNumFloat(text)
                if not n or n < 0 then n = 0 end
                MK.modeS.price = n
                autoSave()
            end)
            setPriceS = setterPriceS

            ui:CreateRowToggle(bodySkin, "Apply Skin Rule", false, function(isOn)
                if not isOn then return end

                local price = tonumber(MK.modeS.price) or 0
                local picked = {}
                for skinId, on in pairs(MK.modeS.selected or {}) do
                    if on then table.insert(picked, tostring(skinId)) end
                end
                if #picked == 0 or price <= 0 then return end

                local lines = {}
                for _, skinId in ipairs(picked) do
                    lines[#lines + 1] = ("%s | %s"):format(skinId, tostring(price))
                end

                ui:Confirm({
                    title = "ADD BOOTH SKIN RULE",
                    badge = "S",
                    meta  = ("Items: %d"):format(#picked),
                    lines = lines,
                    onYes = function()
                        for _, skinId in ipairs(picked) do
                            MK.skinList[skinId] = {
                                mode     = "S",
                                skinId   = skinId,
                                price    = price,
                                itemType = "TradeBoothSkin",
                            }
                        end

                        MK.modeS.selected = {}
                        if ddSkinApi and ddSkinApi.setSelected then
                            ddSkinApi.setSelected({})
                            if ddSkinApi.refreshLabel then ddSkinApi.refreshLabel() end
                        end
                        MK.modeS.price = 0
                        if setPriceS then setPriceS("0") end

                        autoSave()
                        refreshSkinSavedList()
                    end,
                })
            end, nil, { momentary = true })

            refreshSkinSavedList()

            ----------------------------------------------------------------
            -- CONFIG LISTING (Pet / Fruit / Booth) — tidak mengubah section apply
            ----------------------------------------------------------------
            local bodyCfg = createSection("Config Listing", false)

            local function clampCfgSlots(n, fallback)
                n = math.floor(tonumber(n) or fallback or 0)
                if n < 0 then n = 0 end
                if n > 50 then n = 50 end
                return n
            end

            local function ensureCfgCat(cat, defaultMax)
                MK.listingConfig = (type(MK.listingConfig) == "table") and MK.listingConfig or {}
                local rec = MK.listingConfig[cat]
                if type(rec) ~= "table" then
                    rec = {}
                    MK.listingConfig[cat] = rec
                end
                rec.maxSlots = clampCfgSlots(rec.maxSlots, defaultMax)
                rec.perType = (type(rec.perType) == "table") and rec.perType or {}
                return rec
            end

            local cfgPet = ensureCfgCat("pet", 0)
            MK.listingPetConfig = cfgPet
            MK.listingConfig.enabled = (MK.listingConfig.enabled == true)

            local function trimTypeName(s)
                return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "")
            end

            local function detectPetTypes()
                local bagType = {}
                if PetListView and type(PetListView.listPetsAll) == "function" then
                    local ok, list = pcall(PetListView.listPetsAll)
                    if ok and type(list) == "table" then
                        for _, p in ipairs(list) do
                            if p and p.uuid then
                                bagType[tostring(p.uuid)] = p.ptype or p.ptypeLabel
                            end
                        end
                    end
                end
                local types = {}
                for k, rec in pairs(MK.list or {}) do
                    if type(rec) == "table" then
                        local mode = tostring(rec.mode or "A"):upper()
                        local pt
                        if mode == "B" then
                            pt = rec.petType
                        else
                            pt = rec.petType or rec.ptype or bagType[tostring(k)]
                        end
                        pt = trimTypeName(pt)
                        if pt ~= "" then
                            types[pt] = pt
                        end
                    end
                end
                local list = {}
                for key, label in pairs(types) do
                    list[#list + 1] = { key = key, label = label }
                end
                table.sort(list, function(a, b)
                    return tostring(a.label):lower() < tostring(b.label):lower()
                end)
                return list
            end

            local function detectFruitTypes()
                local bag = {}
                if FruitListView and type(FruitListView.listFruitsAll) == "function" then
                    local ok, list = pcall(FruitListView.listFruitsAll)
                    if ok and type(list) == "table" then
                        for _, f in ipairs(list) do
                            if type(f) == "table" then
                                local id = f.uuid or f.listingId
                                if id then
                                    bag[tostring(id)] = f.niceName or f.fruitName
                                end
                            end
                        end
                    end
                end
                local types = {}
                for k, rec in pairs(MK.fruitList or {}) do
                    if type(rec) == "table" then
                        local fn = trimTypeName(rec.fruitName)
                        if fn == "" then
                            fn = trimTypeName(bag[tostring(k)])
                        end
                        if fn ~= "" then
                            types[fn] = fn
                        end
                    end
                end
                local list = {}
                for key, label in pairs(types) do
                    list[#list + 1] = { key = key, label = label }
                end
                table.sort(list, function(a, b)
                    return tostring(a.label):lower() < tostring(b.label):lower()
                end)
                return list
            end

            local function detectBoothTypes()
                local types = {}
                for k, rec in pairs(MK.skinList or {}) do
                    if type(rec) == "table" then
                        local sid = trimTypeName(rec.skinId or k)
                        if sid ~= "" then
                            local label = sid
                            if type(boothSkinDisplayName) == "function" then
                                label = boothSkinDisplayName(sid)
                            end
                            types[sid] = label
                        end
                    end
                end
                local list = {}
                for key, label in pairs(types) do
                    list[#list + 1] = { key = key, label = label }
                end
                table.sort(list, function(a, b)
                    return tostring(a.label):lower() < tostring(b.label):lower()
                end)
                return list
            end

            local function typeSlotOf(cfg, key)
                local per = cfg.perType
                if type(per) ~= "table" then return 0 end
                if per[key] ~= nil then
                    return clampCfgSlots(per[key], 0)
                end
                local want = tostring(key or ""):lower()
                for k, v in pairs(per) do
                    if tostring(k):lower() == want then
                        return clampCfgSlots(v, 0)
                    end
                end
                return 0
            end

            local function cfgGroupHeader(title, desc)
                local row, t, d = ui:CreateRowLabel(bodyCfg, title, desc)
                if t then
                    t.Font = Enum.Font.GothamBold
                    t.TextColor3 = Color3.fromRGB(255, 220, 90)
                end
                if d then
                    -- deskripsi bawaan cuma 1 baris; wrap supaya tidak terpotong di layar kecil
                    d.TextColor3 = Color3.fromRGB(170, 170, 170)
                    d.TextWrapped = true
                    d.TextYAlignment = Enum.TextYAlignment.Top
                    d.Size = UDim2.new(1, 0, 0, 0)
                    d.AutomaticSize = Enum.AutomaticSize.Y
                    if row then
                        row.Size = UDim2.new(1, 0, 0, 0)
                        row.AutomaticSize = Enum.AutomaticSize.Y
                        local pad = Instance.new("UIPadding")
                        pad.PaddingTop = UDim.new(0, 6)
                        pad.PaddingBottom = UDim.new(0, 4)
                        pad.Parent = row
                    end
                end
            end

            local function cfgSubHeader(title)
                local _, t = ui:CreateRowLabel(bodyCfg, title)
                if t then
                    t.Font = Enum.Font.GothamBold
                    t.TextColor3 = Color3.fromRGB(235, 235, 235)
                end
            end

            -- ① Skin booth (dipasang setelah claim)
            do
                local CLAIM_SKIN_NONE = "__none"
                if type(MK.listingConfig.claimSkin) ~= "string" then
                    MK.listingConfig.claimSkin = ""
                end

                local function buildClaimSkinItems()
                    local items = {
                        { key = CLAIM_SKIN_NONE, name = "(Tidak ganti)" },
                        { key = "Default", name = "Default" },
                    }
                    local owned = nil
                    pcall(function()
                        local DS = require(game:GetService("ReplicatedStorage").Modules.DataService)
                        local d = DS:GetData()
                        owned = d and d.TradeBoothSkinData and d.TradeBoothSkinData.OwnedSkins
                    end)
                    local skins = {}
                    if type(owned) == "table" then
                        for id, v in pairs(owned) do
                            local n = (type(v) == "boolean") and (v and 1 or 0) or (tonumber(v) or 0)
                            id = tostring(id)
                            if n > 0 and id ~= "Default" then
                                skins[#skins + 1] = {
                                    key = id,
                                    name = string.format("%s (x%d)", boothSkinDisplayName(id), n),
                                }
                            end
                        end
                    end
                    table.sort(skins, function(a, b)
                        return tostring(a.name):lower() < tostring(b.name):lower()
                    end)
                    for _, it in ipairs(skins) do
                        items[#items + 1] = it
                    end
                    return items
                end

                cfgGroupHeader(
                    "Skin Booth",
                    "Dipasang otomatis setelah claim booth (Auto Market harus jalan)"
                )

                ui:CreateRowDropdown(bodyCfg, {
                    label       = "Skin Saat Claim",
                    placeholder = "(Tidak ganti)",
                    mode        = "single",
                    getItems    = buildClaimSkinItems,
                    initial     = (MK.listingConfig.claimSkin ~= "") and MK.listingConfig.claimSkin or CLAIM_SKIN_NONE,
                    onChanged   = function(_, picked)
                        local v = tostring((type(picked) == "table" and picked.key) or picked or "")
                        if v == CLAIM_SKIN_NONE then v = "" end
                        MK.listingConfig.claimSkin = v
                        autoSave()
                    end,
                })
            end

            -- ② Batas slot listing
            cfgGroupHeader(
                "Batas Slot Listing",
                "Batasi jumlah slot booth per kategori & per type. 0 = tanpa batas. Urutan isi: Pet → Fruit → Skin"
            )

            ui:CreateRowToggle(
                bodyCfg,
                "Aktifkan Batas Slot",
                MK.listingConfig.enabled == true,
                function(on)
                    MK.listingConfig.enabled = (on == true)
                    autoSave()
                end
            )

            local function renderCat(title, maxLabel, catKey, defaultMax, detect, emptyText)
                local cfg = ensureCfgCat(catKey, defaultMax)
                cfgSubHeader(title)
                ui:CreateRowInput(bodyCfg, maxLabel, tostring(cfg.maxSlots or 0), function(text)
                    ensureCfgCat(catKey, defaultMax).maxSlots = clampCfgSlots(text, 0)
                    autoSave()
                end, false)

                local typeList = detect()
                if #typeList == 0 then
                    ui:CreateRowLabel(bodyCfg, "   " .. emptyText)
                    return
                end
                for _, t in ipairs(typeList) do
                    local typeKey = t.key
                    ui:CreateRowInput(
                        bodyCfg,
                        "   • " .. tostring(t.label),
                        tostring(typeSlotOf(cfg, typeKey)),
                        function(text)
                            local rec = ensureCfgCat(catKey, defaultMax)
                            rec.perType[typeKey] = clampCfgSlots(text, 0)
                            autoSave()
                        end,
                        false
                    )
                end
            end

            renderCat("Pet", "Max Total Pet", "pet", 0, detectPetTypes, "Belum ada pet di Listing Pet")
            renderCat("Fruit", "Max Total Fruit", "fruit", 0, detectFruitTypes, "Belum ada fruit di Listing Fruit")
            renderCat("Booth Skin", "Max Total Skin", "booth", 0, detectBoothTypes, "Belum ada skin di Listing Booth Skin")

            MK._refreshListingConfig = function() end
            MK._refreshListingPetConfig = function() end
        end

        render()

            if #sectionSetters >= 1 then
        for i = 1, #sectionSetters do sectionSetters[i](false) end
    end
    end, 1)
    
    ui:RegisterSubTab("auto_market", "list", "MyBooth", function()
    ui:ClearSubContent()

    ----------------------------------------------------------------
    -- list setter section buat open/close
    ----------------------------------------------------------------
    local sectionSetters = {}
    local function createSection(title, defaultOpen)
        local body, setExpanded = ui:CreateSection(title, defaultOpen or false)
        local setter
        setter = function(on)
            if on and #sectionSetters >= 3 then
                for _, fn in ipairs(sectionSetters) do
                    if fn ~= setter then
                        fn(false)
                    end
                end
            end
            setExpanded(on)
            task.defer(function()
                if ui.RelayoutContent then
                    ui:RelayoutContent()
                end
            end)
        end
        table.insert(sectionSetters, setter)
        return body
    end

    ----------------------------------------------------------------
    -- helpers (mirip listing)
    ----------------------------------------------------------------
    local function mkCorner(p, r)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, r or 6)
        c.Parent = p
    end

    local function mkStroke(p, col, th, tr)
        local s = Instance.new("UIStroke")
        s.Color = col or Color3.fromRGB(40,40,40)
        s.Thickness = th or 1
        s.Transparency = tr or 0.5
        s.Parent = p
    end

    local function mkPad(p, l, r, t, b)
        local pad = Instance.new("UIPadding")
        pad.PaddingTop    = UDim.new(0, t or 4)
        pad.PaddingBottom = UDim.new(0, b or 4)
        pad.PaddingLeft   = UDim.new(0, l or 4)
        pad.PaddingRight  = UDim.new(0, r or 4)
        pad.Parent = p
    end

    local function norm(s)
        s = tostring(s or ""):lower()
        s = s:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
        return s
    end

    local function fmt1(n)
        n = tonumber(n)
        if not n then return "" end
        if n % 1 == 0 then return tostring(math.floor(n)) end
        return tostring(n)
    end

    local function parseKgBox(text)
        local s = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then return nil end
        local n = toNumFloat(s)
        if n == nil then return nil end
        return round1(n)
    end

    ----------------------------------------------------------------
    -- Get MK
    ----------------------------------------------------------------
    local MK = (STATE and STATE.main and STATE.main.auto_market) or (rawget(_G,"STATE") and _G.STATE.main and _G.STATE.main.auto_market)
    if type(MK) ~= "table" then
        MK = {}
        STATE.main = STATE.main or {}
        STATE.main.auto_market = MK
    end
    MK.list  = (type(MK.list) == "table") and MK.list or {}

    ----------------------------------------------------------------
    -- label maps (biar UUID tampil nama)
    ----------------------------------------------------------------
    local function buildNotFavItems()
        if PetListView and type(PetListView.buildEntriesNotFav) == "function" then
            return PetListView.buildEntriesNotFav(MK.list) or {}
        end
        if PetListView and type(PetListView.listPetsNotFav) == "function" then
            local raw = PetListView.listPetsNotFav() or {}
            local items = {}
            for _, p in ipairs(raw) do
                items[#items+1] = { key = p.uuid, name = p.name or (p.ptype or p.uuid) }
            end
            return items
        end
        return {}
    end

    local function buildPetTypeItems()
        if PetListView and type(PetListView.buildPetItems) == "function" then
            return PetListView.buildPetItems() or {}
        end
        return {}
    end

    local function buildLabelMapFromItems(items)
        local m = {}
        for _, it in ipairs(items or {}) do
            if it and it.key then
                m[tostring(it.key)] = tostring(it.name or it.key)
            end
        end
        return m
    end

    local notFavLabel = buildLabelMapFromItems(buildNotFavItems())
    local petTypeLabel= buildLabelMapFromItems(buildPetTypeItems())

    local function getLabelForKey(labelMap, key)
        key = tostring(key)
        return tostring(labelMap and labelMap[key] or key)
    end

    ----------------------------------------------------------------
    -- Common Row Builders
    ----------------------------------------------------------------
    local ROW_H = 26
    local ROW_PAD = 4
    local VISIBLE_ROWS = 6
    local LIST_PAD_TOP = 8
    local LIST_PAD_BOT = 8

    local function calcListHeight(count)
        local rows = math.min(count or 0, VISIBLE_ROWS)
        if rows <= 0 then rows = 1 end
        return (rows * ROW_H) + ((rows - 1) * ROW_PAD) + LIST_PAD_TOP + LIST_PAD_BOT
    end

    local function makeMiniLabel(txt, w)
        local lb = Instance.new("TextLabel")
        lb.BackgroundTransparency = 1
        lb.Size = UDim2.new(0, w or 34, 1, 0)
        lb.Font = Enum.Font.Gotham
        lb.TextSize = 11
        lb.TextColor3 = Color3.fromRGB(190,190,190)
        lb.TextXAlignment = Enum.TextXAlignment.Left
        lb.Text = tostring(txt or "")
        return lb
    end

    local function makeMiniBox(w, text, placeholder)
        local box = Instance.new("TextBox")
        box.BackgroundColor3 = Color3.fromRGB(18,18,18)
        box.BorderSizePixel = 0
        box.Size = UDim2.new(0, w, 0, 22)
        box.Font = Enum.Font.Gotham
        box.TextSize = 12
        box.TextColor3 = Color3.fromRGB(235,235,235)
        box.PlaceholderColor3 = Color3.fromRGB(140,140,140)
        box.PlaceholderText = placeholder or ""
        box.ClearTextOnFocus = false
        box.TextXAlignment = Enum.TextXAlignment.Center
        box.Text = tostring(text or "")
        mkCorner(box, 4)
        mkStroke(box, Color3.fromRGB(40,40,40), 1, 0.6)
        return box
    end

    local function makeDeleteBtn(parent, onClick)
        local del = Instance.new("TextButton")
        del.Name = "BtnDelete"
        del.Parent = parent
        del.BackgroundColor3 = Color3.fromRGB(160, 40, 40)
        del.Size = UDim2.new(0, 22, 0, 22)
        del.Position = UDim2.new(1, -22, 0.5, -11)
        del.AutoButtonColor = true
        del.Font = Enum.Font.GothamBold
        del.TextSize = 14
        del.TextColor3 = Color3.fromRGB(255,255,255)
        del.Text = "-"
        del.BorderSizePixel = 0
        mkCorner(del, 4)
        mkStroke(del, Color3.fromRGB(40,40,40), 1, 0.6)
        del.MouseButton1Click:Connect(function()
            if onClick then onClick() end
        end)
        return del
    end

    local function clearRows(sf)
        for _, ch in ipairs(sf:GetChildren()) do
            if ch:IsA("Frame") and ch.Name:sub(1,5) == "Item_" then
                ch:Destroy()
            end
            if ch:IsA("TextLabel") and ch.Name == "EmptyHint" then
                ch:Destroy()
            end
        end
    end

    local function deleteKey(key)
        key = tostring(key or "")
        if key == "" then return end
        MK.list[key] = nil
        autoSave()
    end

    ----------------------------------------------------------------
    -- Section Builder: Editable List (Mode A / Mode B)
    ----------------------------------------------------------------
    local function buildEditableSection(body, modeWanted, titleHint)
        -- search bar
        local searchWrap = Instance.new("Frame")
        searchWrap.Name = "SearchWrap"
        searchWrap.Parent = body
        searchWrap.BackgroundColor3 = Color3.fromRGB(22,22,22)
        searchWrap.BorderSizePixel = 0
        searchWrap.Size = UDim2.new(1, 0, 0, 26)
        mkCorner(searchWrap, 4)
        mkStroke(searchWrap, Color3.fromRGB(40,40,40), 1, 0.5)
        mkPad(searchWrap, 6, 6, 0, 0)

        local searchBox = Instance.new("TextBox")
        searchBox.Name = "Search"
        searchBox.Parent = searchWrap
        searchBox.BackgroundTransparency = 1
        searchBox.Size = UDim2.new(1, 0, 1, 0)
        searchBox.Font = Enum.Font.Gotham
        searchBox.TextSize = 12
        searchBox.TextColor3 = Color3.fromRGB(235,235,235)
        searchBox.TextXAlignment = Enum.TextXAlignment.Center
        searchBox.ClearTextOnFocus = false
        searchBox.Text = ""

        local hint = Instance.new("TextLabel")
        hint.Name = "Hint"
        hint.Parent = searchWrap
        hint.BackgroundTransparency = 1
        hint.Size = UDim2.new(1, 0, 1, 0)
        hint.Font = Enum.Font.Gotham
        hint.TextSize = 12
        hint.TextColor3 = Color3.fromRGB(150,150,150)
        hint.TextXAlignment = Enum.TextXAlignment.Center
        hint.Text = titleHint or "Search"
        hint.ZIndex = searchBox.ZIndex + 1

        local function updateHint()
            local txt = tostring(searchBox.Text or ""):gsub("%s+", "")
            hint.Visible = (txt == "") and (not searchBox:IsFocused())
        end
        updateHint()
        searchBox.Focused:Connect(updateHint)
        searchBox.FocusLost:Connect(function()
            local t = tostring(searchBox.Text or "")
            t = t:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
            searchBox.Text = t
            updateHint()
        end)

        -- list frame
        local sf = Instance.new("ScrollingFrame")
        sf.Name = "SavedList"
        sf.Parent = body
        sf.BackgroundColor3 = Color3.fromRGB(15,15,15)
        sf.BorderSizePixel = 0
        sf.Size = UDim2.new(1, 0, 0, calcListHeight(0))
        sf.CanvasSize = UDim2.new(0, 0, 0, 0)
        sf.ScrollBarThickness = 0
        sf.ScrollBarImageTransparency = 1
        sf.ScrollingDirection = Enum.ScrollingDirection.Y
        sf.AutomaticCanvasSize = Enum.AutomaticSize.Y
        sf.ClipsDescendants = true
        mkCorner(sf, 6)
        mkStroke(sf, Color3.fromRGB(40,40,40), 1, 0.5)
        mkPad(sf, 4, 4, LIST_PAD_TOP, LIST_PAD_BOT)

        local layout = Instance.new("UIListLayout")
        layout.FillDirection = Enum.FillDirection.Vertical
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Padding = UDim.new(0, ROW_PAD)
        layout.Parent = sf

        local function buildRow(i, key, rec, titleText)
            local item = Instance.new("Frame")
            item.Name = "Item_" .. tostring(key)
            item.BackgroundColor3 = Color3.fromRGB(22,22,22)
            local rowH = (modeWanted == "B") and 28 or ROW_H
            item.Size = UDim2.new(1, 0, 0, rowH)
            item.LayoutOrder = i
            item.Parent = sf
            mkCorner(item, 4)

            local ip = Instance.new("UIPadding")
            ip.PaddingLeft = UDim.new(0, 6)
            ip.PaddingRight = UDim.new(0, 6)
            ip.Parent = item

            makeDeleteBtn(item, function()
                deleteKey(key)
                if MK._refreshListTab then MK._refreshListTab() end
            end)

            local xRight = 22
            local gap = 6
            local priceBox

            if modeWanted == "B" then
                xRight = attachModeBListRowControls({
                    item = item,
                    rec = rec,
                    key = key,
                    xRight = xRight,
                    makeMiniBox = makeMiniBox,
                })
            else
                local priceBoxW = 56
                priceBox = makeMiniBox(priceBoxW, rec.price or 0, "price")
            priceBox.Parent = item
            priceBox.Position = UDim2.new(1, -(xRight + priceBoxW), 0.5, -11)
                xRight = xRight + priceBoxW + gap
            end

            local nameLbl = Instance.new("TextLabel")
            nameLbl.BackgroundTransparency = 1
            nameLbl.Position = UDim2.new(0, 0, 0, 0)
            nameLbl.Size = UDim2.new(1, -(xRight + gap), 1, 0)
            nameLbl.Font = Enum.Font.Gotham
            nameLbl.TextSize = 11
            nameLbl.TextXAlignment = Enum.TextXAlignment.Left
            nameLbl.TextColor3 = Color3.fromRGB(235,235,235)
            nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
            nameLbl.Text = tostring(titleText or key)
            nameLbl.Parent = item

            if modeWanted ~= "B" and priceBox then
            priceBox.FocusLost:Connect(function()
                local n = toNumFloat(priceBox.Text)
                if not n or n < 0 then n = 0 end
                MK.list[tostring(key)] = MK.list[tostring(key)] or rec
                MK.list[tostring(key)].price = n
                priceBox.Text = tostring(n)
                autoSave()
            end)
            end
        end

        local function refresh()
            if modeWanted == "B" then normalizeModeBListAges() end
            clearRows(sf)
            updateHint()

            local q = norm(searchBox.Text)
            local shown = 0

            local notFavByUuid = buildNotFavUuidMap()
            local rows = {}

            for key, rec in pairs(MK.list or {}) do
                if type(rec) == "table" then
                    local mode = tostring(rec.mode or "A"):upper()
                    if modeWanted == mode then
                        local title
                        if modeWanted == "A" then
                            title = notFavLabel[tostring(key)] or ("UUID: " .. tostring(key))
                        else
                            local pt = tostring(rec.petType or "")
                            local nm = titleCaseWords(petTypeLabel[pt] or pt)
                            local rmin = tonumber(rec.minKg) or 0
                            local rmax = rec.maxKg ~= nil and tonumber(rec.maxKg) or nil
                            title = ("%s | %s | %s | %s"):format(
                                nm, mutLabel(rec.mutation), kgRangeText(rmin, rmax), ageRangeText(rec.minAge, rec.maxAge))
                        end

                        if q == "" or norm(title):find(q, 1, true) then
                            rows[#rows + 1] = { key = key, rec = rec, title = title }
                        end
                    end
                end
            end

            sortMkListRows(rows, notFavByUuid, modeWanted)
            for i, row in ipairs(rows) do
                shown += 1
                buildRow(shown, row.key, row.rec, row.title)
            end

            if shown == 0 then
                local t = Instance.new("TextLabel")
                t.Name = "EmptyHint"
                t.Parent = sf
                t.BackgroundTransparency = 1
                t.Size = UDim2.new(1, -10, 0, 40)
                t.Position = UDim2.new(0, 5, 0, 0)
                t.Font = Enum.Font.Gotham
                t.TextSize = 12
                t.TextXAlignment = Enum.TextXAlignment.Left
                t.TextYAlignment = Enum.TextYAlignment.Top
                t.TextColor3 = Color3.fromRGB(170,170,170)
                t.RichText = true
                t.TextWrapped = true
                t.Text = (q ~= "")
                    and '<font color="#FFD76A"><b>Tidak ditemukan.</b></font>\n<b>Hapus kata pencarian.</b>'
                    or  '<font color="#FFD76A"><b>Kosong.</b></font>\n<b>Belum ada item untuk mode ini.</b>'
            end

            local baseH = calcListHeight(shown)
            if shown == 0 then baseH = math.max(baseH, 44) end
            sf.Size = UDim2.new(1, 0, 0, baseH)

            if shown > VISIBLE_ROWS then
                sf.ScrollBarThickness = 6
                sf.ScrollBarImageTransparency = 0
            else
                sf.ScrollBarThickness = 0
                sf.ScrollBarImageTransparency = 1
                sf.CanvasPosition = Vector2.new(0, 0)
            end

            task.defer(function()
                if ui.RelayoutContent then
                    ui:RelayoutContent()
                end
            end)
        end

        -- refresh on type
        local sp = false
        searchBox:GetPropertyChangedSignal("Text"):Connect(function()
            updateHint()
            if sp then return end
            sp = true
            task.defer(function()
                sp = false
                refresh()
            end)
        end)

        return refresh
    end

    ----------------------------------------------------------------
    -- Section Builder: Read-only Booth List
    ----------------------------------------------------------------
    local function buildReadOnlyBoothSection(body)
        local sf = Instance.new("ScrollingFrame")
        sf.Name = "BoothReadOnly"
        sf.Parent = body
        sf.BackgroundColor3 = Color3.fromRGB(15,15,15)
        sf.BorderSizePixel = 0
        sf.Size = UDim2.new(1, 0, 0, calcListHeight(0))
        sf.CanvasSize = UDim2.new(0, 0, 0, 0)
        sf.ScrollBarThickness = 0
        sf.ScrollBarImageTransparency = 1
        sf.ScrollingDirection = Enum.ScrollingDirection.Y
        sf.AutomaticCanvasSize = Enum.AutomaticSize.Y
        sf.ClipsDescendants = true
        mkCorner(sf, 6)
        mkStroke(sf, Color3.fromRGB(40,40,40), 1, 0.5)
        mkPad(sf, 8, 8, LIST_PAD_TOP, LIST_PAD_BOT)

        local layout = Instance.new("UIListLayout")
        layout.FillDirection = Enum.FillDirection.Vertical
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Padding = UDim.new(0, ROW_PAD)
        layout.Parent = sf

        local function clear()
            for _, ch in ipairs(sf:GetChildren()) do
                if ch:IsA("Frame") and ch.Name:sub(1,5) == "Item_" then
                    ch:Destroy()
                end
                if ch:IsA("TextLabel") and ch.Name == "EmptyHint" then
                    ch:Destroy()
                end
            end
        end

        local function addRow(i, txt)
            local item = Instance.new("Frame")
            item.Name = "Item_" .. tostring(i)
            item.BackgroundColor3 = Color3.fromRGB(22,22,22)
            item.Size = UDim2.new(1, 0, 0, ROW_H)
            item.LayoutOrder = i
            item.Parent = sf
            mkCorner(item, 4)
            mkPad(item, 6, 6, 2, 2)

            local label = Instance.new("TextLabel")
            label.BackgroundTransparency = 1
            label.Size = UDim2.new(1, 0, 1, 0)
            label.Font = Enum.Font.Gotham
            label.TextSize = 12
            label.TextXAlignment = Enum.TextXAlignment.Left
            label.TextColor3 = Color3.fromRGB(235,235,235)
            label.TextTruncate = Enum.TextTruncate.AtEnd
            label.Text = tostring(txt or "")
            label.Parent = item
        end

        local function refresh()
    clear()

    local function fmt2(n)
        n = tonumber(n)
        if not n then return "?" end
        return string.format("%.2f", n)
    end

    local function fmtAge(a)
        a = tonumber(a)
        if not a or a <= 0 then return "?" end
        return tostring(math.floor(a + 0.0001))
    end

    local function mutPrefix(muts)
        if type(muts) ~= "table" or #muts == 0 then return "" end
        return "[" .. table.concat(muts, ", ") .. "] "
    end

    local function skinDisplayName(skinId)
        skinId = tostring(skinId or "")
        local ok, reg = pcall(function()
            return require(game:GetService("ReplicatedStorage").Data.TradeBoothSkinRegistry)
        end)
        if ok and type(reg) == "table" and type(reg[skinId]) == "table" then
            return tostring(reg[skinId].DisplayName or skinId)
        end
        return skinId ~= "" and skinId or "Booth Skin"
    end

    -- lookup uuid -> pet bag (optional, buat age/kg)
    local bagByUuid = {}
    if PetListView and type(PetListView.listPetsNotFav) == "function" then
        local raw = PetListView.listPetsNotFav() or {}
        for _, p in ipairs(raw) do
            if p and p.uuid then
                bagByUuid[tostring(p.uuid)] = p
            end
        end
    end

    local rows = {}
    local seen = {}

    local function pushRow(label, price, age, kg, uuid)
        local key = tostring(uuid or label)
        if seen[key] then return end
        seen[key] = true
        rows[#rows + 1] = {
            label = label,
            price = tonumber(price) or 0,
            age = tonumber(age) or 0,
            kg = tonumber(kg) or 0,
            uuid = tostring(uuid or ""),
        }
    end

    -- 1) PET listings
    local petListed = {}
    if PetListView and type(PetListView.listPetsListedBooth) == "function" then
        petListed = PetListView.listPetsListedBooth() or {}
    end
    for _, it in ipairs(petListed) do
        local uuid = it and it.uuid and tostring(it.uuid) or ""
        local price = tonumber(it and it.price) or 0
        local boothType = tostring(it and (it.ptype or it.petType or it.itemName or "Pet") or "Pet")
        local boothMuts = it and it.muts
        local bag = (uuid ~= "" and bagByUuid[uuid]) or nil
        local age = bag and bag.age
        local kg  = bag and bag.kg
        local muts = (type(boothMuts) == "table" and #boothMuts > 0) and boothMuts
            or (bag and bag.muts)
            or {}
        local name = (bag and (bag.ptypeLabel or bag.ptypeName)) and tostring(bag.ptypeLabel or bag.ptypeName) or boothType
        local label = string.format(
            "[PET] %s%s | Age %s | %s KG | Price %s",
            mutPrefix(muts),
            name,
            fmtAge(age),
            fmt2(kg),
            tostring(price)
        )
        pushRow(label, price, age, kg, uuid)
    end

    -- 2) FRUIT / Holdable listings
    local fruitListed = {}
    if FruitListView and type(FruitListView.listFruitsListedBooth) == "function" then
        fruitListed = FruitListView.listFruitsListedBooth() or {}
    end
    for _, it in ipairs(fruitListed) do
        local uuid = it and (it.uuid or it.key) and tostring(it.uuid or it.key) or ""
        local price = tonumber(it and it.price) or 0
        local name = tostring(it and (it.name or it.fruitName or "Fruit") or "Fruit")
        -- name dari fruit_list_view sudah ada "Price X"; rapikan
        name = name:gsub("%s*|%s*Price%s*%d+.*$", "")
        local label = string.format("[FRUIT] %s | Price %s", name, tostring(price))
        pushRow(label, price, 0, 0, uuid)
    end

    -- 3) BOOTH SKIN listings (langsung dari booth data)
    do
        local ok, listedSkins = pcall(function()
            local RS = game:GetService("ReplicatedStorage")
            local RepRecv = require(RS.Modules.ReplicationReciever)
            local TradeBoothsData = require(RS.Data.TradeBoothsData)
            local Booths = RepRecv.new("Booths")
            local data = Booths:GetDataAsync()
            if type(data) ~= "table" then return {} end
            local LP = game:GetService("Players").LocalPlayer
            local myId = TradeBoothsData.getPlayerId(LP)
            local p = data.Players and data.Players[myId]
            if not (p and p.Booth) then return {} end
            local booth = data.Booths and data.Booths[p.Booth]
            if not (booth and booth.Owner) then return {} end
            local ownerData = data.Players and data.Players[booth.Owner]
            if not (ownerData and type(ownerData.Listings) == "table") then return {} end

            local out = {}
            for listingUUID, listing in pairs(ownerData.Listings) do
                if type(listing) == "table" and tostring(listing.ItemType or "") == "TradeBoothSkin" then
                    local itemId = listing.ItemId
                    local itemData = ownerData.Items and itemId and ownerData.Items[itemId]
                    local skinId = tostring(
                        (type(itemData) == "table" and (itemData.SkinID or itemData.skinId))
                        or itemId
                        or ""
                    )
                    out[#out + 1] = {
                        uuid = skinId,
                        price = tonumber(listing.Price or listing.price) or 0,
                        skinId = skinId,
                        listingUUID = tostring(listingUUID),
                    }
                end
            end
            return out
        end)

        if ok and type(listedSkins) == "table" then
            for _, it in ipairs(listedSkins) do
                local skinId = tostring(it.skinId or it.uuid or "")
                local price = tonumber(it.price) or 0
                local label = string.format(
                    "[SKIN] %s | Price %s",
                    skinDisplayName(skinId),
                    tostring(price)
                )
                pushRow(label, price, 0, 0, "skin:" .. skinId)
            end
        end
    end

    table.sort(rows, function(a, b)
        return cmpPriceAgeKg(a, b)
    end)

    local shown = 0
    for _, row in ipairs(rows) do
        shown += 1
        addRow(shown, row.label)
    end

    if shown == 0 then
        local t = Instance.new("TextLabel")
        t.Name = "EmptyHint"
        t.Parent = sf
        t.BackgroundTransparency = 1
        t.Size = UDim2.new(1, 0, 0, 36)
        t.Font = Enum.Font.Gotham
        t.TextSize = 12
        t.TextXAlignment = Enum.TextXAlignment.Left
        t.TextYAlignment = Enum.TextYAlignment.Top
        t.TextColor3 = Color3.fromRGB(170,170,170)
        t.TextWrapped = true
        t.RichText = true
        t.Text = '<font color="#FFD76A"><b>Belum ada listing di booth.</b></font>\n<b>Pastikan sudah claim booth.</b>'
    end

    local baseH = calcListHeight(shown)
    if shown == 0 then baseH = math.max(baseH, 44) end
    sf.Size = UDim2.new(1, 0, 0, baseH)

    if shown > VISIBLE_ROWS then
        sf.ScrollBarThickness = 6
        sf.ScrollBarImageTransparency = 0
    else
        sf.ScrollBarThickness = 0
        sf.ScrollBarImageTransparency = 1
        sf.CanvasPosition = Vector2.new(0, 0)
    end

    task.defer(function()
        if ui.RelayoutContent then
            ui:RelayoutContent()
        end
    end)
end


        return refresh
    end

    ----------------------------------------------------------------
    -- Render All
    ----------------------------------------------------------------
    local function render()
        ui:ClearSubContent()

        -- SECTION 1: MODE A editable
        local bodyA = createSection("LIST MODE A", false)
        local refreshA = buildEditableSection(bodyA, "A", "Search Mode A...")

        -- SECTION 2: MODE B editable
        local bodyB = createSection("LIST MODE B", false)
        local refreshB = buildEditableSection(bodyB, "B", "Search Mode B...")

        -- SECTION 3: Booth read-only
        local bodyRO = createSection("LIST BOOTH", false)
        local refreshRO = buildReadOnlyBoothSection(bodyRO)

        -- expose one refresh function
        MK._refreshListTab = function()
            -- refresh label maps (biar nama tetap update)
            notFavLabel = buildLabelMapFromItems(buildNotFavItems())
            petTypeLabel= buildLabelMapFromItems(buildPetTypeItems())

            if refreshA then refreshA() end
            if refreshB then refreshB() end
            if refreshRO then refreshRO() end
        end

        -- initial render
        if MK._refreshListTab then MK._refreshListTab() end
    end

    render()

    -- expand/collapse default
    if #sectionSetters >= 1 then
        sectionSetters[1](false)
        for i = 2, #sectionSetters do sectionSetters[i](false) end
    end
end, 2)

    
    ui:RegisterSubTab("auto_market", "webhook", "Webhook", function()
    ui:ClearSubContent()

    local G = (getgenv and getgenv()) or _G

    -- ✅ MARKET STATE (source of truth: _G.STATE)
    local STATE = rawget(_G, "STATE") or {}
    _G.STATE = STATE
    G.STATE  = STATE

