local DEBUG_MARKET_FOOTER = false

local function _mdbg(...)
    if not DEBUG_MARKET_FOOTER then return end
    local t = {}
    for i = 1, select("#", ...) do t[#t+1] = tostring(select(i, ...)) end
    warn("[AUTO_MARKET/FOOTER]", table.concat(t, " "))
end

local function _getSTATE()
    local G = (getgenv and getgenv()) or _G
    local S = rawget(_G, "STATE") or rawget(G, "STATE")
    if type(S) == "table" then
        _G.STATE = S
        G.STATE = S
    end
    return S
end

local function isauto_marketRunning()
    -- ✅ backup flag publik (kalau loop ketimpa / nil)
    if rawget(_G, "__AUTO_MARKET_RUNNING") == true then
        return true
    end

    local loop = rawget(_G, "market_loop")
    if not loop then return false end

    -- ✅ paling cepat: flag publik
    if loop.running == true then return true end

    -- Support method style ":" dan function "." / self-safe
    if type(loop.IsRunning) == "function" then
        local ok, v = pcall(function()
            -- kalau loop pakai ":" maka perlu self
            return loop.IsRunning(loop)
        end)
        if ok then return v == true end
    end

    if type(loop.isRunning) == "function" then
        local ok, v = pcall(function()
            return loop.isRunning(loop)
        end)
        if ok then return v == true end
    end

    return false
end

local function setMarketEnabled(on)
    local STATE = _getSTATE()
    if type(STATE) ~= "table" then
        _mdbg("setMarketEnabled FAILED: STATE nil")
        return
    end

    STATE.main = STATE.main or {}
    STATE.main.auto_market = STATE.main.auto_market or {}
    STATE.main.auto_market.runtime = STATE.main.auto_market.runtime or {}
    STATE.main.auto_market.runtime.enabled = (on == true)

    _mdbg("setMarketEnabled =", tostring(on == true),
          "| runtime.enabled =", tostring(STATE.main.auto_market.runtime.enabled))
end

-- self-safe caller (aman buat module yang pakai ":" atau ".")
local function callStart(loop)
    if type(loop.Start) == "function" then
        return loop.Start(loop)
    elseif type(loop.start) == "function" then
        return loop.start(loop)
    end
    error("no Start/start")
end

local function callStop(loop, reason)
    reason = reason or "manual"
    if type(loop.Stop) == "function" then
        return loop.Stop(loop, reason)
    elseif type(loop.stop) == "function" then
        return loop.stop(loop, reason)
    end
    error("no Stop/stop")
end


local function isauto_snipeRunning()
    if rawget(_G, "__AUTO_SNIPE_RUNNING") == true then
        return true
    end

    local loop = rawget(_G, "snipe_loop")
    if not loop then return false end

    if loop.running == true then return true end

    if type(loop.IsRunning) == "function" then
        local ok, v = pcall(function() return loop.IsRunning(loop) end)
        if ok then return v == true end
    end
    if type(loop.isRunning) == "function" then
        local ok, v = pcall(function() return loop.isRunning(loop) end)
        if ok then return v == true end
    end

    return false
end

local function callStartAny(loop)
    if type(loop.Start) == "function" then
        return loop.Start(loop)
    elseif type(loop.start) == "function" then
        return loop.start(loop)
    end
    error("no Start/start")
end

local function callStopAny(loop, reason)
    reason = reason or "manual"
    if type(loop.Stop) == "function" then
        return loop.Stop(loop, reason)
    elseif type(loop.stop) == "function" then
        return loop.stop(loop, reason)
    end
    error("no Stop/stop")
end

