            -- tabs_snipe_pet_current.lua
-- SIMPLE BASE KG RULE SECTION

local M = {}

function M.Render(
    body,
    ui,
    STATE,
    PetListView,
    SN,
    autoSave
)

    PetListView = PetListView or {}

    STATE = rawget(_G, "STATE") or STATE or {}
    _G.STATE = STATE

    STATE.main = STATE.main or {}
    STATE.main.auto_market = STATE.main.auto_market or {}
    local MK = STATE.main.auto_market

    ----------------------------------------------------------------
    -- AutoSave (ikut pola NodeHub kamu)
    ----------------------------------------------------------------
    local function autoSave()
        task.defer(function()
            local G = (getgenv and getgenv()) or _G
            local MAIN = rawget(_G, "MAIN") or rawget(G, "MAIN")
            local saveFn = MAIN and (MAIN.save or MAIN.Save)
            if type(saveFn) == "function" then
                pcall(function() saveFn(MAIN) end)
            elseif ui and type(ui.SaveState) == "function" then
                pcall(function() ui:SaveState() end)
            end
        end)
    end

    ----------------------------------------------------------------
    -- Helpers
    ----------------------------------------------------------------
    local function norm(s)
        s = tostring(s or ""):lower()
        s = s:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
        return s
    end

    local function toNumFloat(s)
        s = tostring(s or "")
        s = s:gsub(",", ".")
        local n = tonumber(s)
        if n then return n end

        local t = s:lower():gsub("%s+", "")
        local mul = 1
        if t:sub(-1) == "k" then mul = 1e3; t = t:sub(1, -2) end
        if t:sub(-1) == "m" then mul = 1e6; t = t:sub(1, -2) end
        if t:sub(-1) == "b" then mul = 1e9; t = t:sub(1, -2) end
        local nn = tonumber(t)
        if nn then return nn * mul end
        return nil
    end

    local function round1(n)
        n = tonumber(n) or 0
        return math.floor(n * 10 + 0.5) / 10
    end

    local function clampNum(n, minv, maxv, fallback)
        n = tonumber(n)
        if n == nil then return fallback end
        if minv ~= nil and n < minv then n = minv end
        if maxv ~= nil and n > maxv then n = maxv end
        return n
    end

    local function mkCorner(p, r)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, r or 6)
        c.Parent = p
    end

    local function mkStroke(p, col, th, tr)
        local s = Instance.new("UIStroke")
        s.Color = col or Color3.fromRGB(40,40,40)
        s.Thickness = th or 1
        s.Transparency = tr or 0.5
        s.Parent = p
    end

    local function mkPad(p, l, r, t, b)
        local pad = Instance.new("UIPadding")
        pad.PaddingTop    = UDim.new(0, t or 4)
        pad.PaddingBottom = UDim.new(0, b or 4)
        pad.PaddingLeft   = UDim.new(0, l or 4)
        pad.PaddingRight  = UDim.new(0, r or 4)
        pad.Parent = p
    end

    local function buildLabelMap(items)
        local m = {}
        for _, it in ipairs(items or {}) do
            if it and it.key then m[tostring(it.key)] = tostring(it.name or it.key) end
        end
        return m
    end

    ----------------------------------------------------------------
    -- Dropdown sources
    ----------------------------------------------------------------
    local function buildPetTypeItems()
        if PetListView and type(PetListView.buildPetItems) == "function" then
            return PetListView.buildPetItems() or {}
        end
        return {}
    end
    
    
    local MUT_NO   = "__NONE__"
local MUT_ALL  = "__ALL__"

local function mutUiToStore(k)
    k = tostring(k or "")
    if k == MUT_NO then return "" end          -- no mutation
    if k == MUT_ALL then return "*" end        -- all mutation (token store)
    return k
end

local function mutStoreToUi(v)
    v = tostring(v or "")
    if v == "" then return MUT_NO end
    if v == "*" then return MUT_ALL end
    return v
end

local function normMutationKey(k)
    k = tostring(k or "")
    if k == "__NONE__" then return "" end        -- no mutation
    if k == "__ALL__"  then return "*" end       -- all mutation (wildcard)
    return k
end


local function prependMutationSpecial(items)
    items = items or {}

    -- prevent double
    local hasNo, hasAll = false, false
    for _, it in ipairs(items) do
        local k = tostring(it.key)
        if k == MUT_NO then hasNo = true end
        if k == MUT_ALL then hasAll = true end
    end

    if not hasAll then
        table.insert(items, 1, { key = MUT_ALL, name = "(All mutation)" })
    end
    if not hasNo then
        table.insert(items, 1, { key = MUT_NO, name = "(No mutation)" })
    end
    return items
end




    local function buildMutationItems()
    if PetListView and type(PetListView.listAllMutations) == "function" then
        local items = PetListView.listAllMutations() or {}
        if #items > 0 then
            if type(items[1]) == "string" then
                local out = {}
                for _, s in ipairs(items) do
                    out[#out+1] = { key = s, name = s }
                end
                return prependMutationSpecial(out)
            end
            return prependMutationSpecial(items)
        end
    end

    local RS = game:GetService("ReplicatedStorage")
    local ok, reg = pcall(function()
        return require(RS.Modules.PetMutationRegistry)
    end)

    local items = {}
    if ok and type(reg) == "table" then
        local list = reg.List or reg.Mutations or reg.All or reg
        if type(list) == "table" then
            for k, v in pairs(list) do
                local code = tostring(v.code or v.Code or k)
                local nm   = tostring(v.name or v.Name or code)
                items[#items+1] = { key = code, name = nm }
            end
        end
    end

    table.sort(items, function(a,b) return tostring(a.name) < tostring(b.name) end)
    return prependMutationSpecial(items)
end


local function buildBoothSkinItems()
    local items = {}
    local ok, reg = pcall(function()
        return require(game:GetService("ReplicatedStorage").Data.TradeBoothSkinRegistry)
    end)
    if ok and type(reg) == "table" then
        for key, v in pairs(reg) do
            local id = tostring(key or "")
            if id ~= "" and id ~= "Default" and type(v) == "table" then
                items[#items + 1] = {
                    key = id,
                    name = tostring(v.DisplayName or id),
                }
            end
        end
    end
    table.sort(items, function(a, b) return tostring(a.name) < tostring(b.name) end)
    return items
end


    ----------------------------------------------------------------
    -- Stable Rule ID
    ----------------------------------------------------------------
    local function makeRuleIdPet(petType, mutation, maxPrice, minAge, maxAge, minKg, maxKg)
        petType  = tostring(petType or "")
        mutation = tostring(mutation or "")
        maxPrice = tonumber(maxPrice) or 0
        minAge   = tonumber(minAge) or 0
        maxAge   = tonumber(maxAge) or 0
        minKg    = round1(tonumber(minKg) or 0)
        local maxPart = (maxKg == nil) and "INF" or tostring(round1(maxKg))
        return ("P|%s|%s|%s|%s|%s|%s|%s"):format(petType, mutation, maxPrice, minAge, maxAge, tostring(minKg), maxPart)
    end

    local function makeRuleIdSkin(skinType, maxPrice, minAge)
        skinType = tostring(skinType or "")
        maxPrice = tonumber(maxPrice) or 0
        minAge   = tonumber(minAge) or 0
        return ("S|%s|%s|%s"):format(skinType, maxPrice, minAge)
    end

