        kgMinBox = createMiniBox(item, map.kmin.w, rec.minKg or 0, "", "compact")
        kgMinBox.Position = UDim2.new(0, map.kmin.x, 0.5, -8)

        kgMaxBox = createMiniBox(item, map.kmax.w, rec.maxKg or 0, "", "compact")
        kgMaxBox.Position = UDim2.new(0, map.kmax.x, 0.5, -8)
    else
        local dash1 = createMiniText(item, map.kmin.w, "-", true, "tiny")
        dash1.Position = UDim2.new(0, map.kmin.x, 0.5, -9)
        local dash2 = createMiniText(item, map.kmax.w, "-", true, "tiny")
        dash2.Position = UDim2.new(0, map.kmax.x, 0.5, -9)
    end

    local priceBox = createMiniBox(item, map.price.w, rec.maxPrice or 0, "0", "normal")
    priceBox.Position = UDim2.new(0, map.price.x, 0.5, -9)

    --------------------------------------------------------
    -- commit helper (angka)
    --------------------------------------------------------
    local function commitNumberBox(box, fn)
        box.FocusLost:Connect(function()
            local t = tostring(box.Text or ""):gsub("^%s+",""):gsub("%s+$","")
            local n = toNumFloat(t)
            fn(n, t)
        end)
    end

    commitNumberBox(priceBox, function(n)
        n = tonumber(n) or 0
        if n < 0 then n = 0 end
        rec.maxPrice = n
        ruleId = rekeyRule(ruleId, rec)
        if SN.ui._refreshRules then SN.ui._refreshRules() end
    end)

    commitNumberBox(ageMinBox, function(n)
        n = tonumber(n) or 0
        n = math.max(0, math.floor(n))
        rec.minAge = n
        ruleId = rekeyRule(ruleId, rec)
        if SN.ui._refreshRules then SN.ui._refreshRules() end
    end)

    commitNumberBox(ageMaxBox, function(n)
        n = tonumber(n) or 0
        n = math.max(0, math.floor(n))
        rec.maxAge = n
        ruleId = rekeyRule(ruleId, rec)
        if SN.ui._refreshRules then SN.ui._refreshRules() end
    end)

    if kgMinBox and kgMaxBox then
        commitNumberBox(kgMinBox, function(n)
            n = tonumber(n) or 0
            if n < 0 then n = 0 end
            rec.minKg = round1(n)
            ruleId = rekeyRule(ruleId, rec)
            if SN.ui._refreshRules then SN.ui._refreshRules() end
        end)

        kgMaxBox.FocusLost:Connect(function()
            local t = tostring(kgMaxBox.Text or ""):gsub("^%s+",""):gsub("%s+$","")
            if t == "" then
                rec.maxKg = nil
            else
                local n = toNumFloat(t)
                n = tonumber(n) or 0
                if n < 0 then n = 0 end
                rec.maxKg = round1(n)
            end
            ruleId = rekeyRule(ruleId, rec)
            if SN.ui._refreshRules then SN.ui._refreshRules() end
        end)
    end

    --------------------------------------------------------
    -- resize sync: row ikut header jika UI berubah
    --------------------------------------------------------
    item:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
        local _, m2 = computeColumns(item.AbsoluteSize.X)

        typeText.Position = UDim2.new(0, m2.type.x, 0.5, -9)
        typeText.Size     = UDim2.new(0, m2.type.w, 0, 18)

        mutText.Position  = UDim2.new(0, m2.mut.x, 0.5, -9)
        mutText.Size      = UDim2.new(0, m2.mut.w, 0, 18)

        ageMinBox.Position= UDim2.new(0, m2.amin.x, 0.5, -8)
        ageMinBox.Size    = UDim2.new(0, m2.amin.w, 0, 16)

        ageMaxBox.Position= UDim2.new(0, m2.amax.x, 0.5, -8)
        ageMaxBox.Size    = UDim2.new(0, m2.amax.w, 0, 16)

        priceBox.Position = UDim2.new(0, m2.price.x, 0.5, -9)
        priceBox.Size     = UDim2.new(0, m2.price.w, 0, 18)

        del.Position      = UDim2.new(0, m2.del.x, 0.5, -8)
        del.Size          = UDim2.new(0, m2.del.w, 0, 18)

        if kgMinBox and kgMaxBox then
            kgMinBox.Position = UDim2.new(0, m2.kmin.x, 0.5, -8)
            kgMinBox.Size     = UDim2.new(0, m2.kmin.w, 0, 16)

            kgMaxBox.Position = UDim2.new(0, m2.kmax.x, 0.5, -8)
            kgMaxBox.Size     = UDim2.new(0, m2.kmax.w, 0, 16)
        end
    end)
end


local function refreshRules()
    clearRows()
    updateHint()

    PET_LABEL  = buildLabelMap(buildPetTypeItems())
    MUT_LABEL  = buildLabelMap(buildMutationItems())
    SKIN_LABEL = buildLabelMap(buildBoothSkinItems())

    local q = norm(searchBox.Text)
    local shown = 0

    for ruleId, rec in pairs(SN.rules or {}) do
        if type(rec) == "table" then
            local kind = tostring(rec.kind or "pet"):lower()
            if kind ~= "skin" then
                local title = getRuleTitle(rec)
                local mutName = MUT_LABEL[tostring(rec.mutation or "")] or tostring(rec.mutation or "")
                local full = title .. " " .. mutName
                if q == "" or norm(full):find(q, 1, true) then
                    shown += 1
                    buildRow(shown, ruleId, rec)
                end
            end
        end
    end

    if shown == 0 then
        local t = Instance.new("TextLabel")
        t.Name = "EmptyHint"
        t.Parent = sf
        t.BackgroundTransparency = 1
        t.Size = UDim2.new(1, -10, 0, 40)
        t.Position = UDim2.new(0, 5, 0, 0)
        t.Font = Enum.Font.Gotham
        t.TextSize = 12
        t.TextXAlignment = Enum.TextXAlignment.Left
        t.TextYAlignment = Enum.TextYAlignment.Top
        t.TextColor3 = Color3.fromRGB(170,170,170)
        t.RichText = true
        t.TextWrapped = true
        t.Text = (q ~= "")
            and '<font color="#FFD76A"><b>Tidak ditemukan.</b></font>\n<b>Hapus kata pencarian untuk menampilkan semua.</b>'
            or  '<font color="#FFD76A"><b>Rule masih kosong.</b></font>\n<b>Isi form Add Rule di bawah.</b>'
    end

    local baseH = calcListHeight(shown)
    if shown == 0 then baseH = math.max(baseH, 44) end
    sf.Size = UDim2.new(1, 0, 0, baseH)

    if shown > VISIBLE_ROWS then
        sf.ScrollBarThickness = 6
        sf.ScrollBarImageTransparency = 0
    else
        sf.ScrollBarThickness = 0
        sf.ScrollBarImageTransparency = 1
        sf.CanvasPosition = Vector2.new(0, 0)
    end
end

SN.ui._refreshRules = refreshRules

do
    local sp = false
    searchBox:GetPropertyChangedSignal("Text"):Connect(function()
        updateHint()
        if sp then return end
        sp = true
        task.defer(function()
            sp = false
            if SN.ui._refreshRules then SN.ui._refreshRules() end
        end)
    end)
end

