addLay.FillDirection = Enum.FillDirection.Vertical
addLay.SortOrder = Enum.SortOrder.LayoutOrder
addLay.Padding = UDim.new(0, 8)

local function clearAddInputs()
    for _, ch in ipairs(addWrap:GetChildren()) do
        if ch ~= addLay and not ch:IsA("UIListLayout") and not ch:IsA("UIPadding") and not ch:IsA("UICorner") and not ch:IsA("UIStroke") then
            ch:Destroy()
        end
    end
end

local function renderAddInputs()
    clearAddInputs()
    SN.add.kind = "pet"

    ui:CreateRowDropdown(addWrap, {
        label = "Pet Type",
        placeholder = "Select Pet Type...",
        mode = "multi",
        getItems = function() return buildPetTypeItems() end,
        initial = SN.add.petTypeSelected or {},
        onChanged = function(_, picked)
            local out = {}
            if type(picked) == "table" then
                local hasAny = false
                for k, v in pairs(picked) do
                    if type(k) ~= "number" and v == true then
                        k = tostring(k or "")
                        if k ~= "" then out[k] = true; hasAny = true end
                    end
                end
                if not hasAny then
                    for _, it in ipairs(picked) do
                        local k = (type(it)=="table" and (it.key or it.id or it.value)) or it
                        k = tostring(k or "")
                        if k ~= "" then out[k] = true end
                    end
                end
            end
            SN.add.petTypeSelected = out
            autoSave()
        end,
    })

    ui:CreateRowDropdown(addWrap, {
        label = "Mutation",
        placeholder = "Select Mutation...",
        mode = "single",
        getItems = function() return buildMutationItems() end,
        initial = mutStoreToUi(SN.add.mutation),
        onChanged = function(_, picked)
            local v = (type(picked)=="table" and picked.key) or picked
            SN.add.mutation = mutUiToStore(v)
            autoSave()
        end
    })

    ui:CreateRowInput(addWrap, "Max Price", tostring(SN.add.maxPrice or 0), function(text)
        local n = toNumFloat(text); if not n or n < 0 then n = 0 end
        SN.add.maxPrice = n; autoSave()
    end)

    ui:CreateRowInput(addWrap, "Min Age", tostring(SN.add.minAge or 0), function(text)
        local n = toNumFloat(text); n = math.max(0, math.floor(n or 0))
        SN.add.minAge = n; autoSave()
    end)

    ui:CreateRowInput(addWrap, "Max Age", tostring(SN.add.maxAge or 0), function(text)
        local n = toNumFloat(text); n = math.max(0, math.floor(n or 0))
        SN.add.maxAge = n; autoSave()
    end)

    ui:CreateRowInput(addWrap, "Min KG", tostring(SN.add.minKg or 0), function(text)
        local n = toNumFloat(text); if not n or n < 0 then n = 0 end
        SN.add.minKg = round1(n); autoSave()
    end)

    ui:CreateRowInput(addWrap, "Max KG", tostring(SN.add.maxKg or 0), function(text)
        local n = toNumFloat(text); if not n or n < 0 then n = 0 end
        SN.add.maxKg = round1(n); autoSave()
    end)

    ui:CreateRowToggle(addWrap, "APPLY (Add Rule)", false, function(isOn)
        if not isOn then return end

        local previewLines = {}
        local toCommit = {}

        local function mutLabel(v)
            v = tostring(v or "")
            if v == "*" then return "(All mutation)" end
            if v == ""  then return "(No mutation)" end
            return MUT_LABEL[v] or v
        end

        local function fmtNum(n)
            n = tonumber(n) or 0
            if n % 1 == 0 then return tostring(math.floor(n)) end
            return tostring(n)
        end

        local function fmtKg(n)
            n = tonumber(n)
            if n == nil then return "INF" end
            return tostring(round1(n))
        end

        local sel = SN.add.petTypeSelected or {}
        local any = false
        for _ in pairs(sel) do any = true break end
        if not any then return end

        local minKg = round1(tonumber(SN.add.minKg) or 0)
        local maxKg = SN.add.maxKg
        if maxKg ~= nil and maxKg < minKg then
            local tmp = minKg; minKg = maxKg; maxKg = tmp
        end

        local mut = tostring(SN.add.mutation or "")
        local maxPrice = tonumber(SN.add.maxPrice) or 0
        local minAge   = tonumber(SN.add.minAge) or 0
        local maxAge   = tonumber(SN.add.maxAge) or 0

        table.insert(previewLines, "<b>ADD RULE (PET)</b>")
        table.insert(previewLines, ("Mutation: <b>%s</b>"):format(mutLabel(mut)))
        table.insert(previewLines, ("MaxPrice: <b>%s</b> | Age: <b>%s-%s</b> | KG: <b>%s-%s</b>"):format(
            fmtNum(maxPrice), fmtNum(minAge), fmtNum(maxAge), fmtKg(minKg), fmtKg(maxKg)
        ))
        table.insert(previewLines, " ")
        table.insert(previewLines, "<b>Items:</b>")

        local petArr = {}
        for petTypeKey in pairs(sel) do petArr[#petArr+1] = tostring(petTypeKey) end
        table.sort(petArr)

        for _, petTypeKey in ipairs(petArr) do
            local rid = makeRuleIdPet(petTypeKey, mut, maxPrice, minAge, maxAge, minKg, maxKg)
            local rec = {
                kind     = "pet",
                petType  = tostring(petTypeKey),
                mutation = mut,
                maxPrice = maxPrice,
                minAge   = minAge,
                maxAge   = maxAge,
                minKg    = minKg,
                maxKg    = maxKg,
            }
            toCommit[#toCommit+1] = { id = rid, rec = rec }
            local petName = PET_LABEL[tostring(petTypeKey)] or tostring(petTypeKey)
            table.insert(previewLines, ("• <b>%s</b>  <font color=\"#AAAAAA\">(%s)</font>"):format(petName, rid))
        end

        if #toCommit <= 0 then return end

        ui:Confirm({
            title = "CONFIRM ADD RULE",
            badge = "PET",
            meta  = "Will add: " .. tostring(#toCommit) .. " rule(s)",
            lines = previewLines,
            onYes = function()
                for _, it in ipairs(toCommit) do
                    SN.rules[it.id] = it.rec
                end
                autoSave()
                if SN.ui._refreshRules then SN.ui._refreshRules() end
            end,
            onNo = function() end,
        })
    end, nil, { momentary = true })
end

renderAddInputs()

-- initial paint
refreshRules()

end

