    local ADD   = SN.add or MK.snipe.addBase
    local UI    = SN.ui or MK.snipe.uiBase

    MK.snipe.rulesBase = RULES
    MK.snipe.addBase   = ADD
    MK.snipe.uiBase    = UI

    RULES = RULES or {}
    ADD = ADD or {
        kind = "pet",
