        maxBaseKg = nil,
        skinType = "",
    }
    ADD.kind = "pet" -- section ini pet-only; booth skin punya section sendiri
    MK.snipe.addBase = ADD
    UI = UI or {}

    local SN = { rules = RULES, add = ADD, ui = UI }

------------------------------------------------------------
-- UI constants for list columns
------------------------------------------------------------
local ROW_H = 28
local ROW_PAD = 4
local VISIBLE_ROWS = 6
local LIST_PAD_TOP = 8
local LIST_PAD_BOT = 8

local function calcListHeight(count)
    local rows = math.min(count or 0, VISIBLE_ROWS)
    if rows <= 0 then rows = 1 end
    return (rows * ROW_H) + ((rows - 1) * ROW_PAD) + LIST_PAD_TOP + LIST_PAD_BOT
end

------------------------------------------------------------
-- AUTO COLUMN LAYOUT (single source of truth)
-- urutan: Type | Mut | Amin | Amax | BaseMin | BaseMax | Price | Del
------------------------------------------------------------
local GAP = 3
local PAD_L, PAD_R = 6, 6

local COLSPEC = {
    { key="type",  title="Type",  kind="text", unit=12, min=70,  headAlign="center", textAlign="center"   },
    { key="mut",   title="Mut",   kind="text", unit=9,  min=55,  headAlign="center", textAlign="center"   },

    { key="amin",  title="Amin",  kind="box",  unit=4,  min=28,  headAlign="center", textAlign="center" },
    { key="amax",  title="Amax",  kind="box",  unit=4,  min=28,  headAlign="center", textAlign="center" },
    { key="bmin",  title="Bmin",  kind="box",  unit=5,  min=34,  headAlign="center", textAlign="center" },
    { key="bmax",  title="Bmax",  kind="box",  unit=5,  min=34,  headAlign="center", textAlign="center" },
    { key="price", title="Price", kind="box",  unit=7,  min=54,  headAlign="center", textAlign="center" },

    { key="del",   title="",      kind="btn",  unit=3,  min=20,  headAlign="center", textAlign="center" },
}

local function computeColumns(totalW)
    local usable = totalW - PAD_L - PAD_R
    if usable < 160 then usable = 160 end

    local n = #COLSPEC
    local gapsW = (n - 1) * GAP
    local wAvail = usable - gapsW
    if wAvail < 120 then wAvail = 120 end

    local unitSum = 0
    for _, c in ipairs(COLSPEC) do unitSum += (c.unit or 1) end

    local cols = {}
    for i, c in ipairs(COLSPEC) do
        local w = math.floor(wAvail * ((c.unit or 1) / unitSum))
        w = math.max(c.min or 10, w)
        cols[i] = {
            key       = c.key,
            title     = c.title,
            kind      = c.kind,
            headAlign = c.headAlign,
            textAlign = c.textAlign,
            min       = c.min or 10,
            w         = w,
            x         = 0,
        }
    end

    local function totalUsed()
        local s=0; for _,cc in ipairs(cols) do s += cc.w end; return s
    end

    -- kalau min-width bikin overflow, shrink dari kolom text dulu
    local over = totalUsed() - wAvail
    if over > 0 then
        local shrinkOrder = { "type","mut","price","bmax","bmin","amax","amin" }
        local idxByKey = {}
        for i, cc in ipairs(cols) do idxByKey[cc.key]=i end

        for _, k in ipairs(shrinkOrder) do
            if over <= 0 then break end
            local i = idxByKey[k]
            if i then
                local cc = cols[i]
                local can = cc.w - cc.min
                if can > 0 then
                    local take = math.min(can, over)
                    cc.w -= take
                    over -= take
                end
            end
        end
    end

    -- set posisi x
    local x = PAD_L
    for _, cc in ipairs(cols) do
        cc.x = x
        x += cc.w + GAP
    end

    -- map by key
    local map = {}
    for _, cc in ipairs(cols) do map[cc.key] = cc end
    return cols, map
end

------------------------------------------------------------
-- MiniBox (angka)
------------------------------------------------------------
local function createMiniBox(parent, w, text, placeholder, style)
    style = style or "normal" -- "normal" | "compact"

    local box = Instance.new("TextBox")
    box.BackgroundColor3 = Color3.fromRGB(18,18,18)
    box.BorderSizePixel = 0

    local H = (style == "compact") and 16 or 18
    box.Size = UDim2.new(0, w, 0, H)

    box.Font = Enum.Font.Gotham
    box.TextSize = (style == "compact") and 10 or 10
    box.TextColor3 = Color3.fromRGB(235,235,235)
    box.PlaceholderColor3 = Color3.fromRGB(140,140,140)
    box.PlaceholderText = placeholder or ""
    box.ClearTextOnFocus = false
    box.TextXAlignment = Enum.TextXAlignment.Center
    box.Text = tostring(text or "")

    mkCorner(box, 3)
    mkStroke(box, Color3.fromRGB(40,40,40), 1, 0.65)

    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, 2)
    pad.PaddingRight = UDim.new(0, 2)
    pad.Parent = box

    box.Parent = parent
    return box
end

------------------------------------------------------------
-- Label cell (read-only)
------------------------------------------------------------
local function createMiniText(parent, w, text, alignCenter, style)
    style = style or "normal" -- "normal" | "tiny"

    local lb = Instance.new("TextLabel")
    lb.BackgroundTransparency = 1
    lb.BorderSizePixel = 0

    local H = (style == "tiny") and 16 or 18
    lb.Size = UDim2.new(0, w, 0, H)

    lb.Font = Enum.Font.Gotham
    lb.TextSize = (style == "tiny") and 9 or 10
    lb.TextColor3 = Color3.fromRGB(235,235,235)
    lb.Text = tostring(text or "")
    lb.ClipsDescendants = true
    lb.TextXAlignment = alignCenter and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left
    lb.TextYAlignment = Enum.TextYAlignment.Center
    pcall(function() lb.TextTruncate = Enum.TextTruncate.AtEnd end)

    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, 2)
    pad.PaddingRight = UDim.new(0, 2)
    pad.Parent = lb

    lb.Parent = parent
    return lb
end

