local function makeHeaderLabel(txt, x, w)
    local lb = Instance.new("TextLabel")
    lb.Parent = header
    lb.BackgroundTransparency = 1
    lb.Position = UDim2.new(0, x, 0, 0)
    lb.Size = UDim2.new(0, w, 1, 0)

    lb.Font = Enum.Font.GothamBold -- ✅ bold
    lb.TextSize = 9
    lb.TextColor3 = Color3.fromRGB(205,205,205)

    lb.TextXAlignment = Enum.TextXAlignment.Center
    lb.TextYAlignment = Enum.TextYAlignment.Center
    lb.Text = tostring(txt or "")

    lb.ClipsDescendants = true
    lb.TextWrapped = true -- ✅ wrap kalau sempit
    lb.RichText = false

    -- jangan truncate kalau mau wrap
    pcall(function() lb.TextTruncate = Enum.TextTruncate.None end)

    return lb
end



local function layoutHeader()
    for _, ch in ipairs(header:GetChildren()) do
        if ch:IsA("TextLabel") then ch:Destroy() end
