local function deleteRule(ruleId)
    ruleId = tostring(ruleId or "")
    if ruleId == "" then return end
    RULES[ruleId] = nil
    autoSave()
end

local PET_LABEL  = buildLabelMap(buildPetTypeItems())
local MUT_LABEL  = buildLabelMap(buildMutationItems())
local SKIN_LABEL = buildLabelMap(buildBoothSkinItems())

local function getRuleTitle(rec)
    rec = rec or {}
    if rec.kind == "pet" then
        local pt = tostring(rec.petType or "")
        return PET_LABEL[pt] or pt
    else
        local st = tostring(rec.skinType or "")
        return SKIN_LABEL[st] or st
    end
end

local function rekeyRule(oldId, rec)
    local newId
    if rec.kind == "pet" then
        newId = makeRuleIdPet(rec.petType, rec.mutation, rec.maxPrice, rec.minAge, rec.maxAge, rec.minBaseKg, rec.maxBaseKg)
    else
        newId = makeRuleIdSkin(rec.skinType, rec.maxPrice, rec.minAge)
    end

    newId = tostring(newId)
    oldId = tostring(oldId)

    if newId ~= oldId then
        RULES[newId] = rec
        RULES[oldId] = nil
        autoSave()
        return newId
    else
        RULES[oldId] = rec
        autoSave()
        return oldId
    end
end

