local function clearAddInputs()
    for _, ch in ipairs(addWrap:GetChildren()) do
        if ch ~= addLay and not ch:IsA("UIListLayout") and not ch:IsA("UIPadding") and not ch:IsA("UICorner") and not ch:IsA("UIStroke") then
            ch:Destroy()
        end
    end
end

local function renderAddInputs()
    clearAddInputs()
    ADD.kind = "pet"

    ui:CreateRowDropdown(addWrap, {
        label = "Pet Type",
        placeholder = "Select Pet Type...",
        mode = "multi",
        getItems = function() return buildPetTypeItems() end,
        initial = ADD.petTypeSelected or {},
        onChanged = function(_, picked)
            local out = {}
            if type(picked) == "table" then
                local hasAny = false
                for k, v in pairs(picked) do
                    if type(k) ~= "number" and v == true then
                        k = tostring(k or "")
                        if k ~= "" then out[k] = true; hasAny = true end
                    end
                end
                if not hasAny then
                    for _, it in ipairs(picked) do
                        local k = (type(it)=="table" and (it.key or it.id or it.value)) or it
                        k = tostring(k or "")
                        if k ~= "" then out[k] = true end
                    end
                end
            end
            ADD.petTypeSelected = out
            autoSave()
        end,
    })

    ui:CreateRowDropdown(addWrap, {
        label = "Mutation",
        placeholder = "Select Mutation...",
        mode = "single",
        getItems = function() return buildMutationItems() end,
        initial = mutStoreToUi(ADD.mutation),
        onChanged = function(_, picked)
            local v = (type(picked)=="table" and picked.key) or picked
            ADD.mutation = mutUiToStore(v)
            autoSave()
        end
    })

    ui:CreateRowInput(addWrap, "Max Price", tostring(ADD.maxPrice or 0), function(text)
        local n = toNumFloat(text); if not n or n < 0 then n = 0 end
        ADD.maxPrice = n; autoSave()
    end)

    ui:CreateRowInput(addWrap, "Min Age", tostring(ADD.minAge or 0), function(text)
        local n = toNumFloat(text); n = math.max(0, math.floor(n or 0))
        ADD.minAge = n; autoSave()
    end)

    ui:CreateRowInput(addWrap, "Max Age", tostring(ADD.maxAge or 0), function(text)
        local n = toNumFloat(text); n = math.max(0, math.floor(n or 0))
        ADD.maxAge = n; autoSave()
    end)

    ui:CreateRowInput(addWrap, "Base KG Min (Age 1)", tostring(ADD.minBaseKg or 0), function(text)
        local n = toNumFloat(text); if not n or n < 0 then n = 0 end
        ADD.minBaseKg = round1(n); autoSave()
    end)

    ui:CreateRowInput(addWrap, "Base KG Max (Age 1)", tostring(ADD.maxBaseKg or 0), function(text)
        local t = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if t == "" then
            ADD.maxBaseKg = nil
        else
            local n = toNumFloat(t); if not n or n < 0 then n = 0 end
            ADD.maxBaseKg = round1(n)
        end
        autoSave()
    end)

    ui:CreateRowToggle(addWrap, "APPLY (Add Rule)", false, function(isOn)
        if not isOn then return end

        local previewLines = {}
        local toCommit = {}

        local function mutLabel(v)
            v = tostring(v or "")
            if v == "*" then return "(All mutation)" end
            if v == ""  then return "(No mutation)" end
            return MUT_LABEL[v] or v
        end

        local function fmtNum(n)
            n = tonumber(n) or 0
            if n % 1 == 0 then return tostring(math.floor(n)) end
            return tostring(n)
        end

        local function fmtKg(n)
            n = tonumber(n)
            if n == nil then return "INF" end
            return tostring(round1(n))
        end

        local sel = ADD.petTypeSelected or {}
        local any = false
        for _ in pairs(sel) do any = true break end
        if not any then return end

        local minBaseKg = round1(tonumber(ADD.minBaseKg) or 0)
        local maxBaseKg = ADD.maxBaseKg
        if maxBaseKg ~= nil and maxBaseKg < minBaseKg then
            local tmp = minBaseKg; minBaseKg = maxBaseKg; maxBaseKg = tmp
        end

        local mut = tostring(ADD.mutation or "")
        local maxPrice = tonumber(ADD.maxPrice) or 0
        local minAge   = tonumber(ADD.minAge) or 0
        local maxAge   = tonumber(ADD.maxAge) or 0

        table.insert(previewLines, "<b>ADD RULE (PET · BASE KG AGE 1)</b>")
        table.insert(previewLines, ("Mutation: <b>%s</b>"):format(mutLabel(mut)))
        table.insert(previewLines, ("MaxPrice: <b>%s</b> | Age: <b>%s-%s</b> | Base KG: <b>%s-%s</b>"):format(
            fmtNum(maxPrice), fmtNum(minAge), fmtNum(maxAge), fmtKg(minBaseKg), fmtKg(maxBaseKg)
        ))
        table.insert(previewLines, " ")
        table.insert(previewLines, "<b>Items:</b>")

        local petArr = {}
        for petTypeKey in pairs(sel) do petArr[#petArr+1] = tostring(petTypeKey) end
        table.sort(petArr)

        for _, petTypeKey in ipairs(petArr) do
            local rid = makeRuleIdPet(petTypeKey, mut, maxPrice, minAge, maxAge, minBaseKg, maxBaseKg)
            local rec = {
                kind       = "pet",
                kgMode     = "base_age1",
                petType    = tostring(petTypeKey),
                mutation   = mut,
                maxPrice   = maxPrice,
                minAge     = minAge,
                maxAge     = maxAge,
                minBaseKg  = minBaseKg,
                maxBaseKg  = maxBaseKg,
            }
            toCommit[#toCommit+1] = { id = rid, rec = rec }
            local petName = PET_LABEL[tostring(petTypeKey)] or tostring(petTypeKey)
            table.insert(previewLines, ("• <b>%s</b>  <font color=\"#AAAAAA\">(%s)</font>"):format(petName, rid))
        end

        if #toCommit <= 0 then return end

        ui:Confirm({
            title = "CONFIRM ADD RULE",
            badge = "PET BASE",
            meta  = "Will add: " .. tostring(#toCommit) .. " rule(s)",
            lines = previewLines,
            onYes = function()
                for _, it in ipairs(toCommit) do
                    RULES[it.id] = it.rec
                end
                autoSave()
                if UI._refreshRules then UI._refreshRules() end
            end,
            onNo = function() end,
        })
    end, nil, { momentary = true })
end

renderAddInputs()

-- initial paint
refreshRules()

end

return M
        end,
        required = false,
