            -- ui_snipe_booth_skin.lua
-- Snipe Rules Booth Skin (section terpisah dari Pet)

local M = {}

function M.Render(body, ui, STATE, _PetListView, SN, autoSaveFn)
    STATE = rawget(_G, "STATE") or STATE or {}
    _G.STATE = STATE
    STATE.main = STATE.main or {}
    STATE.main.auto_market = STATE.main.auto_market or {}
    local MK = STATE.main.auto_market

    MK.snipe = MK.snipe or {}
    MK.snipe.rules = MK.snipe.rules or {}
    MK.snipe.addSkin = MK.snipe.addSkin or {}
    MK.snipe.uiSkin = MK.snipe.uiSkin or {}

    SN = SN or {}
    local RULES = SN.rules or MK.snipe.rules
    local ADD   = SN.add or MK.snipe.addSkin
    local UI    = SN.ui or MK.snipe.uiSkin

    MK.snipe.rules = RULES
    MK.snipe.addSkin = ADD
    MK.snipe.uiSkin = UI
    SN = { rules = RULES, add = ADD, ui = UI }

    ADD.selected = type(ADD.selected) == "table" and ADD.selected or {}
    ADD.maxPrice = tonumber(ADD.maxPrice) or 0

    local function autoSave()
        if type(autoSaveFn) == "function" then
            autoSaveFn()
            return
        end
        task.defer(function()
            local G = (getgenv and getgenv()) or _G
            local MAIN = rawget(_G, "MAIN") or rawget(G, "MAIN")
            local saveFn = MAIN and (MAIN.save or MAIN.Save)
            if type(saveFn) == "function" then
                pcall(function() saveFn(MAIN) end)
            elseif ui and type(ui.SaveState) == "function" then
                pcall(function() ui:SaveState() end)
            end
        end)
    end

    local function norm(s)
        s = tostring(s or ""):lower()
        s = s:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
        return s
    end

    local function toNumFloat(s)
        s = tostring(s or ""):gsub(",", ".")
        local n = tonumber(s)
        if n then return n end
        local t = s:lower():gsub("%s+", "")
        local mul = 1
        if t:sub(-1) == "k" then mul = 1e3; t = t:sub(1, -2) end
        if t:sub(-1) == "m" then mul = 1e6; t = t:sub(1, -2) end
        if t:sub(-1) == "b" then mul = 1e9; t = t:sub(1, -2) end
        local nn = tonumber(t)
        if nn then return nn * mul end
        return nil
    end

    local function cleanSelectedMap(m)
        local out = {}
        if type(m) == "table" then
            for k, v in pairs(m) do
                if v == true and tostring(k) ~= "" then
                    out[tostring(k)] = true
                end
            end
        end
        return out
    end

    local function mkCorner(p, r)
        local c = Instance.new("UICorner")
        c.CornerRadius = UDim.new(0, r or 6)
        c.Parent = p
    end

    local function mkStroke(p, col, th, tr)
        local s = Instance.new("UIStroke")
        s.Color = col or Color3.fromRGB(40, 40, 40)
        s.Thickness = th or 1
        s.Transparency = tr or 0.5
        s.Parent = p
    end

    local function mkPad(p, l, r, t, b)
        local pad = Instance.new("UIPadding")
        pad.PaddingTop = UDim.new(0, t or 4)
        pad.PaddingBottom = UDim.new(0, b or 4)
        pad.PaddingLeft = UDim.new(0, l or 4)
        pad.PaddingRight = UDim.new(0, r or 4)
        pad.Parent = p
    end

    local function buildBoothSkinItems()
        local items = {}
        local ok, reg = pcall(function()
            return require(game:GetService("ReplicatedStorage").Data.TradeBoothSkinRegistry)
        end)
        if ok and type(reg) == "table" then
            for key, v in pairs(reg) do
                local id = tostring(key or "")
                if id ~= "" and id ~= "Default" and type(v) == "table" then
                    items[#items + 1] = {
                        key = id,
                        name = tostring(v.DisplayName or id),
                    }
                end
            end
        end
        table.sort(items, function(a, b)
            return tostring(a.name) < tostring(b.name)
        end)
        return items
    end

    local function buildLabelMap(items)
        local m = {}
        for _, it in ipairs(items or {}) do
            if it and it.key then
                m[tostring(it.key)] = tostring(it.name or it.key)
            end
        end
        return m
    end

    local function makeRuleIdSkin(skinType, maxPrice)
        skinType = tostring(skinType or "")
        maxPrice = tonumber(maxPrice) or 0
        return ("S|%s|%s|0"):format(skinType, maxPrice)
    end

    local ROW_H = 28
    local ROW_PAD = 4
    local VISIBLE_ROWS = 6
    local LIST_PAD_TOP = 8
    local LIST_PAD_BOT = 8

    local function calcListHeight(count)
        local rows = math.min(count or 0, VISIBLE_ROWS)
        if rows <= 0 then rows = 1 end
        return (rows * ROW_H) + ((rows - 1) * ROW_PAD) + LIST_PAD_TOP + LIST_PAD_BOT
    end

    local listWrap = Instance.new("Frame")
    listWrap.Name = "SkinSnipeWrap"
    listWrap.Parent = body
    listWrap.BackgroundTransparency = 1
    listWrap.Size = UDim2.new(1, 0, 0, 0)
    listWrap.AutomaticSize = Enum.AutomaticSize.Y

    local listLay = Instance.new("UIListLayout")
    listLay.Parent = listWrap
    listLay.FillDirection = Enum.FillDirection.Vertical
    listLay.SortOrder = Enum.SortOrder.LayoutOrder
    listLay.Padding = UDim.new(0, 8)

    local infoWrap = Instance.new("Frame")
    infoWrap.Parent = listWrap
    infoWrap.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
    infoWrap.BorderSizePixel = 0
    infoWrap.Size = UDim2.new(1, 0, 0, 0)
    infoWrap.AutomaticSize = Enum.AutomaticSize.Y
    infoWrap.LayoutOrder = 1
    mkCorner(infoWrap, 6)
    mkStroke(infoWrap, Color3.fromRGB(40, 40, 40), 1, 0.5)
    mkPad(infoWrap, 8, 8, 8, 8)

    local infoLbl = Instance.new("TextLabel")
    infoLbl.Parent = infoWrap
    infoLbl.BackgroundTransparency = 1
    infoLbl.Size = UDim2.new(1, 0, 0, 0)
    infoLbl.AutomaticSize = Enum.AutomaticSize.Y
    infoLbl.Font = Enum.Font.Gotham
    infoLbl.TextSize = 11
    infoLbl.TextXAlignment = Enum.TextXAlignment.Left
    infoLbl.TextYAlignment = Enum.TextYAlignment.Top
    infoLbl.TextWrapped = true
    infoLbl.TextColor3 = Color3.fromRGB(235, 235, 235)
    infoLbl.RichText = true
    infoLbl.Text =
        '<font color="#7FD6FF"><b>SNIPE BOOTH SKIN</b></font>\n' ..
        '• Pilih booth skin + <b>Max Price</b>, lalu Apply.\n' ..
        '• Loop beli listing <b>TradeBoothSkin</b> di booth jika harga ≤ max.'

    local searchWrap = Instance.new("Frame")
    searchWrap.Parent = listWrap
    searchWrap.BackgroundColor3 = Color3.fromRGB(22, 22, 22)
    searchWrap.BorderSizePixel = 0
    searchWrap.Size = UDim2.new(1, 0, 0, 26)
    searchWrap.LayoutOrder = 2
    mkCorner(searchWrap, 4)
    mkStroke(searchWrap, Color3.fromRGB(40, 40, 40), 1, 0.5)
    mkPad(searchWrap, 6, 6, 0, 0)

    local searchBox = Instance.new("TextBox")
    searchBox.Name = "SkinSearch"
    searchBox.Parent = searchWrap
    searchBox.BackgroundTransparency = 1
    searchBox.Size = UDim2.new(1, 0, 1, 0)
    searchBox.Font = Enum.Font.Gotham
    searchBox.TextSize = 12
    searchBox.TextColor3 = Color3.fromRGB(235, 235, 235)
    searchBox.PlaceholderText = "Cari skin rule..."
    searchBox.PlaceholderColor3 = Color3.fromRGB(140, 140, 140)
    searchBox.Text = ""
    searchBox.ClearTextOnFocus = false

    local sf = Instance.new("ScrollingFrame")
    sf.Name = "SkinRulesList"
    sf.Parent = listWrap
    sf.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
    sf.BorderSizePixel = 0
    sf.LayoutOrder = 3
    sf.Size = UDim2.new(1, 0, 0, calcListHeight(0))
    sf.CanvasSize = UDim2.new(0, 0, 0, 0)
    sf.ScrollBarThickness = 0
    sf.ScrollBarImageTransparency = 1
    sf.ScrollingDirection = Enum.ScrollingDirection.Y
    sf.AutomaticCanvasSize = Enum.AutomaticSize.Y
    sf.ClipsDescendants = true
    mkCorner(sf, 6)
    mkStroke(sf, Color3.fromRGB(40, 40, 40), 1, 0.5)
    mkPad(sf, 4, 4, LIST_PAD_TOP, LIST_PAD_BOT)

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Vertical
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, ROW_PAD)
    layout.Parent = sf

    local function clearRows()
        for _, ch in ipairs(sf:GetChildren()) do
            if ch:IsA("Frame") and ch.Name:sub(1, 5) == "Skin_" then
                ch:Destroy()
            end
            if ch:IsA("TextLabel") and ch.Name == "EmptyHint" then
                ch:Destroy()
            end
        end
    end

    local SKIN_LABEL = buildLabelMap(buildBoothSkinItems())

    local function deleteRule(ruleId)
        ruleId = tostring(ruleId or "")
        if ruleId == "" then return end
        SN.rules[ruleId] = nil
        autoSave()
    end

    local function rekeyRule(oldId, rec)
        local newId = makeRuleIdSkin(rec.skinType, rec.maxPrice)
        oldId = tostring(oldId)
        newId = tostring(newId)
        if newId ~= oldId then
            SN.rules[newId] = rec
            SN.rules[oldId] = nil
        else
            SN.rules[oldId] = rec
        end
        autoSave()
        return newId
    end

    local function refreshRules()
        clearRows()
        SKIN_LABEL = buildLabelMap(buildBoothSkinItems())

        local q = norm(searchBox.Text)
        local rows = {}
        for ruleId, rec in pairs(SN.rules or {}) do
            if type(rec) == "table" and tostring(rec.kind or ""):lower() == "skin" then
                local skinType = tostring(rec.skinType or "")
                local title = SKIN_LABEL[skinType] or skinType
                local full = title .. " " .. tostring(rec.maxPrice or 0)
                if q == "" or norm(full):find(q, 1, true) then
                    rows[#rows + 1] = { id = ruleId, rec = rec, title = title }
                end
            end
        end

        table.sort(rows, function(a, b)
            local pa = tonumber(a.rec.maxPrice) or 0
            local pb = tonumber(b.rec.maxPrice) or 0
            if pa ~= pb then return pa < pb end
            return tostring(a.title) < tostring(b.title)
        end)

        local shown = 0
        for i, row in ipairs(rows) do
            shown += 1
            local ruleId = row.id
            local rec = row.rec

            local item = Instance.new("Frame")
            item.Name = "Skin_" .. tostring(ruleId)
            item.BackgroundColor3 = Color3.fromRGB(22, 22, 22)
            item.Size = UDim2.new(1, 0, 0, ROW_H)
            item.LayoutOrder = i
            item.Parent = sf
            mkCorner(item, 4)

            local ip = Instance.new("UIPadding")
            ip.PaddingLeft = UDim.new(0, 6)
            ip.PaddingRight = UDim.new(0, 6)
            ip.Parent = item

            local del = Instance.new("TextButton")
            del.Parent = item
            del.BackgroundColor3 = Color3.fromRGB(160, 40, 40)
            del.Size = UDim2.new(0, 22, 0, 22)
            del.Position = UDim2.new(1, -22, 0.5, -11)
            del.AutoButtonColor = true
            del.Font = Enum.Font.GothamBold
            del.TextSize = 14
            del.TextColor3 = Color3.fromRGB(255, 255, 255)
            del.Text = "-"
            del.BorderSizePixel = 0
            mkCorner(del, 4)
            mkStroke(del, Color3.fromRGB(40, 40, 40), 1, 0.6)
            del.MouseButton1Click:Connect(function()
                deleteRule(ruleId)
                refreshRules()
            end)

            local priceBoxW = 64
            local priceBox = Instance.new("TextBox")
            priceBox.Parent = item
            priceBox.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
            priceBox.Size = UDim2.new(0, priceBoxW, 0, 22)
            priceBox.Position = UDim2.new(1, -(22 + 6 + priceBoxW), 0.5, -11)
            priceBox.Font = Enum.Font.Gotham
            priceBox.TextSize = 11
            priceBox.TextColor3 = Color3.fromRGB(235, 235, 235)
            priceBox.Text = tostring(rec.maxPrice or 0)
            priceBox.ClearTextOnFocus = false
            mkCorner(priceBox, 4)
            mkStroke(priceBox, Color3.fromRGB(40, 40, 40), 1, 0.6)

            local nameLbl = Instance.new("TextLabel")
            nameLbl.Parent = item
            nameLbl.BackgroundTransparency = 1
            nameLbl.Size = UDim2.new(1, -(22 + 6 + priceBoxW + 6), 1, 0)
            nameLbl.Font = Enum.Font.Gotham
            nameLbl.TextSize = 11
            nameLbl.TextXAlignment = Enum.TextXAlignment.Left
            nameLbl.TextColor3 = Color3.fromRGB(235, 235, 235)
            nameLbl.TextTruncate = Enum.TextTruncate.AtEnd
            nameLbl.Text = tostring(row.title or ruleId)

            priceBox.FocusLost:Connect(function()
                local n = toNumFloat(priceBox.Text)
                if not n or n < 0 then n = 0 end
                rec.maxPrice = n
                priceBox.Text = tostring(n)
                rekeyRule(ruleId, rec)
                refreshRules()
            end)
        end

        if shown == 0 then
            local t = Instance.new("TextLabel")
            t.Name = "EmptyHint"
            t.Parent = sf
            t.BackgroundTransparency = 1
            t.Size = UDim2.new(1, -10, 0, 40)
            t.Position = UDim2.new(0, 5, 0, 0)
            t.Font = Enum.Font.Gotham
            t.TextSize = 12
            t.TextXAlignment = Enum.TextXAlignment.Left
            t.TextYAlignment = Enum.TextYAlignment.Top
            t.TextColor3 = Color3.fromRGB(170, 170, 170)
            t.RichText = true
            t.TextWrapped = true
            t.Text = (q ~= "")
                and '<font color="#7FD6FF"><b>Tidak ditemukan.</b></font>'
                or  '<font color="#7FD6FF"><b>Skin rule kosong.</b></font>\n<b>Pilih skin lalu Apply.</b>'
        end

        local baseH = calcListHeight(shown)
        if shown == 0 then baseH = math.max(baseH, 44) end
        sf.Size = UDim2.new(1, 0, 0, baseH)
        if shown > VISIBLE_ROWS then
            sf.ScrollBarThickness = 6
            sf.ScrollBarImageTransparency = 0
        else
            sf.ScrollBarThickness = 0
            sf.ScrollBarImageTransparency = 1
            sf.CanvasPosition = Vector2.new(0, 0)
        end
    end

    SN.ui._refreshRules = refreshRules

    do
        local sp = false
        searchBox:GetPropertyChangedSignal("Text"):Connect(function()
            if sp then return end
            sp = true
            task.defer(function()
                sp = false
                refreshRules()
            end)
        end)
    end

    local addWrap = Instance.new("Frame")
    addWrap.Name = "AddSkinRuleWrap"
    addWrap.Parent = listWrap
    addWrap.BackgroundColor3 = Color3.fromRGB(16, 16, 16)
    addWrap.BorderSizePixel = 0
    addWrap.Size = UDim2.new(1, 0, 0, 0)
    addWrap.AutomaticSize = Enum.AutomaticSize.Y
    addWrap.LayoutOrder = 4
    mkCorner(addWrap, 6)
    mkStroke(addWrap, Color3.fromRGB(40, 40, 40), 1, 0.5)
    mkPad(addWrap, 8, 8, 8, 8)

    local addLay = Instance.new("UIListLayout")
    addLay.Parent = addWrap
    addLay.FillDirection = Enum.FillDirection.Vertical
    addLay.SortOrder = Enum.SortOrder.LayoutOrder
    addLay.Padding = UDim.new(0, 8)

    local ddSkinApi
    local setPrice

    ddSkinApi = select(2, ui:CreateRowDropdown(addWrap, {
        label = "Select Booth Skin",
        placeholder = "Select Skin...",
        mode = "multi",
        getItems = buildBoothSkinItems,
        initial = ADD.selected,
        onChanged = function(_, selectedMap)
            ADD.selected = cleanSelectedMap(selectedMap)
            autoSave()
        end,
    }))

    local _, priceSetter = ui:CreateRowInput(addWrap, "Max Price", tostring(ADD.maxPrice or 0), function(text)
        local n = toNumFloat(text)
        if not n or n < 0 then n = 0 end
        ADD.maxPrice = n
        autoSave()
    end)
    setPrice = priceSetter

    ui:CreateRowToggle(addWrap, "APPLY (Add Skin Rule)", false, function(isOn)
        if not isOn then return end

        local maxPrice = tonumber(ADD.maxPrice) or 0
        local picked = {}
        for skinId, on in pairs(ADD.selected or {}) do
            if on then picked[#picked + 1] = tostring(skinId) end
        end
        table.sort(picked)
        if #picked == 0 then return end

        local lines = {}
        for _, skinId in ipairs(picked) do
            local nm = SKIN_LABEL[skinId] or skinId
            lines[#lines + 1] = ("%s | max %s"):format(nm, tostring(maxPrice))
        end

        ui:Confirm({
            title = "ADD BOOTH SKIN SNIPE",
            badge = "SKIN",
            meta = ("Items: %d"):format(#picked),
            lines = lines,
            onYes = function()
                for _, skinId in ipairs(picked) do
                    local rid = makeRuleIdSkin(skinId, maxPrice)
                    SN.rules[rid] = {
                        kind = "skin",
                        skinType = skinId,
                        maxPrice = maxPrice,
                        minAge = 0,
                        maxAge = 0,
                        minKg = 0,
                        maxKg = nil,
                        mutation = "",
                        petType = "",
                    }
                end

                ADD.selected = {}
                ADD.maxPrice = 0
                if ddSkinApi and ddSkinApi.setSelected then
                    ddSkinApi.setSelected({})
                    if ddSkinApi.refreshLabel then ddSkinApi.refreshLabel() end
                end
                if setPrice then setPrice("0") end

                autoSave()
                refreshRules()
            end,
        })
    end, nil, { momentary = true })

    refreshRules()
end

return M

        end,
        required = false,
    },

    {
        key = "tabs_main_snipe",
        name = "Snipe Main Tabs",
        factory = function()
            -- ui_tabs_main_snipe.lua
-- Wrapper tab Snipe (tanpa HttpGet / link).
-- Butuh modul Current + Base + BoothSkin dari shortcut main_market_ui,
-- lalu setRuleModules sebelum Register.

local M = {}

M.CurrentRule = nil
M.BaseRule = nil
M.SkinRule = nil

function M.setRuleModules(currentRule, baseRule, skinRule)
    if type(currentRule) == "table" then
        M.CurrentRule = currentRule
    end
    if type(baseRule) == "table" then
        M.BaseRule = baseRule
    end
    if type(skinRule) == "table" then
        M.SkinRule = skinRule
    end
end

local function resolveRuleModules()
    local G = (getgenv and getgenv()) or _G

    local current = M.CurrentRule
        or G.__AUTOMARKET_SNIPE_PET_CURRENT
        or rawget(_G, "__AUTOMARKET_SNIPE_PET_CURRENT")

    local base = M.BaseRule
        or G.__AUTOMARKET_SNIPE_PET_BASE
        or rawget(_G, "__AUTOMARKET_SNIPE_PET_BASE")

    local skin = M.SkinRule
        or G.__AUTOMARKET_SNIPE_BOOTH_SKIN
        or rawget(_G, "__AUTOMARKET_SNIPE_BOOTH_SKIN")

    return current, base, skin
end

local function showMissing(body, msg)
    if not body then return end
    local t = Instance.new("TextLabel")
    t.BackgroundTransparency = 1
    t.Size = UDim2.new(1, 0, 0, 40)
    t.Font = Enum.Font.Gotham
    t.TextSize = 12
    t.TextXAlignment = Enum.TextXAlignment.Left
    t.TextYAlignment = Enum.TextYAlignment.Top
    t.TextColor3 = Color3.fromRGB(255, 180, 80)
    t.TextWrapped = true
    t.RichText = true
    t.Text = tostring(msg or "Module belum loaded.")
    t.Parent = body
end

function M.Register(ui, STATE, PetListView)
    PetListView = PetListView or {}

    STATE = rawget(_G, "STATE") or STATE or {}
    _G.STATE = STATE

    STATE.main = STATE.main or {}
    STATE.main.auto_market = STATE.main.auto_market or {}

    local MK = STATE.main.auto_market
    MK.snipe = MK.snipe or {}

    MK.snipe.rules = MK.snipe.rules or {}
    MK.snipe.rulesBase = MK.snipe.rulesBase or {}
    MK.snipe.add = MK.snipe.add or {}
    MK.snipe.addBase = MK.snipe.addBase or {}
    MK.snipe.addSkin = MK.snipe.addSkin or {}
    MK.snipe.ui = MK.snipe.ui or {}
    MK.snipe.uiBase = MK.snipe.uiBase or {}
    MK.snipe.uiSkin = MK.snipe.uiSkin or {}

    -- pet sections: pet-only
    MK.snipe.add.kind = "pet"
    MK.snipe.addBase.kind = "pet"

    local ctxCurrent = {
        rules = MK.snipe.rules,
        add   = MK.snipe.add,
        ui    = MK.snipe.ui,
    }

    local ctxBase = {
        rules = MK.snipe.rulesBase,
        add   = MK.snipe.addBase,
        ui    = MK.snipe.uiBase,
    }

    local ctxSkin = {
        rules = MK.snipe.rules,
        add   = MK.snipe.addSkin,
        ui    = MK.snipe.uiSkin,
    }

    local function autoSave()
        task.defer(function()
            local G = (getgenv and getgenv()) or _G
            local MAIN = rawget(_G, "MAIN") or rawget(G, "MAIN")
            local saveFn = MAIN and (MAIN.save or MAIN.Save)

            if type(saveFn) == "function" then
                pcall(function()
                    saveFn(MAIN)
                end)
            elseif ui and type(ui.SaveState) == "function" then
                pcall(function()
                    ui:SaveState()
                end)
            end
        end)
    end

    local CurrentRule, BaseRule, SkinRule = resolveRuleModules()

    if type(CurrentRule) ~= "table" and type(BaseRule) ~= "table" and type(SkinRule) ~= "table" then
        warn("[ui_tabs_main_snipe] Snipe modules belum di-load (setRuleModules atau shortcut inject)")
        return
    end

    if ui and type(ui.RegisterMainTab) == "function" then
        ui:RegisterMainTab("auto_market", "Snipe", 1)
    end

    ui:RegisterSubTab("auto_market", "snipe", "Snipe", function()
        ui:ClearSubContent()

        CurrentRule, BaseRule, SkinRule = resolveRuleModules()

        MK.snipe.stopIfPetTotal = (MK.snipe.stopIfPetTotal == true)
        MK.snipe.stopPetTotal = math.max(1, math.floor(tonumber(MK.snipe.stopPetTotal) or 180))
        MK.snipe.stopIfSkinTotal = (MK.snipe.stopIfSkinTotal == true)
        MK.snipe.stopSkinTotal = math.max(0, math.floor(tonumber(MK.snipe.stopSkinTotal) or 0))

        local sectionSetters = {}

        local function createSection(title, defaultOpen)
            local body, setExpanded = ui:CreateSection(title, defaultOpen or false)
            local setter
            setter = function(on)
                if on and #sectionSetters >= 3 then
                    for _, fn in ipairs(sectionSetters) do
                        if fn ~= setter then
                            fn(false)
                        end
                    end
                end
                setExpanded(on)
                task.defer(function()
                    if ui.RelayoutContent then
                        ui:RelayoutContent()
                    end
                end)
            end
            table.insert(sectionSetters, setter)
            return body
        end

        local function countPetsNow()
            if PetListView and type(PetListView.listPetsAll) == "function" then
                local ok, list = pcall(PetListView.listPetsAll)
                if ok and type(list) == "table" then
                    return #list
                end
            end
            return 0
        end

        local function countSkinsNow()
            local snipe = rawget(_G, "snipe_loop")
            if type(snipe) == "table" and type(snipe.CountBoothSkinsTotal) == "function" then
                local ok, n = pcall(snipe.CountBoothSkinsTotal)
                if ok and type(n) == "number" then
                    return n
                end
            end
            return 0
        end

        local bodyCurrent = createSection("Snipe Rules Pet ( Current KG )", false)
        local bodyBase    = createSection("Snipe Rules Pet ( Base KG Age 1 )", false)
        local bodySkin    = createSection("Snipe Rules Booth Skin", false)
        local bodyCfg     = createSection("Config Snipe", false)

        if type(CurrentRule) == "table" and type(CurrentRule.Render) == "function" then
            CurrentRule.Render(bodyCurrent, ui, STATE, PetListView, ctxCurrent, autoSave)
        else
            showMissing(bodyCurrent, '<font color="#FFD76A"><b>Pet Current module belum loaded.</b></font>')
        end

        if type(BaseRule) == "table" and type(BaseRule.Render) == "function" then
            BaseRule.Render(bodyBase, ui, STATE, PetListView, ctxBase, autoSave)
        else
            showMissing(bodyBase, '<font color="#FFD76A"><b>Pet Base module belum loaded.</b></font>')
        end

        if type(SkinRule) == "table" and type(SkinRule.Render) == "function" then
            SkinRule.Render(bodySkin, ui, STATE, PetListView, ctxSkin, autoSave)
        else
            showMissing(bodySkin,
