                    pad.PaddingBottom = UDim.new(0, 4)
                    pad.Parent = row
                end
            end
        end

        -- "12 / 180" + warna: hijau = masih jalan, merah = sudah berhenti, abu = toggle OFF
        local function statusText(count, limit, enabled)
            if not enabled then
                return string.format("%d  (Auto Stop OFF)", count), COLOR_IDLE
            end
            if limit < 1 then
                return string.format("%d  (tanpa batas)", count), COLOR_OK
            end
            if count >= limit then
                return string.format("%d / %d  (berhenti)", count, limit), COLOR_STOP
            end
            return string.format("%d / %d", count, limit), COLOR_OK
        end

        local function statusRow()
            local _, t, d = ui:CreateRowLabel(bodyCfg, "Total Sekarang", "-")
            if t then
                t.Font = Enum.Font.GothamBold
            end
            if d then
                d.TextSize = 12
            end
            return d
        end

        -- ① Pet
