        ui:CreateRowInput(
            bodyCfg,
            "Batas Total Pet",
            tostring(MK.snipe.stopPetTotal or 180),
            function(text)
                local n = math.floor(tonumber(text) or 0)
                if n < 1 then n = 1 end
                MK.snipe.stopPetTotal = n
                autoSave()
            end,
            false
        )

        ui:CreateRowToggle(
            bodyCfg,
            "Auto Stop Snipe Pet",
            MK.snipe.stopIfPetTotal == true,
            function(on)
                MK.snipe.stopIfPetTotal = (on == true)
                autoSave()
            end
        )

        -- ② Booth skin
        cfgGroupHeader(
            "Batas Total Booth Skin",
            "Kalau total booth skin yang dimiliki sudah mencapai batas, hanya snipe booth skin yang berhenti. 0 = tanpa batas. Snipe mati total kalau pet & skin sama-sama penuh"
        )
        local skinStatus = statusRow()

        ui:CreateRowInput(
            bodyCfg,
