            tostring(MK.snipe.stopSkinTotal or 0),
            function(text)
                local n = math.floor(tonumber(text) or 0)
                if n < 0 then n = 0 end
                MK.snipe.stopSkinTotal = n
                autoSave()
            end,
            false
        )

        ui:CreateRowToggle(
            bodyCfg,
            "Auto Stop Snipe Booth Skin",
            MK.snipe.stopIfSkinTotal == true,
            function(on)
                MK.snipe.stopIfSkinTotal = (on == true)
                autoSave()
            end
        )

        task.spawn(function()
            while petStatus and petStatus.Parent do
                local txt, col = statusText(
                    countPetsNow(),
                    math.floor(tonumber(MK.snipe.stopPetTotal) or 0),
                    MK.snipe.stopIfPetTotal == true
                )
                petStatus.Text = txt
                petStatus.TextColor3 = col

                if skinStatus then
                    local txt2, col2 = statusText(
                        countSkinsNow(),
