                        MK.snipe.stopIfSkinTotal == true
                    )
                    skinStatus.Text = txt2
                    skinStatus.TextColor3 = col2
                end
                task.wait(2)
            end
        end)

        if #sectionSetters >= 1 then
            for i = 1, #sectionSetters do
                sectionSetters[i](false)
            end
        end
    end, 3)
end

return M

