-- SERVICES
----------------------------------------------------------------
local Players = game:GetService("Players")
local RS = game:GetService("ReplicatedStorage")
local LP = Players.LocalPlayer

----------------------------------------------------------------
-- SAFE REQUIRE
----------------------------------------------------------------
local function waitChild(parent, name, timeout)
    if typeof(parent) ~= "Instance" then
        return nil
    end
    timeout = tonumber(timeout) or 8
    local existing = parent:FindFirstChild(name)
    if existing then
        return existing
    end
    return parent:WaitForChild(name, timeout)
end

local function safeRequire(obj)
    local ok, mod = pcall(require, obj)
    return ok and mod or nil
end

----------------------------------------------------------------
-- REQUIRE MODULES
----------------------------------------------------------------
local modulesFolder = waitChild(RS, "Modules", 10)
local dataFolder = waitChild(RS, "Data", 10)

local ReplicationReciever = modulesFolder and safeRequire(waitChild(modulesFolder, "ReplicationReciever", 8))
local TradeBoothsData     = dataFolder and safeRequire(waitChild(dataFolder, "TradeBoothsData", 8))

local PetUtilities   = nil
local PetMutRegistry = nil
pcall(function()
    local petServices = modulesFolder and modulesFolder:FindFirstChild("PetServices")
    local petUtil = petServices and petServices:FindFirstChild("PetUtilities")
    if petUtil then
        PetUtilities = safeRequire(petUtil)
    end
end)
pcall(function()
    local petReg = dataFolder and dataFolder:FindFirstChild("PetRegistry")
    local mutReg = petReg and petReg:FindFirstChild("PetMutationRegistry")
    if mutReg then
        PetMutRegistry = safeRequire(mutReg)
    end
end)

if not ReplicationReciever then
    return M
end

local Booths = ReplicationReciever.new("Booths")
local ge = waitChild(RS, "GameEvents", 8)
local te = ge and waitChild(ge, "TradeEvents", 8)
local boothsRE = te and waitChild(te, "Booths", 8)
local BuyRF  = boothsRE and waitChild(boothsRE, "BuyListing", 8)

----------------------------------------------------------------
-- OWNER RESOLVE (sesuai referensi kamu)
----------------------------------------------------------------
local function ownerKeyToUserId(ownerKey)
    if type(ownerKey) == "number" then return ownerKey end
    if type(ownerKey) ~= "string" then return nil end
    local n = tonumber(ownerKey)
    if n then return n end
    local idStr = ownerKey:match("^Player_(%d+)$")
    if idStr then return tonumber(idStr) end
    return nil
end

local function resolveOwnerPlayer(ownerKey)
    local uid = ownerKeyToUserId(ownerKey)
    if uid then
        if TradeBoothsData and TradeBoothsData.getPlayerById then
            local plr = TradeBoothsData.getPlayerById(uid)
            if plr then return plr end
        end
        for _, p in ipairs(Players:GetPlayers()) do
            if p.UserId == uid then return p end
        end
    end
    if type(ownerKey) == "string" then
        local p = Players:FindFirstChild(ownerKey)
        if p then return p end
    end
    return nil
end

----------------------------------------------------------------
-- Booths data get
----------------------------------------------------------------
local function safeGetBoothsData()
    local data = Booths:GetData()
    if data and data.Players then return data end
    local ok, d2 = pcall(function()
        if Booths.GetDataAsync then return Booths:GetDataAsync() end
        if Booths.GetAsyncData then return Booths:GetAsyncData() end
        return nil
    end)
    if ok and d2 and d2.Players then return d2 end
    return nil
end

----------------------------------------------------------------
-- Active owners set (THIS SERVER)
----------------------------------------------------------------
local function buildActiveOwnersSet(data)
    local active = {}
    if data and type(data.Booths) == "table" then
        for _, booth in pairs(data.Booths) do
            local owner = booth and booth.Owner
            if owner ~= nil then
                active[owner] = true
                active[tostring(owner)] = true
            end
        end
    end
    if next(active) == nil then
        for _, plr in ipairs(Players:GetPlayers()) do
            local key = plr.UserId
            if TradeBoothsData and TradeBoothsData.getPlayerId then
                local ok, pid = pcall(function() return TradeBoothsData.getPlayerId(plr) end)
                if ok and pid ~= nil then key = pid end
            end
            active[key] = true
            active[tostring(key)] = true
        end
    end
    return active
end

----------------------------------------------------------------
-- KG + Mutation helpers
----------------------------------------------------------------
local function calcPetKGFromItem(item)
    if not PetUtilities or not PetUtilities.CalculateWeight then return nil end
    if type(item) ~= "table" then return nil end
    local pd = item.PetData
    if type(pd) ~= "table" then return nil end
    if pd.BaseWeight == nil or pd.Level == nil then return nil end
    local ok, kg = pcall(function()
        return PetUtilities:CalculateWeight(pd.BaseWeight, pd.Level)
    end)
    if ok and type(kg) == "number" then return kg end
    return nil
end

local function mutationEnumToName(mutEnum)
    if not mutEnum then return "" end
    if PetMutRegistry and PetMutRegistry.EnumToPetMutation then
        local name = PetMutRegistry.EnumToPetMutation[mutEnum]
        return name and tostring(name) or ""
    end
    return ""
end

local function isNoMutationName(name)
    name = tostring(name or "")
    return (name == "" or name == "None" or name == "Normal")
end

