}


local function mkCorner(inst, r)
    local c = Instance.new("UICorner")
    c.CornerRadius = UDim.new(0, r or 6)
    c.Parent = inst
    return c
end

local function mkStroke(inst, t, color)
    local s = Instance.new("UIStroke")
    s.Thickness = t or 1
    s.Transparency = THEME.strokeT
    s.Color = color or THEME.yellow
    s.Parent = inst
    return s
end

local function clearChildren(frame)
    for _, ch in ipairs(frame:GetChildren()) do
        if not ch:IsA("UIListLayout") and not ch:IsA("UIPadding") then
            ch:Destroy()
        end
    end
end

local function fmtNum(n)
    n = tonumber(n) or 0
    local a = math.abs(n)
    if a >= 1e12 then return string.format("%.2fT", n/1e12) end
    if a >= 1e9  then return string.format("%.2fB", n/1e9) end
    if a >= 1e6  then return string.format("%.2fM", n/1e6) end
    if a >= 1e3  then return string.format("%.2fK", n/1e3) end
    return tostring(math.floor(n + 0.5))
end

local function fmtKg(kg)
    if type(kg) ~= "number" then return "-" end
    if kg >= 1000 then
        return string.format("%.1fK", kg/1000)
    end
    return string.format("%.2f", kg)
end

local function normStr(s)
    s = tostring(s or "")
    return (s:gsub("\n"," "):gsub("\r"," "))
end

local function toNumOrNil(txt)
    if txt == nil then return nil end
    txt = tostring(txt):gsub(",", ""):gsub("%s+", "")
    if txt == "" then return nil end
    return tonumber(txt)
end

local function toIntOrNil(txt)
    local n = toNumOrNil(txt)
    if n == nil then return nil end
    return math.floor(n + 0.0001)
end

----------------------------------------------------------------
-- LISTING COLLECTOR
----------------------------------------------------------------
local function collectListingsServerOnly()
    local data = safeGetBoothsData()
    if not data or type(data.Players) ~= "table" then
        return {}, "data_unavailable"
    end

    local activeOwners = buildActiveOwnersSet(data)
    local out = {}

    for ownerKey, rec in pairs(data.Players) do
        local okOwner = (activeOwners[ownerKey] == true) or (activeOwners[tostring(ownerKey)] == true)
        if okOwner and rec and type(rec.Listings) == "table" and type(rec.Items) == "table" then
            for listingUUID, li in pairs(rec.Listings) do
                if li and li.ItemType == "Pet" and type(li.Price) == "number" and li.ItemId ~= nil then
                    local item = rec.Items[li.ItemId]
                    if item then
                        local petType = item.PetType
                        if type(petType) == "string" and petType ~= "" then
                            local pd = item.PetData
                            local age = nil
                            local mutName = ""
                            local kg = nil

                            if type(pd) == "table" then
                                if pd.Level ~= nil then age = tonumber(pd.Level) end
                                mutName = mutationEnumToName(pd.MutationType)
                                kg = calcPetKGFromItem(item)
                            end

                            table.insert(out, {
                                ownerKey = ownerKey,
                                listingUUID = listingUUID,
                                price = li.Price,
                                petType = petType,
                                age = age,
                                kg = kg,
                                mutation = mutName or "",
                            })
                        end
                    end
                end
            end
        end
    end

    table.sort(out, function(a, b)
        if a.price == b.price then
            return tostring(a.petType) < tostring(b.petType)
        end
        return a.price < b.price
    end)

    return out, nil
end

----------------------------------------------------------------
-- BUY
----------------------------------------------------------------
local function doBuy(ownerKey, listingUUID)
    local ownerPlayer = resolveOwnerPlayer(ownerKey)
    if not ownerPlayer then
        return false
    end
    if not BuyRF then
        return false
    end
    local ok, r1 = pcall(function()
        return BuyRF:InvokeServer(ownerPlayer, listingUUID)
    end)
    return (ok and r1 == true) or false
end

----------------------------------------------------------------
-- FILTER
----------------------------------------------------------------
local function passesFilters(rec, F)
    if F.q and F.q ~= "" then
        local s = tostring(rec.petType or ""):lower()
        if not s:find(F.q, 1, true) then return false end
    end

    if F.mutMode == "no" then
        if not isNoMutationName(rec.mutation) then return false end
    elseif F.mutMode == "has" then
        if isNoMutationName(rec.mutation) then return false end
    end

    if F.ageMin ~= nil and (tonumber(rec.age) or -1) < F.ageMin then return false end
    if F.ageMax ~= nil and (tonumber(rec.age) or -1) > F.ageMax then return false end

    if F.kgMin ~= nil and (tonumber(rec.kg) or -1) < F.kgMin then return false end
    if F.kgMax ~= nil and (tonumber(rec.kg) or -1) > F.kgMax then return false end

    if F.priceMin ~= nil and (tonumber(rec.price) or 0) < F.priceMin then return false end
    if F.priceMax ~= nil and (tonumber(rec.price) or 0) > F.priceMax then return false end

    return true
end


-- Geser text header per kolom (HANYA header)
local HEADER_SHIFT = {
    pet   = 6,
    mut   = 0,
    age   = 8,  -- << lebih kanan
    kg    = 8,  -- << lebih kanan
    price = 40,  -- << lebih kanan (karena align right)
    act   = 15,  -- << lebih kanan
}

local HEADER_SHIFT_X = 10

local shift = isHeader and HEADER_SHIFT_X or 0

local function makeHeadCell(parent, colKey, x, w, text, align)
    local lbl = Instance.new("TextLabel")
    lbl.BackgroundTransparency = 1
    lbl.Text = text or ""
    lbl.Font = Enum.Font.GothamBold
    lbl.TextSize = 12
    lbl.TextColor3 = THEME.text
    lbl.TextXAlignment = align or Enum.TextXAlignment.Left
    lbl.Size = UDim2.new(0, w, 1, 0)

    local shift = HEADER_SHIFT[colKey] or 0
    lbl.Position = UDim2.new(0, x + shift, 0, 0)

    lbl.Parent = parent
    return lbl
end

----------------------------------------------------------------
-- COLUMN LAYOUT (lebih compact)
----------------------------------------------------------------
local function computeColumns(totalW)
local PAD_L, PAD_R = 10, 10
local GAP = 4         -- dari 8 -> 5 (lebih rapat)
local actionW = 54     -- dari 74 -> 54 (lebih kecil, tombol ga keluar)
local RIGHT_COL_PAD = 30   -- geser kiri sedikit utk kolom price/action
local RIGHT_COL_ACT = 20   -- geser kiri sedikit utk kolom price/action

    local usable = math.max(280, (totalW or 700) - PAD_L - PAD_R - actionW - (GAP * 5))

    -- Pet 30% | Mut 22% | Age 10% | KG 14% | Price sisanya
    local petW   = math.floor(usable * 0.30)
    local mutW   = math.floor(usable * 0.22)
    local ageW   = math.floor(usable * 0.10)
    local kgW    = math.floor(usable * 0.14)
    local priceW = math.max(56, usable - (petW + mutW + ageW + kgW))

    local x = PAD_L
    local map = {}
    map.pet   = { x = x, w = petW }   ; x = x + petW + GAP
    map.mut   = { x = x, w = mutW }   ; x = x + mutW + GAP
    map.age   = { x = x, w = ageW }   ; x = x + ageW + GAP
    map.kg    = { x = x, w = kgW }    ; x = x + kgW + GAP
    map.price = { x = x, w = priceW } ; x = x + priceW + GAP
    map.act   = { x = x, w = actionW }
    -- geser kiri sedikit utk price & action biar tidak kepentok kanan
map.price.x = map.price.x - RIGHT_COL_PAD
map.act.x   = map.act.x   - RIGHT_COL_ACT


    return map
end



local function makeCell(parent, x, w, text, isHeader, align)
    local lbl = Instance.new("TextLabel")
    lbl.BackgroundTransparency = 1
    lbl.Text = text or ""
    lbl.Font = isHeader and Enum.Font.GothamBold or Enum.Font.Gotham
    lbl.TextSize = isHeader and 12 or 12
    lbl.TextColor3 = isHeader and THEME.text or THEME.subtext
    lbl.TextXAlignment = align or Enum.TextXAlignment.Left

    lbl.Size = UDim2.new(0, w, 1, 0)

    local shift = (isHeader and (align == Enum.TextXAlignment.Left)) and HEADER_SHIFT_X or 0
    lbl.Position = UDim2.new(0, x + shift, 0, 0)

    lbl.Parent = parent
    return lbl
end


