local function applyMiniBoxStyle(t)
    t.Font = Enum.Font.GothamMedium
    t.TextSize = 11
    t.TextColor3 = THEME.text
    t.PlaceholderColor3 = THEME.hint
    t.ClearTextOnFocus = false
    t.BackgroundColor3 = THEME.bg
    t.BorderSizePixel = 0

    mkCorner(t, 7)
    local st = mkStroke(t, 1, THEME.yellow)
    st.Transparency = 100

    -- padding (hindari double padding: hapus padding lama kalau ada)
    for _, ch in ipairs(t:GetChildren()) do
        if ch:IsA("UIPadding") then ch:Destroy() end
    end
    local p = Instance.new("UIPadding")
    p.PaddingLeft = UDim.new(0, 7)
    p.PaddingRight = UDim.new(0, 7)
    p.Parent = t

    -- biar teks makin kebaca di background gelap
    t.TextStrokeColor3 = Color3.fromRGB(0,0,0)
    t.TextStrokeTransparency = 0.85

    return t
end

