    local t = Instance.new("TextBox")
    t.Text = ""
    t.PlaceholderText = ph or ""
    t.Size = UDim2.new(0, w, 0, 22)
    t.Parent = parent
    return applyMiniBoxStyle(t)
end

local function makeMiniBtnBare(w, text, fill)
