    if fill then
        applyYellowButtonFill(b, text)
        b.TextSize = 11
    else
        applyYellowButton(b, text)
        b.TextSize = 11
    end

    -- text lebih jelas
    b.TextStrokeColor3 = Color3.fromRGB(0,0,0)
    b.TextStrokeTransparency = 0.82

    return b
end

