-- WRAP LAYOUT (REPOSITION, NO CLEAR/DESTROY)
----------------------------------------------------------------
local GAP = 6

local function placeTo(parent, obj, x)
    obj.Position = UDim2.new(0, x, 0, 0)
    obj.Parent = parent
end

local function layoutFilterRow()
    local w1 = wrap1.AbsoluteSize.X
    if w1 <= 10 then return end

    -- update wrap2 width (kalau reset berubah)
    wrap2.Size = UDim2.new(1, -(resetBtn.AbsoluteSize.X + 8), 1, 0)

    local x1, x2 = 0, 0

    local function tryPlace(obj, w)
        obj.Size = UDim2.new(0, w, 0, 22)
        if (x1 + w) <= w1 then
            placeTo(wrap1, obj, x1)
            x1 = x1 + w + GAP
        else
            placeTo(wrap2, obj, x2)
            x2 = x2 + w + GAP
        end
    end

    tryPlace(mutBtn,    150)
    tryPlace(ageMinBox, 52)
    tryPlace(ageMaxBox, 52)
    tryPlace(kgMinBox,  60)
    tryPlace(kgMaxBox,  60)
    tryPlace(pMinBox,   72)
    tryPlace(pMaxBox,   72)

    -- reset tetap di kanan line2
    resetBtn.Parent = line2
end

-- Reflow saat size berubah (aman)
