local function confirmBuy(uiObj, rec, onYes, onNo)
    if not uiObj or type(uiObj.Confirm) ~= "function" then
        -- fallback: langsung jalan
        if onYes then onYes() end
        return
    end

    local petType = tostring(rec.petType or "-")
    local mut = tostring(rec.mutation or "")
    if mut == "" or mut == "None" or mut == "Normal" then mut = "-" end

    local ageText = (rec.age ~= nil) and tostring(math.floor((tonumber(rec.age) or 0) + 0.5)) or "-"
    local kgText  = (type(rec.kg) == "number") and string.format("%.2f", rec.kg) or "-"
    local priceText = fmtNum(rec.price)

    uiObj:Confirm({
        title = "KONFIRMASI PEMBELIAN",
        badge = "LIST SNIPE",
        meta  = "Pastikan Token Cukup",
        lines = {
            ("• Pet Type: <b>%s</b>"):format(petType),
            ("• Mutation: <b>%s</b>"):format(mut),
            ("• Age: <b>%s</b>"):format(ageText),
            ("• KG: <b>%s</b>"):format(kgText),
            ("• Price: <b>%s</b>"):format(priceText),
        },
        onYes = function()
            if onYes then onYes() end
        end,
        onNo = function()
            if onNo then onNo() end
        end,
    })
end

