            -- tabs_misc.lua
-- Main tab "Misc" → Auto Trade (Trading Ticket)

local M = {}

function M.Register(ui, STATE, PetListView)
    PetListView = PetListView or {
        buildPetItems = function() return {} end,
    }

    STATE.trade_cfg = STATE.trade_cfg or TRADE_CFG or {}
    STATE.TRADE_CFG = STATE.trade_cfg
    TRADE_CFG = STATE.trade_cfg
    _G.TRADE_CFG = STATE.trade_cfg
    local tradeCfg = STATE.trade_cfg

    STATE.chat_cfg = STATE.chat_cfg or {}
    local chatCfg = STATE.chat_cfg
    chatCfg.enabled = chatCfg.enabled == true
    chatCfg.mode = nil
    chatCfg.text = tostring(chatCfg.text or "")
    do
        local n = math.floor(tonumber(chatCfg.intervalSec) or 45)
        if n < 30 then n = 30 end
        if n > 86400 then n = 86400 end
        chatCfg.intervalSec = n
        if #chatCfg.text > 200 then
            local cut = 200
            while cut > 0 do
                local b = string.byte(chatCfg.text, cut)
                if b and b >= 128 and b < 192 then
                    cut = cut - 1
                else
                    break
                end
            end
            chatCfg.text = chatCfg.text:sub(1, cut)
        end
    end

    STATE.pet_hold_cfg = STATE.pet_hold_cfg or {}
    local holdCfg = STATE.pet_hold_cfg
    holdCfg.enabled = holdCfg.enabled == true
    holdCfg.mode = (tostring(holdCfg.mode or "manual"):lower() == "auto") and "auto" or "manual"
    holdCfg.selected = holdCfg.selected or {}
    holdCfg.switchDelay = math.max(1, math.floor(tonumber(holdCfg.switchDelay) or 5))
    _G.PET_HOLD_SWITCH_DELAY = holdCfg.switchDelay

    local function autoSave()
        if ui and type(ui.SaveState) == "function" then
            task.defer(function()
                pcall(function() ui:SaveState() end)
            end)
        end
    end

    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    local function _nameKey(name)
        return "name:" .. tostring(name or "")
    end

    local function _isNameKey(k)
        k = tostring(k or "")
        return k:sub(1, 5) == "name:"
    end

    local function _nameFromKey(k)
        k = tostring(k or "")
        if k:sub(1, 5) == "name:" then
            return k:sub(6)
        end
        return k
    end

    local function _migrateTradeTargetsToStableKeys()
        local src = tradeCfg.targets
        if type(src) ~= "table" then
            tradeCfg.targets = {}
            return
        end

        local dst = {}
        local changed = false

        for k, v in pairs(src) do
            local kStr = tostring(k)

            if type(v) == "table" then
                local uid = tonumber(v.userId) or tonumber(kStr)
                local nm  = tostring(v.name or "")

                if uid then
                    dst[tostring(uid)] = {
                        userId = uid,
                        name   = (nm ~= "" and nm) or ("UserId " .. tostring(uid)),
                    }
                else
                    local name = (nm ~= "" and nm) or (_isNameKey(kStr) and _nameFromKey(kStr) or kStr)
                    local plr = Players:FindFirstChild(name)
                    if plr then
                        dst[tostring(plr.UserId)] = { userId = plr.UserId, name = plr.Name }
                        changed = true
                    else
                        dst[_nameKey(name)] = { userId = nil, name = name }
                        changed = true
                    end
                end

            elseif v == true then
                local name = _isNameKey(kStr) and _nameFromKey(kStr) or kStr
                local plr = Players:FindFirstChild(name)
                if plr then
                    dst[tostring(plr.UserId)] = { userId = plr.UserId, name = plr.Name }
                    changed = true
                else
                    dst[_nameKey(name)] = { userId = nil, name = name }
                    changed = true
                end
            end
        end

        tradeCfg.targets = dst
        if changed then
            autoSave()
        end
    end

    local function getTargetItems()
        local items = {}
        local seenUid = {}
        local seenName = {}

        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LocalPlayer then
                local uidStr = tostring(plr.UserId)
                seenUid[uidStr] = true
                seenName[string.lower(plr.Name)] = true
                items[#items + 1] = {
                    key    = uidStr,
                    name   = plr.Name,
                    userId = plr.UserId,
                }
            end
        end

        local src = tradeCfg.targets
        if type(src) == "table" then
            for k, info in pairs(src) do
                local keyStr = tostring(k)
                local uid = tonumber(keyStr)

                if uid then
                    if not seenUid[keyStr] then
                        local nm = (type(info) == "table" and info.name) or ("UserId " .. keyStr)
                        items[#items + 1] = {
                            key    = keyStr,
                            name   = tostring(nm) .. " (offline)",
                            userId = uid,
                        }
                    end
                elseif _isNameKey(keyStr) then
                    local nm = (type(info) == "table" and info.name) or _nameFromKey(keyStr)
                    local low = string.lower(nm or "")
                    if low ~= "" and not seenName[low] then
                        items[#items + 1] = {
                            key    = keyStr,
                            name   = tostring(nm) .. " (offline)",
                            userId = nil,
                        }
                    end
                end
            end
        end

        table.sort(items, function(a, b)
            return tostring(a.name):lower() < tostring(b.name):lower()
        end)

        return items
    end

    local function parseSignedNumber(text)
        text = tostring(text or ""):gsub(",", ".")
        if text == "" or text == "-" then return nil, "partial" end
        local n = tonumber(text)
        if n == nil then return nil, "invalid" end
        return n, "ok"
    end

    ui:RegisterMainTab("misc", "Misc", 4)
    if ui.SetFooterButtonsFor then
        ui:SetFooterButtonsFor("misc", {})
    end

    local function cleanSelectedMap(selectedMap)
        local out = {}
        if type(selectedMap) ~= "table" then
            return out
        end
        for k, v in pairs(selectedMap) do
            if v == true then
                out[tostring(k)] = true
            elseif type(k) == "number" and (type(v) == "string" or type(v) == "number") then
                local s = tostring(v)
                if s ~= "" then out[s] = true end
            elseif type(k) == "number" and type(v) == "table" then
                local kk = v.key or v.name or v.id
                if kk then out[tostring(kk)] = true end
            elseif type(k) == "string" and type(v) == "table" then
                out[tostring(k)] = true
            end
        end
        return out
    end

    local function normalizeDropdownItems(list)
        local out = {}
        if type(list) ~= "table" then return out end
        for _, it in ipairs(list) do
            if type(it) == "string" then
                out[#out + 1] = { key = it, name = it }
            elseif type(it) == "table" then
                local k = it.key or it.name or it.id
                local n = it.name or it.key or it.id
                if k and n then
                    out[#out + 1] = { key = tostring(k), name = tostring(n) }
                end
            end
        end
        return out
    end

    ui:RegisterSubTab("misc", "trade", "Auto Trade", function()
        ui:ClearSubContent()

