        local sendNowSetGet

        local function refreshStatus()
            if not (statusRow and statusRow.Parent) then return end
            if sendNowSetGet and type(sendNowSetGet) == "function" then
                local want = tradeCfg.sendNow == true
                if sendNowSetGet() ~= want then
                    sendNowSetGet(want)
                end
            end
            local AT = resolveAutoTrade()
            local progress = "Menunggu module gift..."
            if AT and type(AT.GetDebugStatus) == "function" then
                local ok, a = pcall(function()
                    return AT.GetDebugStatus()
                end)
                if ok and type(a) == "string" and a ~= "" then
                    progress = a
                elseif not ok then
                    progress = "Status error: " .. tostring(a)
                end
            end
            if statusDetail then
                statusDetail.Text = progress
            else
                statusTitle.Text = progress
            end
        end

        refreshStatus()
        task.spawn(function()
            while statusRow and statusRow.Parent do
                refreshStatus()
                task.wait(0.5)
            end
        end)

        ui:CreateRowDropdown(bodyTrade, {
            label       = "Target",
            placeholder = "Pilih target trade...",
            mode        = "multi",
            getItems    = function()
                _migrateTradeTargetsToStableKeys()
                return getTargetItems()
            end,
            initial = (function()
                local map = {}
                if type(tradeCfg.targets) == "table" then
                    for k, _ in pairs(tradeCfg.targets) do
                        map[tostring(k)] = true
                    end
                end
                return map
            end)(),
            onChanged = function(_, selectedMap)
                local dst = {}
                if type(selectedMap) == "table" then
                    for keyStr, on in pairs(selectedMap) do
                        if on then
                            keyStr = tostring(keyStr)
                            local uid = tonumber(keyStr)

                            if uid then
                                local plr = Players:GetPlayerByUserId(uid)
                                local name = plr and plr.Name or nil
                                local old = tradeCfg.targets and tradeCfg.targets[keyStr]
                                if not name and type(old) == "table" and old.name then
                                    name = old.name
                                end
                                if not name then
                                    name = "UserId " .. keyStr
                                end
                                dst[keyStr] = { userId = uid, name = name }

                            elseif _isNameKey(keyStr) then
                                local name = _nameFromKey(keyStr)
                                local plr = Players:FindFirstChild(name)
                                if plr then
                                    local uidStr = tostring(plr.UserId)
                                    dst[uidStr] = { userId = plr.UserId, name = plr.Name }
                                else
                                    local old = tradeCfg.targets and tradeCfg.targets[keyStr]
                                    if type(old) == "table" and old.name and old.name ~= "" then
                                        name = old.name
                                    end
                                    dst[keyStr] = { userId = nil, name = name }
                                end
                            end
                        end
                    end
                end
                tradeCfg.targets = dst
                autoSave()
            end,
        })

        local petRows = {}
        local currencyRows = {}
        local amountRow = nil

        local function syncCategoryUI()
            local cat = tostring(tradeCfg.category or "pet"):lower()
            local isPet = (cat == "pet")
            local isCurrency = (cat == "token" or cat == "shekels")
            for _, r in ipairs(petRows) do
                if r and r.Parent then r.Visible = isPet end
            end
            for _, r in ipairs(currencyRows) do
                if r and r.Parent then r.Visible = isCurrency end
            end
            if amountRow and amountRow.Parent then
                local mode = tostring(tradeCfg.currencySendMode or "all"):lower()
                amountRow.Visible = isCurrency and mode == "input"
            end
        end

        ui:CreateRowDropdown(bodyTrade, {
            label       = "Category",
            placeholder = "Select category...",
            mode        = "single",
            getItems    = function()
                return { "Pet", "Token", "Shekels" }
            end,
            initial = (function()
                local c = tostring(tradeCfg.category or "pet"):lower()
                if c == "token" then return "Token" end
                if c == "shekels" then return "Shekels" end
                return "Pet"
            end)(),
            onChanged = function(_, selected)
                local v = tostring(selected or "Pet"):lower()
                if v == "token" then tradeCfg.category = "token"
                elseif v == "shekels" then tradeCfg.category = "shekels"
                else tradeCfg.category = "pet"
                end
                autoSave()
                syncCategoryUI()
            end,
        })

        local petTypeRow = ui:CreateRowDropdown(bodyTrade, {
            label       = "Select Pet Type",
            placeholder = "Select Pet...",
            mode        = "multi",
            getItems    = function() return PetItems end,
            initial     = tradeCfg.petType or {},
            onChanged   = function(_, selectedMap)
                tradeCfg.petType = {}
                if type(selectedMap) == "table" then
                    for petName, enabled in pairs(selectedMap) do
                        if enabled then
                            tradeCfg.petType[petName] = true
                        end
                    end
                end
                autoSave()
            end,
        })
        table.insert(petRows, petTypeRow)

        local ageRow = ui:CreateRowInput(bodyTrade, "Age", tostring(tradeCfg.minAge or 0), function(text)
            local num = parseSignedNumber(text)
            if num == nil then return end
            tradeCfg.minAge = num
            autoSave()
        end)
        table.insert(petRows, ageRow)

        local kgRow = ui:CreateRowInput(bodyTrade, "KG ( Assumed at age 100 )", tostring(tradeCfg.minKG or 0), function(text)
            local num, st = parseSignedNumber(text)
            if st ~= "ok" then return end
            tradeCfg.minKG = num
            autoSave()
        end)
        table.insert(petRows, kgRow)

        local amountModeRow = ui:CreateRowDropdown(bodyTrade, {
            label       = "Amount Mode",
            placeholder = "Select amount mode...",
            mode        = "single",
            getItems    = function()
                return { "Send All", "Input" }
            end,
            initial = (function()
                if tostring(tradeCfg.currencySendMode or "all"):lower() == "input" then
                    return "Input"
                end
                return "Send All"
            end)(),
            onChanged = function(_, selected)
                local v = tostring(selected or "Send All"):lower()
                if v:find("input", 1, true) then
                    tradeCfg.currencySendMode = "input"
                else
                    tradeCfg.currencySendMode = "all"
                end
                autoSave()
                syncCategoryUI()
            end,
        })
        table.insert(currencyRows, amountModeRow)

        amountRow = ui:CreateRowInput(bodyTrade, "Amount", tostring(tradeCfg.currencyAmount or 0), function(text)
            local num, st = parseSignedNumber(text)
            if st ~= "ok" or num == nil then return end
            if num < 0 then num = 0 end
            tradeCfg.currencyAmount = math.floor(num)
            autoSave()
        end)
        table.insert(currencyRows, amountRow)

        syncCategoryUI()

        ui:CreateRowDropdown(bodyTrade, {
            label       = "Send Mode",
            placeholder = "Select send mode...",
            mode        = "single",
            getItems    = function()
                return { "Send Auto", "Send Once" }
            end,
            initial = (function()
                if tostring(tradeCfg.sendMode or "auto"):lower() == "once" then
                    return "Send Once"
                end
                return "Send Auto"
            end)(),
            onChanged = function(_, selected)
                local v = tostring(selected or "Send Auto"):lower()
                if v:find("once", 1, true) then
                    tradeCfg.sendMode = "once"
                else
                    tradeCfg.sendMode = "auto"
                end
                autoSave()
            end,
        })

        _, sendNowSetGet = ui:CreateRowToggle(bodyTrade, "Send Now", tradeCfg.sendNow == true, function(isOn)
            tradeCfg.sendNow = isOn and true or false
            autoSave()
        end)

        ui:CreateRowToggle(bodyAccept, "Auto Accept Trade", tradeCfg.autoAcceptTrade == true, function(isOn)
            tradeCfg.autoAcceptTrade = isOn and true or false
            autoSave()
        end)

        if setTradeExpanded then setTradeExpanded(true) end
        if setAcceptExpanded then setAcceptExpanded(false) end
    end, 2)

