            if shopListsReady or shopListsLoading then return end
            shopListsLoading = true
            task.spawn(function()
                local ok, a, b, c, d, e, f, g, h = pcall(function()
                    if type(AutoBuy.GetLists) == "function" then
                        return AutoBuy.GetLists()
                    end
                    return {}, {}, {}, {}, {}, {}, {}, {}
