    ui:RegisterSubTab("misc", "gear", "⚙", function()
        ui:ClearSubContent()

        local function isPetTool(tool)
            if not (tool and tool:IsA("Tool")) then return false end
            local it = tool:GetAttribute("ItemType") or tool:GetAttribute("Itemtype")
            return it and string.lower(tostring(it)) == "pet"
        end

        local function toolUuid(tool)
            if not tool then return nil end
            return tool:GetAttribute("PET_UUID") or tool:GetAttribute("UUID") or tool:GetAttribute("PetUUID")
        end

        local function buildBackpackPetTypeItems()
            local grouped = {}
            local bp = LocalPlayer:FindFirstChildOfClass("Backpack")
                or LocalPlayer:FindFirstChild("Backpack")
            if not bp then return {} end

            local _, index, helpers
            if PetListView and type(PetListView.getDatastoreBagIndex) == "function" then
                local ok, bag, idx, hlp = pcall(PetListView.getDatastoreBagIndex)
                if ok then
                    index = idx
                    helpers = hlp
                end
            end

            for _, tool in ipairs(bp:GetChildren()) do
                if not isPetTool(tool) then
                    continue
                end

                local idAttr = toolUuid(tool)
                local ptype, label

                if index and helpers and idAttr then
                    local core, br = helpers.normUUID(idAttr)
                    local rec = index[core] or index[br]
                    if rec then
                        local PD = rec.PetData or rec.Data or {}
                        local petTypeRaw = rec.Type or rec.PetType or PD.Type or PD.PetType or rec.Name or PD.Name or tool.Name
                        ptype = tostring(petTypeRaw):lower()
                        label = tostring(petTypeRaw)
                    end
                end

                if not ptype then
                    ptype = tostring(tool.Name):lower()
                    label = tostring(tool.Name)
                end

                if not grouped[ptype] then
                    grouped[ptype] = { label = label, count = 0 }
                end
                grouped[ptype].count += 1
            end

            local items = {}
            for ptype, info in pairs(grouped) do
                items[#items + 1] = {
                    key  = ptype,
                    name = string.format("%s x %d", info.label, info.count),
                }
            end

            table.sort(items, function(a, b)
                return tostring(a.name) < tostring(b.name)
            end)
            return items
        end

        local bodyHold, setHoldExpanded = ui:CreateSection("Auto Hold Pet", true)
        local manualPetRow

        local function syncHoldModeUI()
            local isManual = tostring(holdCfg.mode or "manual"):lower() == "manual"
            if manualPetRow then
                manualPetRow.Visible = isManual
            end
        end

        ui:CreateRowDropdown(bodyHold, {
            label       = "Mode",
            placeholder = "Select mode...",
            mode        = "single",
            getItems    = function()
                return {
                    { key = "manual", name = "Manual" },
                    { key = "auto",   name = "Auto (Listed)" },
                }
            end,
            initial = holdCfg.mode,
            onChanged = function(_, selected)
                holdCfg.mode = (tostring(selected or ""):lower() == "auto") and "auto" or "manual"
                syncHoldModeUI()
                autoSave()
            end,
        })

        manualPetRow = ui:CreateRowDropdown(bodyHold, {
            label       = "Pet Type",
            placeholder = "Pilih tipe pet di backpack...",
            mode        = "multi",
            getItems    = function()
                return buildBackpackPetTypeItems()
            end,
            initial = holdCfg.selected,
            onChanged = function(_, selectedMap)
                holdCfg.selected = selectedMap or {}
                autoSave()
            end,
        })

        ui:CreateRowInput(bodyHold, "Switch Delay (Seconds)", tostring(holdCfg.switchDelay or 5), function(text)
            local n = tonumber(text)
            if not n then
                n = tonumber(tostring(text or ""):match("([%d%.]+)"))
            end
            if n then
                holdCfg.switchDelay = math.max(1, math.floor(n))
                _G.PET_HOLD_SWITCH_DELAY = holdCfg.switchDelay
                autoSave()
            end
        end)

        local holdStatusRow, _, holdStatusDetail = ui:CreateRowLabel(bodyHold, "Status", "Idle", 1)
        holdStatusDetail = holdStatusDetail or (holdStatusRow and holdStatusRow:FindFirstChild("DescLabel"))

        ui:CreateRowToggle(bodyHold, "Enabled", holdCfg.enabled == true, function(isOn)
            holdCfg.enabled = isOn and true or false
            _G.PET_HOLD_SWITCH_DELAY = holdCfg.switchDelay
            autoSave()
        end)

        task.spawn(function()
            while bodyHold and bodyHold.Parent do
                pcall(function()
                    if not (holdStatusDetail and holdStatusDetail.Parent) then return end
                    local loop = rawget(_G, "pet_hold_loop")
                    local txt = "Idle"
                    if type(loop) == "table" and type(loop.GetDebugStatus) == "function" then
                        local ok, a, b = pcall(loop.GetDebugStatus)
                        if ok then
                            txt = tostring(a or "")
                            if type(b) == "string" and b ~= "" then
                                txt = txt .. "  " .. b
                            end
                        end
                    end
                    holdStatusDetail.Text = txt
                end)
                task.wait(1)
            end
        end)

        syncHoldModeUI()
        if setHoldExpanded then setHoldExpanded(true) end

        ----------------------------------------------------------------
        -- Auto Chat
        ----------------------------------------------------------------
        do
            local st = rawget(_G, "STATE") or STATE
            if type(st) == "table" then
                st.chat_cfg = st.chat_cfg or chatCfg
                chatCfg = st.chat_cfg
            end
        end

        chatCfg.enabled = chatCfg.enabled == true
        chatCfg.mode = nil
        do
            local n = math.floor(tonumber(chatCfg.intervalSec) or 45)
            if n < 30 then n = 30 end
            if n > 86400 then n = 86400 end
            chatCfg.intervalSec = n
        end
        chatCfg.text = tostring(chatCfg.text or "")

        local bodyChat, setChatExpanded = ui:CreateSection("Auto Chat", false)

        local statusRow, statusTitle, statusDetail = ui:CreateRowLabel(bodyChat, "Status", "Idle  0/200", 1)
        statusDetail = statusDetail or statusRow:FindFirstChild("DescLabel")
        if statusDetail then
            statusDetail.TextWrapped = true
            statusDetail.TextYAlignment = Enum.TextYAlignment.Top
            statusDetail.Size = UDim2.new(1, 0, 0, 40)
            statusRow.Size = UDim2.new(1, 0, 0, 58)
        end

        local function resolveAutoChat()
            local G = (getgenv and getgenv()) or _G
            return G.AutoChat or G.auto_chat
        end

        local function refreshChatStatus()
            if not (statusRow and statusRow.Parent) then return end
            local AC = resolveAutoChat()
            local txt = "Idle  0/200"
            if AC and type(AC.GetDebugStatus) == "function" then
                local ok, a = pcall(function()
                    return AC.GetDebugStatus()
                end)
                if ok and type(a) == "string" and a ~= "" then
                    txt = a
                elseif not ok then
                    txt = "Status error: " .. tostring(a)
                end
            end
            if statusDetail then
                statusDetail.Text = txt
            elseif statusTitle then
                statusTitle.Text = txt
            end
        end

        local msgRow = Instance.new("Frame")
        msgRow.Name = "ChatMessageRow"
        msgRow.BackgroundTransparency = 1
        msgRow.Size = UDim2.new(1, 0, 0, 64)
        msgRow.LayoutOrder = #bodyChat:GetChildren() + 1
        msgRow.Parent = bodyChat

        local msgLabel = Instance.new("TextLabel")
        msgLabel.BackgroundTransparency = 1
        msgLabel.Size = UDim2.new(1, 0, 0, 16)
        msgLabel.Font = Enum.Font.Gotham
        msgLabel.TextSize = 12
        msgLabel.TextXAlignment = Enum.TextXAlignment.Left
        msgLabel.TextColor3 = Color3.fromRGB(180, 180, 180)
        msgLabel.Text = "Message  0/200"
        msgLabel.Parent = msgRow

        local msgBoxWrap = Instance.new("Frame")
        msgBoxWrap.Name = "MessageBox"
        msgBoxWrap.Size = UDim2.new(1, -4, 0, 42)
        msgBoxWrap.Position = UDim2.new(0, 0, 0, 18)
        msgBoxWrap.BackgroundColor3 = Color3.fromRGB(10, 10, 10)
        msgBoxWrap.BackgroundTransparency = 0.05
        msgBoxWrap.Parent = msgRow
        local msgCorner = Instance.new("UICorner")
        msgCorner.CornerRadius = UDim.new(0, 8)
        msgCorner.Parent = msgBoxWrap
        local msgStroke = Instance.new("UIStroke")
        msgStroke.Color = Color3.fromRGB(255, 220, 0)
        msgStroke.Thickness = 1
        msgStroke.Transparency = 0.35
        msgStroke.Parent = msgBoxWrap

        local msgBox = Instance.new("TextBox")
        msgBox.BackgroundTransparency = 1
        msgBox.Size = UDim2.new(1, -16, 1, -6)
        msgBox.Position = UDim2.new(0, 8, 0, 3)
        msgBox.Font = Enum.Font.Gotham
        msgBox.TextSize = 12
        msgBox.TextXAlignment = Enum.TextXAlignment.Left
        msgBox.TextYAlignment = Enum.TextYAlignment.Center
        msgBox.TextColor3 = Color3.fromRGB(230, 230, 230)
        msgBox.ClearTextOnFocus = false
        msgBox.TextTruncate = Enum.TextTruncate.AtEnd
        msgBox.PlaceholderText = "looking for offers on golden lab"
        msgBox.Text = tostring(chatCfg.text or "")
        msgBox.Parent = msgBoxWrap

        local function clampChatTextLocal(s)
            s = tostring(s or "")
            if #s <= 200 then return s end
            local cut = 200
            while cut > 0 do
                local b = string.byte(s, cut)
                if b and b >= 128 and b < 192 then
                    cut = cut - 1
                else
                    break
                end
            end
            return s:sub(1, cut)
        end

        local function refreshMsgCounter()
            msgLabel.Text = string.format("Message  %d/200", #tostring(chatCfg.text or ""))
        end

        local committing = false
        local function commitMessage()
            if committing then return end
            committing = true
            local clipped = clampChatTextLocal(msgBox.Text)
            if msgBox.Text ~= clipped then
                msgBox.Text = clipped
            end
            chatCfg.text = clipped
            refreshMsgCounter()
            autoSave()
            committing = false
        end

        msgBox:GetPropertyChangedSignal("Text"):Connect(function()
            if committing then return end
            local clipped = clampChatTextLocal(msgBox.Text)
            if msgBox.Text ~= clipped then
                committing = true
                msgBox.Text = clipped
                committing = false
            end
            chatCfg.text = clipped
            refreshMsgCounter()
        end)
        msgBox.FocusLost:Connect(commitMessage)
        msgBox.Destroying:Connect(commitMessage)
        refreshMsgCounter()

        ui:CreateRowInput(bodyChat, "Interval (Seconds)", tostring(chatCfg.intervalSec or 45), function(text)
            local v = math.floor(tonumber(text) or 0)
            if v < 30 then v = 30 end
            if v > 86400 then v = 86400 end
            chatCfg.intervalSec = v
            autoSave()
        end, false)

        ui:CreateRowToggle(bodyChat, "Enable", chatCfg.enabled == true, function(on)
            chatCfg.enabled = (on == true)
            autoSave()
        end)

        refreshChatStatus()
        task.spawn(function()
            while statusRow and statusRow.Parent do
                refreshChatStatus()
                task.wait(0.5)
            end
        end)

        if setChatExpanded then setChatExpanded(false) end

        ----------------------------------------------------------------
        -- Config (Copy / Paste / Apply save JSON — seperti Steal Egg)
        ----------------------------------------------------------------
        do
            local bodyCfg, setCfgExpanded = ui:CreateSection("Config", false)
            local statusRow, statusTitle, statusDetail = ui:CreateRowLabel(bodyCfg, "Status", "Idle", 1)

            local function setCfgStatus(text, detail)
                if statusTitle then statusTitle.Text = tostring(text or "Idle") end
                if statusDetail then statusDetail.Text = tostring(detail or "") end
            end

            local function getStateMod()
                local G0 = (getgenv and getgenv()) or _G
                local m = rawget(_G, "MAIN") or rawget(G0, "MAIN")
                if type(m) == "table" and type(m.ExportJson) == "function" then
                    return m
                end
                local Loaded = rawget(_G, "Loaded") or rawget(G0, "Loaded")
                if type(Loaded) == "table" and type(Loaded.state) == "table" then
                    return Loaded.state
                end
                return m
            end

            local function copyText(text)
                if type(setclipboard) == "function" then
                    local ok = pcall(setclipboard, text)
                    if ok then return true end
                end
                if type(toclipboard) == "function" then
                    local ok = pcall(toclipboard, text)
                    if ok then return true end
                end
                if type(set_clipboard) == "function" then
                    local ok = pcall(set_clipboard, text)
                    if ok then return true end
                end
                return false
            end

            local function makeActionBtn(parent, text, order, onClick)
                local row = Instance.new("Frame")
                row.Name = "RowBtn_" .. tostring(text)
                row.BackgroundTransparency = 1
                row.Size = UDim2.new(1, 0, 0, 28)
                row.LayoutOrder = order or (#parent:GetChildren() + 1)
                row.Parent = parent

                local btn = Instance.new("TextButton")
                btn.Name = "Btn"
                btn.AutoButtonColor = false
                btn.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
                btn.Size = UDim2.new(1, 0, 1, 0)
                btn.Font = Enum.Font.GothamBold
                btn.TextSize = 12
                btn.TextColor3 = Color3.fromRGB(240, 240, 240)
                btn.Text = tostring(text)
                btn.BorderSizePixel = 0
                btn.Parent = row
                local c = Instance.new("UICorner")
                c.CornerRadius = UDim.new(0, 8)
                c.Parent = btn
                local s = Instance.new("UIStroke")
                s.Color = Color3.fromRGB(80, 80, 80)
                s.Thickness = 1
                s.Transparency = 0.35
                s.Parent = btn
                btn.MouseButton1Click:Connect(function()
                    if type(onClick) == "function" then
                        pcall(onClick)
                    end
                end)
                return row, btn
            end

            makeActionBtn(bodyCfg, "Copy", 2, function()
                local SM = getStateMod()
                if type(SM) ~= "table" or type(SM.ExportJson) ~= "function" then
                    setCfgStatus("Failed", "state module")
                    return
                end
                local json, err, meta = SM.ExportJson()
                if type(json) ~= "string" or json == "" then
                    setCfgStatus("Failed", tostring(err or "encode"))
                    return
                end
                local clip = copyText(json)
                local chars = (type(meta) == "table" and tonumber(meta.chars)) or #json
                if clip then
                    setCfgStatus("Copied", "chars=" .. tostring(chars))
                else
                    setCfgStatus("Failed", "clipboard")
                end
            end)

            local pasteWrap = Instance.new("Frame")
            pasteWrap.Name = "ConfigPaste"
            pasteWrap.BackgroundTransparency = 1
            pasteWrap.Size = UDim2.new(1, 0, 0, 78)
            pasteWrap.LayoutOrder = 3
            pasteWrap.Parent = bodyCfg

            local pasteBox = Instance.new("TextBox")
            pasteBox.Name = "Input"
            pasteBox.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            pasteBox.Size = UDim2.new(1, 0, 1, 0)
            pasteBox.Font = Enum.Font.Gotham
            pasteBox.TextSize = 11
            pasteBox.TextColor3 = Color3.fromRGB(220, 220, 220)
            pasteBox.PlaceholderColor3 = Color3.fromRGB(110, 110, 110)
            pasteBox.PlaceholderText = "Paste save config"
            pasteBox.Text = ""
            pasteBox.ClearTextOnFocus = false
            pasteBox.MultiLine = true
            pasteBox.TextWrapped = true
            pasteBox.TextXAlignment = Enum.TextXAlignment.Left
            pasteBox.TextYAlignment = Enum.TextYAlignment.Top
            pasteBox.ClipsDescendants = true
            pasteBox.Parent = pasteWrap
            pcall(function()
                pasteBox.TextTruncate = Enum.TextTruncate.None
            end)
            local boxPad = Instance.new("UIPadding")
            boxPad.PaddingLeft = UDim.new(0, 8)
            boxPad.PaddingRight = UDim.new(0, 8)
            boxPad.PaddingTop = UDim.new(0, 6)
            boxPad.PaddingBottom = UDim.new(0, 6)
            boxPad.Parent = pasteBox
            local boxCorner = Instance.new("UICorner")
            boxCorner.CornerRadius = UDim.new(0, 8)
            boxCorner.Parent = pasteBox
            local boxStroke = Instance.new("UIStroke")
            boxStroke.Color = Color3.fromRGB(70, 70, 70)
            boxStroke.Thickness = 1
            boxStroke.Transparency = 0.35
            boxStroke.Parent = pasteBox

            makeActionBtn(bodyCfg, "Apply", 4, function()
                local SM = getStateMod()
                if type(SM) ~= "table" or type(SM.ImportJson) ~= "function" then
                    setCfgStatus("Failed", "state module")
                    return
                end
                local raw = tostring(pasteBox.Text or ""):gsub("^%s+", ""):gsub("%s+$", "")
                if raw == "" then
                    setCfgStatus("Failed", "paste kosong")
                    return
                end
                setCfgStatus("Checking", "chars=" .. tostring(#raw))
                local ok, reason = SM.ImportJson(raw)
                if ok then
                    pasteBox.Text = ""
                    setCfgStatus("Applied", "chars=" .. tostring(#raw) .. " · " .. tostring(reason))
                    pcall(function()
                        if ui and type(ui.SaveState) == "function" then
                            ui:SaveState()
                        end
                    end)
                    _G.__auto_market_DIRTY = true
                    pcall(function()
                        if ui and type(ui.RefreshActiveSubTab) == "function" then
                            ui:RefreshActiveSubTab()
                        end
                    end)
                else
                    local msg = tostring(reason or "import")
                    if reason == "refused_empty_overwrite" then
                        msg = "ditolak: config paste kosong / hapus list. Cek Copy chars dulu."
                    end
                    setCfgStatus("Failed", msg .. " · chars=" .. tostring(#raw))
                end
            end)

            if type(ui.CreateRowLabel) == "function" then
                ui:CreateRowLabel(bodyCfg, "Copy → paste di akun lain → Apply. Cek chars Copy = chars Apply.", nil, 5)
            end

            if setCfgExpanded then setCfgExpanded(false) end
        end

        ----------------------------------------------------------------
        -- Monitor (below Config)
        ----------------------------------------------------------------
        do
            local Mon = rawget(_G, "MarketMonitor")
            if type(Mon) == "table" and type(Mon.attachUi) == "function" then
                Mon.attachUi(ui)
            else
                local bodyMon = ui:CreateSection("Monitor Account", false)
                if type(ui.CreateRowLabel) == "function" then
                    ui:CreateRowLabel(bodyMon, "Monitor module belum loaded", nil, 1)
                end
            end
        end
    end, 4)

    ui:RegisterSubTab("misc", "rejoin", "Rejoin", function()
    ui:ClearSubContent()

    local G = (getgenv and getgenv()) or _G
    local STATE = rawget(_G, "STATE") or {}
    _G.STATE = STATE
    G.STATE  = STATE

    -- Ensure rejoin state
    STATE.rejoin = STATE.rejoin or {}
    local RJ = STATE.rejoin

    -- Mirror globals (for PSReconnect module)
    if rawget(_G, "AUTO_START_ON_REJOIN") == nil then
        _G.AUTO_START_ON_REJOIN = (RJ.auto_exec == true)
    end
    if rawget(_G, "AUTO_RECONNECT_ENABLED") == nil then
        _G.AUTO_RECONNECT_ENABLED = (RJ.auto_reconnect == true)
    end

    ----------------------------------------------------------------
    -- Ensure market paths
    ----------------------------------------------------------------
    STATE.main = STATE.main or {}
    STATE.main.auto_market = STATE.main.auto_market or {}
    local MK = STATE.main.auto_market
    MK.runtime = MK.runtime or { enabled = false }
    if MK.auto_start == nil then MK.auto_start = false end
    if tonumber(MK.ageBreakRejoinEverySec) == nil then
        local oldMin = tonumber(MK.ageBreakRejoinEveryMin)
        MK.ageBreakRejoinEverySec = (oldMin and oldMin > 0) and (oldMin * 60) or 60
    end

    local function clampNum(v, minv, maxv, fallback)
        local n = tonumber(v)
        if not n then return fallback end
        if n < minv then return minv end
        if n > maxv then return maxv end
        return n
    end

    -- Ensure hop config
    MK.hop = (type(MK.hop) == "table") and MK.hop or {}
    local HOP = MK.hop
    if HOP.autohoop == nil then HOP.autohoop = false end
    if tonumber(HOP.waktu) == nil then HOP.waktu = 15 end              -- minutes without SOLD
    if tonumber(HOP.minPlayerNow) == nil then HOP.minPlayerNow = 0 end -- 0 = ignore
    if tonumber(HOP.targetPlayer) == nil then HOP.targetPlayer = 20 end

    ----------------------------------------------------------------
    -- Helpers
    ----------------------------------------------------------------
    local function syncMarketLoopFromState()
        -- Jangan paksa runtime.enabled dari flag boot yang sempat di-reset.
        -- Source of truth: MK.runtime.enabled / auto_start yang sudah di-load dari file.
        MK.runtime = MK.runtime or {}
        if MK.auto_start == true then
            -- auto_start on → mirror enabled agar loop boleh jalan setelah rejoin
            if MK.runtime.enabled ~= true and rawget(_G, "__AUTO_MARKET_RUNNING") == true then
                MK.runtime.enabled = true
            end
        end
        _G.AUTO_MARKET_AUTOSTART = (MK.runtime.enabled == true)
    end

    local function autoSave()
        RJ.auto_exec      = (_G.AUTO_START_ON_REJOIN == true)
        RJ.auto_reconnect = (_G.AUTO_RECONNECT_ENABLED == true)

        -- Jangan rewrite MK.runtime.enabled di sini (bug lama: buka tab Rejoin → save enabled=false)

        if ui and type(ui.SaveState) == "function" then
            task.defer(function()
                pcall(function() ui:SaveState() end)
            end)
        end
    end

    local sectionSetters = {}
    local function createSection(title, defaultOpen)
        local body, setExpanded = ui:CreateSection(title, defaultOpen or false)
        local setter
        setter = function(on)
            if on and #sectionSetters >= 3 then
                for _, fn in ipairs(sectionSetters) do
                    if fn ~= setter then
                        fn(false)
                    end
                end
            end
            setExpanded(on)
            task.defer(function()
                if ui.RelayoutContent then
                    ui:RelayoutContent()
                end
            end)
        end
        table.insert(sectionSetters, setter)
        return body
    end

    ----------------------------------------------------------------
    -- Section 1: Auto Reconnect / Rejoin
    ----------------------------------------------------------------
    local body2 = createSection("Auto Reconnect / Rejoin", true)

    local function syncReconnectModule()
    STATE.rejoin = STATE.rejoin or {}
    local on = (STATE.rejoin.auto_reconnect == true)

    _G.AUTO_RECONNECT_ENABLED = on -- mirror

    if _G.PSReconnect and _G.PSReconnect.SetEnabled then
        _G.PSReconnect.SetEnabled(on)
    end
    end


    syncMarketLoopFromState()


    -------------------------------------------------
    -- TELEPORT TO JOB ID - NO SAVE
    -------------------------------------------------

    local Players = game:GetService("Players")
    local TeleportService = game:GetService("TeleportService")

    local LP = Players.LocalPlayer
    local TELEPORT_JOB_ID = ""

    local function normalizeJobId(jobId)
    jobId = tostring(jobId or "")
        :lower()
        :gsub("%s+", "")
        :gsub("[^%w]", "")

    -- format tanpa strip -> UUID normal
    if #jobId == 32 then
        return string.format(
            "%s-%s-%s-%s-%s",
            jobId:sub(1, 8),
            jobId:sub(9, 12),
            jobId:sub(13, 16),
            jobId:sub(17, 20),
            jobId:sub(21, 32)
        )
    end

    return jobId
    end

    local function sanitizeJobIdInput(text)
    return tostring(text or "")
        :lower()
        :gsub("%s+", "")
        :gsub("[^%w]", "")
    end

    local function CreateJobIdBox(parent)
    local row = Instance.new("Frame")
    row.Name = "JobIdInputRow"
    row.Size = UDim2.new(1, -10, 0, 42)
    row.BackgroundColor3 = Color3.fromRGB(10, 10, 10)
    row.BackgroundTransparency = 0.05
    row.Parent = parent

    Instance.new("UICorner", row).CornerRadius = UDim.new(0, 8)

    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.fromRGB(255, 220, 0)
    stroke.Thickness = 1
    stroke.Transparency = 0.35
    stroke.Parent = row

    local label = Instance.new("TextLabel")
    label.BackgroundTransparency = 1
    label.Size = UDim2.new(0, 105, 1, 0)
    label.Position = UDim2.new(0, 10, 0, 0)
    label.Font = Enum.Font.GothamBold
    label.TextSize = 11
    label.TextXAlignment = Enum.TextXAlignment.Left
    label.TextColor3 = Color3.fromRGB(255, 220, 0)
    label.TextTransparency = 0
    label.Text = "Job ID"
    label.Parent = row

    local box = Instance.new("TextBox")
    box.Name = "JobIdBox"
    box.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
    box.BackgroundTransparency = 0
    box.Size = UDim2.new(1, -125, 0, 28)
    box.Position = UDim2.new(0, 115, 0.5, -14)
    box.ClearTextOnFocus = false
    box.PlaceholderText = " "
    box.Text = ""
    box.Font = Enum.Font.GothamMedium
    box.TextSize = 13
    box.TextColor3 = Color3.fromRGB(255, 255, 255)
    box.TextTransparency = 0
    box.TextStrokeTransparency = 1
    box.PlaceholderColor3 = Color3.fromRGB(170, 170, 170)
    box.TextXAlignment = Enum.TextXAlignment.Center
    box.RichText = false
    box.Parent = row

    Instance.new("UICorner", box).CornerRadius = UDim.new(0, 7)

    local pad = Instance.new("UIPadding")
    pad.PaddingLeft = UDim.new(0, 8)
    pad.PaddingRight = UDim.new(0, 8)
    pad.Parent = box

    local boxStroke = Instance.new("UIStroke")
    boxStroke.Color = Color3.fromRGB(255, 220, 0)
    boxStroke.Thickness = 1
    boxStroke.Transparency = 0.55
    boxStroke.Parent = box

    local editing = false

    box:GetPropertyChangedSignal("Text"):Connect(function()
        if editing then return end
        editing = true

        local clean = sanitizeJobIdInput(box.Text)

        if box.Text ~= clean then
            box.Text = clean
        end

        TELEPORT_JOB_ID = clean
        _G.TELEPORT_TARGET_JOB_ID = clean

        editing = false
    end)

    box.Focused:Connect(function()
        boxStroke.Transparency = 0.15
    end)

    box.FocusLost:Connect(function()
        boxStroke.Transparency = 0.55

        TELEPORT_JOB_ID = normalizeJobId(box.Text)
        box.Text = TELEPORT_JOB_ID

        _G.TELEPORT_TARGET_JOB_ID = TELEPORT_JOB_ID
    end)

    return box
    end

    local jobBox = CreateJobIdBox(body2)

    ui:CreateRowToggle(body2, "Teleport To Job ID", false, function(on)
    if on ~= true then
        return
    end

    local jobId = normalizeJobId(jobBox.Text or TELEPORT_JOB_ID or "")

    if jobId == "" then
        warn("[TeleportJobID] Job ID kosong")
        return
    end

    TELEPORT_JOB_ID = jobId
    _G.TELEPORT_TARGET_JOB_ID = jobId
    jobBox.Text = jobId

    print("[TeleportJobID] Teleport to:", jobId)

    -- Pakai PSReconnect.HopToServer kalau ada (queue auto-exec),
    -- tapi jangan fallback ke Teleport random saat gagal/full.
    local PR = _G.PSReconnect or (getgenv and getgenv().PSReconnect)
    if PR and type(PR.HopToServer) == "function" then
        local ok, err = PR.HopToServer(game.PlaceId, jobId)
        if not ok then
            warn("[TeleportJobID] gagal:", tostring(err))
        end
        return
    end

    pcall(function()
        TeleportService:TeleportToPlaceInstance(game.PlaceId, jobId, LP)
    end)
    end, nil, { momentary = true })


    ui:CreateRowToggle(body2, "Auto Start Market (On Load)", (MK.auto_start == true), function(on)
        MK.auto_start = (on == true)
        autoSave()
    end)

    ui:CreateRowToggle(body2, "Auto Exec", _G.AUTO_START_ON_REJOIN == true, function(on)
        _G.AUTO_START_ON_REJOIN = (on == true)
        autoSave()
    end)

    ui:CreateRowToggle(body2, "Auto Reconnect", (STATE.rejoin and STATE.rejoin.auto_reconnect) == true, function(on)
    STATE.rejoin = STATE.rejoin or {}
    STATE.rejoin.auto_reconnect = (on == true)

    -- mirror global kalau kamu butuh (optional)
    _G.AUTO_RECONNECT_ENABLED = (on == true)

    -- langsung apply ke module (paling penting)
    if _G.PSReconnect and _G.PSReconnect.SetEnabled then
        _G.PSReconnect.SetEnabled(on == true)
    end

    autoSave()
    end)


    ui:CreateRowToggle(body2, "Back To Main World", false, function(on)
        if on ~= true then return end

        if _G.PSReconnect and _G.PSReconnect.TravelToMain then
            _G.PSReconnect.TravelToMain()
            return
        end

        local RS = game:GetService("ReplicatedStorage")
        pcall(function()
            RS.GameEvents.TradeWorld.TravelToMainWorld:FireServer()
        end)
    end)

    local function doRejoinNow()
        local R = _G.PSReconnect or (getgenv and getgenv()).PSReconnect
        if R and type(R.RejoinNow) == "function" then
            local ok, success, reason = pcall(function()
                return R.RejoinNow(true)
            end)
            if not ok then
