    return items
    end

    local function collectTypesFromSnipeRules()
    local pets, skins = {}, {}
    local SN = MK.snipe or {}
    local bags = { SN.rules, SN.rulesBase }

    for _, rules in ipairs(bags) do
        if type(rules) == "table" then
            for _, rec in pairs(rules) do
                if type(rec) == "table" then
                    local kind = tostring(rec.kind or "pet"):lower()
                    if kind == "skin" then
                        local st = tostring(rec.skinType or "")
                        if st ~= "" then skins[st] = true end
                    else
                        local pt = tostring(rec.petType or "")
                        if pt ~= "" then pets[pt] = true end
                    end
                end
            end
        end
    end

    return pets, skins
    end

