-- Output utama:
--   M.buildEntriesNotFav(selectedSet) -> { {key=uuid, name="Label ..."}, ... }
--   M.listPetsNotFav() -> data lengkap (uuid, name, age, kg, ptype, fav, muts)

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local function waitChild(parent, name, timeout)
    if typeof(parent) ~= "Instance" then
        return nil
    end
    local existing = parent:FindFirstChild(name)
    if existing then
        return existing
    end
    return parent:WaitForChild(name, timeout or 8)
end

local function safeRequire(obj)
    if not obj then
        return nil
    end
    local ok, mod = pcall(require, obj)
    return ok and mod or nil
end

-------------------------------------------------------------
-- SOURCE: DataService profile
-------------------------------------------------------------
local DataService = safeRequire(waitChild(waitChild(ReplicatedStorage, "Modules", 8), "DataService", 8))
local PetList = safeRequire(waitChild(waitChild(waitChild(ReplicatedStorage, "Data", 8), "PetRegistry", 8), "PetList", 8))

local function __getBag()
    if type(DataService) ~= "table" or type(DataService.GetData) ~= "function" then
        return nil
    end
    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if not ok or type(profile) ~= "table" then
        warn("[PetListViewNotFav] DataService:GetData gagal:", profile)
        return nil
    end

    local petsData = profile.PetsData
    local bag = petsData and petsData.PetInventory and petsData.PetInventory.Data
    if type(bag) ~= "table" then
        warn("[PetListViewNotFav] profile.PetsData.PetInventory.Data tidak ada")
        return nil
    end
    return bag
end

