local PetRegistry = nil
pcall(function()
    local dataFolder = ReplicatedStorage:FindFirstChild("Data")
    local inst = dataFolder and dataFolder:FindFirstChild("PetRegistry")
    if inst then
        PetRegistry = require(inst)
    end
end)

local SCALE_PER_LVL =
    PetRegistry
    and PetRegistry.PetConfig
    and PetRegistry.PetConfig.WEIGHT_CONFIG
    and PetRegistry.PetConfig.WEIGHT_CONFIG.SCALE_PERCENTAGE_OF_BASE_WEIGHT_PER_LEVEL
    or 0

