-- MUTATION MAP: EnumId (a,b,c,A,B,...) -> Nama mutasi
-------------------------------------------------------------
local PetMutationRegistry = nil
pcall(function()
    local dataFolder = ReplicatedStorage:FindFirstChild("Data")
    local petReg = dataFolder and dataFolder:FindFirstChild("PetRegistry")
    local inst = petReg and (petReg:FindFirstChild("PetMutationRegistry") or petReg:WaitForChild("PetMutationRegistry", 8))
    if inst then
        PetMutationRegistry = require(inst)
    end
end)

local MUT_CODE_TO_NAME = {}
local MUTATION_LIST = {}

do
    -- di referensi: mutationModule.PetMutationRegistry
    local reg = PetMutationRegistry and (PetMutationRegistry.PetMutationRegistry or PetMutationRegistry)
    if type(reg) ~= "table" then
        warn("[PetListViewNotFav] PetMutationRegistry invalid:", typeof(reg))
    else
        for mutName, def in pairs(reg) do
            MUTATION_LIST[#MUTATION_LIST + 1] = tostring(mutName)
            if type(def) == "table" then
                local code = def.EnumId
                if type(code) == "string" and code ~= "" then
                    MUT_CODE_TO_NAME[code] = tostring(mutName)
                end
            end
        end
        table.sort(MUTATION_LIST, function(a, b) return tostring(a) < tostring(b) end)
    end
end

-------------------------------------------------------------
-- HELPERS (mirip referensi)
-------------------------------------------------------------
local function __normUUID(u)
    if not u or u == "" then return nil, nil end
    local core = tostring(u):match("{?([0-9a-fA-F%-]+)}?") or tostring(u)
    return core, "{" .. core .. "}"
end

local function __number_from_candidates(tbl, keys)
    if type(tbl) ~= "table" then return nil end
    for _, k in ipairs(keys) do
        local v = tbl[k]
        if type(v) == "number" then
            return v
        elseif type(v) == "string" then
            local n = tonumber((v:gsub(",", ".")))
            if n then return n end
        end
    end
    return nil
end

local function __age_from_record(rec)
    local PD = (type(rec) == "table" and (rec.PetData or rec.Data)) or {}
    return __number_from_candidates(rec, {"Age","age","Level","level"})
        or __number_from_candidates(PD,  {"Age","age","Level","level"})
        or 0
end

local function __base_from_record(rec)
    local PD = (type(rec) == "table" and (rec.PetData or rec.Data)) or {}
    return __number_from_candidates(rec, {"BaseWeight","BaseWeightKG","WeightBase","baseWeight","base_weight"})
        or __number_from_candidates(PD,  {"BaseWeight","BaseWeightKG","WeightBase","baseWeight","base_weight"})
end

local function __current_from_record(rec)
    local PD = (type(rec) == "table" and (rec.PetData or rec.Data)) or {}
    return __number_from_candidates(rec, {"Weight","weight","KG","kg","W","w","WeightNow","weight_now","currentWeight"})
        or __number_from_candidates(PD,  {"Weight","weight","KG","kg","W","w","WeightNow","weight_now","currentWeight"})
end

local function __is_favorite(rec)
    if type(rec) ~= "table" then return false end
    local PD = rec.PetData or rec.Data or {}
    if typeof(PD.IsFavorite) == "boolean" then return PD.IsFavorite end
    if typeof(rec.IsFavorite) == "boolean" then return rec.IsFavorite end
    return false
end

local function __petTypeLabel(rec)
    if type(rec) ~= "table" then return "Pet" end
    local PD = rec.PetData or rec.Data or {}
    local raw =
        rec.PetType or rec.Type or
        PD.PetType  or PD.Type  or
        rec.Name    or PD.Name  or
        "Pet"
    return tostring(raw)
end

