-- MUTATION names dari record (pakai code->name map)
-------------------------------------------------------------
local function __mutation_names_from_record(rec)
    if type(rec) ~= "table" then return {} end
    local PD = rec.PetData or rec.Data or {}

    local raw =
        PD.MutationType or rec.MutationType or
        PD.Mutations or PD.Mutation or PD.MutationCodes or
        rec.Mutations or rec.Mutation or rec.MutationCodes

    if not raw then return {} end

    local codes = {}

    local function addCode(v)
        if type(v) ~= "string" or v == "" then return end

        -- exact enum dulu: A, a, EV, dll
        if MUT_CODE_TO_NAME[v] then
            codes[#codes + 1] = v
            return
        end

        -- kalau string gabungan, parse pakai longest match
        local i = 1
        while i <= #v do
            local best = nil

            for code in pairs(MUT_CODE_TO_NAME) do
                if v:sub(i, i + #code - 1) == code then
                    if (not best) or #code > #best then
                        best = code
                    end
                end
            end

            if best then
                codes[#codes + 1] = best
                i = i + #best
            else
                i = i + 1
            end
        end
    end

    if type(raw) == "string" then
        addCode(raw)

    elseif type(raw) == "table" then
        for _, v in pairs(raw) do
            if type(v) == "string" then
                addCode(v)

            elseif type(v) == "table" then
                addCode(v.MutationType)
                addCode(v.Mutation)
                addCode(v.EnumId)
                addCode(v.Code)
            end
        end
    end

    local names, seen = {}, {}

    for _, code in ipairs(codes) do
        local name = MUT_CODE_TO_NAME[code] -- exact only, jangan lower/upper

        if name and not seen[name] then
            seen[name] = true
            names[#names + 1] = name
        end
    end

    table.sort(names, function(a, b)
        return tostring(a) < tostring(b)
    end)

    return names
end

-- W100 untuk filter trade/gift (sama auto_hatch)
local function _weight_at_100_for_rec(rec)
    local SCALE = SCALE_PER_LVL or 0
    local age   = __age_from_record(rec)
    local base  = __base_from_record(rec)
    local cur   = __current_from_record(rec)

    if base then
        return base * (1 + SCALE * 100)
    end
    if cur and age then
        local delta = math.max(0, 100 - age)
        return cur * (1 + SCALE * delta)
    end
    return nil
end

local function getDatastoreBagIndex()
    local bag = __getBag()
    if not bag then
        return nil, nil, nil
    end

    local index = {}
    for rawUUID, rec in pairs(bag) do
        if type(rec) == "table" then
            local core, br = __normUUID(rec.UUID or rawUUID)
            if core then
                index[core] = rec
                if br then
                    index[br] = rec
                end
            end
        end
    end

    local helpers = {
        normUUID                   = __normUUID,
        age_from_record            = __age_from_record,
        base_from_record           = __base_from_record,
        current_from_record        = __current_from_record,
        is_favorite                = __is_favorite,
        mutation_names_from_record = __mutation_names_from_record,
        weight_at_100_for_rec      = _weight_at_100_for_rec,
    }

    return bag, index, helpers
end

-------------------------------------------------------------
-- LIST: semua pet di datastore (opsional skip fav) — harus di atas listPetsListedBooth (Luau scope)
-------------------------------------------------------------
local function listPetsFromBag(skipFavorites)
    local pets = {}
    local bag = __getBag()
    if not bag then return pets end

    for rawUUID, rec in pairs(bag) do
        if type(rec) == "table" then
            local core, br = __normUUID(rec.UUID or rawUUID)
            local uuid = br or core

            if uuid then
                local fav = __is_favorite(rec) and true or false
                if skipFavorites ~= true or not fav then
                    local petTypeLabel = __petTypeLabel(rec)
                    local petTypeNorm  = petTypeLabel:lower()

                    local age  = __age_from_record(rec) or 0
                    if age < 1 then age = 1 end

                    local base = __base_from_record(rec)
                    local cur  = __current_from_record(rec)

                    local kgNow
                    if type(base) == "number" and base > 0 then
                        kgNow = base * (1 + (SCALE_PER_LVL or 0) * (age or 0))
                    else
                        kgNow = cur
                    end
                    kgNow = tonumber(kgNow) or 0

                    local baseKg = 0
                    if type(base) == "number" and base > 0 then
                        baseKg = base * (1 + (SCALE_PER_LVL or 0) * (1))
                    end

                    local mutNames  = __mutation_names_from_record(rec)
                    local mutPrefix = (#mutNames > 0) and ("[" .. table.concat(mutNames, ", ") .. "] ") or ""

                    local ageText = (age > 0) and ("Age " .. tostring(age)) or "Age ?"
                    local kgText  = (kgNow and kgNow > 0) and (string.format("%.2f KG", kgNow)) or "? KG"

                    local label = string.format("%s%s | %s | %s",
                        mutPrefix,
                        petTypeLabel,
                        ageText,
                        kgText
                    )

                    pets[#pets + 1] = {
                        uuid        = uuid,
                        key         = uuid,
                        name        = label,
                        age         = age,
                        kg          = kgNow or 0,
                        baseKg      = baseKg or 0,
                        ptype       = petTypeNorm,
                        petType     = petTypeLabel,
                        fav         = fav,
                        muts        = mutNames,
                    }
                end
            end
        end
    end

    table.sort(pets, function(a, b)
        if (a.age or 0) ~= (b.age or 0) then
            return (a.age or 0) < (b.age or 0)
        end
        if (a.kg or 0) ~= (b.kg or 0) then
            return (a.kg or 0) < (b.kg or 0)
        end
        if (a.ptype or "") ~= (b.ptype or "") then
            return tostring(a.ptype) < tostring(b.ptype)
        end
        return tostring(a.uuid) < tostring(b.uuid)
    end)

    return pets
end

-------------------------------------------------------------
-- ✅ LIST: PET YANG SEDANG DI-LISTING DI BOOTH (PISAH)
-- Output item: { uuid, key, name(label), ptype, price, listingUUID, itemType, muts(optional) }
-------------------------------------------------------------
local function listPetsListedBooth()
    local out = {}

    -- try require replion + tradeboothsdata + itemnamefinder (optional)
    local okRep, RepRecv = pcall(function()
        return require(ReplicatedStorage.Modules.ReplicationReciever)
    end)
    local okTB, TradeBoothsData = pcall(function()
        return require(ReplicatedStorage.Data.TradeBoothsData)
    end)

    if not okRep or not okTB then
        return out
    end

    local ItemNameFinder = nil
    pcall(function()
        ItemNameFinder = require(ReplicatedStorage.Modules.ItemNameFinder)
    end)

    local Booths = RepRecv.new("Booths")
    local data
    local okData = pcall(function()
        data = Booths:GetDataAsync()
    end)
    if not okData or type(data) ~= "table" then
        return out
    end

    local me = game:GetService("Players").LocalPlayer
    local myId = TradeBoothsData.getPlayerId(me)

    -- cari booth milik kita
    local p = data.Players and data.Players[myId]
    if not p then return out end

    local boothUUID = p.Booth
    if not boothUUID then
        -- belum claim booth / ga ada booth
        return out
    end

    local booth = data.Booths and data.Booths[boothUUID]
    if not booth or not booth.Owner then return out end

    local ownerId = booth.Owner
    local ownerData = data.Players and data.Players[ownerId]
    if not (ownerData and ownerData.Listings and ownerData.Items) then
        return out
    end

    for listingUUID, listing in pairs(ownerData.Listings) do
        local itemId = listing and listing.ItemId
        local itemType = listing and listing.ItemType
        local price = listing and listing.Price or 0
        local itemData = itemId and ownerData.Items[itemId]

        -- kita hanya ambil yang PET
        if itemData and itemData.PetType then
            local core, br = __normUUID(itemId)
            local uuid = br or core or tostring(itemId)

            local petTypeLabel = tostring(itemData.PetType)
            local mutNames = __mutation_names_from_record(itemData) -- kalau itemData punya mutation codes; aman walau kosong

            local niceName = petTypeLabel
            if ItemNameFinder then
                local okName, n = pcall(function()
                    return ItemNameFinder(petTypeLabel, itemType)
                end)
                if okName and type(n) == "string" and n ~= "" then
                    niceName = n
                end
            end

            local mutPrefix = (#mutNames > 0) and ("[" .. table.concat(mutNames, ", ") .. "] ") or ""
            local label = string.format("%s%s | Price %s",
                mutPrefix,
                niceName,
                tostring(price)
            )

            out[#out+1] = {
                uuid       = uuid,        -- itemId pet uuid
                key        = uuid,
                name       = label,       -- label buat UI
                ptype      = petTypeLabel:lower(),
                price      = price,
                listingUUID= listingUUID, -- penting buat unlist
                itemType   = itemType,
                muts       = mutNames,
            }
        end
    end

    -- enrich age/kg dari tas supaya urutan booth = harga → age → kg
    local bagByUuid = {}
    for _, p in ipairs(listPetsFromBag(true)) do
        if p and p.uuid then
            bagByUuid[tostring(p.uuid)] = p
        end
    end
    for _, row in ipairs(out) do
        local bag = bagByUuid[tostring(row.uuid)]
        if bag then
            row.age = bag.age
            row.kg = bag.kg or bag.baseKg
        end
    end

    table.sort(out, function(a, b)
        if (a.price or 0) ~= (b.price or 0) then
            return (a.price or 0) < (b.price or 0)
        end
        if (a.age or 0) ~= (b.age or 0) then
            return (a.age or 0) < (b.age or 0)
        end
        if (a.kg or 0) ~= (b.kg or 0) then
            return (a.kg or 0) < (b.kg or 0)
        end
        if tostring(a.ptype) ~= tostring(b.ptype) then
            return tostring(a.ptype) < tostring(b.ptype)
        end
        return tostring(a.uuid) < tostring(b.uuid)
    end)

    return out
end

local function buildEntriesListedBooth(selectedSet)
    selectedSet = selectedSet or {}
    local list = listPetsListedBooth()

    table.sort(list, function(a, b)
        local sa = (selectedSet[a.uuid] == true) and 1 or 0
        local sb = (selectedSet[b.uuid] == true) and 1 or 0
        if sa ~= sb then return sa > sb end
        return tostring(a.name) < tostring(b.name)
    end)

    local out = {}
    for _, p in ipairs(list) do
        out[#out + 1] = { key = p.uuid, name = p.name }
    end
    return out
end

local function listPetsNotFav()
    return listPetsFromBag(true)
end

local function listPetsAll()
    return listPetsFromBag(false)
end

local function buildEntriesNotFav(selectedSet)
    selectedSet = selectedSet or {}
    local list = listPetsNotFav()

    -- selected dulu (mirip referensi)
    table.sort(list, function(a, b)
        local sa = (selectedSet[a.uuid] == true) and 1 or 0
        local sb = (selectedSet[b.uuid] == true) and 1 or 0
        if sa ~= sb then return sa > sb end
        return tostring(a.name) < tostring(b.name)
    end)

    local out = {}
    for _, p in ipairs(list) do
        out[#out + 1] = { key = p.uuid, name = p.name }
    end
    return out
end

