local function buildPetItems()
    local list = {}

    if type(PetList) ~= "table" then
        warn("[PetListViewNotFav] PetList bukan table:", typeof(PetList))
        return list
    end

    for petName, cfg in pairs(PetList) do
        list[#list + 1] = {
            key   = petName,
            name  = petName,
            right = cfg and cfg.Rarity or nil,
            icon  = cfg and cfg.Icon or nil,
            raw   = cfg,
        }
    end

    table.sort(list, function(a, b)
        return tostring(a.name) < tostring(b.name)
    end)

    return list
end

