    end
end

-------------------------------------------------------------
-- HELPERS
-------------------------------------------------------------
local function __normUUID(u)
    if u == nil or u == "" then return nil, nil end
    local s = tostring(u)
    local core = s:match("{?([0-9a-fA-F%-]+)}?") or s
    if core == "" then return nil, nil end
    return core, "{" .. core .. "}"
end

local function __fmtKg(n)
    n = tonumber(n)
    if not n then return "?" end
    if n % 1 == 0 then return tostring(math.floor(n)) end
    return string.format("%.2f", n):gsub("0+$", ""):gsub("%.$", "")
end

local function __parseKgFromText(s)
    s = tostring(s or "")
    if s == "" then return nil end

    local kg = s:match("%[(%d+%.?%d*)%s*[kK][gG]%]")
    if kg then return tonumber(kg) end

    kg = s:match("(%d+%.?%d*)%s*[kK][gG]")
    if kg then return tonumber(kg) end

    local bracket = s:match("%[([^%]]+)%]")
    if bracket then
        kg = bracket:match("(%d+%.?%d*)")
        if kg then return tonumber(kg) end
    end

    return nil
end

local function __titleCase(s)
    s = tostring(s or ""):lower()
    return (s:gsub("(%a)([%w_']*)", function(a, b)
        return a:upper() .. b
    end))
end

local function __niceFruitName(raw)
    raw = tostring(raw or "")
    if raw == "" then return "Fruit" end
    if ItemNameFinder then
        local ok, n = pcall(function()
            return ItemNameFinder(raw, "Holdable")
        end)
        if ok and type(n) == "string" and n ~= "" then
            return n
        end
    end
    return __titleCase(raw)
end

local function __number_from_candidates(tbl, keys)
    if type(tbl) ~= "table" then return nil end
    for _, k in ipairs(keys) do
        local v = tbl[k]
        if type(v) == "number" then return v end
        if type(v) == "string" then
            local n = tonumber((v:gsub(",", ".")))
            if n then return n end
        end
    end
    return nil
end

local function __is_favorite(rec, tool)
    if tool then
        local fav = tool:GetAttribute("IsFavorite") or tool:GetAttribute("Favorite")
        if typeof(fav) == "boolean" then return fav end
        if fav == 1 or fav == "1" or fav == true then return true end
    end
    if type(rec) ~= "table" then return false end
    local d = rec.ItemData or rec.Data or rec
    if typeof(rec.IsFavorite) == "boolean" then return rec.IsFavorite end
    if typeof(d.IsFavorite) == "boolean" then return d.IsFavorite end
    return false
end

local function __mutation_label(rec, tool)
    if type(rec) == "table" then
        local d = rec.ItemData or rec.Data or rec
        local mut = d.MutationString or d.Mutation or rec.MutationString or rec.Mutation or ""
        mut = tostring(mut or "")
        if mut ~= "" and mut ~= "0" and mut:lower() ~= "none" then
            return mut
        end
    end
    if tool then
        local names = {}
        for _, attr in ipairs(tool:GetAttributes()) do
            local v = tool:GetAttribute(attr)
            if v == true and type(attr) == "string" then
                local al = attr:lower()
                if al ~= "isfavorite" and al ~= "favorite" and al ~= "c" and al ~= "f" then
                    names[#names + 1] = attr
                end
            end
        end
        if #names > 0 then
            table.sort(names)
            return table.concat(names, ", ")
        end
    end
    return ""
end

local function __variant_label(rec)
    if type(rec) ~= "table" then return "" end
    local d = rec.ItemData or rec.Data or rec
    local v = d.Variant or rec.Variant
    if v == nil or v == "" or v == "Normal" then return "" end
    return tostring(v)
end

local function __fruitNameFromRec(rec)
    if type(rec) ~= "table" then return "Fruit" end
    local d = rec.ItemData or rec.Data or rec
    return tostring(
        d.ItemName or d.HoldableName or d.FruitName or d.Name
        or rec.ItemName or rec.HoldableName or rec.FruitName or rec.Name
        or "Fruit"
    )
end

local function __buildLabel(fruitName, mut, variant, kg)
    local nice = __niceFruitName(fruitName)
    local parts = {}
    if mut ~= "" then parts[#parts + 1] = "[" .. mut .. "]" end
    parts[#parts + 1] = nice
    if variant ~= "" then parts[#parts + 1] = "(" .. variant .. ")" end
    parts[#parts + 1] = __fmtKg(kg) .. "kg"
    return table.concat(parts, " ")
end

