local function __buildToolIndex()
    local byCore = {}

    local function scan(container)
        if not container then return end
        for _, inst in ipairs(container:GetChildren()) do
            if inst:IsA("Tool") then
                local uuidAttr = inst:GetAttribute("c") or inst:GetAttribute("C")
                    or inst:GetAttribute("ITEM_UUID") or inst:GetAttribute("ItemUUID")
                local core, braced = __normUUID(uuidAttr)
                if core then
                    byCore[core] = {
                        tool = inst,
                        uuid = braced or core,
                        fruitName = tostring(inst:GetAttribute("f") or inst:GetAttribute("F") or ""),
                    }
                end
            end
        end
    end

    scan(LP:FindFirstChildOfClass("Backpack") or LP:FindFirstChild("Backpack"))
    if LP.Character then scan(LP.Character) end

    return byCore
end

local __KG_DIRECT_KEYS = {
    "Weight", "weight", "KG", "kg", "W", "w",
    "WeightNow", "weight_now", "currentWeight", "HarvestWeight",
}

local __KG_BASE_KEYS = {
    "BaseWeight", "BaseWeightKG", "WeightBase", "baseWeight", "base_weight",
}

local __KG_MULTI_KEYS = {
    "SizeMulti", "SizeMultiplier", "sizeMulti", "sizeMultiplier",
    "WeightMulti", "weightMulti", "WeightMultiplier", "weightMultiplier",
}

local _fruitViz = nil
local _fruitVizAt = 0

local function __read_value_number(obj)
    if not obj then return nil end
    if obj:IsA("ValueBase") then
        local v = obj.Value
        if type(v) == "number" and v > 0 then return v end
        local n = tonumber(tostring(v):gsub(",", "."))
        if n and n > 0 then return n end
    end
    return nil
end

local function __kg_from_weight_child(tool)
    if not tool then return nil end

    local n = __read_value_number(tool:FindFirstChild("Weight"))
    if n then return n end

    for _, desc in ipairs(tool:GetDescendants()) do
        if desc.Name == "Weight" and desc:IsA("ValueBase") then
            n = __read_value_number(desc)
            if n then return n end
        end
    end
    return nil
end

local function __kg_from_direct_attrs(tool, rec)
    if tool then
        for _, k in ipairs(__KG_DIRECT_KEYS) do
            local aw = tool:GetAttribute(k)
            if aw ~= nil then
                local n = tonumber(tostring(aw):gsub(",", "."))
                if n and n > 0 then return n end
            end
        end
    end
    if type(rec) == "table" then
        local d = rec.ItemData or rec.Data or rec
        local n = __number_from_candidates(rec, __KG_DIRECT_KEYS)
            or __number_from_candidates(d, __KG_DIRECT_KEYS)
        if n and n > 0 then return n end
    end
    return nil
end

local function __kg_from_base_times_multi(tool, rec)
    local base, multi, og = nil, nil, 1

    if tool then
        for _, k in ipairs(__KG_BASE_KEYS) do
            local v = tool:GetAttribute(k)
            if v ~= nil then
                base = tonumber(tostring(v):gsub(",", "."))
                if base and base > 0 then break end
            end
        end
        multi = tonumber(tostring(tool:GetAttribute("SizeMulti")
            or tool:GetAttribute("SizeMultiplier")
            or tool:GetAttribute("WeightMulti")
            or tool:GetAttribute("WeightMultiplier") or ""):gsub(",", "."))
        og = tonumber(tool:GetAttribute("OvertimeGrowth")) or 1
    end

    if (not base or base <= 0) and type(rec) == "table" then
        local d = rec.ItemData or rec.Data or rec
        base = __number_from_candidates(rec, __KG_BASE_KEYS)
            or __number_from_candidates(d, __KG_BASE_KEYS)
    end

    if (not multi or multi <= 0) and type(rec) == "table" then
        local d = rec.ItemData or rec.Data or rec
        multi = __number_from_candidates(rec, __KG_MULTI_KEYS)
            or __number_from_candidates(d, __KG_MULTI_KEYS)
    end

    if base and base > 0 and multi and multi > 0 then
        return base * multi * og
    end
    return nil
end

local function __kg_from_multiplier_only(tool, rec)
    if tool then
        for _, k in ipairs(__KG_MULTI_KEYS) do
            local aw = tool:GetAttribute(k)
            if aw ~= nil then
                local n = tonumber(tostring(aw):gsub(",", "."))
                if n and n > 0 then return n end
            end
        end
    end
    if type(rec) == "table" then
        local d = rec.ItemData or rec.Data or rec
        local n = __number_from_candidates(rec, __KG_MULTI_KEYS)
            or __number_from_candidates(d, __KG_MULTI_KEYS)
        if n and n > 0 then return n end
    end
    return nil
end

local function __getFruitVisualizer()
    local now = os.clock()
    if _fruitViz and (now - _fruitVizAt) <= 3 then
        return _fruitViz
    end
    _fruitVizAt = now
    _fruitViz = nil

    local ps = LP:FindFirstChild("PlayerScripts")
    local controllers = ps and ps:FindFirstChild("Controllers")
    local mod = controllers and controllers:FindFirstChild("FruitVisualizerController")
    if mod and mod:IsA("ModuleScript") then
        local ok, ctrl = pcall(require, mod)
        if ok and type(ctrl) == "table" then
            _fruitViz = ctrl
        end
    end
    return _fruitViz
end

local function __kg_from_viz(tool)
    if not tool then return nil end
    local viz = __getFruitVisualizer()
    if not viz then return nil end
    local ok, kg = pcall(function()
        if type(viz.CalculateFruitWeight) == "function" then
            return viz.CalculateFruitWeight(viz, tool)
        end
        if type(viz.CalculatePlantWeight) == "function" then
            return viz.CalculatePlantWeight(viz, tool)
        end
        return nil
    end)
    if ok and type(kg) == "number" and kg > 0 then
        return kg
    end
    return nil
end

local function __kg_from_text(tool)
    if not tool then return nil end

    local sv = tool:FindFirstChild("Item_String")
    if sv and sv:IsA("ValueBase") then
        local kg = __parseKgFromText(tostring(sv.Value))
        if kg and kg > 0 then return kg end
    end

    local kg = __parseKgFromText(tool.ToolTip)
    if kg and kg > 0 then return kg end
    return __parseKgFromText(tool.Name)
end

local function __kg_from_tool_values(tool)
    if not tool then return nil end
    for _, ch in ipairs(tool:GetChildren()) do
        if ch:IsA("ValueBase") then
            local n = __read_value_number(ch)
            if n and n > 0 then return n end
        end
    end
    return nil
end

local __resolve_kg

local function __refresh_kg_rows(rows, tools, invSvcByCore)
    tools = tools or __buildToolIndex()
    for _, row in ipairs(rows or {}) do
        if not row.kg or tonumber(row.kg) <= 0 then
            local core = select(1, __normUUID(row.listingId or row.key or row.uuid))
            local te = core and tools[core]
            if te and te.tool then
                row.tool = te.tool
                row.hasTool = true
                local ok, kg = pcall(__resolve_kg, te.tool, row.raw, invSvcByCore and invSvcByCore[core])
                if ok and kg and kg > 0 then
                    row.kg = kg
                    row.name = __buildLabel(row.fruitName, row.mut or "", row.variant or "", kg)
                end
            end
        end
    end
end

local function __kg_from_rec(rec)
    return __kg_from_direct_attrs(nil, rec)
        or __kg_from_base_times_multi(nil, rec)
        or __kg_from_multiplier_only(nil, rec)
end

local function __kg_from_tool(tool)
    return __resolve_kg(tool, nil, nil)
end

-------------------------------------------------------------
-- MERGE SOURCES
-------------------------------------------------------------
local function __getInventoryData()
    if type(DataService) ~= "table" or type(DataService.GetData) ~= "function" then
        return nil
    end
    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if not ok or type(profile) ~= "table" then return nil end
    local inv = profile.InventoryData
    return type(inv) == "table" and inv or nil
end

local function __isHoldableType(t)
    t = tostring(t or ""):lower()
    return t == "holdable" or t:find("hold", 1, true) ~= nil
end

local function __resolveUuid(rawKey, rec)
    local core, braced = __normUUID(rawKey)
    if core then return core, braced or core end
    if type(rec) == "table" then
        local d = rec.ItemData or rec.Data or rec
        core, braced = __normUUID(d.UUID or d.ItemId or rec.UUID or rec.ItemId)
        if core then return core, braced or core end
    end
    return nil, nil
end

local __KG_SCAN_HINTS = {
    "weight", "kg", "sizemulti", "sizemultiplier", "weightmulti", "baseweight", "harvestweight",
}

local function __key_looks_like_kg(k)
    k = tostring(k):lower()
    for _, pat in ipairs(__KG_SCAN_HINTS) do
        if k:find(pat, 1, true) then return true end
    end
    return false
end

local function __scan_table_for_kg(tbl, depth)
    if type(tbl) ~= "table" or depth > 4 then return nil end
    for k, v in pairs(tbl) do
        if type(k) == "string" and __key_looks_like_kg(k) then
            local n = tonumber(v)
            if n and n > 0 then return n end
        end
    end
    for _, v in pairs(tbl) do
        if type(v) == "table" then
            local n = __scan_table_for_kg(v, depth + 1)
            if n then return n end
        end
    end
    return nil
end

local function __buildInvSvcHoldableIndex()
    local byCore = {}
    if type(InventoryService) ~= "table" or type(InventoryService.Find) ~= "function" then
        return byCore
    end
    local ok, items = pcall(function()
        return InventoryService:Find("Holdable")
    end)
    if not ok or type(items) ~= "table" then
        return byCore
    end
    for rawKey, item in pairs(items) do
        if type(item) == "table" then
            local core = select(1, __resolveUuid(rawKey, item))
            if core then
                byCore[core] = item
            end
        end
    end
    return byCore
end

-- Sugar Apple: Tool.Weight | Bone Blossom: SizeMulti / datastore / InventoryService
__resolve_kg = function(tool, rec, svcRec)
    local kg = __kg_from_weight_child(tool)
    if kg then return kg end

    kg = __kg_from_tool_values(tool)
    if kg then return kg end

    kg = __kg_from_direct_attrs(tool, rec)
    if kg then return kg end

    if type(rec) == "table" then
        kg = __scan_table_for_kg(rec, 0)
        if kg then return kg end
    end

    kg = __kg_from_base_times_multi(tool, rec)
    if kg then return kg end

    kg = __kg_from_multiplier_only(tool, rec)
    if kg then return kg end

    if type(svcRec) == "table" then
        kg = __kg_from_direct_attrs(nil, svcRec)
            or __kg_from_base_times_multi(nil, svcRec)
            or __kg_from_multiplier_only(nil, svcRec)
            or __scan_table_for_kg(svcRec, 0)
        if kg then return kg end
    end

    kg = __kg_from_viz(tool)
    if kg then return kg end

    return __kg_from_text(tool)
end

local function __collectAllFruits()
    local byCore = {}
    local tools = __buildToolIndex()
    local invSvcByCore = __buildInvSvcHoldableIndex()

    local function add(core, uuid, rec, toolEntry, listingId)
        if not core or byCore[core] then return end

        local tool = toolEntry and toolEntry.tool or nil
        local fruitName = (toolEntry and toolEntry.fruitName ~= "" and toolEntry.fruitName)
            or __fruitNameFromRec(rec)

        if fruitName == "" or fruitName == "Fruit" then
            if tool then
                fruitName = tostring(tool:GetAttribute("f") or tool:GetAttribute("F") or fruitName)
            end
        end

        local mut = __mutation_label(rec, tool)
        local variant = __variant_label(rec)
        local okKg, kg = pcall(__resolve_kg, tool, rec, invSvcByCore[core])
        if not okKg then kg = nil end

        local exactId = listingId or uuid
        local itemType = "Holdable"
        if type(rec) == "table" and rec.ItemType then
            itemType = rec.ItemType
        end
        byCore[core] = {
            uuid      = uuid,
            key       = exactId,
            listingId = exactId,
            name      = __buildLabel(fruitName, mut, variant, kg),
            fruitName = fruitName,
            niceName  = __niceFruitName(fruitName),
            mut       = mut,
            variant   = variant,
            kg        = kg,
            fav       = __is_favorite(rec, tool),
            hasTool   = tool ~= nil,
            tool      = tool,
            itemType  = itemType,
            raw       = rec,
        }
    end

    -- Source of truth (TradeBoothInventoryController): DataService.InventoryData keys
    local inv = __getInventoryData()
    if inv then
        for rawKey, rec in pairs(inv) do
            if type(rec) == "table" and rec.ItemType == "Holdable" then
                local core, uuid = __resolveUuid(rawKey, rec)
                if core then
                    add(core, uuid, rec, tools[core], tostring(rawKey))
                end
            end
        end
    end

    -- Tool di backpack tapi belum ada di InventoryData (mobile sync lambat)
    for core, te in pairs(tools) do
        if not byCore[core] and te and te.tool then
            add(core, te.uuid or core, nil, te, te.uuid or core)
        end
    end

    local out = {}
    for _, row in pairs(byCore) do
        out[#out + 1] = row
    end

    table.sort(out, function(a, b)
        local na = tostring(a.niceName or a.fruitName)
        local nb = tostring(b.niceName or b.fruitName)
        if na ~= nb then return na < nb end
        local ka = tonumber(a.kg) or -1
        local kb = tonumber(b.kg) or -1
        if ka ~= kb then return ka < kb end
        return tostring(a.uuid) < tostring(b.uuid)
    end)

    __refresh_kg_rows(out, tools, invSvcByCore)
    return out
end

local function __safe_collect_all_fruits()
    local ok, res = pcall(__collectAllFruits)
    if ok and type(res) == "table" then
        return res
    end
    warn("[fruit_list_view] collect error:", res)
    return {}
end

local function listFruitsNotFav()
    local all = __safe_collect_all_fruits()
    local out = {}
    for _, f in ipairs(all) do
        if not f.fav then
            out[#out + 1] = f
        end
    end
    return out
end

local function listFruitsAll()
    return __safe_collect_all_fruits()
end

local function __isFruitSelected(f, selectedSet)
    local keys = { f.listingId, f.key, f.uuid }
    for _, k in ipairs(keys) do
        if k and (selectedSet[k] == true or selectedSet[tostring(k)] == true) then
            return true
        end
    end
    return false
end

local function resolveListingId(uuidOrKey)
    local core = select(1, __normUUID(uuidOrKey))
    local inv = __getInventoryData()
    if inv then
        for rawKey, rec in pairs(inv) do
            if type(rec) == "table" and rec.ItemType == "Holdable" then
                if tostring(rawKey) == tostring(uuidOrKey) then
                    return tostring(rawKey)
                end
                local bagCore = select(1, __normUUID(rawKey))
                if core and bagCore == core then
                    return tostring(rawKey)
                end
            end
        end
    end
    return tostring(uuidOrKey or "")
end

local function buildEntriesFruits(selectedSet)
    selectedSet = selectedSet or {}

    local ok, list = pcall(listFruitsNotFav)
    if not ok or type(list) ~= "table" then
        warn("[fruit_list_view] buildEntriesFruits error:", list)
        return {}
    end

    table.sort(list, function(a, b)
        local sa = __isFruitSelected(a, selectedSet) and 1 or 0
        local sb = __isFruitSelected(b, selectedSet) and 1 or 0
        if sa ~= sb then return sa > sb end
        return tostring(a.name) < tostring(b.name)
    end)

    local out = {}
    for _, f in ipairs(list) do
        local key = f.listingId or f.key or f.uuid
        out[#out + 1] = { key = key, name = f.name }
    end
    return out
end

