-- BOOTH: listed holdables
-------------------------------------------------------------
local function listFruitsListedBooth()
    local out = {}

    local okRep, RepRecv = pcall(function()
        return require(ReplicatedStorage.Modules.ReplicationReciever)
    end)
    local okTB, TradeBoothsData = pcall(function()
        return require(ReplicatedStorage.Data.TradeBoothsData)
    end)
    if not okRep or not okTB then
        return out
    end

    local Booths = RepRecv.new("Booths")
    local data
    local okData = pcall(function()
        data = Booths:GetDataAsync()
    end)
    if not okData or type(data) ~= "table" then
        return out
    end

    local myId = TradeBoothsData.getPlayerId(LP)
    local p = data.Players and data.Players[myId]
    if not p then return out end

    local boothUUID = p.Booth
    if not boothUUID then return out end

    local booth = data.Booths and data.Booths[boothUUID]
    if not booth or not booth.Owner then return out end

    local ownerId = booth.Owner
    local ownerData = data.Players and data.Players[ownerId]
    if not (ownerData and ownerData.Listings and ownerData.Items) then
        return out
    end

    for listingUUID, listing in pairs(ownerData.Listings) do
        local itemId = listing and listing.ItemId
        local itemType = listing and listing.ItemType
        local price = listing and listing.Price or 0
        local itemData = itemId and ownerData.Items[itemId]

        local isHoldable = false
        if itemType and tostring(itemType):lower():find("hold") then
            isHoldable = true
        elseif type(itemData) == "table" and not itemData.PetType then
            local nm = itemData.ItemName or itemData.Name
            if nm and nm ~= "" then
                isHoldable = true
            end
        end

        if isHoldable and itemData then
            local core, br = __normUUID(itemId)
            local uuid = br or core or tostring(itemId)

            local fruitName = tostring(itemData.ItemName or itemData.Name or "Fruit")
            local mut = __mutation_label(itemData, nil)
            local variant = __variant_label(itemData)
            local nice = __niceFruitName(fruitName)

            local mutPrefix = (mut ~= "") and ("[" .. mut .. "] ") or ""
            local varSuffix = (variant ~= "") and (" (" .. variant .. ")") or ""
            local label = string.format("%s%s%s | Price %s", mutPrefix, nice, varSuffix, tostring(price))

            out[#out + 1] = {
                uuid        = uuid,
                key         = uuid,
                name        = label,
                fruitName   = fruitName,
                price       = price,
                listingUUID = listingUUID,
                itemType    = itemType or "Holdable",
                mut         = mut,
                variant     = variant,
            }
        end
    end

    local bagByUuid = {}
    for _, f in ipairs(listFruitsAll()) do
        if f and f.uuid then
            bagByUuid[tostring(f.uuid)] = f
        end
    end
    for _, row in ipairs(out) do
        local bag = bagByUuid[tostring(row.uuid)]
        if bag then
            row.kg = bag.kg
        end
    end

    table.sort(out, function(a, b)
        if (a.price or 0) ~= (b.price or 0) then
            return (a.price or 0) < (b.price or 0)
        end
        if (a.kg or 0) ~= (b.kg or 0) then
            return (a.kg or 0) < (b.kg or 0)
        end
        return tostring(a.fruitName) < tostring(b.fruitName)
    end)

    return out
end

local function buildEntriesListedFruitsBooth(selectedSet)
    selectedSet = selectedSet or {}
    local list = listFruitsListedBooth()

    table.sort(list, function(a, b)
        local sa = (selectedSet[a.uuid] == true) and 1 or 0
        local sb = (selectedSet[b.uuid] == true) and 1 or 0
        if sa ~= sb then return sa > sb end
        return tostring(a.name) < tostring(b.name)
    end)

    local out = {}
    for _, f in ipairs(list) do
        out[#out + 1] = { key = f.uuid, name = f.name }
    end
    return out
end

local function normFruitNameKey(name)
    return tostring(name or ""):lower():gsub("%s+", "")
end

-- Ringan: dropdown FA/FB cuma butuh nama buah, tanpa scan kg (HP 170+ fruit)
local function __collectFruitNameCounts()
    local byKey = {}
    local tools = __buildToolIndex()

    local function bump(fruitName)
        fruitName = tostring(fruitName or "")
        if fruitName == "" or fruitName == "Fruit" then return end
        local nk = normFruitNameKey(fruitName)
        if nk == "" then return end
        local row = byKey[nk]
        if not row then
            row = {
                key   = fruitName,
                name  = __niceFruitName(fruitName),
                count = 0,
            }
            byKey[nk] = row
        end
        row.count = (row.count or 0) + 1
    end

    for _, te in pairs(tools) do
        if te and te.fruitName and te.fruitName ~= "" then
            bump(te.fruitName)
        end
    end

    local inv = __getInventoryData()
    if inv then
        for rawKey, rec in pairs(inv) do
            if type(rec) == "table" and rec.ItemType == "Holdable" then
                local core = select(1, __resolveUuid(rawKey, rec))
                if core and tools[core] then
                    continue
                end
                bump(__fruitNameFromRec(rec))
            end
        end
    end

    return byKey
end

local function buildEntriesFruitNames(selectedSet)
    selectedSet = selectedSet or {}

    local ok, byKey = pcall(__collectFruitNameCounts)
    if not ok or type(byKey) ~= "table" then
        warn("[fruit_list_view] buildEntriesFruitNames error:", byKey)
        return {}
    end

    local list = {}
    for _, row in pairs(byKey) do
        list[#list + 1] = row
    end

    table.sort(list, function(a, b)
        local sa = (selectedSet[a.key] == true or selectedSet[tostring(a.key)] == true) and 1 or 0
        local sb = (selectedSet[b.key] == true or selectedSet[tostring(b.key)] == true) and 1 or 0
        if sa ~= sb then return sa > sb end
        return tostring(a.name) < tostring(b.name)
    end)

    local out = {}
    for _, row in ipairs(list) do
        local label = tostring(row.name)
        if (row.count or 0) > 1 then
            label = label .. " (" .. tostring(row.count) .. ")"
        end
        out[#out + 1] = { key = row.key, name = label }
    end
    return out
end

local function parseKgSigned(text)
    local s = tostring(text or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if s == "" then return 0 end
    local n = tonumber(s)
    if n == nil then
        n = tonumber((s:gsub(",", ".")))
    end
    if n == nil then return 0 end
    if n % 1 == 0 then return math.floor(n) end
    return tonumber(string.format("%.2f", n)) or 0
end

local function fruitKgMatches(kg, kgSigned)
    kgSigned = tonumber(kgSigned) or 0
    if kgSigned == 0 then return true end
    kg = tonumber(kg)
    if kg == nil then return false end
    if kgSigned > 0 then return kg >= kgSigned end
    return kg <= math.abs(kgSigned)
end

local _priceSuffixes = nil
local function getPriceSuffixes()
    if _priceSuffixes then return _priceSuffixes end
    local ok, TradeUIStaticData = pcall(function()
        return require(ReplicatedStorage.Modules.TradeControllers.TradingUserInterfaceController.TradeUIStaticData)
    end)
    if ok and type(TradeUIStaticData) == "table" and type(TradeUIStaticData.Suffixes) == "table" then
        _priceSuffixes = TradeUIStaticData.Suffixes
    else
        _priceSuffixes = {
            "CENT", "VIG", "NOV", "OCT", "SEP", "SXD", "QUI", "QUA", "TR", "DU", "UN", "DE", "NO", "OC", "SP", "SX", "QI", "QA", "T", "B", "M", "K",
        }
    end
    return _priceSuffixes
end

local function escapePattern(s)
    return tostring(s):gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%1")
end

local function parseNumberToken(numStr)
    numStr = tostring(numStr or ""):gsub("%s+", "")
    if numStr == "" then return nil end
    numStr = numStr:gsub(",", "")
    return tonumber(numStr)
end

local function parseCompactNumber(text, maxCap)
    local raw = tostring(text or "")
    local s = string.upper(raw:gsub("^%s+", ""):gsub("%s+$", ""))
    if s == "" then return 0 end

    local Suffixes = getPriceSuffixes()
    for i = #Suffixes, 1, -1 do
        local suf = string.upper(tostring(Suffixes[i] or ""))
        if suf ~= "" then
            local num = string.match(s, "^([%d%.,]+)" .. escapePattern(suf) .. "$")
            if num and num ~= "" then
                local v = parseNumberToken(num)
                if v then
                    local mult = 1000 ^ (#Suffixes - i + 1)
                    local out = math.floor(v * mult + 0.5)
                    if out < 1 then out = 1 end
                    if maxCap and out > maxCap then out = maxCap end
                    return out
                end
            end
        end
    end

    local digits = s:gsub("%D+", "")
    local v = tonumber(digits) or 0
    v = math.floor(v + 0.5)
    if v < 0 then v = 0 end
    if maxCap and v > maxCap then v = maxCap end
    return v
end

local function parseCompactPrice(text)
    return parseCompactNumber(text, 100000000)
end

local function parseSignedCompactPrice(text)
    local raw = tostring(text or "")
    local s = raw:gsub("^%s+", ""):gsub("%s+$", "")
    if s == "" then return 0 end

    local negative = false
    if s:sub(1, 1) == "-" then
        negative = true
        s = s:sub(2):gsub("^%s+", "")
    end

    local value = parseCompactNumber(s, nil)
    if negative then return -value end
    return value
end

local function npcPriceMatches(value, npcPriceSigned)
    npcPriceSigned = tonumber(npcPriceSigned) or 0
    if npcPriceSigned == 0 then return true end
    value = tonumber(value)
    if value == nil then return false end
    if npcPriceSigned > 0 then return value >= npcPriceSigned end
    return value <= math.abs(npcPriceSigned)
end

local function __mutationMultiplierFromTool(tool)
    if not tool or not MutationHandler then return 1 end
    local ok, mult = pcall(function()
        return MutationHandler:CalcValueMulti(tool)
    end)
    if ok and type(mult) == "number" and mult > 0 then
        return mult
    end
    return 1
end

local function __npcSellValueFromRow(row)
    if type(row) ~= "table" or not CalculatePlantValue then return nil end

    local tool = row.tool
    if tool then
        local ok, value = pcall(function()
            return CalculatePlantValue(tool)
        end)
        if ok and type(value) == "number" and value > 0 then
            return math.floor(value + 0.5)
        end
    end

    local kg = tonumber(row.kg)
    if (not kg or kg <= 0) and tool then
        local core = select(1, __normUUID(row.listingId or row.key or row.uuid))
        local svc = core and __buildInvSvcHoldableIndex()[core] or nil
        kg = __resolve_kg(tool, row.raw, svc)
    end
    if not kg or kg <= 0 then return nil end

    local rec = row.raw
    local d = (type(rec) == "table") and (rec.ItemData or rec.Data or rec) or {}
    local name = tostring(row.fruitName or d.ItemName or d.HoldableName or "")
    if name == "" or name == "Fruit" then return nil end

    local variant = tostring(d.Variant or row.variant or "Normal")
    local fruitVersion = tonumber(d.FruitVersion or rec.FruitVersion) or 0
    local mutMult = __mutationMultiplierFromTool(tool)

    local ok, value = pcall(function()
        return CalculatePlantValue({
            name               = name,
            variant            = variant,
            weight             = kg,
            mutationMultiplier = mutMult,
            fruitVersion       = fruitVersion,
        })
    end)
    if ok and type(value) == "number" and value > 0 then
        return math.floor(value + 0.5)
    end
    return nil
end

local function getNpcSellValue(row)
    return __npcSellValueFromRow(row)
end

local function makeRuleIdFA(fruitName, kgSigned)
    return ("FA|%s|%s"):format(tostring(fruitName or ""), tostring(kgSigned or 0))
end

local function makeRuleIdFB(fruitName)
    return ("FB|%s"):format(tostring(fruitName or ""))
end

local function kgSignedText(kgSigned)
    kgSigned = tonumber(kgSigned) or 0
    if kgSigned == 0 then return "Any KG" end
    local abs = math.abs(kgSigned)
    if kgSigned < 0 then
        return ("<= %s kg"):format(__fmtKg(abs))
    end
    return (">= %s kg"):format(__fmtKg(abs))
end

local function npcPriceSignedText(npcPriceSigned)
    npcPriceSigned = tonumber(npcPriceSigned) or 0
    if npcPriceSigned == 0 then return "Any NPC" end
    local abs = math.abs(npcPriceSigned)
    if npcPriceSigned < 0 then
        return ("<= %s"):format(tostring(abs))
    end
    return (">= %s"):format(tostring(abs))
end

