local function ensureMarketRemotes()
    if not FRONT_POS then
        local tw = workspace:FindFirstChild("TradeWorld")
        local plat = tw and tw:FindFirstChild("PortalPetePlatform")
        if plat then
            FRONT_REF = plat
            FRONT_POS = getPos(plat)
        end
    end

    if not TradeWorldController then
        local mods = ReplicatedStorage:FindFirstChild("Modules")
        local tc = mods and mods:FindFirstChild("TradeControllers")
        local twc = tc and tc:FindFirstChild("TradeWorldController")
        if twc then
            local ok, mod = pcall(require, twc)
            if ok then
                TradeWorldController = mod
            end
        end
    end

    if not TradeEvents then
        local ge = ReplicatedStorage:FindFirstChild("GameEvents")
        TradeEvents = ge and ge:FindFirstChild("TradeEvents")
    end

    if TradeEvents and not BoothsRE then
        BoothsRE = TradeEvents:FindFirstChild("Booths")
    end

    if BoothsRE then
        RF_Create = RF_Create or BoothsRE:FindFirstChild("CreateListing")
        RF_Remove = RF_Remove or BoothsRE:FindFirstChild("RemoveListing")
        RE_Claim = RE_Claim or BoothsRE:FindFirstChild("ClaimBooth")
        RE_AddToHistory = RE_AddToHistory or BoothsRE:FindFirstChild("AddToHistory")
    end

    return RF_Create ~= nil
        and RF_Remove ~= nil
        and RE_Claim ~= nil
        and type(TradeWorldController) == "table"
        and type(TradeWorldController.IsInWorld) == "function"
end

