local function _uuidKey(u)
    -- normalize like your normUUID (lower + trim spaces)
    u = tostring(u or ""):lower()
    u = u:gsub("%s+", "")
    return u
end

local function _copyPetSnap(s)
    if type(s) ~= "table" then return nil end
    -- copy minimal fields (avoid referencing mutable tables)
    local muts = nil
    if type(s.muts) == "table" then
        muts = {}
        for i = 1, #s.muts do muts[i] = s.muts[i] end
    end
    return {
        uuid   = s.uuid,
        ptype  = s.ptype,
        age    = s.age,
        kg     = s.kg,
        baseKg = s.baseKg,
        muts   = muts or {},
    }
end


local function dprint(...)
    if not CFG.DEBUG then return end
    local parts = {}
    for i = 1, select("#", ...) do parts[#parts+1] = tostring(select(i, ...)) end
    warn("[market_loop]", table.concat(parts, " "))
end

local function listedByUUIDToArray(listedByUUID)
    local arr = {}
    for _, it in pairs(listedByUUID or {}) do
        arr[#arr + 1] = it
    end
    return arr
end

local function now()
    return os.clock()
end

local function canUnlist()
    return (now() - (_lastUnlistAt or 0)) >= (CFG.UNLIST_CD_SEC or 0.2)
end

local function canList()
    return (now() - (_lastListAt or 0)) >= (CFG.LIST_CD_SEC or 0.85)
end

local function markUnlist()
    _lastUnlistAt = now()
end

local function markList()
    _lastListAt = now()
end

local function canAct()
    return (now() - (_lastActionAt or 0)) >= (CFG.COOLDOWN_SEC or 0.5)
end

local function markAct()
    _lastActionAt = now()
end

local function normStr(s)
    s = tostring(s or ""):lower()
    s = s:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    return s
end

local function normUUID(u)
    u = tostring(u or "")
    u = u:lower()
    u = u:gsub("%s+", "")
    -- optional kalau ada format GUID beda:
    -- u = u:gsub("[{}%-]", "")
    return u
end

local function toNum(x, default)
    local n = tonumber(x)
    if n == nil then return default end
    return n
end

local function round1(x)
    x = tonumber(x) or 0
    return math.floor(x * 10 + 0.5) / 10
end

local function _asMax(v)
    v = tonumber(v)
    if v == nil then return math.huge end
    return v
end

local function inRangeHalfOpen(kg, minKg, maxKg)
    kg    = toNum(kg, 0)              -- NO round
    minKg = toNum(minKg, 0)
    maxKg = toNum(maxKg, nil)         -- nil = INF
    local aMax = _asMax(maxKg)
    return (kg >= minKg) and (kg < aMax)
end

local function inRangeInclusiveAge(age, minAge, maxAge)
    age = math.floor(toNum(age, 1) + 0.5)
    if age < 1 then age = 1 end
    minAge = math.floor(toNum(minAge, 0) + 0.5)
    local maxV = toNum(maxAge, nil)
    if maxV == nil then
        return age >= minAge
    end
    maxV = math.floor(maxV + 0.5)
    return (age >= minAge) and (age <= maxV)
end


local function isWebhookEnabled()
    local STATE = rawget(_G, "STATE") or G.STATE
    local wb = STATE and STATE.webhook
    if type(wb) == "table" and wb.enabled ~= nil then
        return wb.enabled == true
    end
    return false
end


local function _emit(eventName, payload, opts)
    if not isWebhookEnabled() then return false end

    eventName = tostring(eventName or "")
    if eventName == "" then return false end
    opts = (type(opts) == "table") and opts or nil

    -- prefer injected sender
    if type(_webhookSend) == "function" then
        local ok, err = pcall(function()
            _webhookSend(eventName, payload, opts)
        end)
        if not ok then dprint("webhook send error:", err) end
        return ok
    end

    -- fallback: kalau kamu punya global Webhook module
    local W = rawget(G, "Webhook") or rawget(_G, "Webhook")
    if type(W) == "table" and type(W.Send) == "function" then
        local ok, err = pcall(function()
            W.Send(eventName, payload, opts)
        end)
        if not ok then dprint("Webhook.Send error:", err) end
        return ok
    end

    -- silent kalau belum ada
    dprint("webhook skipped (no sender) event=", eventName)
    return false
end

----------------------------------------------------------------
-- Resolve HOLDABLE itemType (buat CreateListing fruit)
-- TradeBoothInventoryController: type = v.ItemType string "Holdable"
----------------------------------------------------------------
local _cachedHoldableItemType = nil

local _holdableIdCache = nil
local _holdableIdCacheAt = 0

local function refreshHoldableIdCache()
    local now = os.clock()
    if _holdableIdCache and (now - _holdableIdCacheAt) < 1.5 then
        return
    end
    _holdableIdCacheAt = now
    _holdableIdCache = {}

    if not DataService or type(DataService.GetData) ~= "function" then
        return
    end

    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if not ok or type(profile) ~= "table" then
        return
    end

    local inv = profile.InventoryData
    if type(inv) ~= "table" then
        return
    end

    for rawKey, rec in pairs(inv) do
        if type(rec) == "table" and rec.ItemType == "Holdable" then
            local nk = normUUID(rawKey)
            local exact = tostring(rawKey)
            if nk ~= "" then
                _holdableIdCache[nk] = exact
            end
            _holdableIdCache[exact] = exact
        end
    end
end

local function resolveHoldableListingId(rawUuid)
    if _FruitListView and type(_FruitListView.resolveListingId) == "function" then
        local ok, id = pcall(function()
            return _FruitListView.resolveListingId(rawUuid)
        end)
        if ok and id and id ~= "" then
            return id
        end
    end

    refreshHoldableIdCache()
    local raw = tostring(rawUuid or "")
    if _holdableIdCache and _holdableIdCache[raw] then
        return _holdableIdCache[raw]
    end

    local nk = normUUID(rawUuid)
    if _holdableIdCache and _holdableIdCache[nk] then
        return _holdableIdCache[nk]
    end

    return raw
end

local function resolveHoldableItemType(listedBooth)
    if _cachedHoldableItemType ~= nil then
        return _cachedHoldableItemType
    end

    if type(listedBooth) == "table" then
        for _, it in ipairs(listedBooth) do
            if it and it.itemType ~= nil then
                if tostring(it.itemType):lower() == "holdable" then
                    _cachedHoldableItemType = it.itemType
                    dprint("HoldableItemType from booth listing =", it.itemType)
                    return it.itemType
                end
            end
        end
    end

    _cachedHoldableItemType = "Holdable"
    dprint("HoldableItemType = Holdable (per TradeBoothInventoryController)")
    return _cachedHoldableItemType
end

local function isPetMode(mode)
    mode = tostring(mode or ""):upper()
    return mode == "A" or mode == "B"
end

local function isFruitMode(mode)
    mode = tostring(mode or ""):upper()
    return mode == "F" or mode == "FA" or mode == "FB"
end

local function isSkinMode(mode)
    mode = tostring(mode or ""):upper()
    return mode == "S"
end

local function listPriority(mode)
    mode = tostring(mode or ""):upper()
    if mode == "A" then return 0 end
    if mode == "B" then return 1 end
    if mode == "F" then return 2 end
    if mode == "FA" then return 3 end
    if mode == "FB" then return 4 end
    if mode == "S" then return 5 end
    return 6
end

local function resolveSkinIdFromItem(itemId, itemData)
    if type(itemData) == "table" then
        local d = itemData.ItemData or itemData.Data
        local sid = itemData.SkinID or itemData.skinId or itemData.Id
            or (type(d) == "table" and (d.SkinID or d.skinId or d.Id))
        if sid ~= nil and tostring(sid) ~= "" then
            return tostring(sid)
        end
        local nm = itemData.Name or itemData.ItemName
            or (type(d) == "table" and (d.Name or d.ItemName))
        if nm ~= nil and tostring(nm) ~= "" then
            return tostring(nm)
        end
    end
    if itemId ~= nil and tostring(itemId) ~= "" then
        return tostring(itemId)
    end
    return nil
end

-- Owned TradeBoothSkin yang boleh di-list (exclude Default + CurrentSkin)
-- Catatan: JANGAN filter TradeLocks di sini — skin yang sedang listed sering
-- terkunci / qty=0 di OwnedSkins; kalau di-skip dari desired → unlist loop.
local function getListableBoothSkins()
    local out = {}
    local ok, profile = pcall(function()
        local mods = ReplicatedStorage:FindFirstChild("Modules")
        local dsMod = mods and mods:FindFirstChild("DataService")
        if not dsMod then return nil end
        local DS = require(dsMod)
        if not DS or type(DS.GetData) ~= "function" then return nil end
        return DS:GetData()
    end)
    if not ok or type(profile) ~= "table" then
        return out
    end

    local skinData = profile.TradeBoothSkinData
    if type(skinData) ~= "table" or type(skinData.OwnedSkins) ~= "table" then
        return out
    end

    local current = tostring(skinData.CurrentSkin or "")
    for id, qty in pairs(skinData.OwnedSkins) do
        local skinId = tostring(id or "")
        if skinId ~= "" and skinId ~= "Default" and skinId ~= current then
            if typeof(qty) ~= "boolean" and (tonumber(qty) or 0) > 0 then
                out[skinId] = true
            end
        end
    end
    return out
end

local function resolveFruitListingId(want)
    if type(want) ~= "table" then return nil end
    if want.listingId and tostring(want.listingId) ~= "" then
        return tostring(want.listingId)
    end
    return resolveHoldableListingId(want.rawUuid or want.uuidKey)
end

