local function registerBoothInstance(inst)
    if not inst or not inst.Parent then return end
    local boothUUID = tostring(inst.Name or "")
    if boothUUID ~= "" then
        boothInstances[boothUUID] = inst
    end
end

local function buildBoothInstanceMapFallback()
    boothInstances = boothInstances or {}
    local ok, tagged = pcall(function()
        return CollectionService:GetTagged("TradeBooth")
    end)
    if ok and type(tagged) == "table" then
        for _, inst in ipairs(tagged) do
            registerBoothInstance(inst)
        end
    else
        for _, inst in ipairs(workspace:GetDescendants()) do
            if inst:IsA("Model") and inst:HasTag("TradeBooth") then
                registerBoothInstance(inst)
            end
        end
    end
end

local function startObserveBooths()
    boothInstances = boothInstances or {}

    if Observers and type(Observers.observeTag) == "function" then
        pcall(function()
            Observers.observeTag("TradeBooth", function(inst)
                registerBoothInstance(inst)
            end)
        end)
    end

    buildBoothInstanceMapFallback()
end

