local function getMK()
    local STATE = rawget(_G, "STATE") or G.STATE
    if type(STATE) ~= "table" then return nil end
    local main = STATE.main
    local mk   = main and main.auto_market
    if type(mk) ~= "table" then return nil end
    mk.list  = (type(mk.list)  == "table") and mk.list  or {}
    mk.fruitList = (type(mk.fruitList) == "table") and mk.fruitList or {}
    mk.modeFA = (type(mk.modeFA) == "table") and mk.modeFA or { kg=0, price=0, selected={} }
    mk.modeFB = (type(mk.modeFB) == "table") and mk.modeFB or { npcPrice="", price="", selected={} }
    mk.fruitMode = (mk.fruitMode == "FB") and "FB" or "FA"
    mk.modeA = (type(mk.modeA) == "table") and mk.modeA or { price=0, selected={} }
    mk.modeB = (type(mk.modeB) == "table") and mk.modeB or { price=0, kg=0, selected={} }
    mk.mode  = (tostring(mk.mode or "A"):upper() == "B") and "B" or "A"
    return mk
end

