-- ------------------------------------------------------------
-- BOOTH PRIORITY (cycle order)
-- ------------------------------------------------------------
local __cycleOrder = nil

local function __ensureCycleOrder()
    if __cycleOrder then return end
    __cycleOrder = {}

    for boothUUID, inst in pairs(boothInstances) do
        local p = getPos(inst)
        local dist = math.huge
        if p and FRONT_POS then
            dist = (p - FRONT_POS).Magnitude
        end
        __cycleOrder[#__cycleOrder+1] = { id = tostring(boothUUID), dist = dist }
    end

    table.sort(__cycleOrder, function(a,b)
        if a.dist ~= b.dist then return a.dist < b.dist end
        return a.id < b.id
    end)
end




local function __isBoothEmptyById(data, boothId)
    local rec = data and data.Booths and data.Booths[boothId]
    return (type(rec) == "table" and rec.Owner == nil)
end

local function __pickPreferredEmptyBooth(data)
    __ensureCycleOrder()
    for _, rec in ipairs(__cycleOrder) do
        local bid = rec.id
        if __isBoothEmptyById(data, bid) then
            local inst = boothInstances[bid]
            if inst then return bid, inst end
        end
    end
    return nil
end


local function __getMyBoothId(data)
    local myId = getMyPlayerId()
    local me = myId and data and data.Players and data.Players[myId]
    return me and me.Booth or nil
end

local function __indexOfBoothId(boothId)
    __ensureCycleOrder()
for i, rec in ipairs(__cycleOrder) do
    if rec.id == boothId then return i end
end

    return nil
end

local function __findBetterEmptyBeforeMine(data, myBoothId)
    __ensureCycleOrder()
    local myIdx = __indexOfBoothId(myBoothId)
    if not myIdx then return nil end

    for i = 1, myIdx-1 do
        local bid = __cycleOrder[i].id

        if __isBoothEmptyById(data, bid) then
            local inst = boothInstances[bid]
            if inst then
                return bid, inst
            end
        end
    end
    return nil
end

local function __isInFrontRing(boothId)
    __ensureCycleOrder()
    boothId = tostring(boothId or "")
    local limit = tonumber(CFG.FRONT_RING_SIZE) or 14
    for i = 1, math.min(limit, #__cycleOrder) do
        if __cycleOrder[i].id == boothId then
            return true, i
        end
    end
    return false, __indexOfBoothId(boothId)
end

local function __pickEmptyInFrontRing(data)
    __ensureCycleOrder()
    local limit = tonumber(CFG.FRONT_RING_SIZE) or 14
    for i = 1, math.min(limit, #__cycleOrder) do
        local bid = __cycleOrder[i].id
        if __isBoothEmptyById(data, bid) then
            local inst = boothInstances[bid]
            if inst then return bid, inst end
        end
    end
    return nil
end

local function walkToBooth(inst)

    local char = LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end

    local pos = getPos(inst)
    if not pos then return end

    hrp.CFrame = CFrame.new(pos + Vector3.new(0,3,0))
end

----------------------------------------------------------------
-- Booth skin saat claim (Listing → Config Listing → Booth Skin Saat Claim)
----------------------------------------------------------------
local SKIN_EQUIP_RETRY_SEC = 5
local _lastSkinEquipAt = 0

local function ensureBoothSkin()
    local mk = getMK()
    local cfg = mk and mk.listingConfig
    local want = type(cfg) == "table" and tostring(cfg.claimSkin or "") or ""
    if want == "" then
        return
    end
    if not DataService or type(DataService.GetData) ~= "function" then
        return
    end

    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    local sd = ok and type(profile) == "table" and profile.TradeBoothSkinData
    if type(sd) ~= "table" then
        return
    end

    local cur = tostring(sd.CurrentSkin or "")
    if want == "Default" then
        if cur == "" or cur == "Default" then
            return
        end
    else
        if cur == want then
            return
        end
        -- skin harus dimiliki (bukan sedang di-listing semua)
        local owned = type(sd.OwnedSkins) == "table" and sd.OwnedSkins[want]
        if not owned or (type(owned) == "number" and owned <= 0) then
            return
        end
    end

    local t = now()
    if (t - _lastSkinEquipAt) < SKIN_EQUIP_RETRY_SEC then
        return
    end
    _lastSkinEquipAt = t

    pcall(function()
        ReplicatedStorage.GameEvents.TradeBoothSkinService.Equip:FireServer(want)
    end)
    dprint("Equip booth skin ->", want, "(was", cur, ")")
end

local function ensureClaimBooth()
    if not ensureMarketRemotes() then
        return false, "remotes_not_ready"
    end
    if not TradeWorldController:IsInWorld() then
        return false, "not_in_world"
    end

    local t = now()

    local data = getBoothsData()
    if not data then
        return false, "no_booths_data"
    end

    local myId = getMyPlayerId()
    if not myId then
        return false, "no_myid"
    end

    local me = data.Players and data.Players[myId]

    ----------------------------------------------------------------
    -- 1) Kalau sudah punya booth
    ----------------------------------------------------------------
    if me and me.Booth then
        local myBoothId = tostring(me.Booth)

        -- ✅ LOCK: kalau sudah di ring depan -> jangan pindah
        if CFG.LOCK_FRONT_RING then
            local inFront = false

            -- NOTE: __isInFrontRing bisa error kalau __indexOfBoothId urutannya salah.
            -- Jadi di sini aman: pakai pcall.
            local ok, res = pcall(function()
                return __isInFrontRing(myBoothId)
            end)
            if ok then inFront = (res == true) end

            if inFront then
                _lastClaimAt = t
                return true, "already_has_front_booth"
            end
        end

        -- ✅ kalau belum di front ring, boleh switch (opsional)
        if CFG.AUTO_SWITCH_BETTER_BOOTH then
            if (t - (_lastSwitchCheckAt or 0)) >= (CFG.SWITCH_CHECK_SEC or 12) then
                _lastSwitchCheckAt = t

                -- target switch: cari kosong di FRONT RING saja
                local betterId, betterInst = nil, nil
                local okPick, errPick = pcall(function()
                    betterId, betterInst = __pickEmptyInFrontRing(data)
                end)

                if okPick and betterInst then
                    dprint("Switch booth ->", myBoothId, "=>", betterId)

                    -- remove booth dulu baru claim
                    pcall(function()
                        -- ini asumsi remote remove ada (di kode kamu sudah dipakai)
                        BoothsRE.RemoveBooth:FireServer()
                    end)

                    task.wait(0.2)

                    pcall(function()
                        RE_Claim:FireServer(betterInst)
                    end)
                    
                    task.wait(0.2)
                    walkToBooth(betterInst)

                    _lastClaimAt = t
                    return false, "switch_sent"
                end
            end
        end

        _lastClaimAt = t
        return true, "already_has_booth"
    end

    ----------------------------------------------------------------
    -- 2) Belum punya booth -> tunggu retry (jangan spam claim)
    ----------------------------------------------------------------
    if (t - (_lastClaimAt or 0)) < (CFG.CLAIM_RETRY_SEC or 4) then
        return false, "claim_cooldown"
    end

    local targetBoothUUID, inst = nil, nil

    -- prioritas ring depan
    if CFG.LOCK_FRONT_RING then
        local okPick = pcall(function()
            targetBoothUUID, inst = __pickEmptyInFrontRing(data)
        end)
        if not okPick then
            targetBoothUUID, inst = nil, nil
        end
    end

    -- fallback: ambil mana saja kalau depan penuh
    if (not targetBoothUUID) and (CFG.ALLOW_FALLBACK_BACK_RING ~= false) then
        local okPick = pcall(function()
            targetBoothUUID, inst = __pickPreferredEmptyBooth(data)
        end)
        if not okPick then
            targetBoothUUID, inst = nil, nil
        end
    end

    if not targetBoothUUID or not inst then
        _lastClaimAt = t
        return false, "no_empty_booth"
    end

    dprint("ClaimBooth ->", targetBoothUUID, inst:GetFullName())
    _lastClaimAt = t

    pcall(function()
        RE_Claim:FireServer(inst)
    end)
    
    task.wait(0.2)
    walkToBooth(inst)

    return false, "claim_sent"
end


----------------------------------------------------------------
-- Read current listed booth (real)
----------------------------------------------------------------
local function listCurrentBooth()
    if not RepRecv or not TradeBoothsData then
        return {}
    end

    local Booths = RepRecv.new("Booths")
    local ok, d = pcall(function()
        return Booths:GetDataAsync()
    end)
    if not ok or type(d) ~= "table" then
        return {}
    end

    local myId = nil
    local okId, id = pcall(function()
        return TradeBoothsData.getPlayerId(LP)
    end)
    if okId then myId = id end
    if not myId then
        return {}
    end

    local p = d.Players and d.Players[myId]
    if not (p and p.Booth) then
        return {}
    end

    local boothUUID = p.Booth
    local booth = d.Booths and d.Booths[boothUUID]
    if not (booth and booth.Owner) then
        return {}
    end

    local ownerId = booth.Owner
    local ownerData = d.Players and d.Players[ownerId]
    if not (ownerData and type(ownerData.Listings) == "table") then
        return {}
    end

    local out = {}
    for listingUUID, listing in pairs(ownerData.Listings) do
        if type(listing) == "table" then
            local itemId = listing.ItemId
            local price  = listing.Price or listing.price or 0
            local itemType = listing.ItemType or listing.itemType

            local itemData = ownerData.Items and itemId and ownerData.Items[itemId]
            local ptype = itemData and (itemData.PetType or itemData.Name or itemData.ItemName)
            local skinId = nil
            local uuid = itemId and tostring(itemId) or nil

            -- Booth skin: key desired/listed harus SkinID, bukan ItemId mentah
            if tostring(itemType or "") == "TradeBoothSkin" then
                skinId = resolveSkinIdFromItem(itemId, itemData)
                if skinId and skinId ~= "" then
                    uuid = skinId
                    ptype = skinId
                end
            end

            out[#out+1] = {
                uuid        = uuid,      -- ✅ ini yang dipakai mapListedByUUID
                listingUUID = tostring(listingUUID),
                price       = tonumber(price) or 0,
                itemType    = itemType,
                ptype       = ptype and tostring(ptype) or nil,
                skinId      = skinId,
                itemId      = itemId and tostring(itemId) or nil,
            }
        end
    end

    return out
end


local function mapListedByUUID(listed)
    local by = {}
    for _, it in ipairs(listed or {}) do
        if it and it.uuid then
            by[normUUID(it.uuid)] = it
        end
        -- alias SkinID / ItemId biar match desired tidak miss
        if it and it.skinId and it.skinId ~= it.uuid then
            by[normUUID(it.skinId)] = it
        end
        if it and it.itemId and it.itemId ~= it.uuid then
            local k = normUUID(it.itemId)
            if by[k] == nil then
                by[k] = it
            end
        end
    end
    return by
end


local function getNotFavList()
    if not _PetListView then
        local gplv = rawget(_G, "PetListView") or rawget(G, "PetListView")
        if type(gplv) == "table" then
            _PetListView = gplv
            dprint("AUTO-INJECT _PetListView from _G.PetListView ok")
        else
            dprint("getNotFavList: _PetListView=nil AND _G.PetListView missing. type(gplv)=", type(gplv))
            return {}
        end
    end
    if type(_PetListView.listPetsNotFav) ~= "function" then
        dprint("getNotFavList: _PetListView.listPetsNotFav bukan function. type=", type(_PetListView.listPetsNotFav))
        return {}
    end

    local ok, res = pcall(function()
        return _PetListView.listPetsNotFav()
    end)

    if not ok then
        dprint("getNotFavList: listPetsNotFav ERROR:", res)
        return {}
    end

    if type(res) ~= "table" then
        dprint("getNotFavList: listPetsNotFav return type bukan table:", type(res))
        return {}
    end

    dprint("getNotFavList: count =", #res)
    return res
end

----------------------------------------------------------------
-- CACHE REFRESH
----------------------------------------------------------------
local function refreshNotFavSnapshot()
    if not _PetListView or type(_PetListView.listPetsNotFav) ~= "function" then
        return
    end

    local ok, pets = pcall(function()
        return _PetListView.listPetsNotFav()
    end)
    if not ok or type(pets) ~= "table" then
        return
    end

    -- rebuild map (fresh snapshot)
    local newMap = {}
    for _, p in ipairs(pets) do
        if type(p) == "table" and p.uuid then
            local k = _uuidKey(p.uuid)
            if k ~= "" then
                newMap[k] = {
                    uuid   = p.uuid,
                    ptype  = p.ptype,   -- already normalized lower in your PetListView
                    age    = p.age,
                    kg     = p.kg,
                    baseKg = p.baseKg,
                    muts   = p.muts,
                }
            end
        end
    end
    _snapByUUID = newMap
end

local function refreshListedBoothSnapshot()
    if not _PetListView or type(_PetListView.listPetsListedBooth) ~= "function" then
        return
    end

    local ok, listedNow = pcall(function()
        return _PetListView.listPetsListedBooth()
    end)
    if not ok or type(listedNow) ~= "table" then
        return
    end

    local t = now()
    local seen = {}

    -- add/update listings
    for _, li in ipairs(listedNow) do
        if type(li) == "table" and li.listingUUID then
            local listingUUID = tostring(li.listingUUID)
            seen[listingUUID] = true

            local uuidKey = _uuidKey(li.uuid)
            local petSnap = (uuidKey ~= "" and _snapByUUID[uuidKey]) or nil

            _listedByListingUUID[listingUUID] = {
                listingUUID = listingUUID,
                uuidKey     = uuidKey,
                uuid        = li.uuid,
                price       = li.price,
                itemType    = li.itemType,
                ptype       = li.ptype,
                muts        = li.muts,                 -- from booth itemData (optional)
                pet         = _copyPetSnap(petSnap),   -- from notfav snapshot (most accurate)
                seenAt      = t,
            }

            if uuidKey ~= "" then
                _listingUUIDByUUID[uuidKey] = listingUUID
            end
        end
    end

    -- move missing (gone) listings into grace cache
    for listingUUID, old in pairs(_listedByListingUUID) do
        if not seen[listingUUID] then
            old.goneAt = t
            _recentGoneListings[listingUUID] = old
            _listedByListingUUID[listingUUID] = nil
        end
    end

    -- prune grace cache
    for listingUUID, rec in pairs(_recentGoneListings) do
        if type(rec) == "table" then
            local goneAt = tonumber(rec.goneAt) or t
            if (t - goneAt) > CACHE_GONE_GRACE_SEC then
                _recentGoneListings[listingUUID] = nil
            end
        else
            _recentGoneListings[listingUUID] = nil
        end
    end
end

local function refreshSoldCaches()
    -- order matters: refresh pet snapshot first, then booth snapshot joins it
    refreshNotFavSnapshot()
    refreshListedBoothSnapshot()
end

local function buildNotFavIndex(petsNotFav)
    local byUUID = {}
    local byType = {}
    for _, p in ipairs(petsNotFav or {}) do
        if p and p.uuid then
            local uuid = tostring(p.uuid)
            byUUID[uuid] = p
            local t = normStr(p.ptype)
            byType[t] = byType[t] or {}
            table.insert(byType[t], p)
        end
    end
    return byUUID, byType
end

local function collectCandidatesForRange(petsNotFav, petTypeKey, minKg, maxKg, minAge, maxAge, usedUUID, mutation)
    petTypeKey = normStr(petTypeKey)
    mutation = tostring(mutation == nil and "*" or mutation)
    local mutLower = string.lower(mutation)

    local function petMatchesMutation(p)
        if mutLower == "*"
            or mutLower == "all"
            or mutLower == "all mutation"
            or mutLower == "(all mutation)"
        then
            return true
        end

        local names = {}
        if type(p) == "table" then
            if type(p.muts) == "table" then
                for _, m in ipairs(p.muts) do
                    local s = tostring(m or ""):gsub("^%s+", ""):gsub("%s+$", "")
                    if s ~= "" then
                        names[#names + 1] = string.lower(s)
                    end
                end
            elseif type(p.muts) == "string" then
                local s = p.muts:gsub("^%s+", ""):gsub("%s+$", "")
                if s ~= "" then
                    names[1] = string.lower(s)
                end
            end
        end

        if mutLower == ""
            or mutLower == "none"
            or mutLower == "no mutation"
            or mutLower == "(no mutation)"
        then
            return #names == 0
        end

        for _, n in ipairs(names) do
            if n == mutLower then
                return true
            end
        end
        return false
    end

    local cand = {}

    for _, p in ipairs(petsNotFav or {}) do
        local uuid = p and p.uuid and tostring(p.uuid)
        if uuid then
            local uuidKey = normUUID(uuid)
            if uuidKey ~= "" and not usedUUID[uuidKey] then
                local ptype = normStr(p.ptype)
                if ptype == petTypeKey and petMatchesMutation(p) then
                    local kg = toNum(p.baseKg, toNum(p.kg, 0))

                    if inRangeHalfOpen(kg, minKg, maxKg) then
                        local age = toNum(p.age, 1)
                        if age < 1 then age = 1 end

                        if inRangeInclusiveAge(age, minAge, maxAge) then
                            -- scoring: pilih yang "paling pas" dekat min (lebih stabil)
                            -- + sedikit age biar tie-break stabil
                            local score = math.abs(kg - round1(toNum(minKg, 0))) + (age * 0.01)

                            cand[#cand+1] = {
                                p = p,
                                uuidKey = uuidKey,
                                score = score,
                                kg = kg,
                                age = age,
                            }
                        end
                    end
                end
            end
        end
    end

    table.sort(cand, function(a, b)
        if a.score ~= b.score then return a.score < b.score end
        if a.kg ~= b.kg then return a.kg < b.kg end
        return tostring(a.uuidKey) < tostring(b.uuidKey)
    end)

    return cand
end

local function normFruitNameKey(name)
    if _FruitListView and type(_FruitListView.normFruitNameKey) == "function" then
        return _FruitListView.normFruitNameKey(name)
    end
    return tostring(name or ""):lower():gsub("%s+", "")
end

local function fruitKgMatches(kg, kgSigned)
    if _FruitListView and type(_FruitListView.fruitKgMatches) == "function" then
        return _FruitListView.fruitKgMatches(kg, kgSigned)
    end
    kgSigned = tonumber(kgSigned) or 0
    if kgSigned == 0 then return true end
    kg = tonumber(kg)
    if kg == nil then return false end
    if kgSigned > 0 then return kg >= kgSigned end
    return kg <= math.abs(kgSigned)
end

local function getFruitsNotFav()
    if not _FruitListView then
        local gflv = rawget(_G, "FruitListView") or rawget(G, "FruitListView")
        if type(gflv) == "table" then
            _FruitListView = gflv
        end
    end
    if not _FruitListView or type(_FruitListView.listFruitsNotFav) ~= "function" then
        return {}
    end
    local ok, res = pcall(function()
        return _FruitListView.listFruitsNotFav()
    end)
    if ok and type(res) == "table" then
        return res
    end
    return {}
end

local function npcPriceMatches(value, npcPriceSigned)
    if _FruitListView and type(_FruitListView.npcPriceMatches) == "function" then
        return _FruitListView.npcPriceMatches(value, npcPriceSigned)
    end
    npcPriceSigned = tonumber(npcPriceSigned) or 0
    if npcPriceSigned == 0 then return true end
    value = tonumber(value)
    if value == nil then return false end
    if npcPriceSigned > 0 then return value >= npcPriceSigned end
    return value <= math.abs(npcPriceSigned)
end

local function getFruitNpcSellValue(fruitRow)
    if _FruitListView and type(_FruitListView.getNpcSellValue) == "function" then
        local ok, value = pcall(function()
            return _FruitListView.getNpcSellValue(fruitRow)
        end)
        if ok then return value end
    end
    return nil
end

local function collectFruitCandidates(fruits, fruitName, kgSigned, usedUUID, npcPriceSigned)
    local wantKey = normFruitNameKey(fruitName)
    if wantKey == "" then return {} end

    local cand = {}
    for _, f in ipairs(fruits or {}) do
        if type(f) == "table" and not f.fav then
            local fn = normFruitNameKey(f.fruitName or f.niceName)
            if fn == wantKey then
                local listingId = f.listingId or f.key or f.uuid
                local uuidKey = normUUID(listingId)
                if uuidKey ~= "" and not usedUUID[uuidKey] then
                    local kg = toNum(f.kg, nil)
                    if fruitKgMatches(kg, kgSigned) then
                        local npcValue = getFruitNpcSellValue(f)
                        if npcPriceMatches(npcValue, npcPriceSigned) then
                            local targetKg = math.abs(toNum(kgSigned, 0))
                            local targetNpc = math.abs(toNum(npcPriceSigned, 0))
                            local score = 0
                            if kgSigned ~= 0 then
                                score = score + math.abs((kg or 0) - targetKg)
                            end
                            if npcPriceSigned ~= 0 then
                                score = score + math.abs((npcValue or 0) - targetNpc) * 0.000001
                            end
                            if kgSigned == 0 and npcPriceSigned == 0 then
                                score = kg or 0
                            end
                            cand[#cand + 1] = {
                                f         = f,
                                uuidKey   = uuidKey,
                                listingId = tostring(listingId),
                                kg        = kg or 0,
                                npcValue  = npcValue,
                                score     = score,
                            }
                        end
                    end
                end
            end
        end
    end

    table.sort(cand, function(a, b)
        if a.score ~= b.score then return a.score < b.score end
        if a.kg ~= b.kg then return a.kg < b.kg end
        return tostring(a.uuidKey) < tostring(b.uuidKey)
    end)

    return cand
end

local function addFruitDesired(desired, usedUUID, entry)
    if type(entry) ~= "table" then return end
    local uuidKey = entry.uuidKey
    if not uuidKey or uuidKey == "" or desired[uuidKey] then return end

    desired[uuidKey] = {
        mode       = entry.mode,
        price      = entry.price,
        sourceKey  = entry.sourceKey,
        rawUuid    = entry.rawUuid or entry.listingId,
        listingId  = entry.listingId,
        itemType   = entry.itemType or "Holdable",
        fruitName  = entry.fruitName,
        kgSigned   = entry.kgSigned,
        ruleId     = entry.ruleId,
    }
    usedUUID[uuidKey] = true
end


local applyListingConfig
local applyAutoSlotPerType

local function buildDesired(mk, listedByUUID)
    -- desired key = normUUID(uuid)
    -- value: { mode="A"/"B", price=number, sourceKey=string, rawUuid=string, ruleId=string?, petType=string?, minKg=?, maxKg=? }
    local desired = {}
    local usedUUID = {}

    local petsNotFav = getNotFavList()

    local function readPetListingCfg()
        local cfg = mk and mk.listingConfig and mk.listingConfig.pet
        if type(cfg) ~= "table" then
            cfg = mk and mk.listingPetConfig
        end
        return (type(cfg) == "table") and cfg or nil
    end

    local function petSlotLimit()
        local cfg = readPetListingCfg()
        local n = math.floor(tonumber(cfg and cfg.maxSlots) or 0)
        if n < 0 then n = 0 end
        if n > 50 then n = 50 end
        return n
    end

    local function lookupTypeSlot(pt)
        local cfg = readPetListingCfg()
        if type(cfg) ~= "table" then return nil end
        pt = normStr(pt)
        if pt == "" then return nil end
        local per = cfg.perType
        if type(per) ~= "table" then return nil end
        local compact = pt:gsub("%s+", "")
        for k, v in pairs(per) do
            local nk = normStr(k)
            if nk == pt or nk:gsub("%s+", "") == compact then
                local n = math.floor(tonumber(v) or 0)
                if n <= 0 then return nil end
                return n
            end
        end
        return nil
    end

    local function countDesiredPet(typeKey)
        local cat, typed = 0, 0
        typeKey = typeKey and normStr(typeKey) or ""
        for _, want in pairs(desired) do
            if want then
                local m = tostring(want.mode or ""):upper()
                if m == "A" or m == "B" then
                    cat += 1
                    if typeKey ~= "" and normStr(want.petType) == typeKey then
                        typed += 1
                    end
                end
            end
        end
        return cat, typed
    end

    local function listingCfgOn()
        return type(mk.listingConfig) == "table" and mk.listingConfig.enabled == true
    end

    local function canAddPet(pt)
        if not listingCfgOn() then
            return true
        end
        local maxSlots = petSlotLimit()
        local cat, typed = countDesiredPet(pt)
        if maxSlots > 0 and cat >= maxSlots then
            return false
        end
        local tq = lookupTypeSlot(pt)
        if tq ~= nil and typed >= tq then
            return false
        end
        return true
    end

    local modeAKeys = {}
    local modeBRuleKeys = {}
    local modeFKeys = {}
    local modeFARuleKeys = {}
    local modeFBRuleKeys = {}

    -- pisahkan dari mk.list berdasarkan rec.mode
    for k, rec in pairs(mk.list or {}) do
        if type(rec) == "table" then
            local mode = tostring(rec.mode or "A"):upper()
            if mode == "B" then
                table.insert(modeBRuleKeys, tostring(k)) -- key = ruleId ("B|petType|min|max")
            else
                table.insert(modeAKeys, tostring(k)) -- key = uuid (raw)
            end
        end
    end

    -- fruit list — manual F / rule FA / rule FB
    for k, rec in pairs(mk.fruitList or {}) do
        if type(rec) == "table" then
            local mode = tostring(rec.mode or "F"):upper()
            if mode == "FA" then
                table.insert(modeFARuleKeys, tostring(k))
            elseif mode == "FB" then
                table.insert(modeFBRuleKeys, tostring(k))
            else
                table.insert(modeFKeys, tostring(k))
            end
        end
    end

    table.sort(modeAKeys)
    table.sort(modeFKeys)
    table.sort(modeFARuleKeys)
    table.sort(modeFBRuleKeys)
    table.sort(modeBRuleKeys) -- ruleId sudah stabil (mengandung type|min|max)

    ----------------------------------------------------------------
    -- MODE A: key = UUID langsung
    ----------------------------------------------------------------
    for _, rawUuid in ipairs(modeAKeys) do
        local rec = mk.list[rawUuid]
        if type(rec) == "table" then
           local price = toNum(rec.price, 0)
if price < 0 then price = 0 end

-- ✅ 0 = disable listing
if price > 0 then
    local uuidKey = normUUID(rawUuid)
    if uuidKey ~= "" then
        local petType = nil
        for _, p in ipairs(petsNotFav or {}) do
            if p and normUUID(p.uuid) == uuidKey then
                petType = p.ptype
                break
            end
        end
        if (petType == nil or tostring(petType) == "") and listedByUUID then
            local li = listedByUUID[uuidKey]
            petType = li and li.ptype
        end
        if canAddPet(petType) then
            desired[uuidKey] = {
                mode      = "A",
                price     = price,
                sourceKey = rawUuid,
                rawUuid   = rawUuid,
                petType   = petType,
            }
            usedUUID[uuidKey] = true
        end
    end
else
    -- optional debug
    -- dprint("ModeA skip (price<=0) uuid=", rawUuid)
end
        end
    end

    ----------------------------------------------------------------
    -- MODE FA/FB/F (FRUIT) — skip kalau tidak ada rule fruit
    ----------------------------------------------------------------
    local hasFruitRules = (#modeFKeys > 0) or (#modeFARuleKeys > 0) or (#modeFBRuleKeys > 0)
    if hasFruitRules then
    local fruitsNotFav = getFruitsNotFav()
    local listedArr = listedByUUIDToArray(listedByUUID)
    local holdableItemType = resolveHoldableItemType(listedArr)

    for _, ruleId in ipairs(modeFARuleKeys) do
        local rec = mk.fruitList[ruleId]
        if type(rec) == "table" then
            local price = toNum(rec.price, 0)
            if price > 0 then
                local fruitName = tostring(rec.fruitName or "")
                local kgSigned = toNum(rec.kg, 0)
                if fruitName ~= "" then
                    local candidates = collectFruitCandidates(fruitsNotFav, fruitName, kgSigned, usedUUID)
                    if #candidates > 0 then
                        local picked = {}
                        for _, li in pairs(listedByUUID or {}) do
                            if li and li.uuid then
                                local uuidKey = normUUID(li.uuid)
                                for _, c in ipairs(candidates) do
                                    if c.uuidKey == uuidKey and not usedUUID[uuidKey] then
                                        picked[#picked + 1] = c
                                        break
                                    end
                                end
                            end
                        end
                        for _, c in ipairs(candidates) do
                            if not usedUUID[c.uuidKey] then
                                local found = false
                                for _, p in ipairs(picked) do
                                    if p.uuidKey == c.uuidKey then found = true break end
                                end
                                if not found then
                                    picked[#picked + 1] = c
                                end
                            end
                        end
                        for _, c in ipairs(picked) do
                            addFruitDesired(desired, usedUUID, {
                                mode       = "FA",
                                price      = price,
                                sourceKey  = ruleId,
                                ruleId     = ruleId,
                                rawUuid    = c.listingId,
                                listingId  = c.listingId,
                                itemType   = holdableItemType or "Holdable",
                                fruitName  = fruitName,
                                kgSigned   = kgSigned,
                                uuidKey    = c.uuidKey,
                            })
                        end
                    end
                end
            end
        end
    end

    ----------------------------------------------------------------
    -- MODE FB (FRUIT PRICE RULE)
    ----------------------------------------------------------------
    for _, ruleId in ipairs(modeFBRuleKeys) do
        local rec = mk.fruitList[ruleId]
        if type(rec) == "table" then
            local price = toNum(rec.price, 0)
            if price > 0 then
                local fruitName = tostring(rec.fruitName or "")
                local npcPriceSigned = toNum(rec.npcPrice, 0)
                if fruitName ~= "" then
                    local candidates = collectFruitCandidates(fruitsNotFav, fruitName, 0, usedUUID, npcPriceSigned)
                    if #candidates > 0 then
                        local picked = {}
                        for _, li in pairs(listedByUUID or {}) do
                            if li and li.uuid then
                                local uuidKey = normUUID(li.uuid)
                                for _, c in ipairs(candidates) do
                                    if c.uuidKey == uuidKey and not usedUUID[uuidKey] then
                                        picked[#picked + 1] = c
                                        break
                                    end
                                end
                            end
                        end
                        for _, c in ipairs(candidates) do
                            if not usedUUID[c.uuidKey] then
                                local found = false
                                for _, p in ipairs(picked) do
                                    if p.uuidKey == c.uuidKey then found = true break end
                                end
                                if not found then
                                    picked[#picked + 1] = c
                                end
                            end
                        end
                        for _, c in ipairs(picked) do
                            addFruitDesired(desired, usedUUID, {
                                mode       = "FB",
                                price      = price,
                                sourceKey  = ruleId,
                                ruleId     = ruleId,
                                rawUuid    = c.listingId,
                                listingId  = c.listingId,
                                itemType   = holdableItemType or "Holdable",
                                fruitName  = fruitName,
                                npcPrice   = npcPriceSigned,
                                uuidKey    = c.uuidKey,
                            })
                        end
                    end
                end
            end
        end
    end

    ----------------------------------------------------------------
    -- MODE F (FRUIT MANUAL): key = listing id dari mk.fruitList
    ----------------------------------------------------------------
    for _, rawUuid in ipairs(modeFKeys) do
        local rec = mk.fruitList[rawUuid]
        if type(rec) == "table" then
            local price = toNum(rec.price, 0)
            if price < 0 then price = 0 end
            if price > 0 then
                local uuidKey = normUUID(rawUuid)
                if uuidKey ~= "" and not desired[uuidKey] then
                    local listingId = rec.listingId or resolveHoldableListingId(rawUuid)
                    desired[uuidKey] = {
                        mode       = "F",
                        price      = price,
                        sourceKey  = rawUuid,
                        rawUuid    = rawUuid,
                        listingId  = listingId,
                        itemType   = rec.itemType or holdableItemType or "Holdable",
                        fruitName  = rec.fruitName,
                    }
                    usedUUID[uuidKey] = true
                end
            end
        end
    end

    end -- hasFruitRules

    ----------------------------------------------------------------
    -- MODE S (BOOTH SKIN): key = normUUID(SkinID) dari mk.skinList
    -- Keep desired jika:
    --   a) masih owned/listable, ATAU
    --   b) sudah terpasang di booth (penting: owned qty sering 0 saat listed)
    ----------------------------------------------------------------
    do
        local listableSkins = getListableBoothSkins()
        -- listedByUUID is a map; build listed skin map from it directly
        local listedSkins = {}
        for k, li in pairs(listedByUUID or {}) do
            if li and tostring(li.itemType or "") == "TradeBoothSkin" then
                local sid = tostring(li.skinId or li.uuid or k)
                if sid ~= "" then
                    listedSkins[normUUID(sid)] = li
                end
            end
        end

        for skinKey, rec in pairs(mk.skinList or {}) do
            if type(rec) == "table" then
                local price = toNum(rec.price, 0)
                if price < 0 then price = 0 end
                if price > 0 then
                    local skinId = tostring(rec.skinId or skinKey)
                    local uuidKey = normUUID(skinId)
                    if uuidKey ~= "" and not desired[uuidKey] then
                        local ownedId = nil
                        if listableSkins[skinId] then
                            ownedId = skinId
                        else
                            for sid in pairs(listableSkins) do
                                if normUUID(sid) == uuidKey then
                                    ownedId = sid
                                    break
                                end
                            end
                        end

                        local alreadyListed = listedSkins[uuidKey]
                        if ownedId or alreadyListed then
                            local useId = ownedId
                                or (alreadyListed and (alreadyListed.skinId or alreadyListed.uuid))
                                or skinId
                            desired[uuidKey] = {
                                mode      = "S",
                                price     = price,
                                sourceKey = tostring(skinKey),
                                rawUuid   = tostring(useId),
                                uuid      = tostring(useId),
                                itemType  = rec.itemType or "TradeBoothSkin",
                            }
                            usedUUID[uuidKey] = true
                        end
                    end
                end
            end
        end
    end

    ----------------------------------------------------------------
    -- MODE B: key = ruleId, pilih UUID notfav yang cocok range [min,max)
    ----------------------------------------------------------------
    for _, ruleId in ipairs(modeBRuleKeys) do
        local rec = mk.list[ruleId]
        if type(rec) == "table" then
            local price = toNum(rec.price, 0)
if price < 0 then price = 0 end

-- ✅ 0 = disable listing rule
if price > 0 then
    local petType = tostring(rec.petType or "")
    if petType ~= "" then
        local minKg = round1(toNum(rec.minKg, 0))
        local maxKg = rec.maxKg
        if maxKg ~= nil then maxKg = round1(toNum(maxKg, nil)) end -- nil = INF

        local minAge = math.floor(toNum(rec.minAge, 0) + 0.5)
        local maxAge = rec.maxAge
        if maxAge == nil then
            -- legacy rule (Max Age INF / tidak diset) = tanpa batas atas
        else
            maxAge = math.floor(toNum(maxAge, 0) + 0.5)
            if maxAge < minAge then
                local tmp = minAge; minAge = maxAge; maxAge = tmp
            end
        end

        local wantCount = tonumber(rec.count)
        if wantCount ~= nil and wantCount < 1 then wantCount = 1 end

        local mutation = rec.mutation
        if mutation == nil then
            mutation = "*"
        else
            mutation = tostring(mutation)
        end

        local candidates = collectCandidatesForRange(petsNotFav, petType, minKg, maxKg, minAge, maxAge, usedUUID, mutation)

        if #candidates == 0 then
            dprint("ModeB: no candidates ruleId=", ruleId, "petType=", petType, "mut=", mutation, "range=[", minKg, ",", (maxKg==nil and "INF" or tostring(maxKg)), ")")
        else
            local candByUuidKey = {}
            for _, c in ipairs(candidates) do candByUuidKey[c.uuidKey] = c end

            local pickedList = {}

            for listedUuidKey, li in pairs(listedByUUID or {}) do
                if li and li.ptype and normStr(li.ptype) == normStr(petType) then
                    local c = candByUuidKey[listedUuidKey]
                    if c and not usedUUID[listedUuidKey] then
                        if not canAddPet(petType) then
                            break
                        end
                        pickedList[#pickedList+1] = c
                        usedUUID[listedUuidKey] = true
                        if wantCount and #pickedList >= wantCount then break end
                    end
                end
            end

            if (not wantCount) or (#pickedList < wantCount) then
                for _, c in ipairs(candidates) do
                    if not usedUUID[c.uuidKey] then
                        if not canAddPet(petType) then
                            break
                        end
                        pickedList[#pickedList+1] = c
                        usedUUID[c.uuidKey] = true
                        if wantCount and #pickedList >= wantCount then break end
                    end
                end
            end

            for _, c in ipairs(pickedList) do
                local p = c.p
                if p and p.uuid then
                    local uuidKey = c.uuidKey
                    desired[uuidKey] = {
                        mode      = "B",
                        price     = price,
                        sourceKey = ruleId,
                        ruleId    = ruleId,
                        petType   = petType,
                        minKg     = minKg,
                        maxKg     = maxKg,
                        minAge    = minAge,
                        maxAge    = maxAge,
                        mutation  = mutation,
                        rawUuid   = tostring(p.uuid),
                    }
                end
            end

            dprint("ModeB picked ruleId=", ruleId, "petType=", petType, "mut=", mutation, "picked=", #pickedList, "range=[", minKg, ",", (maxKg==nil and "INF" or tostring(maxKg)), ")")
        end
    else
        dprint("ModeB: skip rule (missing petType) ruleId =", ruleId)
    end
else
    -- optional debug
    -- dprint("ModeB skip (price<=0) ruleId=", ruleId)
end
        end
    end

    return applyListingConfig(mk, desired, petsNotFav, listedByUUID)
end

local function clampListingSlots(n, fallback)
    n = math.floor(tonumber(n) or fallback or 0)
    if n < 0 then n = 0 end
    if n > 50 then n = 50 end
    return n
end

local function sortedTypeList(typeSet)
    local list = {}
    for pt in pairs(typeSet or {}) do
        list[#list + 1] = pt
    end
    table.sort(list)
    return list
end

local function perTypeQuota(perType, typeList, keyFn)
    local quota = {}
    if type(perType) ~= "table" then
        return quota, false
    end
    local hasAny = false
    local raw = {}
    for k, v in pairs(perType) do
        local key = keyFn(k)
        if key ~= "" then
            local n = clampListingSlots(v, 0)
            if n > 0 then
                raw[key] = n
                raw[key:gsub("%s+", "")] = n
                hasAny = true
            end
        end
    end
    if not hasAny then
        return quota, false
    end
    for _, pt in ipairs(typeList) do
        if raw[pt] ~= nil then
            quota[pt] = raw[pt]
        end
        local compact = tostring(pt or ""):gsub("%s+", "")
        if compact ~= "" and raw[compact] ~= nil and quota[pt] == nil then
            quota[pt] = raw[compact]
        end
    end
    return quota, true
end

local function getListingCat(mk, cat)
    local root = mk and mk.listingConfig
    if type(root) == "table" and type(root[cat]) == "table" then
        return root[cat]
    end
    if cat == "pet" and type(mk and mk.listingPetConfig) == "table" then
        return mk.listingPetConfig
    end
    return nil
end

local function resolveCatQuota(cfg, typeList, keyFn)
    if type(cfg) ~= "table" then
        return nil, nil
    end
    local maxSlots = clampListingSlots(cfg.maxSlots, 0)
    if maxSlots <= 0 then
        return nil, nil
    end
    local quota, hasManual = perTypeQuota(cfg.perType, typeList, keyFn)
    if hasManual then
        return quota, maxSlots
    end
    return {}, maxSlots
end

local function applyCategoryCaps(desired, isMember, typeOf, keepPri, quota, maxSlots, listedByUUID)
    local items = {}
    for uuidKey, want in pairs(desired) do
        if want and isMember(want) then
            items[#items + 1] = {
                uuidKey = uuidKey,
                want = want,
                pri = keepPri(want),
                typeKey = typeOf(want, uuidKey) or "",
            }
        end
    end
    table.sort(items, function(a, b)
        local pa = tonumber(a.pri) or 9
        local pb = tonumber(b.pri) or 9
        if pa ~= pb then return pa < pb end
        local la = (listedByUUID and listedByUUID[a.uuidKey]) and 0 or 1
        local lb = (listedByUUID and listedByUUID[b.uuidKey]) and 0 or 1
        if la ~= lb then return la < lb end
        return tostring(a.uuidKey) < tostring(b.uuidKey)
    end)

    local hasTypeQuota = type(quota) == "table" and next(quota) ~= nil
    local usedType = {}
    local usedCat = 0

    local function quotaOf(typeKey)
        if not typeKey or typeKey == "" then return nil end
        if quota[typeKey] ~= nil then return quota[typeKey] end
        local compact = tostring(typeKey):gsub("%s+", "")
        return quota[compact]
    end

    for _, it in ipairs(items) do
        local drop = false
        if maxSlots and usedCat >= maxSlots then
            drop = true
        else
            local q = hasTypeQuota and quotaOf(it.typeKey) or nil
            if q ~= nil and (usedType[it.typeKey] or 0) >= q then
                drop = true
            end
        end
        if drop then
            desired[it.uuidKey] = nil
        else
            usedCat = usedCat + 1
            if it.typeKey ~= "" then
                usedType[it.typeKey] = (usedType[it.typeKey] or 0) + 1
            end
        end
    end
end

local function fruitBagByUUID()
    local bag = {}
    local flv = _FruitListView
    if type(flv) ~= "table" then
        flv = rawget(_G, "FruitListView") or rawget(G, "FruitListView")
        if type(flv) == "table" then
            _FruitListView = flv
        end
    end
    local fn = flv and (flv.listFruitsAll or flv.listFruitsNotFav)
    if type(fn) ~= "function" then
        return bag
    end
    local ok, list = pcall(fn)
    if ok and type(list) == "table" then
        for _, f in ipairs(list) do
            if type(f) == "table" then
                local id = f.uuid or f.listingId
                if id then
                    bag[normUUID(id)] = f.fruitName or f.niceName
                end
            end
        end
    end
    return bag
end

applyListingConfig = function(mk, desired, petsNotFav, listedByUUID)
    if type(desired) ~= "table" then
        return desired
    end
    if not (type(mk) == "table" and type(mk.listingConfig) == "table" and mk.listingConfig.enabled == true) then
        return desired
    end

    local byPetUUID = {}
    for _, p in ipairs(petsNotFav or {}) do
        if p and p.uuid then
            byPetUUID[normUUID(p.uuid)] = p
        end
    end
    if _PetListView and type(_PetListView.listPetsAll) == "function" then
        local okAll, allPets = pcall(_PetListView.listPetsAll)
        if okAll and type(allPets) == "table" then
            for _, p in ipairs(allPets) do
                if p and p.uuid then
                    local k = normUUID(p.uuid)
                    if byPetUUID[k] == nil then
                        byPetUUID[k] = p
                    end
                end
            end
        end
    end

    local function resolvePetType(want, uuidKey)
        local pt = normStr(want and want.petType)
        if pt == "" then
            local p = byPetUUID[uuidKey]
            pt = p and normStr(p.ptype or p.ptypeLabel) or ""
        end
        if pt == "" and listedByUUID then
            local li = listedByUUID[uuidKey]
            pt = normStr(li and li.ptype)
        end
        if want and pt ~= "" then
            want.petType = pt
        end
        return pt
    end

    local petTypes = {}
    for k, rec in pairs(mk and mk.list or {}) do
        if type(rec) == "table" then
            local mode = tostring(rec.mode or "A"):upper()
            local pt
            if mode == "B" then
                pt = rec.petType
            else
                local p = byPetUUID[normUUID(k)]
                pt = rec.petType or rec.ptype or (p and p.ptype)
            end
            pt = normStr(pt)
            if pt ~= "" then
                petTypes[pt] = true
            end
        end
    end
    for uuidKey, want in pairs(desired) do
        local pt = resolvePetType(want, uuidKey)
        if pt ~= "" then
            petTypes[pt] = true
        end
    end

    local petQuota, petMax = resolveCatQuota(getListingCat(mk, "pet"), sortedTypeList(petTypes), normStr)
    if petMax then
        applyCategoryCaps(
            desired,
            function(want)
                local m = tostring(want.mode or ""):upper()
                return m == "A" or m == "B"
            end,
            resolvePetType,
            function(want)
                return (tostring(want.mode or "") == "A") and 0 or 1
            end,
            petQuota,
            petMax,
            listedByUUID
        )
    end

    local byFruitUUID = fruitBagByUUID()

    local fruitTypes = {}
    for k, rec in pairs(mk and mk.fruitList or {}) do
        if type(rec) == "table" then
            local fn = rec.fruitName
            if fn == nil or tostring(fn) == "" then
                fn = byFruitUUID[normUUID(k)]
            end
            fn = normFruitNameKey(fn)
            if fn ~= "" then
                fruitTypes[fn] = true
            end
        end
    end
    for _, want in pairs(desired) do
        local fn = normFruitNameKey(want and want.fruitName)
        if fn ~= "" then
            fruitTypes[fn] = true
        end
    end

    local boothTypes = {}
    for k, rec in pairs(mk and mk.skinList or {}) do
        if type(rec) == "table" then
            local sid = normUUID(rec.skinId or k)
            if sid ~= "" then
                boothTypes[sid] = true
            end
        end
    end

    local fruitQuota, fruitMax = resolveCatQuota(getListingCat(mk, "fruit"), sortedTypeList(fruitTypes), normFruitNameKey)
    local boothQuota, boothMax = resolveCatQuota(getListingCat(mk, "booth"), sortedTypeList(boothTypes), normUUID)

    if fruitMax then
        applyCategoryCaps(
            desired,
            function(want)
                return isFruitMode(want.mode)
            end,
            function(want, uuidKey)
                local fn = normFruitNameKey(want.fruitName)
                if fn == "" then
                    fn = normFruitNameKey(byFruitUUID[uuidKey])
                    if fn ~= "" then
                        want.fruitName = byFruitUUID[uuidKey]
                    end
                end
                return fn
            end,
            function(want)
                return (tostring(want.mode or ""):upper() == "F") and 0 or 1
            end,
            fruitQuota,
            fruitMax,
            listedByUUID
        )
    end

    if boothMax then
        applyCategoryCaps(
            desired,
            function(want)
                return isSkinMode(want.mode)
            end,
            function(want, uuidKey)
                return normUUID(want.rawUuid or want.sourceKey or uuidKey)
            end,
            function()
                return 0
            end,
            boothQuota,
            boothMax,
            listedByUUID
        )
    end

    return desired
end

applyAutoSlotPerType = applyListingConfig



----------------------------------------------------------------
-- Diff -> queues
----------------------------------------------------------------
local function buildQueues(desired, listed, listedByUUID)
    local toUnlist = {} -- {listingUUID, uuid, reason}
    local toList   = {} -- {uuid, price, reason, mode, sourceKey}

    -- helper: cepat cek apakah sudah ada di toUnlist
    local willUnlistByUUID = {}
    local function markWillUnlist(uuid)
        if uuid then willUnlistByUUID[normUUID(uuid)] = true end
    end

    ----------------------------------------------------------------
    -- 1) Unlist "extra" + "price mismatch" (logika lama)
    ----------------------------------------------------------------
    for _, li in ipairs(listed or {}) do
        local uuid = li and li.uuid and tostring(li.uuid)
        local listingUUID = li and li.listingUUID
        if uuid and listingUUID then
            local uuidKey = normUUID(uuid)
            local want = desired[uuidKey]

            if not want then
                if CFG.CLEAN_EXTRA then
                    table.insert(toUnlist, { listingUUID=listingUUID, uuid=uuid, reason="extra_not_desired" })
                    markWillUnlist(uuid)
                end
            else
                local curPrice = toNum(li.price, 0)
                if curPrice ~= toNum(want.price, 0) then
                    table.insert(toUnlist, { listingUUID=listingUUID, uuid=uuid, reason="price_mismatch" })
                    markWillUnlist(uuid)
                end
            end
        end
    end

    ----------------------------------------------------------------
    -- 2) Hitung kebutuhan Mode A yang belum listed
    ----------------------------------------------------------------
    local missingA = {}
    for uuidKey, want in pairs(desired or {}) do
        if want and want.mode == "A" then
            if not listedByUUID[uuidKey] then
                table.insert(missingA, {
                    uuid      = uuidKey,
                    uuidKey   = uuidKey,
                    price     = want.price,
                    mode      = "A",
                    sourceKey = want.sourceKey,
                })
            end
        end
    end
    table.sort(missingA, function(a, b)
        return tostring(a.uuid) < tostring(b.uuid)
    end)

    ----------------------------------------------------------------
    -- 3) Booth penuh: evict Skin/Fruit supaya Pet (A lalu B) bisa masuk
    --    Pet > Fruit > Booth Skin. Mode B tidak di-evict kecuali butuh slot Mode A.
    ----------------------------------------------------------------
    local listedCount = #listed
    local willUnlist = #toUnlist
    local slotsAfter = math.max(0, CFG.MAX_SLOTS - (listedCount - willUnlist))

    local missingBCount = 0
    for uuidKey, want in pairs(desired or {}) do
        if want and tostring(want.mode or "") == "B" and not listedByUUID[uuidKey] then
            missingBCount += 1
        end
    end

    local missingPet = #missingA + missingBCount
    local needEvict = 0
    if slotsAfter < missingPet then
        needEvict = missingPet - slotsAfter
    end

    if needEvict > 0 then
        local evictCand = {}
        for _, li in ipairs(listed or {}) do
            local uuid = li and li.uuid and tostring(li.uuid)
            local listingUUID = li and li.listingUUID
            if uuid and listingUUID then
                local uuidKey = normUUID(uuid)
                if not willUnlistByUUID[uuidKey] then
                    local want = desired[uuidKey]
                    if want and isSkinMode(want.mode) then
                        table.insert(evictCand, {
                            uuid = uuid,
                            uuidKey = uuidKey,
                            listingUUID = listingUUID,
                            ptype = li.ptype,
                            price = toNum(li.price, 0),
                            sourceKey = want.sourceKey,
                            evictPri = 0,
                        })
                    elseif want and isFruitMode(want.mode) then
                        table.insert(evictCand, {
                            uuid = uuid,
                            uuidKey = uuidKey,
                            listingUUID = listingUUID,
                            ptype = li.ptype,
                            price = toNum(li.price, 0),
                            sourceKey = want.sourceKey,
                            evictPri = 1,
                        })
                    elseif want and want.mode == "B" and #missingA > 0 then
                        table.insert(evictCand, {
                            uuid = uuid,
                            uuidKey = uuidKey,
                            listingUUID = listingUUID,
                            ptype = li.ptype,
                            price = toNum(li.price, 0),
                            sourceKey = want.sourceKey,
                            evictPri = 2,
                        })
                    end
                end
            end
        end

        table.sort(evictCand, function(a, b)
            local pa = tonumber(a.evictPri) or 9
            local pb = tonumber(b.evictPri) or 9
            if pa ~= pb then return pa < pb end
            local pta = tostring(a.ptype or "")
            local ptb = tostring(b.ptype or "")
            if pta ~= ptb then return pta > ptb end
            return tostring(a.uuidKey) > tostring(b.uuidKey)
        end)

        for i = 1, math.min(needEvict, #evictCand) do
            local e = evictCand[i]
            table.insert(toUnlist, {
                listingUUID = e.listingUUID,
                uuid = e.uuid,
                reason = (e.evictPri == 0) and "evict_for_pet_skin"
                    or (e.evictPri == 1) and "evict_for_pet_fruit"
                    or "evict_for_modeA",
            })
            markWillUnlist(e.uuid)
        end

        willUnlist = #toUnlist
        slotsAfter = math.max(0, CFG.MAX_SLOTS - (listedCount - willUnlist))

        dprint("Evict for Pet:", "needEvict=", needEvict, "evicted=", math.min(needEvict, #evictCand), "slotsAfter=", slotsAfter)
    end

    ----------------------------------------------------------------
    -- 4) Build candidates toList — A dulu, lalu B, lalu fruit, lalu skin
    ----------------------------------------------------------------
    local candidates = {}

    for _, m in ipairs(missingA) do
        table.insert(candidates, m)
    end

    for uuidKey, want in pairs(desired or {}) do
        if want and (not listedByUUID[uuidKey]) then
            if want.mode == "B" then
                table.insert(candidates, {
                    uuid      = uuidKey,
                    uuidKey   = uuidKey,
                    price     = want.price,
                    mode      = want.mode,
                    sourceKey = want.sourceKey,
                })
            elseif isFruitMode(want.mode) then
                local listingId = resolveFruitListingId(want)
                table.insert(candidates, {
                    uuid      = listingId or want.rawUuid or uuidKey,
                    listingId = listingId,
                    uuidKey   = uuidKey,
                    price     = want.price,
                    mode      = want.mode,
                    sourceKey = want.sourceKey,
                    itemType  = want.itemType,
                })
            elseif isSkinMode(want.mode) then
                table.insert(candidates, {
                    uuid      = want.rawUuid or uuidKey,
                    uuidKey   = uuidKey,
                    price     = want.price,
                    mode      = want.mode,
                    sourceKey = want.sourceKey,
                    itemType  = want.itemType or "TradeBoothSkin",
                })
            end
        end
    end

    table.sort(candidates, function(a, b)
        local pa = listPriority(a.mode)
        local pb = listPriority(b.mode)
        if pa ~= pb then return pa < pb end
        return tostring(a.uuidKey or a.uuid) < tostring(b.uuidKey or b.uuid)
    end)

    for i = 1, math.min(slotsAfter, #candidates) do
        local c = candidates[i]
        table.insert(toList, {
            uuid      = c.uuid,
            listingId = c.listingId,
            price     = c.price,
            reason    = "missing",
            mode      = c.mode,
            sourceKey = c.sourceKey,
            itemType  = c.itemType,
        })
    end

    return toUnlist, toList
end


----------------------------------------------------------------
-- Execute actions
----------------------------------------------------------------
local function doUnlist(one)
    if not one or not one.listingUUID then return false end
    if not canUnlist() then return false end

    local ok, res = pcall(function()
        return RF_Remove:InvokeServer(one.listingUUID)
    end)

    markUnlist()

    local success = ok and (res == true or res == nil)
    dprint("Unlist", one.uuid, "listingUUID", one.listingUUID, "ok", ok, "res", res, "reason", one.reason)

    return success
end

local function buildItemIdCandidates(one)
    local seen = {}
    local out = {}

    local function add(id)
        id = tostring(id or "")
        if id == "" or seen[id] then return end
        seen[id] = true
        out[#out + 1] = id
    end

    if one.mode == "F" or one.mode == "FA" or one.mode == "FB" then
        add(one.listingId)
        add(one.sourceKey)
        add(resolveHoldableListingId(one.listingId or one.sourceKey or one.uuid))
    else
        add(one.listingId)
        add(one.sourceKey)
        add(resolveHoldableListingId(one.listingId or one.sourceKey or one.uuid))
    end

    return out
end

local function isCreateListingSuccess(ok, res, isFruit)
    if not ok then return false end
    if isFruit then
        return res == true or res == nil
    end
    return res == true or res == nil
end

local function doList(one, listedBooth)
    if not one or not one.uuid then return false end
    if not canList() then return false end

    local price = toNum(one.price, 0)
    if price < 1 then price = 1 end
    if price > 100000000 then price = 100000000 end

    if isFruitMode(one.mode) then
        local itemType = one.itemType or resolveHoldableItemType(listedBooth)
        if itemType == nil then
            dprint("List skip fruit: itemType nil mode=", one.mode, "uuid=", one.uuid)
            return false
        end

        _holdableIdCacheAt = 0
        refreshHoldableIdCache()

        local itemIds = buildItemIdCandidates(one)
        if #itemIds == 0 then
            dprint("List skip fruit: no itemId mode=", one.mode, "uuid=", one.uuid)
            return false
        end

        for _, itemId in ipairs(itemIds) do
            local ok, res = pcall(function()
                return RF_Create:InvokeServer(itemType, itemId, price)
            end)

            markList()
            dprint("List fruit", itemId, "type", itemType, "price", price, "ok", ok, "res", res, "mode", one.mode)

            if isCreateListingSuccess(ok, res, true) then
                local key = normUUID(one.listingId or one.uuid or itemId or "")
                if key ~= "" then
                    _listFailUntil[key] = nil
                end
                return true
            end
        end

        do
            local key = normUUID(one.listingId or one.uuid or "")
            if key ~= "" then
                _listFailUntil[key] = now() + (CFG.LIST_FAIL_SKIP_SEC or 30)
            end
        end
        dprint("FAILED fruit type=", itemType, "ids=", table.concat(itemIds, " | "), "price=", price)
        return false
    end

    if isSkinMode(one.mode) then
        local itemType = one.itemType or "TradeBoothSkin"
        local itemId = tostring(one.uuid or one.sourceKey or "")
        if itemId == "" then
            dprint("List skip skin: empty itemId mode=", one.mode)
            return false
        end

        local ok, res = pcall(function()
            return RF_Create:InvokeServer(itemType, itemId, price)
        end)

        markList()
        dprint("List skin", itemId, "type", itemType, "price", price, "ok", ok, "res", res, "mode", one.mode)

        local success = ok and (res == true or res == nil)
        if success then
            _listFailUntil[itemId] = nil
        else
            _listFailUntil[itemId] = now() + (CFG.LIST_FAIL_SKIP_SEC or 30)
        end
        return success
    end

    -- PET: sama persis versi sebelum fruit
    local ok, res = pcall(function()
        return RF_Create:InvokeServer("Pet", one.uuid, price)
    end)

    markList()

    dprint("List", one.uuid, "price", price, "ok", ok, "res", res, "mode", one.mode, "key", one.sourceKey)
    return ok and (res == true or res == nil)
end


----------------------------------------------------------------
-- WEBHOOK SOLD: Build payload from history log
----------------------------------------------------------------
local function _safeUser(u)
    if type(u) ~= "table" then return { userId = 0, username = "?" } end
    return {
        userId   = tonumber(u.userId) or 0,
        username = tostring(u.username or u.Name or "?"),
    }
end

local function getTradeTokenText()
    local ok, txt = pcall(function()
        local mods = ReplicatedStorage:FindFirstChild("Modules")
        local dsMod = mods and mods:FindFirstChild("DataService")
        if not dsMod then return nil end
        local DS = require(dsMod)
        if not DS or type(DS.GetData) ~= "function" then return nil end
        local profile = DS:GetData()
        if type(profile) ~= "table" then return nil end

        local td = profile.TradeData
        if type(td) == "table" then
            local n = tonumber(td.Tokens) or tonumber(td.TradeTokens)
            if n and n >= 0 then return tostring(n) end
        end
        for _, c in ipairs({
            profile.TradeTokens,
            profile.TradeToken,
            profile.Tokens,
            profile.tokens,
        }) do
            local n = tonumber(c)
            if n and n >= 0 then return tostring(n) end
        end
        return nil
    end)
    if ok then return txt end
    return nil
end


local function _inferItemName(itemData)
    if type(itemData) ~= "table" then return "Unknown" end
    -- dari history: item.data bisa punya ItemData atau PetType/SkinID
    local raw =
        (itemData.ItemData and itemData.ItemData.ItemName)
        or itemData.PetType
        or itemData.ItemName
        or itemData.Name
        or itemData.SkinID
        or "Unknown"
    return tostring(raw)
end

local function _inferItemId(itemRec)
    -- history: item.id (kadang), atau item.data punya id? aman fallback
    if type(itemRec) ~= "table" then return nil end
    local id = itemRec.id
    if id ~= nil then return tostring(id) end
    -- beberapa log: item.data mungkin punya ItemId?
    local d = itemRec.data
    if type(d) == "table" then
        local x = d.ItemId or d.UUID or d.Id
        if x ~= nil then return tostring(x) end
    end
    return nil
end

local _PetMutRegistry = nil
local function _getPetMutRegistry()
    if _PetMutRegistry ~= nil then
        return _PetMutRegistry ~= false and _PetMutRegistry or nil
    end
    local ok, mod = pcall(function()
        local data = ReplicatedStorage:FindFirstChild("Data")
        local petReg = data and data:FindFirstChild("PetRegistry")
        local m = petReg and petReg:FindFirstChild("PetMutationRegistry")
        return m and require(m) or nil
    end)
    if ok and type(mod) == "table" then
        _PetMutRegistry = mod
        return mod
    end
    ok, mod = pcall(function()
        return require(ReplicatedStorage.Data.PetRegistry.PetMutationRegistry)
    end)
    if ok and type(mod) == "table" then
        _PetMutRegistry = mod
        return mod
    end
    _PetMutRegistry = false
    return nil
end

local function _mutationEnumToName(mutEnum)
    if mutEnum == nil then return "" end
    local reg = _getPetMutRegistry()
    if type(mutEnum) == "string" then
        local s = mutEnum:gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" or s == "None" or s == "Normal" then return "" end
        if reg and reg.EnumToPetMutation then
            local name = reg.EnumToPetMutation[s]
            if name then return tostring(name) end
        end
        return s
    end
    if reg and reg.EnumToPetMutation then
        local name = reg.EnumToPetMutation[mutEnum]
        return name and tostring(name) or ""
    end
    return tostring(mutEnum)
end

local function _mutsFromPetData(pd)
    if type(pd) ~= "table" then return nil end
    local name = _mutationEnumToName(pd.MutationType)
    if name == "" then return nil end
    return { name }
end

local function _detailsFromHistoryItemData(itemData)
    local pd = (type(itemData) == "table" and (itemData.PetData or itemData.Data)) or nil
    local baseKg = nil
    local age = nil
    local kg = nil
    local muts = nil
    local ptype = nil

    if type(itemData) == "table" then
        ptype = itemData.PetType or itemData.SkinID
            or (itemData.ItemData and itemData.ItemData.ItemName)
            or nil
        if ptype ~= nil then ptype = tostring(ptype) end
    end

    if type(pd) == "table" then
        baseKg = toNum(pd.BaseWeight or pd.BaseWeightKG or pd.WeightBase, nil)
        age = toNum(pd.Level or pd.Age or pd.PetAge, nil)
        kg = toNum(pd.Weight or pd.KG or pd.Kg or pd.CurrentWeight, nil)
        muts = _mutsFromPetData(pd)
        if not ptype and pd.Name then
            -- Name is nickname; keep PetType preferred
        end
    end

    return {
        ptype = ptype,
        baseKg = baseKg,
        age = age,
        kg = kg,
        muts = muts,
        petData = pd,
    }
end

local function _getKgFromNotFavIndex(byUUID, uuidStr)
    if type(byUUID) ~= "table" or not uuidStr then return nil end
    local p = byUUID[uuidStr]
    if not p then return nil end
    return toNum(p.kg, nil), toNum(p.age, nil), tostring(p.ptype or "")
end

local function _connectHistoryIfNeeded()
    if _historyConn or not RE_AddToHistory or typeof(RE_AddToHistory) ~= "Instance" then
        return
    end
    if not RE_AddToHistory.OnClientEvent then
        return
    end

    _historyConn = RE_AddToHistory.OnClientEvent:Connect(function(log)
        -- log: {id, price, finishTime, seller, buyer, item={type,data,id?}, status={result}}
        if type(log) ~= "table" then return end

        local id = tostring(log.id or "")
        if id == "" then return end
        if _seenHistoryIds[id] then return end
        _seenHistoryIds[id] = true

        local n = 0
        for _ in pairs(_seenHistoryIds) do n += 1 end
        if n > 250 then
            _seenHistoryIds = { [id] = true }
        end

        local status = log.status
        if type(status) == "table" and tostring(status.result) == "Failed" then
            return
        end

        local myId = LP and LP.UserId or 0
        local seller = _safeUser(log.seller)
        local buyer = _safeUser(log.buyer)
        local isSold = (seller.userId == myId)
        local isBuy = (not isSold) and (buyer.userId == myId)
        if not isSold and not isBuy then
            return
        end

        if isSold then
            pcall(function()
                local env = (getgenv and getgenv()) or _G
                local AH = rawget(_G, "AutoHop") or (env and env.AutoHop)
                if type(AH) == "table" and type(AH.NotifySold) == "function" then
                    local price = tonumber(log.price) or 0
                    if (buyer.userId or 0) > 0 and price > 0 then
                        AH.NotifySold()
                    end
                end
            end)
        end

        local item = log.item
        local itemType = (type(item) == "table") and item.type or nil
        local itemData = (type(item) == "table") and item.data or nil
        local itemNameRaw = _inferItemName(itemData)

        local itemNameNice = itemNameRaw
        if ItemNameFinder and itemType ~= nil then
            local okName, n2 = pcall(function()
                return ItemNameFinder(itemNameRaw, itemType)
            end)
            if okName and type(n2) == "string" and n2 ~= "" then
                itemNameNice = n2
            end
        end

        local uuid = _inferItemId(item) or (type(itemData) == "table" and (itemData.ItemId or itemData.UUID)) or nil
        if uuid ~= nil then uuid = tostring(uuid) end

        local hist = _detailsFromHistoryItemData(itemData)
        local kg, age, ptype, muts, baseKg = hist.kg, hist.age, hist.ptype, hist.muts, hist.baseKg

        local uuidKey = uuid and _uuidKey(uuid) or ""
        local listingUUID = nil
        local snap = nil

        if isSold then
            listingUUID = (uuidKey ~= "" and _listingUUIDByUUID[uuidKey]) or nil
            if listingUUID then
                snap = _listedByListingUUID[listingUUID] or _recentGoneListings[listingUUID]
            end
            local petSnap = (snap and snap.pet) or (uuidKey ~= "" and _snapByUUID[uuidKey]) or nil
            if type(petSnap) == "table" then
                kg     = toNum(petSnap.kg, nil) or kg
                age    = toNum(petSnap.age, nil) or age
                ptype  = (petSnap.ptype and tostring(petSnap.ptype)) or ptype
                baseKg = toNum(petSnap.baseKg, nil) or baseKg
                muts   = (type(petSnap.muts) == "table") and petSnap.muts or muts
            end
            if (not muts) and snap and type(snap.muts) == "table" then
                muts = snap.muts
            end
        else
            -- buy: history PetData is source of truth; bag snapshot optional for current kg
            if (kg == nil or baseKg == nil) and uuidKey ~= "" and type(_snapByUUID[uuidKey]) == "table" then
                local petSnap = _snapByUUID[uuidKey]
                kg = kg or toNum(petSnap.kg, nil)
                baseKg = baseKg or toNum(petSnap.baseKg, nil)
                age = age or toNum(petSnap.age, nil)
                if (not muts) and type(petSnap.muts) == "table" then
                    muts = petSnap.muts
                end
            end
            if (not muts) and type(hist.petData) == "table" then
                muts = _mutsFromPetData(hist.petData)
            end
        end

        local priceGross = tonumber(log.price) or 0
        local priceNet = tonumber(log.priceWithFee)
        if priceNet == nil then
            priceNet = priceGross
        end
        local fee = math.max(0, priceGross - priceNet)
        local finishTime = tonumber(log.finishTime) or os.time()
        local tokenText = getTradeTokenText()
        local kindName = tostring(itemType or ""):lower()
        local isSkin = kindName:find("skin", 1, true) ~= nil or (type(itemData) == "table" and itemData.SkinID ~= nil)

        if isSold then
            local payload = {
                kind       = "market_sold",
                id         = id,
                price      = priceNet,       -- harga setelah fee (net seller)
                priceGross = priceGross,     -- harga listing / buyer bayar
                fee        = fee,
                token      = tokenText,
                finishTime = finishTime,
                seller     = seller,
                buyer      = buyer,
                listing = {
                    listingUUID = listingUUID,
                    listedPrice = snap and snap.price or priceGross,
                    itemType    = snap and snap.itemType or itemType,
                    totalListed = _lastListedCount,
                    maxSlots    = CFG.MAX_SLOTS,
                    slotsLeft   = math.max(0, (CFG.MAX_SLOTS or 0) - (_lastListedCount or 0)),
                },
                item = {
                    uuid     = uuid,
                    type     = itemType,
                    name     = itemNameNice,
                    nameRaw  = itemNameRaw,
                    ptype    = ptype,
                    kg       = kg,
                    baseKg   = baseKg,
                    age      = age,
                    muts     = muts,
                }
            }

            if CFG.WEBHOOK_ENABLED then
                _emit(CFG.WEBHOOK_EVENT_SOLD, payload)
            end

            local MR = rawget(_G, "MarketResult")
            if type(MR) == "table" and type(MR.RecordSell) == "function" then
                pcall(function()
                    MR.RecordSell(payload)
                end)
            end
            return
        end

        -- BUY (buyer == LocalPlayer) — price = yang dibayar (sebelum fee seller)
        local payload = {
            kind       = "market_buy",
            title      = "Buy",
            id         = id,
            price      = priceGross,
            priceGross = priceGross,
            priceNet   = priceNet,
            fee        = fee,
            token      = tokenText,
            finishTime = finishTime,
            seller     = seller,
            buyer      = buyer,
            item = {
                uuid      = uuid,
                type      = itemType or (isSkin and "TradeBoothSkin" or "Pet"),
                name      = itemNameNice,
                nameRaw   = itemNameRaw,
                ptype     = ptype,
                kg        = kg or baseKg,
                kgCurrent = kg or baseKg,
                kgBase    = baseKg,
                baseKg    = baseKg,
                age       = age,
                muts      = muts,
            }
        }

        if CFG.WEBHOOK_ENABLED then
            _emit(CFG.WEBHOOK_EVENT_BUY, payload, { shareToDC = true })
        end

        local MR = rawget(_G, "MarketResult")
        if type(MR) == "table" and type(MR.RecordBuy) == "function" then
            pcall(function()
                MR.RecordBuy({
                    id          = id,
                    price       = priceGross,
                    fee         = fee,
                    petType     = ptype or itemNameNice,
                    skinType    = isSkin and itemNameNice or nil,
                    kind        = isSkin and "skin" or "pet",
                    kg          = kg or baseKg,
                    baseKg      = baseKg,
                    age         = age,
                    muts        = muts,
                    token       = tokenText,
                    seller      = seller,
                    uuid        = uuid,
                    item        = payload.item,
                })
            end)
        end
    end)
end

-- Main step
----------------------------------------------------------------
local function step()
    if not _running then return end
    if not ensureMarketRemotes() then
        dprint("market remotes not ready -> skip")
        return
    end
    if not TradeWorldController:IsInWorld() then
        return
    end

    -- ensure history hook up
    _connectHistoryIfNeeded()
        refreshSoldCaches()


    -- 1) ensure booth claimed
    local hasBooth, reason = ensureClaimBooth()
    if reason == "claim_sent" or reason == "no_empty_booth" or tostring(reason):find("missing") then
        return
    end
    if hasBooth then
        pcall(ensureBoothSkin)
    end

local listed = listCurrentBooth()
_lastListedCount = (type(listed)=="table") and #listed or 0
if _lastListedCount ~= (_prevListedCount or -1) then
    _holdableIdCacheAt = 0
    _prevListedCount = _lastListedCount
end
if type(listed) ~= "table" then
    dprint("listCurrentBooth not table -> skip")
    return
end

-- ✅ booth kosong itu VALID (jangan dianggap not ready)
if #listed == 0 then
    dprint("listed=0 (booth empty, OK) -> continue")
end

local listedByUUID = mapListedByUUID(listed)

-- debug optional
local mapCount = 0
for _ in pairs(listedByUUID) do mapCount += 1 end
dprint("listedByUUID_mapCount =", mapCount)

-- 3) read desired from state
local mk = getMK()
if not mk then return end
if mk.runtime and mk.runtime.enabled ~= true then
    M.Stop()
    return
end

local desired = buildDesired(mk, listedByUUID)

-- 4) diff -> queues
local toUnlist, toList = buildQueues(desired, listed, listedByUUID)

-- 5) UNLIST BURST dulu (biar cepet bersih)
if #toUnlist > 0 then
    local maxBurst = CFG.UNLIST_PER_STEP or 4

    -- backoff sederhana kalau sering gagal
    if _unlistBurstFail >= 3 then
        maxBurst = math.max(1, math.floor(maxBurst / 2))
    end

    local did = 0
    local fail = 0

    for i = 1, math.min(maxBurst, #toUnlist) do
        local ok = doUnlist(toUnlist[i])
        if ok then
            did += 1
        else
            fail += 1
        end

        -- jeda kecil supaya InvokeServer gak “nabrak”
        task.wait(CFG.UNLIST_CD_SEC or 0.18)
    end

    if did == 0 and fail > 0 then
        _unlistBurstFail += 1
    else
        _unlistBurstFail = 0
    end

    -- selesai unlist burst, stop dulu (biar list tetep ikutin tick)
    return
end

-- 7) LIST tetap 1 per step (aman)
if #toList > 0 then
    doList(toList[1], listed)
    return
end


end

