-- Public API
----------------------------------------------------------------
function M.SyncFromState(STATE)
    if type(STATE) == "table" then
        _G.STATE = STATE
    end
end

function M.SetPetListView(plv)
    _PetListView = plv
end

function M.SetFruitListView(flv)
    _FruitListView = flv
end

function M.SetWebhook(senderFn)
    -- senderFn(eventName, payloadTable)
    if senderFn == nil then
        _webhookSend = nil
        return
    end
    if type(senderFn) ~= "function" then
        error("[market_loop] SetWebhook expects function(eventName,payload)")
    end
    _webhookSend = senderFn
end

function M.SetDebug(on)
    CFG.DEBUG = (on == true)
end

function M.SetWebhookEnabled(on)
    CFG.WEBHOOK_ENABLED = (on == true)
end

function M.Configure(opts)
    if type(opts) ~= "table" then return end
    for k, v in pairs(opts) do
        if CFG[k] ~= nil then
            CFG[k] = v
        end
    end
end

function M.IsRunning()
    return _running == true
end

function M.Start()
    if _running then return end
    _running = true
    M.running = true
    _lastActionAt = 0
    _lastClaimAt  = 0
    _cachedHoldableItemType = nil

    startObserveBooths()
    _connectHistoryIfNeeded()
    
    pcall(function()
    local AH = rawget(_G, "AutoHop") or ((getgenv and getgenv()) or _G).AutoHop
    if type(AH) == "table" and type(AH.Start) == "function" then
        AH.Start()
    end
end)


    _thread = task.spawn(function()
        -- Boot: claim/replion sering belum siap di tick pertama → 2 step cepat lalu interval normal
        local bootWaits = { 0.45, 1.0 }
        for _, w in ipairs(bootWaits) do
            if not _running then return end
            local ok, err = pcall(step)
            if not ok then
                dprint("step error (boot):", err)
            end
            task.wait(w)
        end

        while _running do
            local ok, err = pcall(step)
            if not ok then
                dprint("step error:", err)
            end
            task.wait(CFG.TICK_SEC)
        end
    end)
end

function M.Stop()
    _running = false
    M.running = false
    
    pcall(function()
    local AH = rawget(_G, "AutoHop") or ((getgenv and getgenv()) or _G).AutoHop
    if type(AH) == "table" and type(AH.Stop) == "function" then
        AH.Stop()
    end
end)

end

function M.StepOnce()
    _connectHistoryIfNeeded()
    local ok, err = pcall(step)
    if not ok then
        dprint("StepOnce error:", err)
    end
end

function M.EnsureHistoryHook()
    pcall(ensureMarketRemotes)
    _connectHistoryIfNeeded()
    return _historyConn ~= nil
end

-- History sold/buy harus hidup meski Auto Market list off (auto-snipe masih butuh RecordBuy)
task.spawn(function()
    for _ = 1, 40 do
        if _historyConn then
            break
        end
        pcall(ensureMarketRemotes)
        _connectHistoryIfNeeded()
        if _historyConn then
            break
        end
        task.wait(1)
    end
end)

return M

