local RS = game:GetService("ReplicatedStorage")
local DataService = require(RS.Modules.DataService)

local G = (getgenv and getgenv()) or _G

local MUT_CODE_TO_NAME = {}
do
    local ok, mod = pcall(function()
        return require(RS.Data.PetRegistry.PetMutationRegistry)
    end)
    if ok and type(mod) == "table" then
        local reg = mod.PetMutationRegistry or mod
        if type(reg) == "table" then
            for mutName, def in pairs(reg) do
                if type(def) == "table" and type(def.EnumId) == "string" and def.EnumId ~= "" then
                    MUT_CODE_TO_NAME[def.EnumId] = tostring(mutName)
                end
            end
        end
    end
end

local SCALE_PER_LVL = 0
pcall(function()
    local PetRegistry = require(RS.Data.PetRegistry)
    local wc = PetRegistry
        and PetRegistry.PetConfig
        and PetRegistry.PetConfig.WEIGHT_CONFIG
    if wc then
        SCALE_PER_LVL = wc.SCALE_PERCENTAGE_OF_BASE_WEIGHT_PER_LEVEL or 0
    end
end)

local M = {}

local running = false
local _lastRejoinAt = 0
local _stallCount = 0
local _lastTimeLeft = nil
local _travelBusy = false
local _resumeBusy = false
local _rejoinBusy = false

-- Runtime aktif hanya di TradeWorld (memori). MK disimpan hanya saat rejoin pending.
local _live = nil -- { petKey, startedAt, startLeft, frozenSec }

local REJOIN_PRE_DELAY = 20
local MAX_REJOIN_STALL = 5
local RESUME_WAIT      = 12
local POLL_SEC         = 1

----------------------------------------------------------------
-- DEBUG (default OFF — nyalakan: _G.AGEBREAK_REJOIN_DEBUG = true)
----------------------------------------------------------------
if rawget(_G, "AGEBREAK_REJOIN_DEBUG") == nil then
    _G.AGEBREAK_REJOIN_DEBUG = false
end

local function dbgEnabled()
    return _G.AGEBREAK_REJOIN_DEBUG == true
end

local function dbg(...)
    if not dbgEnabled() then return end
    print("[AgeBreakRejoin]", ...)
end

local function dbgw(...)
    if not dbgEnabled() then return end
    warn("[AgeBreakRejoin]", ...)
end

local function isInMarketWorld()
    return workspace:FindFirstChild("TradeWorld") ~= nil
end

local function getMK()
    local STATE = rawget(_G, "STATE") or G.STATE
    if type(STATE) ~= "table" then return nil end
    local mk = STATE.main and STATE.main.auto_market
    return type(mk) == "table" and mk or nil
end

local function isEnabled()
    local mk = getMK()
    return mk and mk.ageBreakRejoinReduce == true
end

local function rejoinUserIntervalSec()
    local mk = getMK()
    local sec = mk and tonumber(mk.ageBreakRejoinEverySec)
    if not sec then
        local oldMin = mk and tonumber(mk.ageBreakRejoinEveryMin)
        if oldMin and oldMin > 0 then
            sec = oldMin * 60
        end
    end
    if not sec or sec < 15 then
        sec = 60
    end
    return math.floor(sec)
end

-- Total tunggu antar rejoin = input UI + REJOIN_PRE_DELAY (contoh 130 + 20 = 150)
local function rejoinCooldownSec()
    return rejoinUserIntervalSec() + REJOIN_PRE_DELAY
end

local function getMachine()
    local ok, profile = pcall(function()
        return DataService:GetData()
    end)
    if ok and type(profile) == "table" then
        return profile.PetAgeBreakMachine
    end
    return nil
end

local function snapMachine(machine)
    machine = machine or getMachine()
    if type(machine) ~= "table" then return nil end

    local timeLeft = tonumber(machine.TimeLeft) or 0
    return {
        timeLeft     = timeLeft,
        petReady     = machine.PetReady == true,
        hasSubmitted = type(machine.SubmittedPet) == "table",
        isRunning    = machine.IsRunning == true or timeLeft > 0,
    }
end

local function shouldReturnMain(s)
    s = s or snapMachine()
    if not s then return false end
    return s.petReady == true or s.timeLeft <= 0
end

function M.FormatTimeLeft(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    if sec < 60 then
        return string.format("%ds", sec)
    end
    local h = math.floor(sec / 3600)
    local m = math.floor((sec % 3600) / 60)
    if h > 0 and m > 0 then
        return string.format("%dh %dm", h, m)
    end
    if h > 0 then
        return string.format("%dh", h)
    end
    return string.format("%dm", m)
end

function M.FormatRuntime(sec)
    sec = math.max(0, math.floor(tonumber(sec) or 0))
    if sec < 60 then
        return string.format("%ds", sec)
    end
    local totalMin = math.floor(sec / 60)
    local h = math.floor(totalMin / 60)
    local m = totalMin % 60
    if h > 0 and m > 0 then
        return string.format("%dh %dm", h, m)
    end
    if h > 0 then
        return string.format("%dh", h)
    end
    return string.format("%dm", m)
end

local function petSessionKey(machine)
    if type(machine) ~= "table" then return nil end
    local sp = machine.SubmittedPet
    if type(sp) ~= "table" then return nil end
    local u = sp.UUID or sp.uuid or sp.PetUUID or sp.Id
    if u and tostring(u) ~= "" then
        return tostring(u)
    end
    local ptype = tostring(sp.PetType or sp.Type or sp.Name or "")
    local PD = sp.PetData or sp.Data or {}
    local age = tonumber(sp.Age) or tonumber(sp.Level)
        or tonumber(PD and PD.Age) or tonumber(PD and PD.Level) or 0
    if ptype ~= "" then
        return ptype .. "|" .. tostring(age)
    end
    return nil
end

local function wallNow()
    if os and type(os.time) == "function" then
        return os.time()
    end
    return math.floor(tick())
end

local function clearRuntimeSession()
    local mk = getMK()
    if not mk then return end
    mk.ageBreakRuntimePetKey = nil
    mk.ageBreakRuntimeStartLeft = nil
    mk.ageBreakRuntimeStartedAt = nil
end

local function saveRuntimeSession()
    -- Market JSON dulu (ageBreakRuntime* hanya ada di nodehub/market/*.json)
    local marketSave = rawget(_G, "__NodeHubMarketSave")
    if type(marketSave) == "function" then
        pcall(marketSave)
    end
    local ui = rawget(_G, "NodeHubUI") or rawget(_G, "UI")
    if ui and type(ui.SaveState) == "function" then
        pcall(function() ui:SaveState() end)
    end
    local MAIN = rawget(_G, "MAIN")
    if type(MAIN) == "table" then
        if type(MAIN.Save) == "function" then
            pcall(function() MAIN:Save() end)
        elseif type(MAIN.save) == "function" then
            pcall(function() MAIN.save() end)
        end
    end
end

local function liveRuntimeSec()
    if type(_live) ~= "table" then return 0 end
    if _live.frozenSec then
        return math.max(0, math.floor(tonumber(_live.frozenSec) or 0))
    end
    local startedAt = tonumber(_live.startedAt)
    if not startedAt then return 0 end
    return math.max(0, wallNow() - startedAt)
end

local function liveStartLeft()
    if type(_live) ~= "table" then return nil end
    return tonumber(_live.startLeft)
end

local function freezeLiveRuntime()
    if type(_live) ~= "table" or _live.frozenSec then return end
    _live.frozenSec = liveRuntimeSec()
end

local function persistLiveToMk()
    local mk = getMK()
    if not mk or type(_live) ~= "table" then return end
    mk.ageBreakRuntimePetKey = _live.petKey
    mk.ageBreakRuntimeStartLeft = _live.startLeft
    mk.ageBreakRuntimeStartedAt = _live.startedAt
end

local function restoreLiveFromMk()
    local mk = getMK()
    if not mk then return false end
    local startedAt = tonumber(mk.ageBreakRuntimeStartedAt)
    if not startedAt then return false end
    if type(_live) == "table" and tonumber(_live.startedAt) == startedAt then
        return true
    end
    _live = {
        petKey = mk.ageBreakRuntimePetKey,
        startedAt = startedAt,
        startLeft = tonumber(mk.ageBreakRuntimeStartLeft),
        frozenSec = nil,
    }
    return true
end

local function tryRestoreLiveForKey(key)
    if not key then return false end
    if type(_live) == "table" and _live.petKey == key then
        return true
    end
    local mk = getMK()
    if not mk then return false end
    local startedAt = tonumber(mk.ageBreakRuntimeStartedAt)
    if not startedAt then return false end
    local mkKey = mk.ageBreakRuntimePetKey
    if mkKey and tostring(mkKey) ~= tostring(key) and mk.ageBreakSessionPending ~= true then
        return false
    end
    _live = {
        petKey = key,
        startedAt = startedAt,
        startLeft = tonumber(mk.ageBreakRuntimeStartLeft),
        frozenSec = nil,
    }
    return true
end

local function hasPersistedRuntime()
    local mk = getMK()
    return mk and tonumber(mk.ageBreakRuntimeStartedAt) ~= nil
end

local function ensureRejoinLoopActive()
    if not isEnabled() then return end
    if not isInMarketWorld() then return end
    if running then return end
    running = true
    M.running = true
    dbg("ensureRejoinLoopActive")
end

local function clearRejoinPendingAfterResume()
    local mk = getMK()
    if mk and mk.ageBreakSessionPending == true then
        saveSessionPending(false)
        dbg("clear rejoin pending (resume ok)")
    end
end

local function startLiveRuntime(machine, s)
    if not isInMarketWorld() then return end
    if type(machine) ~= "table" or type(s) ~= "table" or not s.hasSubmitted then return end
    if shouldReturnMain(s) then
        freezeLiveRuntime()
        return
    end

    local key = petSessionKey(machine)
    if not key then return end

    if type(_live) ~= "table" or _live.petKey ~= key then
        if not tryRestoreLiveForKey(key) then
            _live = {
                petKey = key,
                startedAt = wallNow(),
                startLeft = (s.timeLeft > 0) and s.timeLeft or nil,
                frozenSec = nil,
            }
            clearRuntimeSession()
        end
    end

    if not _live.startLeft and s.timeLeft > 0 then
        _live.startLeft = s.timeLeft
        persistLiveToMk()
        saveRuntimeSession()
    end
end

local function getDisplayRuntime(machine, s)
    if not isInMarketWorld() then
        return 0, nil
    end

    if type(_live) ~= "table" then
        restoreLiveFromMk()
    end

    if type(_live) ~= "table" then
        return 0, nil
    end

    if type(machine) == "table" and type(s) == "table" and s.hasSubmitted then
        local key = petSessionKey(machine)
        if key and _live.petKey and key ~= _live.petKey then
            local mk = getMK()
            if mk and mk.ageBreakSessionPending == true then
                _live.petKey = key
            else
                return 0, nil
            end
        end
        if shouldReturnMain(s) then
            freezeLiveRuntime()
        end
    end

    return liveRuntimeSec(), liveStartLeft()
end

local function _numFrom(tbl, keys)
    if type(tbl) ~= "table" then return nil end
    for _, k in ipairs(keys) do
        local v = tbl[k]
        if type(v) == "number" then return v end
        if type(v) == "string" then
            local n = tonumber((v:gsub(",", ".")))
            if n then return n end
        end
    end
    return nil
end

local function _mutNames(sp)
    if type(sp) ~= "table" then return {} end
    local PD = sp.PetData or sp.Data or {}
    local raw = PD.MutationType or sp.MutationType
        or PD.Mutations or sp.Mutations or PD.Mutation or sp.Mutation
    if not raw then return {} end

    local names, seen = {}, {}
    local function addName(n)
        n = tostring(n or "")
        if n == "" or n == "None" or seen[n] then return end
        seen[n] = true
        names[#names + 1] = n
    end

    if type(raw) == "string" then
        addName(MUT_CODE_TO_NAME[raw] or raw)
    elseif type(raw) == "table" then
        for _, v in pairs(raw) do
            if type(v) == "string" then
                addName(MUT_CODE_TO_NAME[v] or v)
            elseif type(v) == "table" then
                local c = v.MutationType or v.Mutation or v.EnumId or v.Code
                if c then addName(MUT_CODE_TO_NAME[c] or c) end
            end
        end
    end
    table.sort(names)
    return names
end

function M.FormatSubmittedPet(sp)
    if type(sp) ~= "table" then return nil end

    local PD = sp.PetData or sp.Data or {}
    local petType = tostring(
        sp.PetType or sp.Type or sp.Name
        or PD.PetType or PD.Type or PD.Name or "Pet"
    )

    local age = _numFrom(sp, { "Age", "age", "Level", "level" })
        or _numFrom(PD, { "Age", "age", "Level", "level" })
        or 0

    local kg = _numFrom(sp, { "Weight", "weight", "KG", "kg", "W", "w", "WeightNow", "currentWeight" })
        or _numFrom(PD, { "Weight", "weight", "KG", "kg", "W", "w", "WeightNow", "currentWeight" })

    if not kg then
        local base = _numFrom(sp, { "BaseWeight", "BaseWeightKG", "WeightBase", "baseWeight" })
            or _numFrom(PD, { "BaseWeight", "BaseWeightKG", "WeightBase", "baseWeight" })
        if base and age >= 0 then
            kg = base * (1 + (SCALE_PER_LVL or 0) * age)
        end
    end

    local muts = _mutNames(sp)
    local parts = {}
    if #muts > 0 then
        parts[#parts + 1] = "[" .. table.concat(muts, ", ") .. "]"
    end
    parts[#parts + 1] = petType
    if age > 0 then
        parts[#parts + 1] = string.format("Age %d", math.floor(age))
    end
    if kg then
        parts[#parts + 1] = string.format("%.1fkg", kg)
    end

    return {
        petType = petType,
        age = age,
        kg = kg,
        mutations = muts,
        line = table.concat(parts, " · "),
    }
end

local function _petFromMachine(machine)
    if type(machine) ~= "table" then return nil end
    return M.FormatSubmittedPet(machine.SubmittedPet)
end

local function saveSessionPending(on)
    local mk = getMK()
    if not mk then return end
    mk.ageBreakSessionPending = (on == true)
    saveRuntimeSession()
end

local function endAgeBreakSession()
    _live = nil
    local mk = getMK()
    if mk then
        mk.ageBreakSessionPending = false
        clearRuntimeSession()
    end
    _lastRejoinAt = 0
    _stallCount = 0
    _stallWarned = false
    saveRuntimeSession()
    dbg("EndSession — runtime cleared + saved")
end

function M.EndSession()
    endAgeBreakSession()
end

M.ResetOnClaim = M.EndSession

local function tickSessionAlways()
    if not isInMarketWorld() then
        return
    end

    local machine = getMachine()
    local s = snapMachine(machine)
    if not s or not s.hasSubmitted then
        if hasPersistedRuntime() or (getMK() and getMK().ageBreakSessionPending == true) then
            restoreLiveFromMk()
        end
        return
    end

    restoreLiveFromMk()
    startLiveRuntime(machine, s)
end

local function fireTravelToMain()
    if _G.PSReconnect and type(_G.PSReconnect.TravelToMain) == "function" then
        return pcall(function() return _G.PSReconnect:TravelToMain() end)
    end
    return pcall(function()
        local ev = RS:FindFirstChild("GameEvents")
            and RS.GameEvents:FindFirstChild("TradeWorld")
            and RS.GameEvents.TradeWorld:FindFirstChild("TravelToMainWorld")
        if ev then ev:FireServer() end
    end)
end

local function goToMain(reason)
    if _travelBusy then return false end
    if not isInMarketWorld() then
        return true
    end

    _travelBusy = true
    dbg("TravelToMain", reason or "")
    local ok, err = fireTravelToMain()
    if not ok then
        dbgw("TravelToMain FAIL", err)
    else
        _stallCount = 0
        _stallWarned = false
        _lastTimeLeft = nil
    end
    task.delay(4, function() _travelBusy = false end)
    return ok
end

local _stallWarned = false

local function tryRejoinReduce(s)
    if not isEnabled() then return end
    if not isInMarketWorld() then return end
    if shouldReturnMain(s) then return end
    if not s or not s.hasSubmitted then return end
    if _rejoinBusy then return end

    local now = tick()
    local userSec = rejoinUserIntervalSec()
    local cooldown = userSec + REJOIN_PRE_DELAY

    -- Rejoin pertama ikut interval yang sama (bukan langsung 20 detik)
    if _lastRejoinAt <= 0 then
        _lastRejoinAt = now
        dbg(string.format(
            "Rejoin cooldown start | tunggu %ds (input=%ds + pre=%ds)",
            cooldown, userSec, REJOIN_PRE_DELAY
        ))
        return
    end

    if (now - _lastRejoinAt) < cooldown then
        return
    end

    if _stallCount >= MAX_REJOIN_STALL then
        if not _stallWarned then
            _stallWarned = true
            dbgw("Rejoin stall limit — timer tidak turun setelah beberapa rejoin. Cek manual atau Rejoin Now.")
        end
        return
    end

    local R = _G.PSReconnect or G.PSReconnect
    if not R or type(R.RejoinNow) ~= "function" then
        dbgw("RejoinNow unavailable (PSReconnect)")
        return
    end

    _rejoinBusy = true
    _lastRejoinAt = now
    _lastTimeLeft = s.timeLeft
    pcall(function() startLiveRuntime(getMachine(), s) end)
    persistLiveToMk()
    saveSessionPending(true)
    saveRuntimeSession()

    dbg(string.format(
        "RejoinNow | TimeLeft=%.0f tunggu selesai %ds (input=%ds + pre=%ds)",
        s.timeLeft, cooldown, userSec, REJOIN_PRE_DELAY
    ))

    local ok, err = pcall(function()
        R.RejoinNow(true)
    end)
    _rejoinBusy = false
    if not ok then
        dbgw("RejoinNow error:", err)
    end
end

local function tickOnce()
    tickSessionAlways()

    if not running then return end
    if not isEnabled() then return end
    if not isInMarketWorld() then return end

    local machine = getMachine()
    local s = snapMachine(machine)
    if not s or not s.hasSubmitted then
        return
    end

    if shouldReturnMain(s) then
        freezeLiveRuntime()
        goToMain(string.format("ready=%s timeLeft=%.0f", tostring(s.petReady), s.timeLeft))
        return
    end

    if s.isRunning and s.timeLeft > 0 then
        -- Stall = setelah rejoin, TimeLeft tidak turun (bukan setiap poll 1 detik)
        if _lastTimeLeft and _lastRejoinAt > 0 then
            local sinceRejoin = tick() - _lastRejoinAt
            if sinceRejoin >= rejoinCooldownSec() and s.timeLeft >= (_lastTimeLeft - 5) then
                _stallCount += 1
            elseif s.timeLeft < (_lastTimeLeft - 5) then
                _stallCount = 0
                _stallWarned = false
            end
        end
        local okRejoin, errRejoin = pcall(function()
            tryRejoinReduce(s)
        end)
        if not okRejoin then
            dbgw("tryRejoinReduce error:", errRejoin)
        end
    end
end

local function resumeAfterLoad()
    if _resumeBusy then return end
    _resumeBusy = true

    if not isEnabled() then
        _resumeBusy = false
        return
    end

    if isInMarketWorld() then
        running = true
        M.running = true
    end

    local mk = getMK()
    local pending = mk and mk.ageBreakSessionPending == true
    if not pending and not isInMarketWorld() then
        _resumeBusy = false
        return
    end

    task.wait(RESUME_WAIT)

    if not isEnabled() then
        _resumeBusy = false
        return
    end

    local s = snapMachine()
    if not s or not s.hasSubmitted then
        if hasPersistedRuntime() or (mk and mk.ageBreakSessionPending == true) then
            restoreLiveFromMk()
            dbg("Resume waiting for machine data (keep runtime)")
        end
        _resumeBusy = false
        return
    end

    if shouldReturnMain(s) then
        if isInMarketWorld() then
            goToMain("resume_ready")
        end
        _resumeBusy = false
        return
    end

    if isInMarketWorld() then
        restoreLiveFromMk()
        startLiveRuntime(getMachine(), s)
        dbg("Resume in market | TimeLeft=", string.format("%.0f", s.timeLeft), "runtime=", liveRuntimeSec())
        running = true
        M.running = true
    end

    task.delay(5, function() _resumeBusy = false end)
end

local function _statusWithRuntime(base, text, kind)
    local runtimeSec, startLeft = 0, nil
    if type(base.machine) == "table" and type(base.snap) == "table" then
        runtimeSec, startLeft = getDisplayRuntime(base.machine, base.snap)
    end
    local runtimeText = nil
    if runtimeSec > 0 then
        runtimeText = M.FormatRuntime(runtimeSec)
    end
    return {
        text = text,
        kind = kind,
        petLine = base.petLine,
        pet = base.pet,
        timeLeft = base.timeLeft,
        runtimeSec = runtimeSec,
        runtimeText = runtimeText,
        startTimeLeft = startLeft,
    }
end

function M.GetMachineStatus()
    if not isInMarketWorld() then
        return { text = "—", kind = "idle", petLine = nil, pet = nil, runtimeSec = 0, runtimeText = nil }
    end

    local machine = getMachine()
    local s = snapMachine(machine)
    local pet = _petFromMachine(machine)

    if not s or not s.hasSubmitted then
        local mk = getMK()
        if mk and mk.ageBreakSessionPending == true then
            local runtimeSec, startLeft = getDisplayRuntime(nil, nil)
            local runtimeText = runtimeSec > 0 and M.FormatRuntime(runtimeSec) or nil
            return {
                text = "Loading…",
                kind = "idle",
                petLine = nil,
                pet = nil,
                runtimeSec = runtimeSec,
                runtimeText = runtimeText,
                startTimeLeft = startLeft,
            }
        end
        return { text = "No pet", kind = "idle", petLine = nil, pet = nil, runtimeSec = 0, runtimeText = nil }
    end

    local base = {
        petLine = pet and pet.line or nil,
        pet = pet,
        timeLeft = s.timeLeft,
        machine = machine,
        snap = s,
    }

    if s.petReady then
        return _statusWithRuntime(base, "Ready → main", "ready")
    end

    if s.timeLeft > 0 or (type(machine) == "table" and machine.IsRunning == true) then
        return _statusWithRuntime(
            base,
            string.format("⏱ %s", M.FormatTimeLeft(s.timeLeft)),
            "running"
        )
    end

    return _statusWithRuntime(base, "Pick dupes", "waiting")
end

