    local phase = _status.phase or "Idle"
    local extra = _status.detail or ""
    local nxt = tonumber(_status.nextIn) or 0
    if extra ~= "" then
        if nxt > 0 then
            return string.format("%s  %s  next %ds", phase, extra, math.ceil(nxt))
        end
        return phase .. "  " .. extra
    end
    if nxt > 0 then
        return string.format("%s  next %ds", phase, math.ceil(nxt))
    end
    return phase
end

local function pass()
    local rj = getRJ()
    if not rj then
        setStatus("Idle", "no state")
        return
    end

    local delayOn = rj.backMainEnabled == true
    local ascOn = rj.backMainIfAscensionReady == true
    local everySec = getEverySec(rj)
    rj.backMainEverySec = everySec
    rj.backMainEverySec = everySec

    if not delayOn and not ascOn then
        _delayAnchor = 0
        setStatus("Idle", "off")
        return
    end

    if not isInMarket() then
        _delayAnchor = 0
        setStatus("Idle", "already main")
        return
    end

    if ascOn and isAscensionReady() then
        setStatus("Travel", "ascension ready")
        local ok, err = travelToMain()
        if not ok then
            setStatus("Failed", tostring(err or "travel"))
        end
        return
    end

    if delayOn then
        if _delayAnchor <= 0 then
            _delayAnchor = now()
        end
        local remain = everySec - (now() - _delayAnchor)
        if remain > 0 then
            local extra = ascOn and "wait delay (ascension not ready)" or "wait delay"
            setStatus("Idle", extra, remain)
            return
        end
        _delayAnchor = now()
        setStatus("Travel", "delay")
        local ok, err = travelToMain()
        if not ok then
            setStatus("Failed", tostring(err or "travel"))
        end
        return
    end

    setStatus("Idle", "waiting ascension")
end

