    if _loopStarted then
        return
    end
    _loopStarted = true
    task.spawn(function()
        while true do
            local ok, err = pcall(pass)
            if not ok then
                setStatus("Failed", tostring(err))
            end
            task.wait(POLL_SEC)
        end
    end)
end

function M.Start()
    startLoop()
end

