local function ownerKeyToUserId(ownerKey)
    if type(ownerKey) == "number" then return ownerKey end
    if type(ownerKey) ~= "string" then return nil end

    local n = tonumber(ownerKey)
    if n then return n end

    local idStr = ownerKey:match("^Player_(%d+)$")
    if idStr then return tonumber(idStr) end

    return nil
end

local function resolveOwnerPlayer(ownerKey)
    local uid = ownerKeyToUserId(ownerKey)
    if uid then
        if TradeBoothsData and TradeBoothsData.getPlayerById then
            local plr = TradeBoothsData.getPlayerById(uid)
            if plr then return plr end
        end
        for _, p in ipairs(Players:GetPlayers()) do
            if p.UserId == uid then return p end
        end
    end

    if type(ownerKey) == "string" then
        local p = Players:FindFirstChild(ownerKey)
        if p then return p end
    end
    return nil
end

