local function buildActiveOwnersSet(data)
    local active = {}

    if data and type(data.Booths) == "table" then
        for _, booth in pairs(data.Booths) do
            local owner = booth and booth.Owner
            if owner ~= nil then
                active[owner] = true
                active[tostring(owner)] = true
            end
        end
    end

    if next(active) == nil then
        for _, plr in ipairs(Players:GetPlayers()) do
            local key = plr.UserId
            if TradeBoothsData and TradeBoothsData.getPlayerId then
                local ok, pid = pcall(function() return TradeBoothsData.getPlayerId(plr) end)
                if ok and pid ~= nil then key = pid end
            end
            active[key] = true
            active[tostring(key)] = true
        end
    end

    return active
end

