local function numFrom(tbl, keys)
    if type(tbl) ~= "table" then return nil end
    for _, k in ipairs(keys) do
        local v = tbl[k]
        if v ~= nil then
            local n = tonumber(v)
            if n ~= nil then return n end
        end
    end
    return nil
end

local function getPetData(item)
    if type(item) ~= "table" then return nil end
    return item.PetData or item.Data
end

local function getPetAge(item, pd)
    pd = pd or getPetData(item)
    return numFrom(item, { "Level", "Age", "level", "age" })
        or numFrom(pd, { "Level", "Age", "level", "age" })
end

local function getBaseWeight(item, pd)
    pd = pd or getPetData(item)
    return numFrom(pd, { "BaseWeight", "BaseWeightKG", "WeightBase", "baseWeight", "base_weight" })
        or numFrom(item, { "BaseWeight", "BaseWeightKG", "WeightBase", "baseWeight", "base_weight" })
end

local function getCurrentWeight(item, pd)
    pd = pd or getPetData(item)
    return numFrom(pd, { "Weight", "weight", "KG", "kg", "CurrentWeight", "currentWeight" })
        or numFrom(item, { "Weight", "weight", "KG", "kg", "CurrentWeight", "currentWeight" })
end

local _scalePerLvl = nil
local function getScalePerLvl()
    if _scalePerLvl ~= nil then return _scalePerLvl end
    local scale = 0.1
    local PetRegistry = safeRequire(RS.Data:FindFirstChild("PetRegistry"))
    if PetRegistry then
        local ok, reg = pcall(function() return require(PetRegistry) end)
        if ok and type(reg) == "table" then
            scale = tonumber(reg.ScalePerLevel or reg.SCALE_PER_LVL) or scale
        end
    end
    _scalePerLvl = scale
    return _scalePerLvl
end

local function calcPetKG(itemData)
    if type(itemData) ~= "table" then return nil end
    local pd = getPetData(itemData)
    if not pd then return nil end

    local level = getPetAge(itemData, pd)
    local baseWeight = getBaseWeight(itemData, pd)

    if PetUtilities and PetUtilities.CalculateWeight and baseWeight and level then
        local ok, kg = pcall(function()
            return PetUtilities:CalculateWeight(baseWeight, level)
        end)
        if ok and type(kg) == "number" then return kg end
    end

    local direct = getCurrentWeight(itemData, pd)
    if direct and direct > 0 then return direct end

    if baseWeight and level then
        local scale = getScalePerLvl()
        return baseWeight * (1 + scale * level)
    end

    return nil
end

-- Base KG at Age 1 (sama formula market_result / wmarket)
local function calcBaseKgAtAge1(itemData)
    local pd = getPetData(itemData)
    if not pd then return nil end

    local scale = getScalePerLvl()
    local bw = getBaseWeight(itemData, pd)
    if bw and bw > 0 then
        return bw * (1 + scale * 1)
    end

    local kg = calcPetKG(itemData)
    local age = getPetAge(itemData, pd)
    if kg and kg > 0 and age and age > 0 then
        local denom = 1 + scale * age
        if denom > 0 then
            local base = kg / denom
            return base * (1 + scale * 1)
        end
    end

    return kg
end

local function mutationEnumToName(mutEnum)
    if mutEnum == nil then return "" end

    if type(mutEnum) == "string" then
        local s = mutEnum:gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" or s == "None" or s == "Normal" then return "" end
        if PetMutRegistry then
            if PetMutRegistry.EnumToPetMutation then
                local name = PetMutRegistry.EnumToPetMutation[s]
                if name then return tostring(name) end
            end
            if PetMutRegistry.PetMutationToEnum and PetMutRegistry.EnumToPetMutation then
                for name, code in pairs(PetMutRegistry.PetMutationToEnum) do
                    if tostring(code) == s then
                        local resolved = PetMutRegistry.EnumToPetMutation[code]
                        return resolved and tostring(resolved) or tostring(name)
                    end
                end
            end
        end
        return s
    end

    if PetMutRegistry and PetMutRegistry.EnumToPetMutation then
        local name = PetMutRegistry.EnumToPetMutation[mutEnum]
        return name and tostring(name) or ""
    end
    return tostring(mutEnum)
end

-- rule.mutation:
-- "*" => all
-- ""  => only no mutation
-- else => exact match name (case-insensitive)
local function mutationMatch(ruleMut, itemMutName)
    ruleMut = tostring(ruleMut or "*")
    itemMutName = tostring(itemMutName or "")

    local r = string.lower(ruleMut)

    -- wildcard / all mutation
    if r == "*"
        or r == "(all mutation)"
        or r == "all mutation"
        or r == "all"
    then
        return true
    end

    -- no mutation only
    if r == ""
        or r == "none"
        or r == "normal"
    then
        return itemMutName == ""
            or itemMutName == "None"
            or itemMutName == "Normal"
    end

    return r == string.lower(itemMutName)
end

