-- RULE COMPILE (from STATE.main.auto_market.snipe.rules MAP)
----------------------------------------------------------------
local Compiled = {
    ok = false,
    rulesByPetType = {},
    rulesBySkinType = {},
    minMaxPriceByPetType = {},
    rulesCount = 0,
}

local function toNum(x, def)
    local n = tonumber(x)
    if n == nil then return def end
    return n
end

local function normSkinKey(s)
    s = tostring(s or ""):lower()
    s = s:gsub("%s+", "")
    return s
end

local function resolveListingSkinType(li, item)
    if type(item) == "table" then
        local d = item.ItemData or item.Data
        local sid = item.SkinID or item.skinId or item.Id
            or (type(d) == "table" and (d.SkinID or d.skinId or d.Id))
        if sid ~= nil and tostring(sid) ~= "" then
            return tostring(sid)
        end
        local nm = item.Name or item.ItemName or (type(d) == "table" and (d.Name or d.ItemName))
        if nm ~= nil and tostring(nm) ~= "" then
            return tostring(nm)
        end
    end
    if li and li.ItemId ~= nil and tostring(li.ItemId) ~= "" then
        return tostring(li.ItemId)
    end
    return ""
end

local function cleanRule(ruleId, rec)
    if type(rec) ~= "table" then return nil end
    local kind = tostring(rec.kind or "pet"):lower()

    if kind == "skin" then
        local skinType = tostring(rec.skinType or "")
        if skinType == "" then return nil end
        local maxPrice = toNum(rec.maxPrice, 0)
        if maxPrice < 0 then maxPrice = 0 end
        return {
            id = tostring(ruleId),
            kind = "skin",
            skinType = skinType,
            skinKey = normSkinKey(skinType),
            maxPrice = maxPrice,
        }
    end

    if kind ~= "pet" then
        return nil
    end

    local petType = tostring(rec.petType or "")
    if petType == "" then return nil end

    local maxPrice = toNum(rec.maxPrice, 0)
    local minAge   = math.max(0, math.floor(toNum(rec.minAge, 0)))
    if minAge > PET_MAX_AGE then minAge = PET_MAX_AGE end

    -- maxAge 0 / nil = unlimited (default rule UI sering simpan 0)
    local maxAge = nil
    if rec.maxAge ~= nil then
        maxAge = math.floor(toNum(rec.maxAge, 0))
        if maxAge <= 0 then
            maxAge = nil
        elseif maxAge > PET_MAX_AGE then
            maxAge = PET_MAX_AGE
        end
    end
    local kgMode = tostring(rec.kgMode or "current"):lower()
    if kgMode ~= "base_age1" and tostring(ruleId or ""):sub(1, 3) == "PB|" then
        kgMode = "base_age1"
    end

    local minKg, maxKg
    if kgMode == "base_age1" then
        minKg = toNum(rec.minBaseKg, toNum(rec.minKg, 0))
        maxKg = rec.maxBaseKg
        if maxKg == nil and rec.maxKg ~= nil then maxKg = rec.maxKg end
        if maxKg ~= nil then
            maxKg = toNum(maxKg, nil)
            if maxKg ~= nil and maxKg <= 0 then maxKg = nil end
            if maxKg ~= nil and maxKg > PET_MAX_KG then maxKg = PET_MAX_KG end
        end
    else
        minKg = toNum(rec.minKg, 0)
        maxKg = rec.maxKg
        if maxKg ~= nil then
            maxKg = toNum(maxKg, nil)
            if maxKg ~= nil and maxKg <= 0 then maxKg = nil end
            if maxKg ~= nil and maxKg > PET_MAX_KG then maxKg = PET_MAX_KG end
        end
    end

    local mut = rec.mutation
    if mut == nil then mut = "*" end
    mut = tostring(mut)

    if maxAge ~= nil and minAge ~= nil and maxAge < minAge then
        local tmp = minAge; minAge = maxAge; maxAge = tmp
    end
    if maxKg ~= nil and maxKg < minKg then
        local tmp = minKg; minKg = maxKg; maxKg = tmp
    end

    return {
        id = tostring(ruleId),
        kind = "pet",
        petType = petType,
        mutation = mut,
        maxPrice = maxPrice,
        minAge = minAge,
        maxAge = maxAge,
        minKg = minKg,
        maxKg = maxKg, -- nil=INF
        kgMode = kgMode,
    }
end

local function countPetsTotal()
    local PLV = rawget(_G, "PetListView")
    if type(PLV) == "table" and type(PLV.listPetsAll) == "function" then
        local ok, list = pcall(PLV.listPetsAll)
        if ok and type(list) == "table" then
            return #list
        end
    end
    return nil
end

-- Total booth skin yang dimiliki (profile.TradeBoothSkinData.OwnedSkins: nama -> jumlah / bool)
local function countBoothSkinsTotal()
    local profile = getPlayerProfile()
    local sd = profile and profile.TradeBoothSkinData
    local owned = type(sd) == "table" and sd.OwnedSkins
    if type(owned) ~= "table" then
        return nil
    end
    local total = 0
    for _, v in pairs(owned) do
        if type(v) == "boolean" then
            if v then total += 1 end
        else
            total += math.max(0, math.floor(tonumber(v) or 0))
        end
    end
    return total
end

local function getStopSkinLimit()
    local STATE = rawget(_G, "STATE")
    local SN = STATE and STATE.main and STATE.main.auto_market and STATE.main.auto_market.snipe
    if type(SN) ~= "table" or SN.stopIfSkinTotal ~= true then
        return 0
    end
    return math.max(0, math.floor(tonumber(SN.stopSkinTotal) or 0))
end

-- true = toggle ON dan sudah sampai batas booth skin → jangan snipe skin lagi (0 = tanpa batas)
local function skinLimitReached()
    local limit = getStopSkinLimit()
    if limit < 1 then
        return false
    end
    local n = countBoothSkinsTotal()
    return type(n) == "number" and n >= limit
end

M.CountBoothSkinsTotal = countBoothSkinsTotal
M.SkinLimitReached = skinLimitReached

local function getStopPetCfg()
    local STATE = rawget(_G, "STATE")
    local SN = STATE and STATE.main and STATE.main.auto_market and STATE.main.auto_market.snipe
    if type(SN) ~= "table" then
        return false, 0
    end
    local limit = math.floor(tonumber(SN.stopPetTotal) or 0)
    return SN.stopIfPetTotal == true, limit
end

local function stopBecausePetTotal(count, limit)
    running = false
    M.running = false
    _G.__AUTO_SNIPE_RUNNING = false
    _G.__auto_market_DIRTY = true
end

-- true = toggle ON dan total pet sudah sampai batas → jangan snipe pet lagi
local function petLimitReached()
    local enabled, limit = getStopPetCfg()
    if not enabled or limit < 1 then
        return false
    end
    local n = countPetsTotal()
    return type(n) == "number" and n >= limit
end

M.PetLimitReached = petLimitReached

-- Batas pet & booth skin berdiri sendiri-sendiri; loop snipe baru dimatikan
-- kalau SEMUA kategori yang punya rule sudah kena batas (tidak ada yang bisa dibeli lagi).
local function shouldStopForPetTotal()
    local hasPetRules = next(Compiled.rulesByPetType) ~= nil
    local hasSkinRules = next(Compiled.rulesBySkinType) ~= nil
    if not hasPetRules and not hasSkinRules then
        return false
    end

    local petBlocked = (not hasPetRules) or petLimitReached()
    local skinBlocked = (not hasSkinRules) or skinLimitReached()
    if petBlocked and skinBlocked then
        stopBecausePetTotal()
        return true
    end
    return false
end

local function getRulesMapFromState()
    local STATE = rawget(_G, "STATE")
    if type(STATE) ~= "table" then return nil end
    local MK = STATE.main and STATE.main.auto_market
    local SN = MK and MK.snipe
    if type(SN) ~= "table" then return nil end

    local merged = {}
    if type(SN.rules) == "table" then
        for ruleId, rec in pairs(SN.rules) do
            merged[ruleId] = rec
        end
    end
    if type(SN.rulesBase) == "table" then
        for ruleId, rec in pairs(SN.rulesBase) do
            merged[ruleId] = rec
        end
    end
    if next(merged) == nil then return nil end
    return merged
end




local function compileRules()
    Compiled.rulesByPetType = {}
    Compiled.rulesBySkinType = {}
    Compiled.minMaxPriceByPetType = {}
    Compiled.rulesCount = 0

    local rulesMap = getRulesMapFromState()
    if type(rulesMap) ~= "table" then
        Compiled.ok = false
        return false
    end

    for ruleId, rec in pairs(rulesMap) do
        local r = cleanRule(ruleId, rec)
        if r then
            if r.kind == "skin" then
                local sk = r.skinKey
                Compiled.rulesBySkinType[sk] = Compiled.rulesBySkinType[sk] or {}
                table.insert(Compiled.rulesBySkinType[sk], r)
            else
                Compiled.rulesByPetType[r.petType] = Compiled.rulesByPetType[r.petType] or {}
                table.insert(Compiled.rulesByPetType[r.petType], r)

                local cur = Compiled.minMaxPriceByPetType[r.petType]
                if cur == nil or r.maxPrice < cur then
                    Compiled.minMaxPriceByPetType[r.petType] = r.maxPrice
                end
            end
            Compiled.rulesCount += 1
        end
    end

    for _, arr in pairs(Compiled.rulesByPetType) do
        table.sort(arr, function(a, b)
            if a.maxPrice ~= b.maxPrice then
                return a.maxPrice < b.maxPrice
            end
            local aKgSpan = (a.maxKg or math.huge) - a.minKg
            local bKgSpan = (b.maxKg or math.huge) - b.minKg
            if aKgSpan ~= bKgSpan then return aKgSpan < bKgSpan end
            local aAgeSpan = (a.maxAge or math.huge) - (a.minAge or 0)
            local bAgeSpan = (b.maxAge or math.huge) - (b.minAge or 0)
            return aAgeSpan < bAgeSpan
        end)
    end

    for _, arr in pairs(Compiled.rulesBySkinType) do
        table.sort(arr, function(a, b)
            if a.maxPrice ~= b.maxPrice then
                return a.maxPrice < b.maxPrice
            end
            return tostring(a.id) < tostring(b.id)
        end)
    end

    Compiled.ok = (Compiled.rulesCount > 0)
    return Compiled.ok
end


local _lastRulesSig = nil

local function calcRulesSig(rulesMap)
    if type(rulesMap) ~= "table" then return "nil" end
    local n = 0
    local parts = {}

    for ruleId, rec in pairs(rulesMap) do
        if type(rec) == "table" then
            n += 1
            parts[#parts+1] = table.concat({
                tostring(ruleId),
                tostring(rec.kind or ""),
                tostring(rec.petType or ""),
                tostring(rec.skinType or ""),
                tostring(rec.mutation or "*"),
                tostring(rec.maxPrice or 0),
                tostring(rec.minAge or 0),
                tostring(rec.maxAge or 0),
                tostring(rec.kgMode or "current"),
                tostring(rec.minKg or rec.minBaseKg or 0),
                tostring(rec.maxKg or rec.maxBaseKg or "INF"),
            }, "|")
        end
    end

    table.sort(parts)
    -- signature ringkas: count + beberapa awal
    local head = table.concat(parts, "||", 1, math.min(#parts, 25))
    return tostring(n) .. "@" .. head
end

local function recompileIfRulesChanged()
    local rulesMap = getRulesMapFromState()
    local sig = calcRulesSig(rulesMap)
    if sig ~= _lastRulesSig then
        _lastRulesSig = sig
        compileRules()
        return true
    end
    return false
end
----------------------------------------------------------------
-- FILTER + PICK BEST CANDIDATE
----------------------------------------------------------------
local listingCooldownUntil = {} -- listingUUID -> time
local lastBuyAt = 0
local BUY_LOCK = false

-- Listing yang gagal dibeli berkali-kali tidak dihitung "pending" (biar hop tidak nunggu selamanya)
M.GIVE_UP_ROUNDS = 3
local failRounds = {} -- listingUUID -> count
local giveUp = {}     -- listingUUID -> true

local function listingOnCooldown(uuid)
    local t = listingCooldownUntil[uuid]
    return (t ~= nil and t > now())
end

local function setListingCooldown(uuid, secs)
    listingCooldownUntil[uuid] = now() + (secs or M.LISTING_COOLDOWN)
end

local function buyOnCooldown()
    return (now() - lastBuyAt) < M.BUY_COOLDOWN
end

local function setBuyCooldown()
    lastBuyAt = now()
end

local function ruleMatch(rule, item, price)
    -- price already <= rule.maxPrice
    local pd = getPetData(item)
    if not pd then return false, "no PetData" end

    local age = getPetAge(item, pd)
    if type(age) ~= "number" then return false, "bad age" end

    if age < rule.minAge then return false, "age<min" end
    if rule.maxAge ~= nil and age > rule.maxAge then return false, "age>max" end

    local mutRaw = pd.MutationType or item.MutationType
    local mutName = mutationEnumToName(mutRaw)
    if not mutationMatch(rule.mutation, mutName) then
        return false, "mut miss"
    end

    local kg
    if rule.kgMode == "base_age1" then
        kg = calcBaseKgAtAge1(item)
    else
        kg = calcPetKG(item)
    end
    if type(kg) ~= "number" then
        return false, (rule.kgMode == "base_age1") and "baseKg?" or "kg?"
    end
    if kg < rule.minKg then return false, (rule.kgMode == "base_age1") and "base<min" or "kg<min" end
    if rule.maxKg ~= nil and kg > rule.maxKg then return false, (rule.kgMode == "base_age1") and "base>max" or "kg>max" end

    return true, { age = age, kg = kg, mutName = mutName, kgMode = rule.kgMode }
end

local function collectCandidates(data, ignoreCooldown)
    if not Compiled.ok then return {}, 0, 0 end
    local activeOwners = buildActiveOwnersSet(data)
    local skipSkins = skinLimitReached()
    local skipPets = petLimitReached()

    local scanned = 0
    local considered = 0
    local byListing = {}

    for ownerKey, rec in pairs(data.Players or {}) do
        local okOwner = true
        if M.SERVER_ONLY then
            okOwner = (activeOwners[ownerKey] == true) or (activeOwners[tostring(ownerKey)] == true)
        end

        if okOwner and rec and type(rec.Listings) == "table" and type(rec.Items) == "table" then
            for listingUUID, li in pairs(rec.Listings) do
                scanned += 1

                if (scanned % M.YIELD_EVERY) == 0 then
                    task.wait()
                end

                if (ignoreCooldown == true or not listingOnCooldown(listingUUID))
                    and li
                    and type(li.Price) == "number"
                    and li.ItemId ~= nil
                then
                    local price = li.Price
                    local itemType = tostring(li.ItemType or "")
                    local item = rec.Items[li.ItemId]

                    if itemType == "Pet" and item and not skipPets then
                        local petType = tostring(item.PetType or "")

                        if petType ~= "" then
                            local arr = Compiled.rulesByPetType[petType]

                            if arr then
                                considered += 1

                                for _, rule in ipairs(arr) do
                                    if price <= rule.maxPrice then
                                        local ok, infoOrWhy = ruleMatch(rule, item, price)

                                        if ok then
                                            local info = infoOrWhy
                                            local cand = {
                                                kind = "pet",
                                                ownerKey = ownerKey,
                                                listingUUID = listingUUID,
                                                itemId = li.ItemId,
                                                price = price,
                                                petType = petType,
                                                rule = rule,
                                                age = info.age,
                                                kg = info.kg,
                                                kgMode = info.kgMode,
                                                mutName = info.mutName,
                                            }

                                            local prev = byListing[listingUUID]
                                            if (not prev) or (cand.price < prev.price) then
                                                byListing[listingUUID] = cand
                                            end

                                            break
                                        end
                                    end
                                end
                            end
                        end
                    elseif itemType == "TradeBoothSkin" and not skipSkins then
                        local skinType = resolveListingSkinType(li, item)
                        local skinKey = normSkinKey(skinType)
                        local arr = (skinKey ~= "") and Compiled.rulesBySkinType[skinKey] or nil

                        if arr then
                            considered += 1

                            for _, rule in ipairs(arr) do
                                if price <= rule.maxPrice then
                                    local cand = {
                                        kind = "skin",
                                        ownerKey = ownerKey,
                                        listingUUID = listingUUID,
                                        itemId = li.ItemId,
                                        price = price,
                                        petType = skinType, -- reuse display field
                                        skinType = skinType,
                                        rule = rule,
                                        age = nil,
                                        kg = nil,
                                        mutName = "Booth Skin",
                                    }

                                    local prev = byListing[listingUUID]
                                    if (not prev) or (cand.price < prev.price) then
                                        byListing[listingUUID] = cand
                                    end
                                    break
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    local list = {}
    for _, cand in pairs(byListing) do
        list[#list + 1] = cand
    end

    table.sort(list, function(a, b)
        if a.price ~= b.price then return a.price < b.price end
        return tostring(a.listingUUID) < tostring(b.listingUUID)
    end)

    return list, scanned, considered
end

----------------------------------------------------------------
-- CONFIRM SNAPSHOT BEFORE BUY
----------------------------------------------------------------
local function confirmCandidateFresh(cand)
    local data2 = safeGetBoothsData()
    if not data2 or type(data2.Players) ~= "table" then
        return false, "no data2"
    end

    local rec = data2.Players[cand.ownerKey] or data2.Players[tostring(cand.ownerKey)]
    if not rec or type(rec.Listings) ~= "table" or type(rec.Items) ~= "table" then
        return false, "owner rec missing"
    end

    local li = rec.Listings[cand.listingUUID]
    if not li then return false, "listing gone" end
    if li.Price ~= cand.price then return false, "price changed" end
    if li.ItemId ~= cand.itemId then return false, "itemId changed" end

    local kind = tostring((cand.rule and cand.rule.kind) or cand.kind or "pet"):lower()
    local item = rec.Items[li.ItemId]

    if kind == "skin" then
        if li.ItemType ~= "TradeBoothSkin" then return false, "type changed" end
        local skinType = resolveListingSkinType(li, item)
        if normSkinKey(skinType) ~= normSkinKey(cand.skinType or cand.petType) then
            return false, "item changed"
        end
        if type(cand.rule) ~= "table" or type(cand.rule.maxPrice) ~= "number" then
            return false, "bad skin rule"
        end
        if li.Price > cand.rule.maxPrice then
            return false, "rule no longer match: price>max"
        end
        cand.skinType = skinType
        cand.petType = skinType
        cand.mutName = "Booth Skin"
        return true, nil
    end

    if li.ItemType ~= "Pet" then return false, "type changed" end
    if not item or item.PetType ~= cand.petType then
        return false, "item changed"
    end

    local ok, infoOrWhy = ruleMatch(cand.rule, item, cand.price)
    if not ok then
        return false, "rule no longer match: " .. tostring(infoOrWhy)
    end

    local info = infoOrWhy
    cand.age = info.age
    cand.kg = info.kg
    cand.kgMode = info.kgMode
    cand.mutName = info.mutName
    return true, nil
end


----------------------------------------------------------------
-- BUY (1 attempt — retry handled by caller)
----------------------------------------------------------------
local NO_RETRY_REASONS = {
    ["buy lock"] = true,
    ["buy cooldown"] = true,
    ["not in trade world"] = true,
    ["token"] = true,
    ["owner"] = true,
}

local function buyListingOnce(cand, attemptNo)
    if BUY_LOCK then return false, "buy lock" end
    if buyOnCooldown() then return false, "buy cooldown" end
    if not isInTradeWorld() then return false, "not in trade world" end

    local enough, tokenTxt, tokenErr = hasEnoughTokens(cand.price)
    if not enough then
        setListingCooldown(cand.listingUUID, 2.0)
        return false, "token"
    end

    if M.CONFIRM_BEFORE_BUY then
        local ok = confirmCandidateFresh(cand)
        if not ok then
            return false, "confirm"
        end
    end

    local ownerPlayer = resolveOwnerPlayer(cand.ownerKey)
    if not ownerPlayer then
        return false, "owner"
    end

    BUY_LOCK = true

    if not BuyRF then
        BUY_LOCK = false
        return false, "remote"
    end

    local ok, r1, r2 = pcall(function()
        return BuyRF:InvokeServer(ownerPlayer, cand.listingUUID)
    end)

    BUY_LOCK = false

    if ok and r1 == true then
        setBuyCooldown()
        setListingCooldown(cand.listingUUID, M.LISTING_COOLDOWN)

        -- Buy webhook + monitor dari AddToHistory (buyer) di market_loop — hindari double notify

        return true, "bought"
    end

    return false, "buy failed"
end

local function markFailRound(uuid)
    local n = (failRounds[uuid] or 0) + 1
    failRounds[uuid] = n
    if n >= (tonumber(M.GIVE_UP_ROUNDS) or 3) then
        giveUp[uuid] = true
    end
end

local function tryBuyCandidate(cand)
    local maxTry = math.max(1, math.floor(tonumber(M.MAX_BUY_ATTEMPTS) or 3))

    for attempt = 1, maxTry do
        local ok, reason = buyListingOnce(cand, attempt)
        if ok then
            failRounds[cand.listingUUID] = nil
            return true, "bought", attempt
        end

        reason = tostring(reason or "buy failed")
        if reason == "owner" then
            markFailRound(cand.listingUUID)
        end
        if NO_RETRY_REASONS[reason] then
            return false, reason, attempt
        end

        if attempt < maxTry then
            task.wait(tonumber(M.RETRY_BUY_DELAY) or 0.08)
        end
    end

    setListingCooldown(cand.listingUUID, M.BUY_FAIL_COOLDOWN)
    markFailRound(cand.listingUUID)
    return false, "buy failed", maxTry
end

local function processSnipeCycle(data)
    local cands, scanned, considered = collectCandidates(data)
    local candCount = #cands
    if candCount == 0 then
        return false, "no match", 0, 0, scanned, considered, candCount
    end

    local maxPets = math.max(1, math.floor(tonumber(M.MAX_PETS_PER_CYCLE) or 5))
    local limit = math.min(maxPets, #cands)

    local bought = 0
    local petsTried = 0

    for i = 1, limit do
        local cand = cands[i]

        -- batas skin bisa tercapai di tengah cycle (beli beberapa skin sekaligus)
        if cand.kind == "skin" and skinLimitReached() then
            continue
        end
        if cand.kind == "pet" and petLimitReached() then
            continue
        end

        petsTried += 1

        local ok = tryBuyCandidate(cand)
        if ok then
            bought += 1
            if shouldStopForPetTotal() then
                break
            end
        end

        if buyOnCooldown() or BUY_LOCK then
            break
        end
    end

    if bought > 0 then
        return true, ("bought " .. tostring(bought)), bought, petsTried, scanned, considered, candCount
    end
    if petsTried > 0 then
        return false, ("tried " .. tostring(petsTried)), bought, petsTried, scanned, considered, candCount
    end
    return false, "no match", bought, petsTried, scanned, considered, candCount
end

----------------------------------------------------------------
-- PUBLIC API
----------------------------------------------------------------

function M.RecompileRules()
    return compileRules()
end

function M.TickOnce()
    if shouldStopForPetTotal() then
        return false, "pet total limit"
    end

    recompileIfRulesChanged()

    if not Compiled.ok then
        compileRules()
        if not Compiled.ok then
            return false, "no rules"
        end
    end

    local data = safeGetBoothsData()
    if not data then return false, "no booth data" end

    local ok, msg, bought = processSnipeCycle(data)

    if (tonumber(bought) or 0) > 0 then
        shouldStopForPetTotal()
    end

    return ok, msg
end

-- true kalau di server ini masih ada listing yang cocok rule snipe dan bisa dibeli
-- returns: pending(bool), count(number), reason(string)
function M.HasPendingBuy()
    if BUY_LOCK then
        return true, 1, "buying"
    end
    if not running then
        return false, 0, "snipe off"
    end
    if not isInTradeWorld() then
        return false, 0, "not in trade world"
    end

    recompileIfRulesChanged()
    if not Compiled.ok then
        compileRules()
        if not Compiled.ok then
            return false, 0, "no rules"
        end
    end

    local data = safeGetBoothsData()
    if not data then
        return false, 0, "no booth data"
    end

    local cands = collectCandidates(data, true)
    local balance = getTradeTokenBalance()
    local n = 0

    for _, cand in ipairs(cands) do
        if not giveUp[cand.listingUUID]
            and (balance == nil or cand.price <= balance)
            and resolveOwnerPlayer(cand.ownerKey) ~= nil
        then
            n += 1
        end
    end

    if n > 0 then
        return true, n, "pending"
    end
    return false, 0, "no match"
end

function M.Start()
    if running then
        return
    end
    running = true
    M.running = true
    failRounds = {}
    giveUp = {}
    compileRules()

    loopThread = task.spawn(function()
        -- yield dulu: footer START set flag running sesudah Start() return
        task.wait()
        while running do
            if shouldStopForPetTotal() then
                break
            end
            M.TickOnce()
            if not running then
                break
            end
            task.wait(M.SCAN_INTERVAL)
        end
        running = false
        M.running = false
        _G.__AUTO_SNIPE_RUNNING = false
        _G.__auto_market_DIRTY = true
    end)
end

function M.Stop()
    running = false
    M.running = false
end

function M.IsRunning()
    return running
end

return M

        end,
        required = false,
    },

