}

local _scanStats = {
    petTools   = 0,
    indexSize  = 0,
    noRec      = 0,
    favorite   = 0,
    locked     = 0,
    noAgeW100  = 0,
    filterFail = 0,
    sendable   = 0,
}
local _lastScanAt = 0
local SCAN_REFRESH_SEC = 2

local function _reasonText(code)
    code = tostring(code or "")
    local map = {
        character_missing      = "Karakter belum load",
        ticket_not_in_backpack = "Trading Ticket tidak ada di backpack",
        equip_timeout          = "Gagal equip Trading Ticket ke tangan",
        no_ticket              = "Trading Ticket tidak ditemukan",
        no_target              = "Target tidak valid",
        in_flight              = "Trade sebelumnya masih berjalan",
        replicator_timeout     = "Trade window tidak terbuka (timeout)",
        add_item_failed        = "Pet gagal masuk ke offer trade",
        accept_timeout         = "Target tidak accept trade",
        confirm_timeout        = "Konfirmasi trade gagal / timeout",
        empty_batch            = "Batch pet kosong",
        zero_amount            = "Jumlah kirim 0",
        insufficient_balance   = "Saldo tidak cukup",
        set_currency_failed    = "Token/Shekels gagal masuk ke offer",
        set_tokens_missing     = "Remote SetTokens tidak ada",
        set_sheckles_missing   = "Remote SetSheckles tidak ada",
        remotes                = "Remote trade belum ready",
        GameEvents_missing     = "GameEvents belum load",
        TradeEvents_missing    = "TradeEvents belum load",
        ["Trade remotes incomplete"] = "Remote trade tidak lengkap",
        ["ReplicationReciever missing"] = "ReplicationReciever belum load",
    }
    if map[code] then return map[code] end
    if code:find("^global_cooldown:") then
        return "Cooldown global " .. code:match(":(%d+)") .. "s"
    end
    if code:find("^target_cooldown:") then
        return "Cooldown target " .. code:match(":(%d+)") .. "s"
    end
    if code:find("^request_blocked:") then
        return _reasonText(code:match("^request_blocked:(.+)$") or code)
    end
    return code
end

