local function _getTradeCfg()
    local G = (getgenv and getgenv()) or _G
    local st = rawget(G, "STATE") or rawget(_G, "STATE")
    if type(st) == "table" and type(st.trade_cfg) == "table" then
        return st.trade_cfg
    end
    return rawget(G, "TRADE_CFG") or rawget(_G, "TRADE_CFG") or TRADE_CFG or {}
end

-- #region agent log
local function _agentLog(hypothesisId, location, message, data)
    task.spawn(function()
        pcall(function()
            HttpService:PostAsync(
                "http://127.0.0.1:7313/ingest/e032e678-c208-497b-8912-923de43b2ca1",
                HttpService:JSONEncode({
                    sessionId = "c68d66",
                    runId = "gift-trade",
                    hypothesisId = hypothesisId,
                    location = location,
                    message = message,
                    data = data or {},
                    timestamp = DateTime.now().UnixTimestampMillis,
                }),
                Enum.HttpContentType.ApplicationJson,
                false,
                { ["X-Debug-Session-Id"] = "c68d66" }
            )
        end)
    end)
end
local function _setStatus(phase, detail, targetName)
    _debugStatus.phase  = tostring(phase or "")
    _debugStatus.detail = tostring(detail or "")
    if targetName ~= nil then
        _debugStatus.target = tostring(targetName or "")
    end
    -- #region agent log
    _agentLog("H0", "gift.lua:_setStatus", phase, {
        detail = detail,
        target = _debugStatus.target,
    })
    -- #endregion
end

local function safeRequire(obj)
    local ok, mod = pcall(function() return require(obj) end)
    return ok and mod or nil
end

local function _ensureRemotes()
    local ge = ReplicatedStorage:FindFirstChild("GameEvents")
    if not ge then
        _R.ready = false
        return false, "GameEvents missing"
    end
    local te = ge:FindFirstChild("TradeEvents")
    if not te then
        _R.ready = false
        return false, "TradeEvents missing"
    end

    _R.SendRequestRE = te:FindFirstChild("SendRequest")
    _R.AddItemRE = te:FindFirstChild("AddItem")
    _R.AcceptTradeRE = te:FindFirstChild("AcceptTrade") or te:FindFirstChild("Accept")
    _R.ConfirmTradeRE = te:FindFirstChild("ConfirmTrade") or te:FindFirstChild("Confirm")
    _R.UpdateStateRE = te:FindFirstChild("UpdateTradeState") or te:FindFirstChild("UpdatedTradeState")
    _R.DeclineRE = te:FindFirstChild("Decline") or te:FindFirstChild("DeclineTrade")
    _R.SetTokensRE = te:FindFirstChild("SetTokens")
    _R.SetShecklesRE = te:FindFirstChild("SetSheckles")

    local mods = ReplicatedStorage:FindFirstChild("Modules")
    if mods then
        local repMod = mods:FindFirstChild("ReplicationReciever")
        if repMod then
            _R.ReplicationReciever = safeRequire(repMod)
        end
    end

    local dataFolder = ReplicatedStorage:FindFirstChild("Data")
    if dataFolder then
        local td = dataFolder:FindFirstChild("TradeData")
        if td then
            _R.TradeData = safeRequire(td) or _R.TradeData
        end
    end

    if not (_R.SendRequestRE and _R.AddItemRE and _R.AcceptTradeRE and _R.ConfirmTradeRE and _R.UpdateStateRE) then
        _R.ready = false
        return false, "Trade remotes incomplete"
    end
    if not _R.ReplicationReciever then
        _R.ready = false
        return false, "ReplicationReciever missing"
    end

    _R.ready = true
    return true, "ok"
end

local _trade = {
    inFlight = false,
    targetUserId = nil,
    tradeId = nil,
    replicator = nil,
    cooldownUntil = 0,
    perTargetCooldown = {},
}

local function _now() return os.clock() end

local function _waitUntil(pred, timeout)
    local t0 = os.clock()
    while os.clock() - t0 < (timeout or 10) do
        local ok, why = pred()
        if ok then return true, why end
        RunService.Heartbeat:Wait()
    end
    return false, "timeout"
end

local function _destroyRep()
    if _trade.replicator then pcall(function() _trade.replicator:Destroy() end) end
    _trade.replicator = nil
end

local function _resetTradeSession()
    _trade.inFlight = false
    _trade.targetUserId = nil
    _trade.tradeId = nil
    _destroyRep()
end

local function _setTargetCD(userId, secs)
    if userId then
        _trade.perTargetCooldown[userId] = _now() + (secs or 0)
        -- #region agent log
        _agentLog("H9", "gift.lua:_setTargetCD", "target_cooldown", {
            userId = userId,
            secs = secs or 0,
        })
        -- #endregion
    end
end

local function _setGlobalCooldown(secs, reason)
    _trade.cooldownUntil = _now() + (secs or 0)
    -- #region agent log
    _agentLog("H9", "gift.lua:_setGlobalCooldown", "global_cooldown", {
        secs = secs or 0,
        reason = reason or "",
    })
    -- #endregion
end

local _tradeHooked = false
local function _hookTradeOnce()
    if _tradeHooked then return end
    local ok = _ensureRemotes()
    if not ok then return end
    _tradeHooked = true
    _R.UpdateStateRE.OnClientEvent:Connect(function(arg)
        if typeof(arg) == "string" then
            local low = string.lower(arg)
            if string.find(low, "declined", 1, true) or string.find(low, "busy", 1, true) or string.find(low, "closed", 1, true) then
                if _trade.targetUserId then
                    local cd = string.find(low, "busy", 1, true) and TRADE_BUSY_COOLDOWN or TRADE_DECLINE_COOLDOWN
                    _setTargetCD(_trade.targetUserId, cd)
                    _setGlobalCooldown(cd, low)
                end
                _setStatus("Trade Ditutup", _reasonText(low))
                _resetTradeSession()
                return
            end
            _trade.tradeId = arg
        else
            _trade.tradeId = arg
        end
        _destroyRep()
        if _trade.tradeId then
            local okRep, rep = pcall(function() return _R.ReplicationReciever.new(_trade.tradeId) end)
            if okRep and rep then _trade.replicator = rep end
        end
    end)
end

task.spawn(function()
    local t0 = os.clock()
    while os.clock() - t0 < 30 do
        local ok, reason = _ensureRemotes()
        if ok then
            _hookTradeOnce()
            _setStatus("Ready", "Remote trade OK — siap kirim")
            break
        end
        _setStatus("Waiting", "Menunggu remote: " .. _reasonText(reason or "?"))
        task.wait(0.5)
    end
end)

local function _normCoreUUID(u)
    u = tostring(u or "")
    return (u:match("{?([0-9a-fA-F%-]+)}?") or u)
end

local function _getMyOffer()
    if not _trade.replicator then return nil end
    local data = _trade.replicator:GetData()
    if not data then return nil end
    local myIdx
    for i, p in ipairs(data.players or {}) do
        if p == LocalPlayer then myIdx = i break end
    end
    if not myIdx then return nil end
    local bucket = (data.offers and data.offers[myIdx]) or {}
    return {
        items = bucket.items or {},
        sheckles = tonumber(bucket.sheckles) or 0,
        tokens = tonumber(bucket.tokens or bucket.TradeTokens or bucket.tradeTokens) or 0,
        states = data.states or {},
        players = data.players or {},
        lastChange = tonumber(data.lastChange) or 0,
    }
end

local function _myOfferHasCurrency(category, minAmount)
    minAmount = math.floor(tonumber(minAmount) or 0)
    if minAmount <= 0 then return false end
    local o = _getMyOffer()
    if not o then return false end
    category = tostring(category or ""):lower()
    if category == "shekels" then
        return (tonumber(o.sheckles) or 0) >= minAmount
    end
    if category == "token" then
        if (tonumber(o.tokens) or 0) >= minAmount then return true end
        for _, it in pairs(o.items or {}) do
            if it then
                local t = tostring(it.type or ""):lower()
                if t == "token" or t == "tokens" then
                    local a = tonumber(it.amount or it.count or it.quantity) or 0
                    if a >= minAmount then return true end
                end
            end
        end
    end
    return false
end

local function _getPlayerProfile()
    local ok, profile = pcall(function()
        local mods = ReplicatedStorage:FindFirstChild("Modules")
        local dsMod = mods and mods:FindFirstChild("DataService")
        if not dsMod then return nil end
        local DS = require(dsMod)
        if DS and type(DS.GetData) == "function" then
            return DS:GetData()
        end
        return nil
    end)
    if ok and type(profile) == "table" then return profile end
    return nil
end

-- Trade Token Reader (DataService only — profile.TradeData.Tokens)
local function _pickTokenFromProfile(profile)
    if type(profile) ~= "table" then return nil end
    local td = profile.TradeData
    if type(td) == "table" then
        local n = tonumber(td.Tokens) or tonumber(td.TradeTokens)
        if n and n >= 0 then return n end
    end
    for _, c in ipairs({
        profile.TradeTokens,
        profile.TradeToken,
        profile.Tokens,
        profile.tokens,
    }) do
        local n = tonumber(c)
        if n and n >= 0 then return n end
    end
    return nil
end

local function _getTokenBalance()
    return _pickTokenFromProfile(_getPlayerProfile())
end

local function _getShecklesBalance()
    local v = tonumber(LocalPlayer:GetAttribute("Sheckles"))
    if v and v >= 0 then return math.floor(v) end
    local profile = _getPlayerProfile()
    if profile then
        local candidates = {
            profile.Sheckles,
            profile.CurrencyData and profile.CurrencyData.Sheckles,
            profile.Stats and profile.Stats.Sheckles,
        }
        for _, c in ipairs(candidates) do
            local n = tonumber(c)
            if n and n >= 0 then return math.floor(n) end
        end
    end
    return 0
end

local function _resolveCurrencyAmount(cfg, category)
    category = tostring(category or ""):lower()
    local mode = tostring(cfg.currencySendMode or "all"):lower()
    local balance
    if category == "token" then
        balance = _getTokenBalance()
    elseif category == "shekels" then
        balance = _getShecklesBalance()
    else
        return nil, "Category bukan Token/Shekels"
    end
    balance = math.floor(tonumber(balance) or 0)
    if balance <= 0 then
        return nil, "Saldo " .. category .. " = 0"
    end
    if mode == "input" then
        local amt = math.floor(tonumber(cfg.currencyAmount) or 0)
        if amt <= 0 then return nil, "Amount input = 0" end
        if amt > balance then return nil, "Amount > saldo (" .. tostring(balance) .. ")" end
        return amt
    end
    return balance
end

local function _myOfferCount()
    local o = _getMyOffer()
    if not o then return nil end
    local c = 0
    for _ in pairs(o.items) do c += 1 end
    return c
end

local function _hasItemInMyOffer(typeName, uuid)
    local o = _getMyOffer()
    if not o then return false end
    local want = _normCoreUUID(uuid)
    for _, it in pairs(o.items) do
        if it and it.type == typeName and _normCoreUUID(it.id) == want then
            return true
        end
    end
    return false
end

local function _cooldownSatisfied()
    local o = _getMyOffer()
    if not o then return false end
    local cd = tonumber(_R.TradeData.ButtonCooldown) or 0
    return (workspace:GetServerTimeNow() - (o.lastChange or 0)) >= cd
end

local function _bothAccepted()
    local o = _getMyOffer()
    if not o then return false end
    local myIdx
    for i, p in ipairs(o.players or {}) do
        if p == LocalPlayer then myIdx = i break end
    end
    if not myIdx then return false end
    local otherIdx = (myIdx == 1) and 2 or 1
    return o.states[myIdx] == "Accepted" and o.states[otherIdx] == "Accepted"
end

local function _canRequest(target)
    if not target then return false, "no_target" end
    local t = _now()
    if t < (_trade.cooldownUntil or 0) then
        return false, "global_cooldown:" .. math.ceil((_trade.cooldownUntil or 0) - t)
    end
    local tcd = _trade.perTargetCooldown[target.UserId]
    if tcd and t < tcd then
        return false, "target_cooldown:" .. math.ceil(tcd - t)
    end
    if _trade.inFlight then return false, "in_flight" end
    return true, "ok"
end

local function _isTicketTool(t)
    return t and t:IsA("Tool")
        and string.find(string.lower(t.Name), string.lower(TICKET_NAME), 1, true) ~= nil
end

local function _ticketOnCharacter()
    local char = LocalPlayer.Character
    if not char then return false end
    for _, t in ipairs(char:GetChildren()) do
        if _isTicketTool(t) then return true, t end
    end
    return false
end

local function _findTicketInBackpack()
    local bp = _getBackpack()
    if not bp then return nil end
    for _, t in ipairs(bp:GetChildren()) do
        if _isTicketTool(t) then return t end
    end
    return nil
end

local function _unequipAllTools()
    local char = LocalPlayer.Character
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function() hum:UnequipTools() end)
    end
    local bp = _getBackpack()
    if bp then
        for _, obj in ipairs(char:GetChildren()) do
            if obj:IsA("Tool") then
                obj.Parent = bp
            end
        end
    end
end

local function _getTicketStatusLabel()
    if _ticketOnCharacter() then return "Ticket: di tangan" end
    if _findTicketInBackpack() then return "Ticket: di backpack" end
    return "Ticket: tidak ada"
end

local function _ensureHoldingTradingTicket()
    local char = LocalPlayer.Character
    local hum  = char and char:FindFirstChildOfClass("Humanoid")
    if not (char and hum) then
        return false, "character_missing"
    end

    if _ticketOnCharacter() then
        return true, "already_equipped"
    end

    local ticket = _findTicketInBackpack()
    if not ticket then
        return false, "ticket_not_in_backpack"
    end

    _setStatus("Equip Ticket", "Unequip tool lalu equip Trading Ticket...")
    _unequipAllTools()
    task.wait(0.15)

    pcall(function()
        hum:EquipTool(ticket)
    end)

    local ok = _waitUntil(function()
        return _ticketOnCharacter()
    end, 2.0)
    if ok then
        -- #region agent log
        _agentLog("H6", "gift.lua:_ensureHoldingTradingTicket", "equipped", { ticket = ticket.Name })
        -- #endregion
        return true, "equipped"
    end

    pcall(function()
        ticket.Parent = char
        hum:EquipTool(ticket)
    end)
    ok = _waitUntil(function()
        return _ticketOnCharacter()
    end, 1.5)
    if ok then
        -- #region agent log
        _agentLog("H6", "gift.lua:_ensureHoldingTradingTicket", "equipped_fallback", { ticket = ticket.Name })
        -- #endregion
        return true, "equipped_fallback"
    end

    -- #region agent log
    _agentLog("H6", "gift.lua:_ensureHoldingTradingTicket", "equip_failed", {})
    -- #endregion
    return false, "equip_timeout"
end

local function _hasTradingTicket()
    return _ticketOnCharacter() or (_findTicketInBackpack() ~= nil)
end

local function _forceDecline()
    if _R.DeclineRE then pcall(function() _R.DeclineRE:FireServer() end) end
    _waitUntil(function()
        if not _trade.tradeId or not _trade.replicator then return true end
        local d = _trade.replicator:GetData()
        return (not d) or (not d.players) or (#d.players == 0)
    end, TRADE_TIMEOUT_STEP)
    if _trade.targetUserId then _setTargetCD(_trade.targetUserId, TRADE_DECLINE_COOLDOWN) end
    _setGlobalCooldown(TRADE_DECLINE_COOLDOWN, "force_decline")
    _resetTradeSession()
end

local function _sendRequest(target)
    local can, why = _canRequest(target)
    if not can then
        return false, "request_blocked:" .. tostring(why)
    end
    _trade.inFlight = true
    _trade.targetUserId = target.UserId
    _trade.tradeId = nil
    _destroyRep()
    pcall(function() _R.SendRequestRE:FireServer(target) end)
    return true, "sent"
end

local function _waitReplicatorReady()
    local ok = _waitUntil(function()
        if _trade.replicator and _getMyOffer() then return true end
        return false
    end, TRADE_TIMEOUT_OPEN)
    if not ok then
        if _trade.targetUserId then _setTargetCD(_trade.targetUserId, TRADE_FAIL_COOLDOWN) end
        _setGlobalCooldown(TRADE_FAIL_COOLDOWN, "replicator_timeout")
        _resetTradeSession()
        return false
    end
    _trade.inFlight = false
    return true
end

local function _isTradeLockedUUID(uuidCoreOrAny)
    local ok, profile = pcall(function()
        local mods = ReplicatedStorage:FindFirstChild("Modules")
        local dsMod = mods and mods:FindFirstChild("DataService")
        if not dsMod then return nil end
        local DS = require(dsMod)
        if DS and type(DS.GetData) == "function" then
            return DS:GetData()
        end
        return nil
    end)
    if not ok or type(profile) ~= "table" then return false end
    local petLocks = profile.TradeData and profile.TradeData.TradeLocks and profile.TradeData.TradeLocks.Pet
    if type(petLocks) ~= "table" then return false end
    local core = _normCoreUUID(uuidCoreOrAny)
    local rec = petLocks[core] or petLocks["{" .. core .. "}"]
    if type(rec) ~= "table" or type(rec.Value) ~= "number" then return false end
    return os.time() < rec.Value
end

local function _resolveTargetsFromMap(targetsMap)
    local result = {}
    if type(targetsMap) ~= "table" then return result end
    for key, info in pairs(targetsMap) do
        local keyStr = tostring(key)
        local userId = (type(info) == "table" and info.userId) or tonumber(keyStr)
        local name   = type(info) == "table" and info.name or nil
        if not name or name == "" then
            if keyStr:sub(1, 5) == "name:" then
                name = keyStr:sub(6)
            else
                name = keyStr
            end
        end

        local plr
        if userId then plr = Players:GetPlayerByUserId(userId) end
        if (not plr) and name and name ~= "" then
            plr = Players:FindFirstChild(name)
            if not plr then
                local want = string.lower(name)
                for _, p in ipairs(Players:GetPlayers()) do
                    if string.lower(p.Name) == want then plr = p break end
                end
            end
        end
        if plr and plr ~= LocalPlayer then result[#result + 1] = plr end
    end
    return result
end

local function _takeTradeBatch(queue)
    local batch = {}
    local count = math.min(#queue, TRADE_MAX_ITEMS_PER_SESSION)
    for i = 1, count do batch[#batch + 1] = queue[i] end
    return batch
end

local function _runTradeBatch(target, queueBatch)
    local tName = target and target.Name or "?"
    if not target or not queueBatch or #queueBatch == 0 then
        return false, "empty_batch"
    end

    local remOk, remReason = _ensureRemotes()
    if not remOk then
        return false, remReason or "remotes"
    end

    _setStatus("Equip Ticket", "Equip Trading Ticket ke karakter...", tName)
    local ticketOk, ticketWhy = _ensureHoldingTradingTicket()
    if not ticketOk then
        return false, ticketWhy or "no_ticket"
    end

    _setStatus("Kirim Request", "Membuka trade ke " .. tName .. "...", tName)
    local sentOk, sentWhy = _sendRequest(target)
    if not sentOk then
        return false, sentWhy or "request_blocked"
    end

    _setStatus("Buka Trade", "Menunggu trade window terbuka...", tName)
    if not _waitReplicatorReady() then
        return false, "replicator_timeout"
    end

    local added = 0
    for i, item in ipairs(queueBatch) do
        local tool = item.tool
        if tool and tool.Parent then
            local uuid = tool:GetAttribute("PET_UUID") or tool:GetAttribute("UUID") or tool:GetAttribute("PetUUID")
            if uuid then
                _setStatus("Tambah Pet", ("Memasukkan pet %d/%d ke offer..."):format(i, #queueBatch), tName)
                local beforeCount = _myOfferCount() or 0
                pcall(function() _R.AddItemRE:FireServer("Pet", uuid) end)
                local okAdd = _waitUntil(function()
                    if _hasItemInMyOffer("Pet", uuid) then return true end
                    local c = _myOfferCount()
                    if c and c > beforeCount then return true end
                    return false
                end, TRADE_TIMEOUT_STEP)
                if okAdd then
                    added += 1
                    task.wait(TRADE_DELAY_ADD)
                end
            end
        end
    end

    if added == 0 then
        _forceDecline()
        return false, "add_item_failed"
    end

    _setStatus("Accept", "Menunggu accept dari kedua pihak...", tName)
    _waitUntil(_cooldownSatisfied, TRADE_TIMEOUT_STEP)
    task.wait(0.4)
    pcall(function() _R.AcceptTradeRE:FireServer() end)
    if not _waitUntil(_bothAccepted, TRADE_TIMEOUT_STEP) then
        _forceDecline()
        return false, "accept_timeout"
    end

    _setStatus("Confirm", "Konfirmasi trade...", tName)
    _waitUntil(_cooldownSatisfied, TRADE_TIMEOUT_STEP)
    task.wait(0.4)
    pcall(function() _R.ConfirmTradeRE:FireServer() end)
    local okClose = _waitUntil(function()
        if not _trade.tradeId or not _trade.replicator then return true end
        local d = _trade.replicator:GetData()
        return (not d) or (not d.players) or (#d.players == 0)
    end, TRADE_TIMEOUT_STEP)
    if not okClose then
        _forceDecline()
        return false, "confirm_timeout"
    end
    _resetTradeSession()
    task.wait(TRADE_DELAY_AFTER)
    return true, "ok"
end

local function _runCurrencyTradeBatch(target, category, amount)
    local tName = target and target.Name or "?"
    category = tostring(category or ""):lower()
    amount = math.floor(tonumber(amount) or 0)
    if not target or amount <= 0 then
        return false, "zero_amount"
    end

    local remOk, remReason = _ensureRemotes()
    if not remOk then
        return false, remReason or "remotes"
    end

    if category == "token" and not _R.SetTokensRE then
        return false, "set_tokens_missing"
    end
    if category == "shekels" and not _R.SetShecklesRE then
        return false, "set_sheckles_missing"
    end

    _setStatus("Equip Ticket", "Equip Trading Ticket ke karakter...", tName)
    local ticketOk, ticketWhy = _ensureHoldingTradingTicket()
    if not ticketOk then
        return false, ticketWhy or "no_ticket"
    end

    _setStatus("Kirim Request", "Membuka trade ke " .. tName .. "...", tName)
    local sentOk, sentWhy = _sendRequest(target)
    if not sentOk then
        return false, sentWhy or "request_blocked"
    end

    _setStatus("Buka Trade", "Menunggu trade window terbuka...", tName)
    if not _waitReplicatorReady() then
        return false, "replicator_timeout"
    end

    local label = (category == "token") and "Token" or "Shekels"
    _setStatus("Set " .. label, ("Memasukkan %d %s ke offer..."):format(amount, label), tName)
    if category == "token" then
        pcall(function() _R.SetTokensRE:FireServer(amount) end)
    else
        pcall(function() _R.SetShecklesRE:FireServer(amount) end)
    end

    -- #region agent log
    _agentLog("H8", "gift.lua:_runCurrencyTradeBatch", "set_currency", {
        category = category,
        amount = amount,
        target = tName,
    })
    -- #endregion

    local okSet = _waitUntil(function()
        return _myOfferHasCurrency(category, amount)
    end, TRADE_TIMEOUT_STEP)
    if not okSet then
        _forceDecline()
        return false, "set_currency_failed"
    end

    _setStatus("Accept", "Menunggu accept dari kedua pihak...", tName)
    _waitUntil(_cooldownSatisfied, TRADE_TIMEOUT_STEP)
    task.wait(0.4)
    pcall(function() _R.AcceptTradeRE:FireServer() end)
    if not _waitUntil(_bothAccepted, TRADE_TIMEOUT_STEP) then
        _forceDecline()
        return false, "accept_timeout"
    end

    _setStatus("Confirm", "Konfirmasi trade...", tName)
    _waitUntil(_cooldownSatisfied, TRADE_TIMEOUT_STEP)
    task.wait(0.4)
    pcall(function() _R.ConfirmTradeRE:FireServer() end)
    local okClose = _waitUntil(function()
        if not _trade.tradeId or not _trade.replicator then return true end
        local d = _trade.replicator:GetData()
        return (not d) or (not d.players) or (#d.players == 0)
    end, TRADE_TIMEOUT_STEP)
    if not okClose then
        _forceDecline()
        return false, "confirm_timeout"
    end
    _resetTradeSession()
    task.wait(TRADE_DELAY_AFTER)
    return true, "ok"
end

local function _applySendOnceStop(cfg)
    if tostring(cfg.sendMode or "auto"):lower() == "once" then
        cfg.sendNow = false
        _setStatus("Selesai", "Send Once — auto stop setelah 1x kirim")
        pcall(function()
            local MAIN = rawget(_G, "MAIN")
            if MAIN and type(MAIN.Save) == "function" then
                task.defer(function() MAIN.Save() end)
            end
        end)
        -- #region agent log
        _agentLog("H5", "gift.lua:_applySendOnceStop", "send_once_complete", {})
        -- #endregion
    end
end

local function _buildTradeQueue(cfg, bp, index, helpers)
    local queue = {}
    local stats = {
        petTools = 0, noRec = 0, favorite = 0, locked = 0,
        noAgeW100 = 0, filterFail = 0, sendable = 0,
    }

    for _, tool in ipairs(bp:GetChildren()) do
        if _isPetTool(tool) then
            stats.petTools += 1
            local idAttr = tool:GetAttribute("PET_UUID") or tool:GetAttribute("UUID") or tool:GetAttribute("PetUUID")
            if idAttr then
                local core, br = helpers.normUUID(idAttr)
                local rec = index[core] or index[br]
                if not rec then
                    stats.noRec += 1
                elseif helpers.is_favorite(rec) then
                    stats.favorite += 1
                elseif _isTradeLockedUUID(core) or _isTradeLockedUUID(idAttr) then
                    stats.locked += 1
                else
                    local age  = helpers.age_from_record(rec)
                    local w100 = helpers.weight_at_100_for_rec(rec)
                    if not age or not w100 then
                        stats.noAgeW100 += 1
                    else
                        local PD = rec.PetData or rec.Data or {}
                        local petTypeRaw = rec.Type or rec.PetType or PD.Type or PD.PetType or rec.Name or PD.Name or "Pet"
                        local petTypeNorm = tostring(petTypeRaw):lower()
                        if _passesGiftGroup(w100, age, cfg.minKG, cfg.minAge)
                            and _passesPetType(petTypeNorm, cfg.petType)
                        then
                            queue[#queue + 1] = {
                                tool = tool,
                                uuidFmt = br or ("{" .. tostring(core) .. "}"),
                                age = age,
                                w100 = w100,
                            }
                            stats.sendable += 1
                        else
                            stats.filterFail += 1
                        end
                    end
                end
            end
        end
    end

    _scanStats.petTools   = stats.petTools
    _scanStats.noRec      = stats.noRec
    _scanStats.favorite   = stats.favorite
    _scanStats.locked     = stats.locked
    _scanStats.noAgeW100  = stats.noAgeW100
    _scanStats.filterFail = stats.filterFail
    _scanStats.sendable   = stats.sendable

    -- #region agent log
    _agentLog("H7", "gift.lua:_buildTradeQueue", "scan", stats)
    -- #endregion

    table.sort(queue, function(a, b)
        if a.w100 ~= b.w100 then return a.w100 > b.w100 end
        return (a.age or 0) > (b.age or 0)
    end)
    return queue
end

local function _countSavedTargets(targetsMap)
    local n = 0
    if type(targetsMap) == "table" then
        for _ in pairs(targetsMap) do n += 1 end
    end
    return n
end

local function _autoTradePass()
    local cfg = _getTradeCfg()
    if cfg.sendNow ~= true then
        _setStatus("Siap", "Send Now OFF — nyalakan toggle untuk mulai kirim")
        return
    end

    local category = tostring(cfg.category or "pet"):lower()

    local remOk, remReason = _ensureRemotes()
    if not remOk then
        _setStatus("Blocked", _reasonText(remReason))
        return
    end

    local savedCount = _countSavedTargets(cfg.targets)
    local targets = _resolveTargetsFromMap(cfg.targets)
    if savedCount == 0 then
        _setStatus("Blocked", "Belum pilih target di dropdown")
        return
    end
    if #targets == 0 then
        _setStatus("Blocked", ("Target tersimpan: %d — semua offline"):format(savedCount))
        return
    end

    if not _hasTradingTicket() then
        _setStatus("Blocked", "Trading Ticket tidak ada di backpack/tangan")
        return
    end

    if _trade.inFlight then
        _setStatus("Busy", "Sedang proses trade...")
        return
    end

    local target = _pickLeastBackpackTarget(targets)
    if not target then
        _setStatus("Blocked", "Gagal memilih target")
        return
    end

    if category == "token" or category == "shekels" then
        local amount, amtErr = _resolveCurrencyAmount(cfg, category)
        _scanStats.sendable = amount and 1 or 0
        if not amount or amount <= 0 then
            _setStatus("Skip", amtErr or "Jumlah kirim 0")
            return
        end

        local label = (category == "token") and "Token" or "Shekels"
        _setStatus("Mulai Trade", ("Kirim %d %s ke %s (%d target online)"):format(amount, label, target.Name, #targets), target.Name)

        -- #region agent log
        _agentLog("H8", "gift.lua:_autoTradePass", "currency_attempt", {
            category = category,
            amount = amount,
            target = target.Name,
            mode = cfg.currencySendMode,
        })
        -- #endregion

        local ok, reason = _runCurrencyTradeBatch(target, category, amount)
        if ok then
            _setStatus("Berhasil", ("%d %s terkirim ke %s"):format(amount, label, target.Name), target.Name)
            _agentLog("H1", "gift.lua:_autoTradePass", "currency_ok", { category = category, amount = amount })
            _applySendOnceStop(cfg)
        else
            _setStatus("Gagal", _reasonText(reason), target.Name)
            _agentLog("H2", "gift.lua:_autoTradePass", "currency_fail", { reason = reason })
        end
        return
    end

    if category ~= "pet" then
        _setStatus("Skip", "Category tidak dikenal: " .. category)
        return
    end

    local PLV = _resolvePetListView()
    if not PLV or type(PLV.getDatastoreBagIndex) ~= "function" then
        _setStatus("Blocked", "PetListView.getDatastoreBagIndex tidak ada — update pet_list_view.lua")
        return
    end
    local bp = _getBackpack()
    if not bp then
        _setStatus("Blocked", "Backpack tidak ditemukan")
        return
    end
    local _, index, helpers = PLV.getDatastoreBagIndex()
    if not index or not helpers then
        _setStatus("Blocked", "Datastore pet kosong — tunggu DataService load")
        return
    end

    local indexSize = 0
    for k in pairs(index) do indexSize += 1 end
    _scanStats.indexSize = indexSize

    local queue = _buildTradeQueue(cfg, bp, index, helpers)
    -- #region agent log
    _agentLog("H4", "gift.lua:_autoTradePass", "pre_ticket_scan", { count = #queue })
    -- #endregion
    if #queue == 0 then
        local why = ("Tool:%d Index:%d fav:%d lock:%d filter:%d noData:%d"):format(
            _scanStats.petTools or 0,
            _scanStats.indexSize or 0,
            _scanStats.favorite or 0,
            _scanStats.locked or 0,
            _scanStats.filterFail or 0,
            _scanStats.noRec or 0
        )
        _setStatus("Skip", "Tidak ada pet sendable — " .. why)
        dbg("AutoTrade: no sendable pet -> skip ticket")
        return
    end

    local batch = _takeTradeBatch(queue)
    _setStatus("Mulai Trade", ("Kirim %d pet ke %s (%d target online)"):format(#batch, target.Name, #targets), target.Name)

    -- #region agent log
    _agentLog("H1", "gift.lua:_autoTradePass", "trade_attempt", { target = target.Name, batch = #batch })
    -- #endregion

    local ok, reason = _runTradeBatch(target, batch)
    if ok then
        _setStatus("Berhasil", ("Pet terkirim ke %s via Trading Ticket"):format(target.Name), target.Name)
        -- #region agent log
        _agentLog("H1", "gift.lua:_autoTradePass", "trade_ok", {})
        -- #endregion
        _applySendOnceStop(cfg)
    else
        _setStatus("Gagal", _reasonText(reason), target.Name)
        -- #region agent log
        _agentLog("H2", "gift.lua:_autoTradePass", "trade_fail", { reason = reason })
        -- #endregion
    end
end

----------------------------------------------------------------
-- MODULE API & LOOP START
----------------------------------------------------------------
local M = {}
local _loopStarted = false

local function _startLoop()
    if _loopStarted then return end
    _loopStarted = true

    task.spawn(function()
        dbg("AutoTrade loop START")
        while true do
            local ok, err = pcall(_autoTradePass)
            if not ok then warn("[AutoTrade] ERROR:", err) end
            task.wait(AUTO_TRADE_SCAN_INTERVAL)
        end
    end)
end

-- Auto start loop saat module di-require
_startLoop()

-- Optional API: manual single pass
function M.RunOneTradePass()
    local ok, err = pcall(_autoTradePass)
    if not ok then warn("[AutoTrade] RunOneTradePass error:", err) end
end

function M.CountSendableTrade()
    local cfg = _getTradeCfg()
    local category = tostring(cfg.category or "pet"):lower()
    if category == "token" or category == "shekels" then
        local amount = _resolveCurrencyAmount(cfg, category)
        _scanStats.sendable = (amount and amount > 0) and 1 or 0
        _lastScanAt = os.clock()
        return _scanStats.sendable
    end
    if category ~= "pet" then
        _scanStats.sendable = 0
        return 0
    end
    local PLV = _resolvePetListView()
    if not PLV or type(PLV.getDatastoreBagIndex) ~= "function" then
        return _scanStats.sendable or 0
    end
    local bp = _getBackpack()
    if not bp then return _scanStats.sendable or 0 end
    local _, index, helpers = PLV.getDatastoreBagIndex()
    if not index or not helpers then return _scanStats.sendable or 0 end
    local indexSize = 0
    for k in pairs(index) do indexSize += 1 end
    _scanStats.indexSize = indexSize
    local n = #_buildTradeQueue(cfg, bp, index, helpers)
    _lastScanAt = os.clock()
    return n
end

local function _refreshScanStatsIfNeeded(force)
    local now = os.clock()
    if force or (now - (_lastScanAt or 0)) >= SCAN_REFRESH_SEC then
        pcall(M.CountSendableTrade)
    end
end

function M.GetScanStats()
    return _scanStats
end

function M.StopTradeSendNow()
    local cfg = _getTradeCfg()
    cfg.sendNow = false
end

function M.IsAutoAcceptTradeEnabled()
    local cfg = _getTradeCfg()
    return cfg and cfg.autoAcceptTrade == true
end

function M.GetDebugStatus()
    local line = tostring(_debugStatus.detail or "")
    if _debugStatus.target ~= "" then
        line = line .. " → " .. tostring(_debugStatus.target)
    end
    if line == "" then
        line = tostring(_debugStatus.phase or "Siap")
    end
    return line, ""
end

G.auto_trade = M
rawset(_G, "auto_trade", M)

return M

        end,
        required = false,
    },

    {
        key = "pet_hold_loop",
        name = "pet_hold_loop",
        factory = function()
            -- pet_hold_loop.lua
-- Auto hold pet tool berdasarkan STATE.pet_hold_cfg
-- Mode manual: pet dipilih dari backpack
-- Mode auto   : pet yang sedang di-listing booth
-- Rotate      : jika >1 target, ganti pet tiap switchDelay detik

local M = {}

local Players = game:GetService("Players")
local LocalPlayer = Players.LocalPlayer
local G = (getgenv and getgenv()) or _G

local SCAN_INTERVAL = 1.0
local DEFAULT_SWITCH_DELAY = 5

local _debugStatus = {
    phase  = "Idle",
    detail = "",
}

local _rotateIndex = 1
local _lastSwitchAt = 0
local _lastTargetsKey = ""

local function _setStatus(phase, detail)
    _debugStatus.phase = tostring(phase or "")
    _debugStatus.detail = tostring(detail or "")
end

local function _getBackpack()
    return LocalPlayer:FindFirstChildOfClass("Backpack")
        or LocalPlayer:FindFirstChild("Backpack")
end

local function _isPetTool(tool)
    if not (tool and tool:IsA("Tool")) then return false end
    local it = tool:GetAttribute("ItemType") or tool:GetAttribute("Itemtype")
    return it and string.lower(tostring(it)) == "pet"
end

local function _toolUuid(tool)
    if not tool then return nil end
    return tool:GetAttribute("PET_UUID") or tool:GetAttribute("UUID") or tool:GetAttribute("PetUUID")
end

local function _normUuid(uuid)
    if uuid == nil then return nil end
    uuid = tostring(uuid):gsub("[{}]", ""):lower()
    if uuid == "" then return nil end
    return uuid
end

local function _findPetTool(uuid)
    local want = _normUuid(uuid)
    if not want then return nil end

    local function scan(parent)
        if not parent then return nil end
        for _, child in ipairs(parent:GetChildren()) do
            if _isPetTool(child) and _normUuid(_toolUuid(child)) == want then
                return child
            end
        end
        return nil
    end

    local char = LocalPlayer.Character
    return scan(char) or scan(_getBackpack())
end

local function _getHeldUuid()
    local char = LocalPlayer.Character
    if not char then return nil end
    for _, child in ipairs(char:GetChildren()) do
        if _isPetTool(child) then
            return _normUuid(_toolUuid(child))
        end
    end
    return nil
end

local function _equipTool(tool)
    local char = LocalPlayer.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not (char and hum and tool) then return false end
    if tool.Parent == char then return true end

    pcall(function()
        hum:EquipTool(tool)
    end)
    return tool.Parent == char
end

local function _getCfg()
    local st = rawget(_G, "STATE") or G.STATE or {}
    st.pet_hold_cfg = st.pet_hold_cfg or {}
    return st.pet_hold_cfg
end

local function _getSwitchDelay(cfg)
    local n = tonumber(cfg and cfg.switchDelay)
    if not n then
        n = tonumber(rawget(_G, "PET_HOLD_SWITCH_DELAY"))
    end
    if not n or n < 1 then
        n = DEFAULT_SWITCH_DELAY
    end
    return math.max(1, math.floor(n))
end

local function _uniqueSorted(uuids)
    local seen = {}
    local out = {}
    for _, raw in ipairs(uuids) do
        local id = _normUuid(raw)
        if id and not seen[id] then
            seen[id] = true
            out[#out + 1] = id
        end
    end
    table.sort(out)
    return out
end

local function _resolvePetListView()
    return rawget(_G, "PetListView") or G.PetListView
end

local function _resolveTargets(cfg)
    local mode = tostring(cfg.mode or "manual"):lower()
    local uuids = {}

    if mode == "auto" then
        local PLV = _resolvePetListView()
        if PLV and type(PLV.listPetsListedBooth) == "function" then
            for _, row in ipairs(PLV.listPetsListedBooth() or {}) do
                if row and row.uuid then
                    uuids[#uuids + 1] = tostring(row.uuid)
                end
            end
        end
        return _uniqueSorted(uuids)
    end

    local selectedTypes = {}
    if type(cfg.selected) == "table" then
        for key, on in pairs(cfg.selected) do
            if on then
                selectedTypes[tostring(key):lower()] = true
            end
        end
    end
    if not next(selectedTypes) then
        return uuids
    end

    local bp = _getBackpack()
    local char = LocalPlayer.Character
    local PLV = _resolvePetListView()
    if not (PLV and type(PLV.getDatastoreBagIndex) == "function") then
        return uuids
    end

    local ok, bag, index, helpers = pcall(PLV.getDatastoreBagIndex)
    if not (ok and index and helpers) then
        return uuids
    end

    local function collectFrom(parent)
        if not parent then return end
        for _, tool in ipairs(parent:GetChildren()) do
            if _isPetTool(tool) then
                local idAttr = _toolUuid(tool)
                if idAttr then
                    local core, br = helpers.normUUID(idAttr)
                    local rec = index[core] or index[br]
                    if rec then
                        local PD = rec.PetData or rec.Data or {}
                        local petTypeRaw = rec.Type or rec.PetType or PD.Type or PD.PetType or rec.Name or PD.Name
                        local ptype = tostring(petTypeRaw):lower()
                        if selectedTypes[ptype] then
                            uuids[#uuids + 1] = tostring(br or core or idAttr)
                        end
                    end
                end
            end
        end
    end

    collectFrom(bp)
    collectFrom(char)

    return _uniqueSorted(uuids)
end

local function _targetsKey(targets)
    return table.concat(targets, "|")
end

local function _indexOf(targets, uuid)
    local want = _normUuid(uuid)
    if not want then return nil end
    for i, id in ipairs(targets) do
        if id == want then
            return i
        end
    end
    return nil
end

local function _holdUuid(uuid)
    local norm = _normUuid(uuid)
    if not norm then return false end

    local held = _getHeldUuid()
    if held == norm then
        return true
    end

    local tool = _findPetTool(uuid)
    if tool and _equipTool(tool) then
        _setStatus("Holding", tool.Name)
        return true
    end
    return false
end

local function _holdPass()
    local cfg = _getCfg()
    if cfg.enabled ~= true then
        _lastSwitchAt = 0
        _setStatus("Idle", "Hold pet OFF")
        return
    end

    local targets = _resolveTargets(cfg)
    if #targets == 0 then
        _rotateIndex = 1
        _lastSwitchAt = 0
        _lastTargetsKey = ""
        _setStatus("Waiting", (tostring(cfg.mode or "manual"):lower() == "auto")
            and "Tidak ada pet listed di booth"
            or "Belum pilih pet di backpack")
        return
    end

    local switchDelay = _getSwitchDelay(cfg)
    local now = os.clock()
    local held = _getHeldUuid()
    local heldIdx = _indexOf(targets, held)

    -- Pet yang sedang dipegang masih target: jangan ganti sebelum delay habis
    -- (list booth sering di-sort ulang tiap detik → tanpa ini ganti 1s)
    if heldIdx then
        _rotateIndex = heldIdx
        _lastTargetsKey = _targetsKey(targets)
        if _lastSwitchAt <= 0 then
            _lastSwitchAt = now
        end
        if #targets == 1 then
            _setStatus("Holding", string.format("locked  delay %ds", switchDelay))
            return
        end
        local elapsed = now - _lastSwitchAt
        if elapsed < switchDelay then
            local remain = math.max(1, math.ceil(switchDelay - elapsed))
            _setStatus("Holding", string.format("next in %ds  (%d/%d)  delay %ds",
                remain, heldIdx, #targets, switchDelay))
            return
        end
        _rotateIndex = (heldIdx % #targets) + 1
        _lastSwitchAt = now
        local nextUuid = targets[_rotateIndex]
        if _holdUuid(nextUuid) then
            _setStatus("Holding", string.format("switched  (%d/%d)  delay %ds",
                _rotateIndex, #targets, switchDelay))
        else
            _lastSwitchAt = now - switchDelay + 1
            _setStatus("Waiting", "Pet berikutnya belum ada di backpack")
        end
        return
    end

    -- Belum megang target: equip slot sekarang, timer mulai dari sini
    if _rotateIndex > #targets or _rotateIndex < 1 then
        _rotateIndex = 1
    end
    local want = targets[_rotateIndex]
    if _holdUuid(want) then
        if _lastSwitchAt <= 0 then
            _lastSwitchAt = now
        end
        _lastTargetsKey = _targetsKey(targets)
        _setStatus("Holding", string.format("equip  (%d/%d)  delay %ds",
            _rotateIndex, #targets, switchDelay))
        return
    end
    _setStatus("Waiting", "Pet target belum ada di backpack")
end

local _loopStarted = false

local function _startLoop()
    if _loopStarted then return end
    _loopStarted = true

    task.spawn(function()
        while true do
            local ok, err = pcall(_holdPass)
            if not ok then
                warn("[pet_hold_loop] ERROR:", err)
            end
            task.wait(SCAN_INTERVAL)
        end
    end)
end

function M.RunOnce()
    local ok, err = pcall(_holdPass)
    if not ok then
        warn("[pet_hold_loop] RunOnce error:", err)
    end
end

