    local line = tostring(_debugStatus.detail or "")
    if line == "" then
        line = tostring(_debugStatus.phase or "Idle")
    end
    return line, ""
end

function M.ResetRotate()
    _rotateIndex = 1
    _lastSwitchAt = 0
    _lastTargetsKey = ""
end

_startLoop()

G.pet_hold_loop = M
rawset(_G, "pet_hold_loop", M)

return M

