    {
        key = "auto_chat",
        name = "auto_chat",
        factory = function()
            -- auto_chat.lua
-- Auto Chat: kirim teks manual ke RBXGeneral tiap interval (min 30s)

local M = {}

local TextChatService = game:GetService("TextChatService")
local Players = game:GetService("Players")
local G = (getgenv and getgenv()) or _G
local LP = Players.LocalPlayer

local MAX_BYTES = 200
local MIN_INTERVAL = 30
local DEFAULT_INTERVAL = 45
local SCAN_INTERVAL = 1.0

local _status = {
    phase = "Idle",
    chars = 0,
    detail = "",
}

local _lastSentAt = 0
local _wasEnabled = false

local function _now()
    return os.clock()
end

local function clampUtf8Bytes(s, maxBytes)
    s = tostring(s or "")
    maxBytes = tonumber(maxBytes) or MAX_BYTES
    if #s <= maxBytes then
        return s
    end
    local cut = maxBytes
    while cut > 0 do
        local b = string.byte(s, cut)
        if b and b >= 128 and b < 192 then
            cut = cut - 1
        else
            break
        end
    end
    return s:sub(1, cut)
end

local function _getCfg()
    local st = rawget(_G, "STATE") or G.STATE or {}
    st.chat_cfg = st.chat_cfg or {}
    local cfg = st.chat_cfg
    cfg.enabled = (cfg.enabled == true)
    cfg.mode = nil
    cfg.text = clampUtf8Bytes(cfg.text, MAX_BYTES)
    local n = math.floor(tonumber(cfg.intervalSec) or DEFAULT_INTERVAL)
    if n < MIN_INTERVAL then n = MIN_INTERVAL end
    if n > 86400 then n = 86400 end
    cfg.intervalSec = n
    return cfg
end

local function _getChannel()
    local channels = TextChatService:FindFirstChild("TextChannels")
    local ch = channels and channels:FindFirstChild("RBXGeneral")
    return ch
end

local function _setStatus(phase, extra)
    _status.phase = tostring(phase or "Idle")
    _status.detail = tostring(extra or "")
    local cfg = _getCfg()
    _status.chars = #(cfg.text or "")
end

local function _statusText()
    local cfg = _getCfg()
    local phase = _status.phase or "Idle"
    local chars = tonumber(_status.chars) or #(cfg.text or "")
    local extra = tostring(_status.detail or "")
    local line1 = string.format("%s  %d/200", phase, chars)
    if extra ~= "" then
        line1 = line1 .. "  " .. extra
    end
    return line1
end

local _lastSend = {
    sent = "",
    returned = "",
    statusName = "",
    hashed = false,
}

local _pendingSend = nil

local function _isHashed(s)
    s = tostring(s or "")
    if s == "" then
        return false
    end
    local compact = s:gsub("%s+", "")
    if compact == "" then
        return false
    end
    return compact:gsub("#", "") == ""
end

local function _statusNameOf(msg)
    if type(msg) ~= "table" then
        return ""
    end
    local st = msg.Status
    if typeof(st) == "EnumItem" then
        return tostring(st.Name or st)
    end
    return tostring(st or "")
end

local function _fromLocalPlayer(msg)
    if type(msg) ~= "table" then
        return false
    end
    local src = msg.TextSource
    local uid = src and src.UserId
    if not uid then
        return false
    end
    local me = LP or Players.LocalPlayer
    return me and uid == me.UserId
end

pcall(function()
    TextChatService.MessageReceived:Connect(function(msg)
        if not _pendingSend then
            return
        end
        if not _fromLocalPlayer(msg) then
            return
        end
        local got = tostring(msg.Text or "")
        if got == "" then
            return
        end
        if got == _pendingSend.sent or _isHashed(got) then
            _pendingSend.msg = msg
            _pendingSend.done = true
        end
    end)
end)

local function _classifySendStatus(msg)
    local name = string.lower(_statusNameOf(msg))
    local returned = ""
    if type(msg) == "table" then
        returned = tostring(msg.Text or "")
    end
    if _isHashed(returned) or name:find("filter", 1, true) or name:find("moderat", 1, true) then
        return "Filter"
    end
    if name:find("success", 1, true) then
        return "Sent"
    end
    if returned ~= "" and not _isHashed(returned) then
        return "Sent"
    end
    if name == "" or name == "nil" then
        return "Unknown"
    end
    return "Failed"
end

local function _send(text)
    text = clampUtf8Bytes(text, MAX_BYTES)
    if text == "" then
        return false, "empty"
    end
    local ch = _getChannel()
    if not ch then
        return false, "no_channel"
    end

    _pendingSend = { sent = text, done = false, msg = nil }

    local ok, msg = pcall(function()
        return ch:SendAsync(text)
    end)
    if not ok then
        _pendingSend = nil
        _lastSend.sent = text
        _lastSend.returned = ""
        _lastSend.statusName = "pcall"
        _lastSend.hashed = false
        return false, tostring(msg)
    end

    local t0 = os.clock()
    while (not _pendingSend.done) and (os.clock() - t0) < 4 do
        local liveText = (type(msg) == "table") and tostring(msg.Text or "") or ""
        local liveStatus = _statusNameOf(msg)
        if liveText ~= "" or (liveStatus ~= "" and liveStatus ~= "nil") then
            if not _pendingSend.msg then
                _pendingSend.msg = msg
            end
            if liveText ~= "" then
                _pendingSend.done = true
                break
            end
        end
        task.wait(0.05)
    end

    local final = _pendingSend.msg or msg
    _pendingSend = nil

    local returned = ""
    if type(final) == "table" then
        returned = tostring(final.Text or "")
    end
    _lastSend.sent = text
    _lastSend.returned = returned
    _lastSend.statusName = _statusNameOf(final)
    _lastSend.hashed = _isHashed(returned)

    warn(string.format(
        "[auto_chat] send bytes=%d status=%s hashed=%s sent=%s returned=%s",
        #text,
        _lastSend.statusName ~= "" and _lastSend.statusName or "?",
        tostring(_lastSend.hashed),
        text,
        returned
    ))

    return true, _classifySendStatus(final)
end

local function _pass()
    local cfg = _getCfg()

    if not cfg.enabled then
        _wasEnabled = false
        _setStatus("Idle")
        return
    end

    if not _wasEnabled then
        _wasEnabled = true
        _lastSentAt = _now()
        _setStatus("Idle", "next in " .. tostring(cfg.intervalSec) .. "s")
        return
    end

    local remain = cfg.intervalSec - (_now() - _lastSentAt)
    if remain > 0 then
        local keep = tostring(_status.phase or "Idle")
        local extra = "next in " .. tostring(math.ceil(remain)) .. "s"
        if keep ~= "Filter" and keep ~= "Sent" and keep ~= "Failed" and keep ~= "Unknown" then
            keep = "Idle"
        elseif _lastSend.hashed then
            extra = "Roblox hashed  " .. extra
        end
        _setStatus(keep, extra)
        return
    end

    local text = clampUtf8Bytes(cfg.text, MAX_BYTES)
    if text == "" then
        _setStatus("Idle", "empty")
        _lastSentAt = _now()
        return
    end

    _lastSentAt = _now()
    local ok, result = _send(text)
    if not ok then
        _setStatus("Failed", tostring(result or ""))
        return
    end
    local extra = tostring(_lastSend.statusName or "")
    if _lastSend.hashed then
        extra = "Roblox hashed  " .. extra
    end
    _setStatus(result or "Sent", extra)
end

local _loopStarted = false

local function _startLoop()
    if _loopStarted then
        return
    end
    _loopStarted = true
    task.spawn(function()
        while true do
            local ok, err = pcall(_pass)
            if not ok then
                warn("[auto_chat] ERROR:", err)
                _setStatus("Failed", tostring(err))
            end
            task.wait(SCAN_INTERVAL)
        end
    end)
end

function M.GetDebugStatus()
    return _statusText(), ""
end

function M.GetStatus()
    return _status
end

_startLoop()

G.auto_chat = M
rawset(_G, "auto_chat", M)
G.AutoChat = M
rawset(_G, "AutoChat", M)

return M

