			for i = 1, qty do
				if not STATE.autoBuySeeds then break end
				BuySeedStock:FireServer("Shop", name)
				task.wait(0.15)
			end
		end,
	},
	egg = {
		infoTable = EGG_INFO,
		stockPath = "PetEggStock",
		buyFn     = function(name, qty)
			if not EGG_INDEX_BY_NAME then buildEggList() end
			local idx = EGG_INDEX_BY_NAME and EGG_INDEX_BY_NAME[name]
			if not idx then
				dwarn("Egg index not found for:", name)
				return
			end

			dprint("BUY egg", name, "idx", idx, "qty", qty)
			for i = 1, qty do
				if not STATE.autoBuyEgg then break end
				BuyPetEgg:FireServer(idx)
				task.wait(0.15)
			end
		end,
	},
	gear = {
		infoTable = GEAR_INFO,
		stockPath = "GearStock",
		buyFn     = function(name, qty)
			dprint("BUY gear", name, "qty", qty)
			for i = 1, qty do
				if not STATE.autoBuyGear then break end
				BuyGearStock:FireServer(name)
				task.wait(0.15)
			end
		end,
	},
	event = {
		infoTable = EVENT_INFO,
		stockPath = "EventShopStock",
		buyFn     = function(name, qty, shopName)
			qty = math.max(0, math.floor(tonumber(qty) or 0))
			if qty <= 0 then return end
			-- 10 parallel fires per 1 stock (stock 2 → 20 FireServer)
			local fires = qty * 10
			dprint("BUY event parallel", name, "stock", qty, "fires", fires, "shop", tostring(shopName))
			for i = 1, fires do
				if not STATE.autoBuyEvent then break end
				task.spawn(function()
					if shopName and shopName ~= "" then
						pcall(function()
							BuyEventShopStock:FireServer(name, shopName)
						end)
					else
						local ok = pcall(function()
							BuyEventShopStock:FireServer(name)
						end)
