-- =========================================================
-- EVENT STOCK READER (FIX UTAMA)
-- =========================================================
local function getEventRoot(profile)
	-- 1) dari profile
	if type(profile) == "table" and type(profile.EventShopStock) == "table" then
		return profile.EventShopStock
	end
	-- 2) fallback: DataService.EventShopStock
	if type(DataService.EventShopStock) == "table" then
		return DataService.EventShopStock
	end
	return nil
end

local function getAllEventShopsFromRoot(root)
	if type(root) ~= "table" then return {} end

	local shops = {}

	-- A) root.Stocks = root shop
	if type(root.Stocks) == "table" then
		shops[#shops+1] = { shopName = nil, stocks = root.Stocks }
	end

	-- B) subshops
	for k, v in pairs(root) do
		if type(v) == "table" and type(v.Stocks) == "table" then
			local shopName = (type(k) == "string" and k ~= "" and k) or nil
			shops[#shops+1] = { shopName = shopName, stocks = v.Stocks }
		end
	end

	return shops
end

local function getAllEventShops(profile)
	local root = getEventRoot(profile)
	return getAllEventShopsFromRoot(root)
end

local function getEventStockCount(stockRec)
	return (type(stockRec) == "table" and tonumber(stockRec.Stock)) or 0
end

local function fmtShortPrice(n)
	n = tonumber(n) or 0
	local abs = math.abs(n)
	local sign = (n < 0) and "-" or ""
	local function trim(v)
		local s
		if v >= 100 then
			s = string.format("%.0f", v)
		elseif v >= 10 then
			s = string.format("%.1f", v):gsub("%.0$", "")
		else
			s = string.format("%.2f", v):gsub("%.?0+$", "")
		end
		return s
	end
	if abs >= 1e12 then
		return sign .. trim(abs / 1e12) .. "t"
	end
	if abs >= 1e9 then
		return sign .. trim(abs / 1e9) .. "b"
	end
	if abs >= 1e6 then
		return sign .. trim(abs / 1e6) .. "m"
	end
	if abs >= 1e3 then
		return sign .. trim(abs / 1e3) .. "k"
	end
	if abs == math.floor(abs) then
		return sign .. tostring(math.floor(abs))
	end
	return sign .. string.format("%.1f", abs):gsub("%.0$", "")
end

local CURRENCY_ABBR = {
	Sheckles = "S",
	MoonCoins = "MC",
	HoneyCoins = "HC",
	Honey = "H",
	TideTokens = "TT",
	RoyalJelly = "RJ",
	ChocCoins = "CC",
	GardenCoins = "GC",
	SummerCoins = "SC",
	CandyCorn = "CN",
	FairyPoints = "FP",
	Chi = "Chi",
	PassPoints = "PP",
	CarrotCoins = "CRC",
	ButtercupCoins = "BC",
	HeartCoins = "HT",
	AdventToken = "AT",
}

local function currencyAbbr(cur)
	cur = tostring(cur or "Sheckles")
	if CURRENCY_ABBR[cur] then
		return CURRENCY_ABBR[cur]
	end
	local letters = cur:gsub("[^%u]", "")
	if letters ~= "" then
		return letters
	end
	return cur:sub(1, 2):upper()
end

local function eventPriceRec(name, shopName)
	local info = EVENT_INFO[tostring(name)]
	if type(info) ~= "table" then
		return nil
	end
	if shopName and type(info.byShop) == "table" and type(info.byShop[shopName]) == "table" then
		return info.byShop[shopName]
	end
	return info
end

local function fmtEventPriceTag(name, shopName)
	local rec = eventPriceRec(name, shopName)
	if type(rec) ~= "table" then
		return nil
	end
	local price = tonumber(rec.price) or 0
	if price <= 0 then
		return nil
	end
	return fmtShortPrice(price) .. " " .. currencyAbbr(rec.currency)
end

local function fmtRestock(sec)
	sec = math.max(0, math.floor(tonumber(sec) or 0))
	if sec <= 0 then
		return "now"
	end
	local m = math.floor(sec / 60)
	local s = sec % 60
	if m >= 60 then
		local h = math.floor(m / 60)
		m = m % 60
		return string.format("%dh%02dm", h, m)
	end
	if m > 0 then
		return string.format("%dm%02ds", m, s)
	end
	return string.format("%ds", s)
end

local function getEventRestockSec(shopName, shopData)
	local reset = 300
	if EventShopConfigData and type(EventShopConfigData.GetShopResetTime) == "function" then
		local ok, t = pcall(function()
			return EventShopConfigData.GetShopResetTime(shopName)
		end)
		if ok and tonumber(t) then
			reset = tonumber(t)
		end
	end
	local now = workspace:GetServerTimeNow()
	if typeof(now) ~= "number" then
		now = os.time()
	end
	local endAt = type(shopData) == "table" and tonumber(shopData.ForcedEventShopEndTimestamp)
	if endAt and now < endAt and (endAt - now) <= reset then
		return endAt - now
	end
	return reset - now % reset
end

local function getLiveEventStockMap()
	local map = {}
	local ok, profile = pcall(function()
		return DataService:GetData()
	end)
	if not ok then
		profile = nil
	end
	local root = getEventRoot(profile)
	for _, shop in ipairs(getAllEventShops(profile)) do
		if type(shop.stocks) == "table" then
			local shopName = shop.shopName
			local shopData = (type(root) == "table" and shopName and root[shopName]) or nil
			local restockSec = getEventRestockSec(shopName, shopData or root)
			for itemName, stockRec in pairs(shop.stocks) do
				local key = tostring(itemName)
				local n = getEventStockCount(stockRec)
				local prev = map[key]
				if not prev or n > (prev.stock or 0) then
					map[key] = {
						stock = n,
						shopName = shopName,
						restockSec = restockSec,
					}
				end
			end
		end
	end
	return map
end

function M.GetEventDropdownItems()
	ensureListsBuilt()
	local stockMap = getLiveEventStockMap()
	local out = {}
	for _, name in ipairs(EventItems or {}) do
		local key = tostring(name)
		local rec = stockMap[key]
		local n = rec and tonumber(rec.stock) or 0
		local priceTag = fmtEventPriceTag(key, rec and rec.shopName)
		local label = string.format("%s x %d", key, n)
		if priceTag then
			label = label .. " · " .. priceTag
		end
		out[#out + 1] = {
			key = key,
			name = label,
		}
	end
	return out
end

local function getShopWeatherLabel()
	if workspace:GetAttribute("BloodMoonEvent") == true then
		return "Blood Moon"
	end
	if workspace:GetAttribute("NightEvent") == true then
		return "Night"
	end
	return nil
end

function M.GetEventShopStatusText()
	local ok, profile = pcall(function()
		return DataService:GetData()
	end)
	if not ok then
		profile = nil
	end
	local root = getEventRoot(profile)
	local weather = getShopWeatherLabel()

	local shopName = nil
	if weather == "Blood Moon" then
		shopName = "Blood Moon Shop"
	elseif weather == "Night" then
		shopName = "Twilight Shop"
	else
		local shops = getAllEventShops(profile)
		for _, shop in ipairs(shops) do
			if shop.shopName == "Moon Coin Shop" then
				shopName = "Moon Coin Shop"
				break
			end
		end
	end

	local shopData = (type(root) == "table" and shopName and root[shopName]) or nil
	return "Restock: " .. fmtRestock(getEventRestockSec(shopName, shopData or root))
end

-- =========================================================
-- SYNC GLOBAL -> STATE
-- =========================================================
function M.SyncFromGlobals()
	ensureListsBuilt()

	STATE.autoBuySeeds = (AUTO_BUY_SEED_ENABLED == true)
	STATE.autoBuyEgg   = (AUTO_BUY_EGG_ENABLED  == true)
	STATE.autoBuyGear  = (AUTO_BUY_GEAR_ENABLED == true)
	STATE.autoBuyEvent = (AUTO_BUY_EVENT_ENABLED == true)
	STATE.autoBuyTravelingMerchant = (AUTO_BUY_TRAVELING_MERCHANT_ENABLED == true)
	STATE.autoBuyGardenCoin = (AUTO_BUY_GARDEN_COIN_ENABLED == true)
	STATE.autoBuySeasonPass = (AUTO_BUY_SEASON_PASS_ENABLED == true)
	STATE.autoClaimSeasonPass = (AUTO_CLAIM_SEASON_PASS_ENABLED == true)
	STATE.autoBuyCosmetic = (AUTO_BUY_COSMETIC_ENABLED == true)

	SHOP_INFO.seed.selected  = SEED_SELECTED  or {}
	SHOP_INFO.egg.selected   = EGG_SELECTED   or {}
	SHOP_INFO.gear.selected  = GEAR_SELECTED  or {}
	SHOP_INFO.event.selected = EVENT_SELECTED or {}
	SHOP_INFO.traveling_merchant.selected = TRAVELING_MERCHANT_SELECTED or {}
	SHOP_INFO.garden_coin.selected = GARDEN_COIN_SELECTED or {}
	SHOP_INFO.season_pass.selected = SEASON_PASS_SELECTED or {}
	SHOP_INFO.cosmetic.selected = COSMETIC_SELECTED or {}

	dprint("SyncFromGlobals:", STATE.autoBuySeeds, STATE.autoBuyEgg, STATE.autoBuyGear, STATE.autoBuyEvent, STATE.autoBuyTravelingMerchant, STATE.autoBuyGardenCoin, STATE.autoBuySeasonPass, STATE.autoClaimSeasonPass, STATE.autoBuyCosmetic)
end

local function levelAlreadyClaimed(claimedList, level)
	if type(claimedList) ~= "table" then return false end
	if claimedList[level] == true then return true end
	return table.find(claimedList, level) ~= nil
end

local function claimSeasonPassRewards(profile)
	if STATE.autoClaimSeasonPass ~= true then return end
	if not ClaimSeasonPassReward then
		dwarn("ClaimSeasonPassReward missing")
		return
	end

	local season = SeasonPassData and SeasonPassData.CurrentSeason
	if not season or season == "" then
		dwarn("season_pass claim: no CurrentSeason")
		return
	end

	local seasonRoot = type(profile.SeasonPass) == "table" and profile.SeasonPass[season]
	if type(seasonRoot) ~= "table" then
		dwarn("season_pass claim: no season data")
		return
	end

	local totalXp = tonumber(seasonRoot.TotalExperience) or 0
	local level = 0
	if SeasonPassUtils and type(SeasonPassUtils.CalculateLevel) == "function" then
		local ok, lv = pcall(SeasonPassUtils.CalculateLevel, totalXp)
		if ok then level = tonumber(lv) or 0 end
	end
	if level <= 0 then return end

	local maxLevel = tonumber(SeasonPassStaticData and SeasonPassStaticData.MAX_LEVEL) or 50
	local claimUpTo = math.min(level, maxLevel)
	local freeClaimed = seasonRoot.ClaimedLevelFreeRewards
	local premiumClaimed = seasonRoot.ClaimedLevelPremiumRewards
	local isPremium = seasonRoot.IsPremium == true

	for tier = 1, claimUpTo do
		if STATE.autoClaimSeasonPass ~= true then break end

		if not levelAlreadyClaimed(freeClaimed, tier) then
			dprint("SP CLAIM free tier", tier)
			local ok = pcall(function()
				ClaimSeasonPassReward:FireServer(tier, false)
			end)
			if not ok then
				dwarn("SP CLAIM free failed:", tier)
				break
			end
			task.wait(0.15)
		end

		if isPremium and not levelAlreadyClaimed(premiumClaimed, tier) then
			dprint("SP CLAIM premium tier", tier)
			local ok = pcall(function()
				ClaimSeasonPassReward:FireServer(tier, true)
			end)
			if not ok then
				dwarn("SP CLAIM premium failed:", tier)
				break
			end
			task.wait(0.15)
		end
	end

	-- Infinite rewards after max level
	if level < maxLevel then return end
	if not ClaimSeasonPassInfReward then return end

	local infClaimed = tonumber(seasonRoot.InfRewardsClaimed) or 0
	local infCount = 0
	if SeasonPassUtils and type(SeasonPassUtils.CalculateInfClaimCount) == "function" then
		local ok, n = pcall(SeasonPassUtils.CalculateInfClaimCount, totalXp, infClaimed)
		if ok then infCount = math.floor(tonumber(n) or 0) end
	end

	if infCount < 1 then return end
	local infTier = maxLevel + 1
	for i = 1, math.min(infCount, 20) do
		if STATE.autoClaimSeasonPass ~= true then break end
		dprint("SP CLAIM inf", i, "/", infCount)
		local ok = pcall(function()
			ClaimSeasonPassInfReward:FireServer(infTier, false)
		end)
		if not ok then
			dwarn("SP CLAIM inf failed")
			break
		end
		task.wait(0.15)
	end
end

-- =========================================================
-- Tick logic
-- =========================================================
local function getStockAmount(entry)
	if entry == nil then return 0 end
	if type(entry) == "number" then return entry end
	if type(entry) == "table" then return entry.Stock or 0 end
	return 0
end

local function getSheckles(profile)
	if not profile then return 0 end
	if type(profile.Sheckles) == "number" then return profile.Sheckles end
	if type(profile.CurrencyData) == "table" and type(profile.CurrencyData.Sheckles) == "number" then
		return profile.CurrencyData.Sheckles
	end
	if type(profile.Stats) == "table" and type(profile.Stats.Sheckles) == "number" then
		return profile.Stats.Sheckles
	end
	return 0
end

local function getGardenCoins(profile)
	if not profile then return 0 end
	if type(profile.GardenCoins) == "number" then return profile.GardenCoins end
	if type(profile.CurrencyData) == "table" and type(profile.CurrencyData.GardenCoins) == "number" then
		return profile.CurrencyData.GardenCoins
	end
	if type(profile.Stats) == "table" and type(profile.Stats.GardenCoins) == "number" then
		return profile.Stats.GardenCoins
	end
	return 0
end

local function getPassPoints(profile)
	if not profile then return 0 end
	if type(profile.SpecialCurrency) == "table" and type(profile.SpecialCurrency.PassPoints) == "number" then
		return profile.SpecialCurrency.PassPoints
	end
	if type(profile.PassPoints) == "number" then return profile.PassPoints end
	return 0
end

local function hasAnySelected(map)
	if type(map) ~= "table" then return false end
	for _, on in pairs(map) do
		if on then return true end
	end
	return false
end

function M.Tick()
	M.SyncFromGlobals()

	local profile = DataService:GetData()
	if not profile then
		dwarn("Tick: DataService:GetData() returned nil")
		return
	end

	local sheckles    = getSheckles(profile)
	local gardenCoins = getGardenCoins(profile)
	local passPoints  = getPassPoints(profile)
	dprint("Tick balances:", "Sheckles", sheckles, "GardenCoins", gardenCoins, "PassPoints", passPoints)

	-- Season Pass reward claim (independent from shop buy)
	if STATE.autoClaimSeasonPass == true then
		local okClaim, errClaim = pcall(claimSeasonPassRewards, profile)
		if not okClaim then
			dwarn("claimSeasonPassRewards error:", errClaim)
		end
	end

	for catKey, cfg in pairs(SHOP_INFO) do
		local categoryOn = false
		if catKey == "seed" then
			categoryOn = (STATE.autoBuySeeds == true)
		elseif catKey == "egg" then
			categoryOn = (STATE.autoBuyEgg == true)
		elseif catKey == "gear" then
			categoryOn = (STATE.autoBuyGear == true)
		elseif catKey == "event" then
			categoryOn = (STATE.autoBuyEvent == true)
		elseif catKey == "traveling_merchant" then
			categoryOn = (STATE.autoBuyTravelingMerchant == true)
		elseif catKey == "garden_coin" then
			categoryOn = (STATE.autoBuyGardenCoin == true)
		elseif catKey == "season_pass" then
			categoryOn = (STATE.autoBuySeasonPass == true)
		elseif catKey == "cosmetic" then
			categoryOn = (STATE.autoBuyCosmetic == true)
		end

		if not categoryOn then
			continue
		end

		ensureListsBuilt()

		-- =========================
		-- EGG (array stocks)
		-- =========================
		if catKey == "egg" then
			local stockRoot = profile[cfg.stockPath]
			local stocks = stockRoot and stockRoot.Stocks
			if typeof(stocks) ~= "table" then
				dwarn("Egg stocks not table:", typeof(stocks))
			else
				local selected = cfg.selected or {}
				local hasSelected = hasAnySelected(selected)

				for idx, eggRec in ipairs(stocks) do
					if type(eggRec) == "table" then
						local name = eggRec.EggName
						local stockCount = tonumber(eggRec.Stock) or 0
						local priceType = eggRec.PriceType

						local allowed = true
						if stockCount <= 0 then allowed = false end
						if allowed and priceType == "Robux" then allowed = false end
						if allowed and hasSelected and not selected[name] then allowed = false end

						if allowed then
							dprint("Egg allowed:", idx, name, "stock", stockCount, "priceType", tostring(priceType))
							for i = 1, stockCount do
								if not STATE.autoBuyEgg then break end
								BuyPetEgg:FireServer(idx)
								task.wait(0.15)
							end
						end
					end
				end
			end

		-- =========================
		-- EVENT (map stocks per shop)
		-- =========================
		elseif catKey == "event" then
			local selected = cfg.selected or {}
			local hasSelected = hasAnySelected(selected)

			local shops = getAllEventShops(profile)
			if #shops == 0 then
				dwarn("event: no shops found in EventShopStock")
			else
				for _, shop in ipairs(shops) do
					local shopName = shop.shopName
					local stocks   = shop.stocks

					dprint("event: scanning shop =", tostring(shopName), "items =", (typeof(stocks) == "table" and "OK" or typeof(stocks)))

					for itemName, stockRec in pairs(stocks) do
						local stockCount = getEventStockCount(stockRec)
						local allowed = stockCount > 0
						if allowed and hasSelected and not selected[itemName] then
							allowed = false
						end
						local info = EVENT_INFO[itemName]
						if allowed and type(info) == "table" and (tonumber(info.price) or 0) <= 0 then
							allowed = false
						end
						if allowed then
							dprint("EVENT BUY:", itemName, "stock", stockCount, "shop", tostring(shopName), hasSelected and "selected" or "all")
							task.spawn(function()
								cfg.buyFn(itemName, stockCount, shopName)
							end)
						end
					end
				end
			end

		-- =========================
		-- TRAVELING MERCHANT
		-- =========================
		elseif catKey == "traveling_merchant" then
			local selected = cfg.selected or {}
			local hasSelected = hasAnySelected(selected)
			if not hasSelected then
				dwarn("traveling_merchant: no items selected")
			else
				local root = profile.TravelingMerchantShopStock
				local stocks = root and root.Stocks
				if typeof(stocks) ~= "table" then
					dwarn("traveling_merchant stocks not table:", typeof(stocks), "merchant=", root and tostring(root.MerchantType))
				else
					dprint("traveling_merchant active:", tostring(root.MerchantType))
					for itemName, on in pairs(selected) do
						if on == true then
							local stockCount = getEventStockCount(stocks[itemName])
							if stockCount > 0 then
								dprint("TM BUY:", itemName, "stock", stockCount)
								cfg.buyFn(itemName, stockCount)
							end
						end
					end
				end
			end

		-- =========================
		-- GARDEN COIN SHOP
		-- =========================
		elseif catKey == "garden_coin" then
			local selected = cfg.selected or {}
			local hasSelected = hasAnySelected(selected)
			if not hasSelected then
				dwarn("garden_coin: no items selected")
			else
				local stats = profile.GardenCoinShopStats
				if type(stats) == "table" and stats.UnlockedGardenCoins ~= true then
					dwarn("garden_coin: shop locked (UnlockedGardenCoins=false)")
				else
					local root = profile.GardenCoinShopStock
					local stocks = root and root.Stocks
					local purchases = (type(stats) == "table" and type(stats.LifetimePurchases) == "table") and stats.LifetimePurchases or {}
					if typeof(stocks) ~= "table" then
						dwarn("garden_coin stocks not table:", typeof(stocks))
					else
						local balance = gardenCoins
						for itemName, on in pairs(selected) do
							if on == true then
								local info = cfg.infoTable[itemName]
								if info then
									local lifetimeLimit = tonumber(info.lifetimeLimit)
									local bought = tonumber(purchases[itemName]) or 0
									local allowed = true

									if lifetimeLimit and bought >= lifetimeLimit then
										allowed = false
									end

									local dep = info.lifetimeLimitDependancy
									if allowed and dep and dep ~= "" then
										local depInfo = GardenCoinShopData[dep]
										local depLimit = depInfo and tonumber(depInfo.LifetimeLimit)
										local depBought = tonumber(purchases[dep]) or 0
										if depLimit and depBought < depLimit then
											allowed = false
										end
									end

									local price = tonumber(info.price) or 0
									if allowed and price > 0 and balance < price then
										allowed = false
									end

									local stockCount = getEventStockCount(stocks[itemName])
									if allowed and stockCount > 0 then
										dprint("GC BUY:", itemName, "stock", stockCount, "price", price)
										cfg.buyFn(itemName, stockCount)
										balance = math.max(0, balance - (price * stockCount))
									end
								end
							end
						end
					end
				end
			end

		-- =========================
		-- SEASON PASS STORE (PassPoints)
		-- =========================
		elseif catKey == "season_pass" then
			local selected = cfg.selected or {}
			local hasSelected = hasAnySelected(selected)
			if not hasSelected then
				dwarn("season_pass: no items selected")
			else
				local season = SeasonPassData and SeasonPassData.CurrentSeason
				if not season or season == "" then
					dwarn("season_pass: no CurrentSeason")
				else
					local seasonRoot = type(profile.SeasonPass) == "table" and profile.SeasonPass[season]
					local stocks = seasonRoot and seasonRoot.Stocks
					if typeof(stocks) ~= "table" then
						dwarn("season_pass stocks not table:", typeof(stocks), "season=", tostring(season))
					else
						local balance = passPoints
						for itemKey, on in pairs(selected) do
							if on == true then
								local info = cfg.infoTable[itemKey]
								if info and info.robuxOnly ~= true then
									local price = tonumber(info.price) or 0
									local stockCount = getEventStockCount(stocks[itemKey])
									local canAfford = (price <= 0) or (balance >= price)
									if stockCount > 0 and canAfford then
										local maxByCash = (price > 0) and math.floor(balance / price) or stockCount
										local qty = math.min(stockCount, maxByCash)
										if qty > 0 then
											dprint("SP BUY:", itemKey, "stock", stockCount, "qty", qty, "price", price)
											cfg.buyFn(itemKey, qty)
											balance = math.max(0, balance - (price * qty))
										end
									end
								end
							end
						end
					end
				end
			end

		-- =========================
		-- COSMETIC SHOP (Sheckles)
		-- =========================
		elseif catKey == "cosmetic" then
			local selected = cfg.selected or {}
			local hasSelected = hasAnySelected(selected)
			if not hasSelected then
				dwarn("cosmetic: no items selected")
			else
				local root = profile.CosmeticStock
				local tabStocks = root and root.TabStocks
				if typeof(tabStocks) ~= "table" then
					dwarn("cosmetic TabStocks not table:", typeof(tabStocks))
				else
					local balance = sheckles
					local ownedFences = (type(profile.FenceSkinData) == "table" and type(profile.FenceSkinData.OwnedFences) == "table")
						and profile.FenceSkinData.OwnedFences
						or {}

					for itemKey, on in pairs(selected) do
						if on == true then
							local info = cfg.infoTable[itemKey]
							if info then
								local category = info.category or "Cosmetics"
								local tab = tabStocks[category]
								local stockMap
								if info.kind == "crate" then
									stockMap = tab and tab.CrateStocks
								elseif info.kind == "fence" then
									stockMap = tab and tab.FenceStocks
								else
									stockMap = tab and tab.ItemStocks
								end

								local stockCount = getEventStockCount(stockMap and stockMap[itemKey])
								local price = tonumber(info.price) or 0
								local allowed = stockCount > 0

								if info.kind == "fence" then
									local fenceName = info.fenceName or itemKey
									if ownedFences[fenceName] == true then
										allowed = false
									elseif stockCount <= 0 then
										-- fence may still be buyable once even if stock display differs
										allowed = true
										stockCount = 1
									end
								end

								if allowed and price > 0 and balance < price then
									allowed = false
								end

								if allowed and stockCount > 0 then
									local maxByCash = (price > 0) and math.floor(balance / price) or stockCount
									local qty = math.min(stockCount, maxByCash)
									if qty > 0 then
										dprint("COS BUY:", itemKey, "kind", info.kind, "qty", qty, "price", price)
										cfg.buyFn(itemKey, qty)
										balance = math.max(0, balance - (price * qty))
									end
								end
							end
						end
					end
				end
			end

		-- =========================
		-- SEED / GEAR (map stocks normal)
		-- =========================
		else
			local infoTable = cfg.infoTable
			local stockRoot = profile[cfg.stockPath]
			local rawStocks

			if catKey == "seed" then
				rawStocks = stockRoot and stockRoot.Shop and stockRoot.Shop.Stocks
			else
				rawStocks = stockRoot and stockRoot.Stocks
			end

			if typeof(rawStocks) ~= "table" then
				dwarn(catKey, "rawStocks not table:", typeof(rawStocks))
			else
				local stockTable = {}
				for key, entry in pairs(rawStocks) do
					stockTable[key] = getStockAmount(entry)
				end

				local selected = cfg.selected or {}
				local hasSelected = hasAnySelected(selected)

				local function processItem(name)
					local info = infoTable[name]
					if not info then return end

					local currency = info.currency or "Sheckles"
					local price    = tonumber(info.price) or 0
					if price <= 0 then return end

					local balance    = (currency == "GardenCoins") and gardenCoins or sheckles
					local stockCount = stockTable[name] or 0
					if stockCount <= 0 then return end
					if balance < price then return end

					dprint("Process", catKey, name, "stock", stockCount, "price", price, "cur", currency)
					cfg.buyFn(name, stockCount)
				end

				if hasSelected then
					for name, on in pairs(selected) do
						if on then processItem(name) end
					end
				else
					for name, _ in pairs(infoTable) do
						processItem(name)
					end
				end
			end
		end
	end
end

-- =========================================
-- LOOP RUNNER
-- =========================================
local RUNNING = false

function M.Start()
	if RUNNING then return end
	RUNNING = true
	dprint("Start() loop running")

	task.spawn(function()
		while RUNNING do
			local ok, err = pcall(M.Tick)
			if not ok then
				dwarn("Tick error:", err)
			end
			task.wait(5) -- interval beli
		end
	end)
end

function M.Stop()
	RUNNING = false
	dprint("Stop() loop stopped")
end

function M.IsRunning()
	return RUNNING
end

do
	local G = (getgenv and getgenv()) or _G
	G.AutoBuyModule = M
	rawset(_G, "AutoBuyModule", M)
end

return M

