local function _debugOn()
    local GG = (getgenv and getgenv()) or _G
    return (GG.PSRECONNECT_DEBUG == true) or (rawget(_G, "PSRECONNECT_DEBUG") == true)
end

local function _dbg(tag, ...)
    if not _debugOn() then return end
    local parts = {}
    for i=1, select("#", ...) do
        parts[#parts+1] = tostring(select(i, ...))
    end
    warn(("[PSReconnect][%s] %s"):format(tostring(tag), table.concat(parts, " ")))
end

--------------------------------------------------
-- FLAGS (runtime)
--------------------------------------------------
local TELEPORT_BLOCKED       = false
local AUTO_RECONNECT_ENABLED = true

--------------------------------------------------
-- FILE HELPERS
--------------------------------------------------
local CAN_FS = (type(readfile)=="function" and type(isfile)=="function")

local function safeName(s)
    s = tostring(s or "player")
    s = s:gsub("[^%w%-_.]", "_")
    s = s:gsub("_+", "_")
    return s:sub(1, 48)
end

local function getSaveFile()
    if not LP then return nil end
    return (SAVE_DIR .. "/" .. safeName(LP.Name) .. ".json")
end

--------------------------------------------------
-- FILE CACHE
--------------------------------------------------
local _fileCache = { t=0, txt=nil, data=nil }
local function readDecodedFile()
    if not CAN_FS then
        _dbg("FILE", "FS not available (readfile/isfile missing)")
        return nil, "fs_missing"
    end

    local f = getSaveFile()
    if not f then
        _dbg("FILE", "getSaveFile=nil")
        return nil, "no_file"
    end
    if not isfile(f) then
        _dbg("FILE", "file not found:", f)
        return nil, "not_found"
    end

    local now = os.clock()
    if _fileCache.data ~= nil and (now - (_fileCache.t or 0)) < 1.0 then
        return _fileCache.data, "cache"
    end

    local ok, txt = pcall(readfile, f)
    if not ok or type(txt) ~= "string" or txt == "" then
        _dbg("FILE", "readfile failed/empty", f)
        return nil, "read_fail"
    end

    local ok2, data = pcall(HttpService.JSONDecode, HttpService, txt)
    if not ok2 or type(data) ~= "table" then
        _dbg("FILE", "JSONDecode failed", f)
        return nil, "json_fail"
    end

    _fileCache.t    = now
    _fileCache.txt  = txt
    _fileCache.data = data
    return data, "ok"
end

local function extractRejoinTable(data)
    if type(data) ~= "table" then return {} end
    if type(data.rejoin) == "table" then return data.rejoin end
    if type(data.state) == "table" and type(data.state.rejoin) == "table" then return data.state.rejoin end
    if type(data.market) == "table"
        and type(data.market.state) == "table"
        and type(data.market.state.rejoin) == "table" then
        return data.market.state.rejoin
    end
    return {}
end

local function readFlagsFromFile()
    local DEFAULT_RECONNECT = false
    local DEFAULT_EXEC      = false

    if not CAN_FS then
        local S = rawget(_G, "STATE")
        if type(S) == "table" and type(S.rejoin) == "table" then
            _dbg("FLAGS", "fallback runtime STATE.rejoin (fs missing)")
            return (S.rejoin.auto_reconnect == true), (S.rejoin.auto_exec == true)
        end
        _dbg("FLAGS", "fs missing -> default false/false")
        return DEFAULT_RECONNECT, DEFAULT_EXEC
    end

    local data = select(1, readDecodedFile())
    if type(data) ~= "table" then
        local S = rawget(_G, "STATE")
        if type(S) == "table" and type(S.rejoin) == "table" then
            _dbg("FLAGS", "file read fail -> fallback runtime STATE.rejoin")
            return (S.rejoin.auto_reconnect == true), (S.rejoin.auto_exec == true)
        end
        _dbg("FLAGS", "file read fail -> default false/false")
        return DEFAULT_RECONNECT, DEFAULT_EXEC
    end

    local r = extractRejoinTable(data)
    local autoReconnect = (r.auto_reconnect == true)
    local autoExec      = (r.auto_exec == true)
    _dbg("FLAGS", "file flags:", "auto_reconnect=", autoReconnect, "auto_exec=", autoExec)
    return autoReconnect, autoExec
end

local function webhookHasTarget(wh)
    local S = rawget(_G, "STATE")
    if type(S) == "table" and type(S.webhook) == "table" then
        local u = tostring(S.webhook.targetUrl or "")
        u = u:match("^%s*(.-)%s*$")
        if u ~= "" then return true end
    end
    -- legacy
    if type(S) == "table" then
        local u = tostring(S.webhookUrl or "")
        u = u:match("^%s*(.-)%s*$")
        if u ~= "" then return true end
    end
    return false
end

--------------------------------------------------
-- DISCONNECT WEBHOOK (USE webhook.lua)
--------------------------------------------------
local _lastDisconnectSentT = 0
local MIN_DISCONNECT_WEBHOOK_INTERVAL = 8

local function getWebhookModule()
    local GG = (getgenv and getgenv()) or _G
    local wh = rawget(GG, "Webhook") or GG.Webhook or rawget(_G, "Webhook") or _G.Webhook
    if type(wh) == "table" and type(wh.Send) == "function" then
        return wh
    end
    return nil
end

local function isWebhookReady()
    local S = rawget(_G, "STATE")
    if type(S) ~= "table" then return false, "no_state" end
    local wb = S.webhook
    if type(wb) ~= "table" then return false, "no_webhook_table" end

    local target = tostring(wb.targetUrl or ""):match("^%s*(.-)%s*$")
    if target == "" then return false, "target_empty" end
    if wb.enabled ~= true then return false, "disabled" end

    local wh = getWebhookModule()
    if not wh then return false, "no_webhook_module" end
    return true, wh
end

local function sendDisconnectWebhook(reasonText, extra)
    local okReady, whOrReason = isWebhookReady()
    if not okReady then
        _dbg("WEBHOOK", "skip DISCONNECT:", whOrReason, "reason=", reasonText)
        return false, tostring(whOrReason)
    end
    local wh = whOrReason

    local now = os.clock()
    if (now - _lastDisconnectSentT) < MIN_DISCONNECT_WEBHOOK_INTERVAL then
        _dbg("WEBHOOK", "dedupe skip (interval) reason=", reasonText)
        return false, "dedupe"
    end
    _lastDisconnectSentT = now

    local payload = {
            reason = tostring(reasonText or ""), -- ini reasonAll
    reasonAll = tostring(reasonText or ""), -- optional mirror
        teleportBlocked = (TELEPORT_BLOCKED == true),
        autoReconnectEnabled = (AUTO_RECONNECT_ENABLED == true),
        rejoinInFlight = (_rejoinInFlight == true),
        env = { placeId = game.PlaceId, jobId = game.JobId },
        extra = extra,
    }

local dkey = "DISCONNECT|"..tostring(game.JobId).."|"..tostring(reasonText or ""):sub(1,200)

local ok, res = wh.Send("DISCONNECT", payload, {
    pingEveryone = true,
    shareToDC = false,
    dedupeKey = dkey,
    dedupeWindow = 120, -- 2 menit
    mode = "SIMPLE",
})


    _dbg("WEBHOOK", "Send(DISCONNECT):", ok, res)
    return ok, res
end

