local function getQTP()
    return queue_on_teleport
        or (syn and syn.queue_on_teleport)
        or (fluxus and fluxus.queue_on_teleport)
        or queueteleport
        or queueonteleport
end

--------------------------------------------------
-- QUEUE ON TELEPORT (STRICT GATED + MARKER)
--------------------------------------------------
local function QueueAutoExecIfEnabled()
    local _, autoExec = readFlagsFromFile()
    if autoExec ~= true then
        _dbg("QTP", "skip queue (auto_exec=false)")
        return false, "auto_exec=false"
    end

    local qtp = getQTP()
    if not qtp then
        _dbg("QTP", "qtp not found")
        return false, "qtp not found"
    end

    -- queue_on_teleport menumpuk: cukup antre sekali per sesi (tetap tersimpan walau teleport gagal)
    -- flag diikat ke JobId: getgenv di sebagian executor tetap hidup setelah teleport
    local GQ = (getgenv and getgenv()) or _G
    local jobNow = tostring(game.JobId or "")
    if GQ.__NODEHUB_QTP_QUEUED_JOB == jobNow then
        _dbg("QTP", "already queued this server")
        return true, "already_queued"
    end

    local template = [[
    -- beberapa chunk antre bisa jalan bersamaan setelah teleport: hanya yang pertama load
    local G0 = (getgenv and getgenv()) or _G
    local job0 = tostring(game.JobId or "")
    if G0.__NODEHUB_QTP_RAN_JOB == job0 then return end
    G0.__NODEHUB_QTP_RAN_JOB = job0

    task.wait(3)

    local url = "__URL__"
    local SAVE_DIR = "__SAVE_DIR__"

    -- marker: bukti QTP jalan
    pcall(function()
        if type(writefile)=="function" then
            if type(makefolder)=="function" and type(isfolder)=="function" then
                if not isfolder(SAVE_DIR) then pcall(makefolder, SAVE_DIR) end
            end
            writefile(SAVE_DIR .. "/_qtp_ran.txt",
                "ran@"..os.time()..
                "\nfile="..tostring(SAVE_DIR)..
                "\nenabled=true"..
                "\nurl="..tostring(url)
            )
        end
    end)

    -- reset guards (biar loader gak ke-block)
    local G = (getgenv and getgenv()) or _G
    G.__NODEHUB_LOADED = nil
    G.__NODEHUB_LOADED_SESSION = nil
    G.__NODEHUB_AUTOEXECED = nil
    G.__MAINUI_LOADED = nil
    G.__UI_LOADED = nil

    -- kalau loader kamu punya guard lain, ini optional tapi sering perlu:
    -- G.__NODEHUB_MAIN_RUNNING = nil
    -- G.__NODEHUB_MARKET_RUNNING = nil

    -- fetch loader (retry)
    local src
    for i=1,10 do
        local ok, res = pcall(function() return game:HttpGet(url) end)
        if ok and type(res)=="string" and #res>0 then
            src = res
            break
        end
        task.wait(1.2)
    end

    if not src then return end
    pcall(function() loadstring(src)() end)
]]


    -- gsub replacement: '%' di URL (mis. %20) harus literal — pakai function
    local chunk = template
        :gsub("__URL__", function()
            return tostring(SCRIPT_URL)
        end)
        :gsub("__SAVE_DIR__", function()
            return tostring(SAVE_DIR)
        end)

    local ok, err = pcall(function()
        qtp(chunk)
    end)

    if not ok then
        _dbg("QTP", "queue failed:", err)
        return false, tostring(err)
    end
    GQ.__NODEHUB_QTP_QUEUED_JOB = jobNow
    _dbg("QTP", "queued ok")
    return true, "queued"
end

--------------------------------------------------
-- TELEPORT BLOCK (private/restricted)
--------------------------------------------------
-- Latch singkat: abaikan prompt overlay setelah gagal teleport (GameFull dll)
local _ignorePromptUntil = 0

TeleportService.TeleportInitFailed:Connect(function(player, result, errMsg)
    if player ~= LP then return end
    local m = string.lower(errMsg or "")
    local resultName = tostring(result)

    -- Server full / gagal join instance → jangan dianggap disconnect
    if result == Enum.TeleportResult.GameFull
        or result == Enum.TeleportResult.GameEnded
        or result == Enum.TeleportResult.GameNotFound
        or m:find("full", 1, true)
        or m:find("teleport", 1, true) then
        _ignorePromptUntil = os.clock() + 8
        _dbg("TPFAIL", "TeleportInitFailed (no rejoin):", resultName, tostring(errMsg))
        return
    end

    if result == Enum.TeleportResult.Unauthorized
        or m:find("restricted", 1, true)
        or m:find("private", 1, true)
        or m:find("not authorized", 1, true) then
        TELEPORT_BLOCKED = true
        _ignorePromptUntil = os.clock() + 8
        _dbg("TPFAIL", "TeleportInitFailed blocked:", resultName, tostring(errMsg))
    else
        _dbg("TPFAIL", "TeleportInitFailed:", resultName, tostring(errMsg))
    end
end)

--------------------------------------------------
-- REJOIN CORE
--------------------------------------------------
local function doTeleport()
    if TELEPORT_BLOCKED then
        _dbg("TP", "blocked=true -> cancel teleport")
        return false, "blocked"
    end
    local ok, err = pcall(function()
        TeleportService:Teleport(game.PlaceId, LP)
    end)
    if not ok then
        _dbg("TP", "Teleport error:", err)
        return false, tostring(err)
    end
    _dbg("TP", "Teleport fired OK")
    return true
end

local function canTriggerRejoin()
    local now = os.clock()
    if _rejoinInFlight then
        _dbg("REJOIN", "blocked: inFlight=true")
        return false
    end
    if (now - _lastRejoinT) < MIN_REJOIN_INTERVAL then
        _dbg("REJOIN", "blocked: minInterval", ("%.2f"):format(now - _lastRejoinT))
        return false
    end
    _lastRejoinT = now
    return true
end

local function tryRejoin()
    _dbg("REJOIN", "tryRejoin called")
    if not canTriggerRejoin() then return end
    _rejoinInFlight = true

    local fileAutoReconnect = select(1, readFlagsFromFile())
    if not (fileAutoReconnect == true and AUTO_RECONNECT_ENABLED == true) then
        _dbg("REJOIN", "skip: fileAutoReconnect or runtime disabled", "file=", fileAutoReconnect, "runtime=", AUTO_RECONNECT_ENABLED)
        _rejoinInFlight = false
        return
    end
    if TELEPORT_BLOCKED then
        _dbg("REJOIN", "skip: TELEPORT_BLOCKED=true")
        _rejoinInFlight = false
        return
    end

    task.delay(REJOIN_DELAY_SEC, function()
        _dbg("REJOIN", "delay reached -> queue + teleport", "delay=", REJOIN_DELAY_SEC)

        local okQ, reasonQ = QueueAutoExecIfEnabled()
        _dbg("REJOIN", "QueueAutoExecIfEnabled:", okQ, reasonQ)

        local _, ax = readFlagsFromFile()
        if ax == true and not okQ then
            _dbg("REJOIN", "HARD GATE cancel teleport (auto_exec ON but QTP failed):", reasonQ)
            _rejoinInFlight = false
            return
        end

        if okQ then task.wait(0.8) end
        doTeleport()

        task.delay(2, function()
            _rejoinInFlight = false
            _dbg("REJOIN", "inFlight reset")
        end)
    end)
end

--------------------------------------------------
-- DISCONNECT DETECTION
--------------------------------------------------
-- Prompt gagal teleport (server full, dll) BUKAN disconnect.
-- Jangan trigger RejoinNow / Teleport random.
local function isTeleportFailPrompt(t)
    t = string.lower(tostring(t or ""))
    if t == "" then return false end

    if t:find("game is full", 1, true)
        or t:find("server is full", 1, true)
        or t:find("this game is full", 1, true)
        or t:find("gamefull", 1, true)
        or t:find("teleport failed", 1, true)
        or t:find("failed to teleport", 1, true)
        or t:find("unable to join", 1, true)
        or t:find("could not teleport", 1, true)
        or t:find("cannot teleport", 1, true)
        or t:find("teleport was unsuccessful", 1, true)
        or t:find("instance is full", 1, true)
        or t:find("experience is full", 1, true)
        or (t:find("full", 1, true) and t:find("teleport", 1, true))
        or (t:find("penuh", 1, true) and (t:find("server", 1, true) or t:find("game", 1, true) or t:find("teleport", 1, true)))
    then
        return true
    end

    return false
end

local function isDisconnectText(t)
    t = string.lower(tostring(t or ""))
    if t == "" then return false end

    -- Abaikan popup gagal teleport (mis. Job ID server full)
    if isTeleportFailPrompt(t) then
        return false
    end

    if t:find("disconnected", 1, true)
        or t:find("lost connection", 1, true)
        or t:find("connection error", 1, true)
        or t:find("attempting to reconnect", 1, true)
        or t:find("kicked", 1, true) then
        return true
    end

    if t:find("koneksi terputus", 1, true)
        or t:find("hubungkan kembali", 1, true)
        or t:find("akun yang sama", 1, true)
        or t:find("perangkat yang berbeda", 1, true)
        or t:find("kode error", 1, true)
        or t:find("error:273", 1, true)
        or t:find("kode error:273", 1, true) then
        return true
    end

    -- Jangan match kata "error" generik — popup teleport failed juga mengandung "error"
    -- dan sebelumnya memicu RejoinNow (teleport ke server random).

    return false
end

-- anti spam detect (scan loop)
local _lastPromptDetectedT = 0
local MIN_PROMPT_DETECT_INTERVAL = 2.0
-- anti spam per reason (popup yang sama)
local _lastDiscKey = nil
local _discLatched = false
local DISC_COOLDOWN_SEC = 90  -- 1.5 menit (ubah sesukamu)
local _lastDiscSentAt = 0

local function hookPrompt()
    task.spawn(function()
        local gui = CoreGui:WaitForChild("RobloxPromptGui", 30)
        if not gui then
            _dbg("PROMPT", "RobloxPromptGui not found")
            return
        end

        local overlay = gui:WaitForChild("promptOverlay", 30)
        if not overlay then
            _dbg("PROMPT", "promptOverlay not found")
            return
        end

        _dbg("PROMPT", "hooked promptOverlay OK")

        local function readAnyText(obj)
            if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                return tostring(obj.Text or "")
            end
            return ""
        end
        
        local function extractErrorCode(text)
    text = tostring(text or "")
    -- cari "Kode Error: 273" / "Error: 273" / "(Kode Error: 273)"
    local code =
        text:match("[Kk]ode%s*[Ee]rror%s*:%s*(%d+)") or
        text:match("[Ee]rror%s*:%s*(%d+)") or
        text:match("%((%d+)%)")
    return tonumber(code)
end

local function collectDialogTextsFromOverlay(overlay)
    -- kita cari kandidat title/body/errorcode dari semua TextLabel/TextButton/TextBox di overlay
    local title, body, codeText
    local all = {}

    for _, d in ipairs(overlay:GetDescendants()) do
        local t = readAnyText(d)
        t = (t and t:match("^%s*(.-)%s*$")) or ""
        if t ~= "" then
            all[#all+1] = t

            local low = string.lower(t)

            -- Title biasanya "Koneksi Terputus" / "Disconnected"
            if not title and (#t <= 40) and (low:find("koneksi terputus") or low:find("disconnected")) then
                title = t
            end

            -- Body biasanya panjang, ada "Akun yang sama..." dll
            if not body and (#t >= 40) and (low:find("akun yang sama") or low:find("perangkat") or low:find("hubungkan kembali") or low:find("connection")) then
                body = t
            end

            -- code text biasanya mengandung "Kode Error" atau "273"
            if not codeText and (low:find("kode error") or low:find("error:") or low:find("273")) then
                codeText = t
            end
        end
    end

    -- fallback kalau body belum ketemu: ambil kalimat terpanjang (biasanya isi dialog)
    if not body then
        local best, bestLen = nil, 0
        for _, t in ipairs(all) do
            if #t > bestLen then
                best = t
                bestLen = #t
            end
        end
        body = best
    end

    local code = extractErrorCode(codeText or body or "")

    -- reasonAll (gabungan rapi)
    local reasonAll = ""
    do
        local parts = {}
        if title and title ~= "" then parts[#parts+1] = title end
        if body and body ~= "" and body ~= title then parts[#parts+1] = body end
        if codeText and codeText ~= "" and codeText ~= body then parts[#parts+1] = codeText end
        reasonAll = table.concat(parts, "\n")
        if reasonAll == "" then
            reasonAll = table.concat(all, "\n")
        end
    end

    return {
        title = title,
        body = body,
        code = code,
        reasonAll = reasonAll,
        rawTexts = all, -- opsional buat debug
    }
end


        local function scan()
    local now = os.clock()
    if (now - _lastPromptDetectedT) < MIN_PROMPT_DETECT_INTERVAL then
        return
    end

    -- Baru gagal teleport (Job ID full dll) → jangan scan sebagai disconnect
    if now < (_ignorePromptUntil or 0) then
        return
    end

    for _, v in ipairs(overlay:GetDescendants()) do
        local txt = readAnyText(v)
        if txt ~= "" and isDisconnectText(txt) then
            _lastPromptDetectedT = now

            -- ✅ ambil alasan lengkap dari seluruh dialog
            local dialog = collectDialogTextsFromOverlay(overlay)
            local reasonAll = tostring(dialog.reasonAll or "")

            -- Double-check seluruh isi dialog (bukan cuma 1 label)
            if isTeleportFailPrompt(reasonAll) or isTeleportFailPrompt(txt) then
                _dbg("PROMPT", "ignore teleport-fail prompt (no rejoin):", reasonAll ~= "" and reasonAll or txt)
                return
            end

            _dbg("PROMPT", "disconnect detected:", txt)
            _dbg("PROMPT", "reasonAll:", reasonAll)
            if dialog.code then _dbg("PROMPT", "errorCode:", dialog.code) end
-- bikin key stabil dari dialog (reasonAll + errorCode)
local key = reasonAll .. "|code=" .. tostring(dialog.code or "")
key = key:gsub("%s+", " "):sub(1, 400) -- normalisasi biar stabil

-- latch: kalau popup sama & belum berubah, jangan kirim lagi
local now2 = os.clock()

if _discLatched and _lastDiscKey == key then
    return
end

-- cooldown global biar gak spam kalau UI re-render
if (now2 - (_lastDiscSentAt or 0)) < DISC_COOLDOWN_SEC then
    return
end

_discLatched = true
_lastDiscKey = key
_lastDiscSentAt = now2

            -- ✅ kirim payload lengkap
            local okW, reasonW = sendDisconnectWebhook(reasonAll, {
                source = "promptOverlay",
                node   = v.Name,

                reasonTitle = dialog.title,
                reasonBody  = dialog.body,
                errorCode   = dialog.code,

                -- kalau mau debug super lengkap:
                -- rawTexts = dialog.rawTexts,
            })
            _dbg("PROMPT", "webhook:", okW, reasonW)

            -- Pakai tryRejoin (hormati Auto Reconnect), bukan RejoinNow paksa
            tryRejoin()
            return
        end
    end
end


        scan()
        overlay.DescendantRemoving:Connect(function()
    -- kalau overlay berubah (prompt mulai hilang), lepas latch biar next disconnect bisa terkirim
    task.defer(function()
        -- cek masih ada teks disconnect?
        local still = false
        for _, d in ipairs(overlay:GetDescendants()) do
            local t = readAnyText(d)
            if t ~= "" and isDisconnectText(t) then
                still = true
                break
            end
        end
        if not still then
            _discLatched = false
            _lastDiscKey = nil
        end
    end)
end)


        while true do
            task.wait(0.6)
            scan()
        end
    end)
end

hookPrompt()

