function M.SetEnabled(on)
    AUTO_RECONNECT_ENABLED = (on == true)
    _dbg("API", "SetEnabled", AUTO_RECONNECT_ENABLED)
end

function M.SetDelay(sec)
    local n = tonumber(sec)
    if n and n >= 0 then
        REJOIN_DELAY_SEC = n
    end
    _dbg("API", "SetDelay", REJOIN_DELAY_SEC)
end

function M.TryRejoinNow()
    _dbg("API", "TryRejoinNow")
    tryRejoin()
end

function M.RejoinOnce(delaySec)
    delaySec = tonumber(delaySec) or 0
    _dbg("API", "RejoinOnce", delaySec)
    task.delay(math.max(0, delaySec), function()
        tryRejoin()
    end)
end

function M.RejoinNow()
    _dbg("API", "RejoinNow")

    local _, ax = readFlagsFromFile()
    if ax == true then
        local okQ, reasonQ = QueueAutoExecIfEnabled()
        _dbg("API", "RejoinNow queue:", okQ, reasonQ)
        if not okQ then
            return false, reasonQ
        end
        task.wait(0.8)
    end

    return doTeleport()
end

function M.IsTeleportBlocked()
    _dbg("API", "IsTeleportBlocked", TELEPORT_BLOCKED)
    return TELEPORT_BLOCKED
end

local function fireTravelRemote(toTrade)
    local RS = game:GetService("ReplicatedStorage")
    local TW = RS:WaitForChild("GameEvents", 10)
    TW = TW and TW:WaitForChild("TradeWorld", 8)
    local r = TW and TW:WaitForChild(toTrade and "TravelToTradeWorld" or "TravelToMainWorld", 8)
    if not r then
        return false, "travel remote missing"
    end

    local ok, err = pcall(function()
        r:FireServer()
    end)

    _dbg("TRAVEL", toTrade and "TravelToTradeWorld" or "TravelToMainWorld", "ok=", ok, "err=", err)
    return ok, err
end

function M.TravelToMarket()
    _dbg("API", "TravelToMarket")
    local _, ax = readFlagsFromFile()
    if ax == true then
        local okQ, reasonQ = QueueAutoExecIfEnabled()
        _dbg("API", "TravelToMarket queue:", okQ, reasonQ)
        if not okQ then
            return false, "QTP failed: " .. tostring(reasonQ)
        end
        task.wait(0.2)
    end
    return fireTravelRemote(true)
end

function M.TravelToMain()
    _dbg("API", "TravelToMain")
    local _, ax = readFlagsFromFile()
    if ax == true then
        local okQ, reasonQ = QueueAutoExecIfEnabled()
        _dbg("API", "TravelToMain queue:", okQ, reasonQ)
        if not okQ then
            return false, "QTP failed: " .. tostring(reasonQ)
        end
        task.wait(0.2)
    end
    return fireTravelRemote(false)
end

function M.HopToServer(a, b, c, d)
    -- ✅ kompatibel: dot-call & colon-call
    local placeId, jobId, teleportData
    if type(a) == "table" then
        -- dipanggil pakai colon: PR:HopToServer(placeId, jobId, td)
        placeId, jobId, teleportData = b, c, d
    else
        -- dipanggil pakai dot: PR.HopToServer(placeId, jobId, td)
        placeId, jobId, teleportData = a, b, c
    end

    _dbg("API", "HopToServer", placeId, jobId)

    placeId = tonumber(placeId) or game.PlaceId
    jobId   = tostring(jobId or "")
    if jobId == "" then
        return false, "jobId_empty"
    end

    local _, ax = readFlagsFromFile()
    if ax == true then
        local okQ, reasonQ = QueueAutoExecIfEnabled()
        _dbg("API", "HopToServer queue:", okQ, reasonQ)
        if not okQ then
            return false, "QTP failed: " .. tostring(reasonQ)
        end
        task.wait(0.2)
    end

    local tpOpts = nil
    if type(teleportData) == "table" then
        tpOpts = Instance.new("TeleportOptions")
        local okTD, errTD = pcall(function()
            tpOpts:SetTeleportData(teleportData)
        end)
        _dbg("API", "HopToServer SetTeleportData:", okTD, errTD)
    end

    local ok, err = pcall(function()
        if tpOpts then
            TeleportService:TeleportToPlaceInstance(placeId, jobId, LP)
        else
            TeleportService:TeleportToPlaceInstance(placeId, jobId, LP)
        end
    end)

    if not ok then
        _dbg("API", "HopToServer teleport error:", err)
        return false, tostring(err)
    end
    return true, "teleport_called"
end



