local function getGiftCfg()
    -- coba beberapa nama, tergantung kamu assign di mana
    local cfg = rawget(G, "GIFT_CFG")
        or G.GIFT_CFG
        or rawget(_G, "GIFT_CFG")
        or _G.GIFT_CFG
        or rawget(_G, "giftCfg")
        or _G.giftCfg
        or _G.GIFT_CONFIG
        or GIFT_CFG

    if typeof(cfg) ~= "table" then
        return nil
    end
    return cfg
end

local function isAutoGiftOn()
    local cfg = getGiftCfg()
    return cfg and cfg.autoAcceptGift == true
end

local function getTradeCfg()
    local st = rawget(G, "STATE") or rawget(_G, "STATE")
    if type(st) == "table" and type(st.trade_cfg) == "table" then
        return st.trade_cfg
    end
    return rawget(G, "TRADE_CFG") or rawget(_G, "TRADE_CFG") or TRADE_CFG or {}
end

local function isAutoTradeOn()
    local cfg = getTradeCfg()
    return cfg and cfg.autoAcceptTrade == true
end

