----------------------------------------------------------------
-- AFK nudge — VirtualUser + Right (tidak klik tengah UI)
----------------------------------------------------------------
local function nudge()
    pcall(function()
        VirtualUser:CaptureController()
        VirtualUser:ClickButton2(Vector2.new(0, 0))
    end)

    pcall(function()
        VIM:SendKeyEvent(true, Enum.KeyCode.Right, false, game)
        task.wait(0.03)
        VIM:SendKeyEvent(false, Enum.KeyCode.Right, false, game)
    end)

    pcall(function()
        VIM:SendMouseMoveEvent(10, 10, 0, game)
    end)

    pcall(function()
        local cam = workspace.CurrentCamera
        if cam then
            local cf = cam.CFrame
            cam.CFrame = cf * CFrame.Angles(0, math.rad(0.1), 0)
            task.wait(0.02)
            cam.CFrame = cf
        end
    end)

    dprint("nudge")
end

----------------------------------------------------------------
-- Skip loading (cara anti-AFK + Space)
----------------------------------------------------------------
local function loadingGui()
    if not LP then
        LP = Players.LocalPlayer
    end
    if not LP then
        return nil
    end
    local pg = LP:FindFirstChild("PlayerGui")
    local gui = pg and pg:FindFirstChild("LoadingGui")
    if gui and gui.Enabled == true then
        return gui
    end
    return nil
end

local function skipReady(gui)
    for _, d in ipairs(gui:GetDescendants()) do
        if d:IsA("TextLabel") or d:IsA("TextButton") then
            local t = string.lower(tostring(d.Text or ""))
            if string.find(t, "click", 1, true)
                or string.find(t, "tap", 1, true)
                or string.find(t, "press", 1, true)
                or string.find(t, "skip", 1, true) then
                return true
            end
        end
    end
    return false
end

local function pressSkipKeys()
    pcall(function()
        VirtualUser:CaptureController()
        VirtualUser:ClickButton2(Vector2.new(0, 0))
    end)

    pcall(function()
        VIM:SendKeyEvent(true, Enum.KeyCode.Right, false, game)
        task.wait(0.03)
        VIM:SendKeyEvent(false, Enum.KeyCode.Right, false, game)
    end)

    pcall(function()
        VIM:SendKeyEvent(true, Enum.KeyCode.Space, false, game)
        task.wait(0.03)
        VIM:SendKeyEvent(false, Enum.KeyCode.Space, false, game)
    end)
end

local function clearLeftoverBlur()
    local blur = Lighting:FindFirstChild("LoadingBlur")
    if blur then
        pcall(function()
            blur:Destroy()
        end)
    end
end

-- Loop terus: kalau "Click to skip" muncul → press. Tidak one-shot / flag stale.
function M.AutoSkipLoading(reason)
    if M._skipWatcher then
        dprint("skip watcher already on", tostring(reason or ""))
        return
    end
    M._skipWatcher = true
    dprint("skip watcher start", tostring(reason or ""))

    task.spawn(function()
        local idleAfterDone = 0
        while M._skipWatcher do
            local gui = loadingGui()
            if gui and skipReady(gui) then
                idleAfterDone = 0
                local now = os.clock()
                if now - (M._lastSkipPress or 0) >= 0.9 then
                    M._lastSkipPress = now
                    dprint("skip press")
                    pressSkipKeys()
                end
            elseif not gui then
                if LP and (LP:GetAttribute("LoadingScreenDone") == true
                    or workspace.CurrentCamera.CameraType == Enum.CameraType.Custom) then
                    clearLeftoverBlur()
                    idleAfterDone += 1
                    -- Sudah selesai beberapa detik → stop watcher
                    if idleAfterDone > 20 then
                        dprint("skip watcher done")
                        break
                    end
                end
            end
            task.wait(0.35)
        end
        M._skipWatcher = false
    end)
end

function M.Start()
    M.AutoSkipLoading("start")

    if M.running then
        return
    end

    M.running = true
    dprint("start")

    if M.connection then
        M.connection:Disconnect()
        M.connection = nil
    end

    if not LP then
        LP = Players.LocalPlayer
    end

    if LP then
        M.connection = LP.Idled:Connect(function()
            if not M.running then
                return
            end
            dprint("idled")
            nudge()
        end)
    end

    M.thread = task.spawn(function()
        while M.running do
            if not M.running then
                break
            end
            nudge()
            task.wait(600 + math.random(0, 20))
        end
    end)
end

function M.Stop()
    if not M.running then
        return
    end

    dprint("stop")
    M.running = false
    M._skipWatcher = false

    if M.connection then
        M.connection:Disconnect()
        M.connection = nil
    end
end

function M.IsRunning()
    return M.running == true
end

function M.SetDebug(v)
    M.DEBUG = v == true
end

G.AntiAFK = M
G.antiafk = M
_G.AntiAFK = M
_G.antiafk = M

-- Langsung start watcher + AFK (skip tidak nunggu 5 detik)
task.defer(function()
    pcall(function()
        M.AutoSkipLoading("boot")
    end)
    task.wait(5)
    pcall(function()
        M.Start()
    end)
end)

return M

