    {
        key = "webhook",
        name = "webhook",
        factory = function()
            -- webhook.lua (NodeHub) - Direct Discord webhook (Market Sold/Buy/Result/PetBag/Disconnect)
-- Builds Discord embeds locally and POSTs to STATE.webhook.targetUrl (no PHP).

local Webhook = {}

--------------------------------------------------
-- SERVICES
--------------------------------------------------
local Players     = game:GetService("Players")
local HttpService = game:GetService("HttpService")
local RunService  = game:GetService("RunService")
local RS = game:GetService("ReplicatedStorage")

