local TokenRAPController = require(RS.Modules.TradeTokens.TokenRAPController)
local LP = Players.LocalPlayer

--------------------------------------------------
-- INTERNAL
--------------------------------------------------
local _STATE = nil
local _SaveState = nil

local AVATAR_URL = "https://golaspay.net/assets/sc_logo.jpg"
local WEBHOOK_USERNAME_FALLBACK = "NodeHub"

local _debug = true
local _queue = {}
local _worker = false

local MAX_RETRY  = 6
local BASE_DELAY = 0.45
local MAX_QUEUE  = 180

local _lastSend = {}
local DEDUPE_WIN = 0.8

local MONTHS = {
    "Jan","Feb","Mar","Apr","May","Jun",
    "Jul","Aug","Sep","Oct","Nov","Dec",
}

--------------------------------------------------
-- HELPERS
--------------------------------------------------
local function nowStr()
    local t = os.date("*t")
    return string.format("%02d:%02d:%02d", t.hour, t.min, t.sec)
end

local function DBG(...)
    if not _debug then return end
    print("[Webhook]["..nowStr().."]", ...)
end

local function WARN(...)
    if not _debug then return end
    warn("[Webhook]["..nowStr().."]", ...)
end

local function trim(s)
    s = tostring(s or "")
    return (s:match("^%s*(.-)%s*$"))
end

local function upperMode(m)
    m = trim(m):upper()
    if m ~= "SIMPLE" and m ~= "FULL" then m = "SIMPLE" end
    return m
end

local function getSTATE()
    local S = rawget(_G, "STATE")
    if type(S) == "table" then return S end
    return _STATE
end

local function getRequestFunc()
    return (syn and syn.request)
        or (http and http.request)
        or http_request
        or (fluxus and fluxus.request)
        or request
end

local function jsonEncode(t)
    local ok, s = pcall(HttpService.JSONEncode, HttpService, t)
    if ok and type(s) == "string" then return s end
    return "{}"
end

local function httpPost(url, body)
    local req = getRequestFunc()
    if not req then return false, "NO_REQUEST_FUNC" end

    local ok, res = pcall(function()
        return req({
            Url = url,
            Method = "POST",
            Headers = { ["Content-Type"] = "application/json" },
            Body = body,
        })
    end)
    if not ok then return false, tostring(res) end

    if type(res) == "table" then
        local code = tonumber(res.StatusCode or res.Status or 0) or 0
        if code >= 200 and code < 300 then return true, res end
        return false, "HTTP_" .. tostring(code)
    end
    return true, res
end

local function toNum(v, d)
    local n = tonumber(v)
    if n == nil then return d end
    return n
end

local function fmtInt(num)
    num = math.floor(tonumber(num) or 0)
    local neg = num < 0
    if neg then num = -num end
    local s = tostring(num)
    local out = s:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
    if neg then out = "-" .. out end
    return out
end

local function fmtFloat(num, dp)
    dp = dp or 2
    num = tonumber(num) or 0
    local fmt = "%." .. tostring(dp) .. "f"
    local s = string.format(fmt, num)
    local intPart, frac = s:match("^(-?%d+)%.(%d+)$")
    if not intPart then
        return fmtInt(num)
    end
    return fmtInt(tonumber(intPart)) .. "." .. frac
end

local function isoTimestamp(ts)
    ts = tonumber(ts) or os.time()
    return os.date("!%Y-%m-%dT%H:%M:%SZ", ts)
end

local function fmtTimeWib(ts, withSeconds)
    ts = tonumber(ts) or os.time()
    local t = os.date("!*t", ts + 7 * 3600)
    local mon = MONTHS[t.month] or tostring(t.month)
    local hour = t.hour % 12
    if hour == 0 then hour = 12 end
    local ampm = (t.hour >= 12) and "PM" or "AM"
    if withSeconds then
        return string.format(
            "%02d %s %04d | %02d:%02d:%02d WIB",
            t.day, mon, t.year, t.hour, t.min, t.sec
        )
    end
    return string.format(
        "%02d %s %04d | %02d:%02d %s",
        t.day, mon, t.year, hour, t.min, ampm
    )
end

local function prettyPetName(name)
    name = trim(name):gsub("%s+", " ")
    if name == "" then return "Unknown" end
    return name:gsub("[^%s%-%_]+", function(w)
        return w:sub(1, 1):upper() .. w:sub(2):lower()
    end)
end

local function calcBaseAge1(kg, age)
    kg = tonumber(kg)
    age = tonumber(age)
    if not kg or not age then return nil end
    local mult = 1 + (0.1 * age)
    if mult <= 0 then return nil end
    local baseAge0 = kg / mult
    local w100 = baseAge0 * 11
    return w100 / 10
end

local function mutsText(muts)
    if type(muts) ~= "table" then return "-" end
    local clean = {}
    for k, v in pairs(muts) do
        local m = (type(k) == "string" and not tonumber(k)) and k or v
        m = trim(m)
        if m ~= "" then
            clean[#clean + 1] = m
        end
    end
    if #clean == 0 then return "-" end
    if #clean > 8 then
        local slim = {}
        for i = 1, 8 do slim[i] = clean[i] end
        clean = slim
    end
    return table.concat(clean, ", ")
end

local function truncate(s, maxLen)
    s = tostring(s or "")
    if #s <= maxLen then return s end
    return s:sub(1, maxLen) .. "\n\n**Note**\n│ truncated : yes"
end

local function panelSection(title, rows)
    local out = { "**" .. tostring(title) .. "**" }
    for _, r in ipairs(rows or {}) do
        local label = trim(r.label or "")
        local value = r.value
        if label ~= "" then
            if type(value) == "table" then
                value = table.concat(value, "\n")
            else
                value = trim(value)
                if value == "" then value = "-" end
            end
            out[#out + 1] = "│ " .. label .. " : " .. value
        end
    end
    return table.concat(out, "\n")
end

local function panelBlock(sections)
    return table.concat(sections or {}, "\n\n")
end

local function isDiscordWebhookUrl(url)
    url = trim(url):lower()
    if url == "" then return false end
    return url:find("discord.com/api/webhooks", 1, true) ~= nil
        or url:find("discordapp.com/api/webhooks", 1, true) ~= nil
end

--------------------------------------------------
-- STATE READERS
--------------------------------------------------
local function getWB()
    local S = getSTATE()
    if type(S) == "table" and type(S.webhook) == "table" then
        return S.webhook
    end
    return nil
end

local function isSoldBuyEnabled()
    local wb = getWB()
    if wb and wb.enabled ~= nil then return wb.enabled == true end
    if _STATE and _STATE.webhookOn ~= nil then return _STATE.webhookOn == true end
    if _STATE and _STATE.setting and _STATE.setting.webhookOn ~= nil then
        return _STATE.setting.webhookOn == true
    end
    return false
end

local function isResultEnabled()
    local wb = getWB()
    if wb and wb.resultEnabled ~= nil then
        return wb.resultEnabled == true
    end
    return true
end

local function isPetInventoryEnabled()
    local wb = getWB()
    if wb and wb.petInventoryEnabled == false then
        return false
    end
    return true
end

local function isEventEnabled(eventName)
    eventName = tostring(eventName or "")
    if eventName == "MARKET_RESULT" then
        return isResultEnabled()
    end
    if eventName == "MARKET_PET_BAG" then
        return isPetInventoryEnabled()
    end
    if eventName == "MARKET_SOLD" or eventName == "MARKET_BUY" then
        return isSoldBuyEnabled()
    end
    if eventName == "DISCONNECT" then
        return isSoldBuyEnabled()
    end
    return isSoldBuyEnabled()
end

local function getMode()
