    if wb and type(wb.mode) == "string" and wb.mode ~= "" then
        return upperMode(wb.mode)
    end
    if _STATE and type(_STATE.webhookMode) == "string" then
        return upperMode(_STATE.webhookMode)
    end
    return "SIMPLE"
end

local function getTargetWebhook()
    local wb = getWB()
    local url = wb and wb.targetUrl
    if type(url) == "string" and trim(url) ~= "" then return trim(url) end
    url = _STATE and _STATE.webhookUrl
    if type(url) == "string" and trim(url) ~= "" then return trim(url) end
    return nil
end

local function getShareToDC()
    local wb = getWB()
    if wb and wb.shareToDCChannel ~= nil then
        return wb.shareToDCChannel == true
    end
