end

local function getOrCreateAlias()
    if not _STATE then return nil end

    local wb = getWB()
    if wb and type(wb.dcAlias) == "string" and trim(wb.dcAlias) ~= "" then
        wb.dcAlias = trim(wb.dcAlias)
        return wb.dcAlias
    end

    if type(_STATE.dcAlias) == "string" and trim(_STATE.dcAlias) ~= "" then
        _STATE.dcAlias = trim(_STATE.dcAlias)
        if wb then wb.dcAlias = _STATE.dcAlias end
        return _STATE.dcAlias
    end

    local adjectives = { "Hidden","Silent","Lucky","Ghost","Shadow","Golden","Rapid","Quiet" }
    local animals    = { "Fox","Dog","Cat","Llama","Panda","Wolf","Owl","Tiger" }
    math.randomseed((os.clock() * 1000000) % 2147483647)

    local alias = string.format(
        "%s%s#%d",
        adjectives[math.random(1,#adjectives)],
        animals[math.random(1,#animals)],
        math.random(100,999)
    )

    _STATE.dcAlias = alias
    if wb then wb.dcAlias = alias end
    if type(_SaveState) == "function" then pcall(_SaveState) end

    return alias
end

local function getAliasIfAny()
    if not _STATE then return nil end
    local wb = getWB()

    if wb and type(wb.dcAlias) == "string" and trim(wb.dcAlias) ~= "" then
        return trim(wb.dcAlias)
    end

    if type(_STATE.dcAlias) == "string" and trim(_STATE.dcAlias) ~= "" then
        return trim(_STATE.dcAlias)
    end

    return nil
end

local function envInfo()
    local ping = nil
    pcall(function()
        local Stats = game:GetService("Stats")
        local net = Stats:FindFirstChild("Network")
        local ssi = net and net:FindFirstChild("ServerStatsItem")
        local dp = ssi and ssi:FindFirstChild("Data Ping")
        if dp and dp.GetValue then ping = tonumber(dp:GetValue()) end
    end)

    return {
        placeId  = game.PlaceId,
        jobId    = game.JobId,
        pingMs   = ping,
        isStudio = RunService:IsStudio(),
    }
end

local function getFirstMutation(item)
    if type(item) ~= "table" then return "Normal" end
    if type(item.muts) == "table" and item.muts[1] then
        return tostring(item.muts[1])
    end
    if item.mutation then
        return tostring(item.mutation)
    end
    return "Normal"
end

local function normalizeMutation(mut)
    mut = tostring(mut or "Normal")
    if mut == "" or mut == "None" or mut == "Normal" then
        return "Normal"
    end
    return mut
end

local function addBuyPetRAP(data)
    if type(data) ~= "table" then return data end
    if type(data.item) ~= "table" then return data end
    if data.item.rap ~= nil then return data end

    local item = data.item
    local petType = item.name or item.petType or item.PetType
    if not petType or tostring(petType) == "" then
        return data
    end

    local level = tonumber(item.age or item.level) or 1
    local mut = normalizeMutation(getFirstMutation(item))

    local rapItem = {
        PetType = tostring(petType),
        PetData = {
            MutationType = mut,
            Level = math.floor(level),
        }
    }

    local rap
    pcall(function()
        rap = TokenRAPController:GetRAPAsync("Pet", rapItem)
    end)
    rap = tonumber(rap)

    if rap then
        item.rap = rap
        local price = tonumber(data.price)
        if price then
            item.profit = rap - price
            item.pricePercentOfRap = (price / rap) * 100
        end
    end

    return data
end

--------------------------------------------------
-- DISCORD EMBED BUILDERS (ported from wmarket/wdisconected)
--------------------------------------------------
local function resolveBrandName(embed, override)
    override = trim(override)
    if override ~= "" then return override end
    local title = trim(embed and embed.title)
    if title ~= "" then return title end
    local author = embed and embed.author and trim(embed.author.name)
    if author and author ~= "" then return author end
    return WEBHOOK_USERNAME_FALLBACK
end

local function applyEmbedBranding(embed, authorName)
    local brand = resolveBrandName(embed, authorName)
    embed.author = {
        name = brand,
        icon_url = AVATAR_URL,
    }
    if trim(embed.title or ""):lower() == brand:lower() then
        embed.title = nil
    end
    return embed, brand
end

local function discordPayload(embed, username, content)
    local branded, brand = applyEmbedBranding(embed, username)
    return {
        content = content or "",
        username = brand,
        avatar_url = AVATAR_URL,
        embeds = { branded },
        allowed_mentions = {
            parse = (content == "@everyone") and { "everyone" } or {},
        },
    }
end

local function fmtKgRange(minKg, maxKg)
    minKg = tonumber(minKg) or 0
    maxKg = tonumber(maxKg) or minKg
    if minKg <= 0 and maxKg <= 0 then return "?" end
    if math.abs(maxKg - minKg) < 0.05 then
        return fmtFloat(minKg, 1) .. "kg"
    end
    return fmtFloat(minKg, 1) .. "-" .. fmtFloat(maxKg, 1) .. "kg"
end

local function fmtAgeRange(minAge, maxAge)
    minAge = math.floor(tonumber(minAge) or 0)
    maxAge = math.floor(tonumber(maxAge) or minAge)
    if minAge <= 0 and maxAge <= 0 then return "Age ?" end
    if minAge == maxAge then return "Age " .. fmtInt(minAge) end
    return "Age " .. fmtInt(minAge) .. "-" .. fmtInt(maxAge)
end

local function kgBucketLabel(bucket)
    local n = tonumber(bucket)
    if not n then return tostring(bucket or "NA") end
    n = math.floor(n)
    return n .. "-" .. (n + 1) .. " KG"
end

local function ageBandLabelEn(band)
    band = trim(band):upper()
    if band == "GE100" then return "Age 100+" end
    if band == "LT100" then return "Age <100" end
    if band == "" then return "Age ?" end
    return band
end

local function formatPeriodRuntime(startTs, endTs)
    endTs = tonumber(endTs) or os.time()
    startTs = tonumber(startTs) or 0
    if startTs <= 0 then return "0s" end
    local sec = math.max(0, endTs - startTs)
    if sec < 60 then return sec .. "s" end
    local min = math.floor(sec / 60)
    local rem = sec % 60
    if min < 60 then
        return rem > 0 and (min .. "m " .. rem .. "s") or (min .. "m")
    end
    local hr = math.floor(min / 60)
    local minRem = min % 60
    if minRem > 0 then return hr .. "h " .. minRem .. "m" end
    return hr .. "h"
end

local function buildWalletLines(data)
    local wallet = type(data.wallet) == "table" and data.wallet or nil
    if not wallet then return {} end

    local tokenStart = toNum(wallet.tokenStart, nil)
    local tokenNow = toNum(wallet.tokenNow, nil)
    local trackedIn = math.floor(toNum(wallet.trackedIn, 0))
    local trackedOut = math.floor(toNum(wallet.trackedOut, 0))
    local trackedNet = math.floor(toNum(wallet.trackedNet, trackedIn - trackedOut))
    local walletDelta = toNum(wallet.walletDelta, nil)
    local match = wallet.balanceMatch

    local lines = { "", "💳 **Token**" }
    if tokenStart ~= nil then
        lines[#lines + 1] = "Start: **" .. fmtInt(math.floor(tokenStart + 0.5)) .. "**"
    else
        lines[#lines + 1] = "Start: _unknown_"
    end
    if tokenNow ~= nil then
        lines[#lines + 1] = "Now: **" .. fmtInt(math.floor(tokenNow + 0.5)) .. "**"
    else
        lines[#lines + 1] = "Now: _unreadable_"
    end
    if walletDelta ~= nil then
        local sign = walletDelta >= 0 and "+" or ""
        lines[#lines + 1] = "Token Δ: **" .. sign .. fmtInt(math.floor(walletDelta + 0.5)) .. "**"
    end
    local netSign = trackedNet >= 0 and "+" or ""
    lines[#lines + 1] = "Flow: In **" .. fmtInt(trackedIn)
        .. "** · Out **" .. fmtInt(trackedOut)
        .. "** · Net **" .. netSign .. fmtInt(trackedNet) .. "**"
    if match == true then
        lines[#lines + 1] = "✅ Token total matches flow"
    elseif match == false and walletDelta ~= nil then
        lines[#lines + 1] = "⚠️ Token Δ differs from flow net"
    end
    return lines
end

local function formatMobileStackBuckets(rows, maxLines, emptyText)
    if type(rows) ~= "table" or #rows == 0 then
        return emptyText or "_(none)_"
    end
    local lines = {}
    local n = 0
    for _, row in ipairs(rows) do
        if type(row) == "table" then
            n = n + 1
            if n > maxLines then
                lines[#lines + 1] = "_+" .. tostring(#rows - maxLines) .. " more_"
                break
            end
            local pet = prettyPetName(row.petType or "?")
            local kg = kgBucketLabel(row.kgBucket)
            local band = ageBandLabelEn(row.ageBand or "")
            local cnt = math.floor(toNum(row.count, 0))
            local tok = math.floor(toNum(row.tokens, 0))
            lines[#lines + 1] = "• **" .. pet .. "**"
            lines[#lines + 1] = "  " .. fmtInt(tok) .. " tokens · " .. kg
                .. " · " .. band .. " · " .. fmtInt(cnt) .. "×"
        end
    end
    return table.concat(lines, "\n")
end

local function buildMarketPetBagEmbed(data, playerName, tsUnix)
    local username = trim(data.username or playerName)
    if username == "" then username = playerName end
    local totalPets = math.floor(toNum(data.totalPets, 0))
    local groups = type(data.groups) == "table" and data.groups or {}

    local lines = {
        "📌 **Market — Pet Inventory**",
        "🐾 Total : " .. fmtInt(totalPets),
        "👤 " .. username,
        "",
    }

    if #groups == 0 then
        lines[#lines + 1] = "(no pets in datastore)"
    else
        local shown = 0
        for _, g in ipairs(groups) do
            if type(g) == "table" then
                shown = shown + 1
                if shown > 40 then
                    lines[#lines + 1] = "... +" .. tostring(#groups - 40) .. " more types"
                    break
                end
                local petType = prettyPetName(g.petType or "Unknown")
                local typeTotal = math.floor(toNum(g.total, 0))
                lines[#lines + 1] = petType .. " - Total " .. fmtInt(typeTotal)

                local subLines = type(g.lines) == "table" and g.lines or {}
                local subCount = 0
                for _, ln in ipairs(subLines) do
                    if type(ln) == "table" then
                        subCount = subCount + 1
                        if subCount > 8 then
                            lines[#lines + 1] = "└ ... +" .. tostring(#subLines - 8) .. " more"
                            break
                        end
                        local kgTxt = fmtKgRange(ln.minKg, ln.maxKg)
                        local ageTxt = fmtAgeRange(ln.minAge, ln.maxAge)
                        local cnt = math.floor(toNum(ln.count, 0))
                        lines[#lines + 1] = "└ KG " .. kgTxt .. " • " .. ageTxt
                            .. " (" .. fmtInt(cnt) .. ")"
                    end
                end
                lines[#lines + 1] = ""
            end
        end
    end

    local desc = truncate(table.concat(lines, "\n"), 3900)
    return {
        title = "NodeHub — Pet Inventory",
        description = desc,
        color = 0x3B82F6,
        footer = { text = "NodeHub Market" },
        timestamp = isoTimestamp(tsUnix),
    }
end

local function buildMarketResultEmbed(data, playerName, tsUnix)
    local periodStart = math.floor(toNum(data.periodStart, 0))
    local periodEnd = math.floor(toNum(data.periodEnd, tsUnix))
    local username = trim(data.username or playerName)
    if username == "" then username = playerName end

    local totals = type(data.totals) == "table" and data.totals or {}
    local sellTokens = math.floor(toNum(totals.sellTokens, 0))
    local buyTokens = math.floor(toNum(totals.buyTokens, 0))
    local netTokens = math.floor(toNum(totals.netTokens, sellTokens - buyTokens))
    local sellCount = math.floor(toNum(totals.sellCount, 0))
    local buyCount = math.floor(toNum(totals.buyCount, 0))

    local topBuckets = type(data.topBuckets) == "table" and data.topBuckets or {}
    if #topBuckets == 0 and type(data.buckets) == "table" then
        topBuckets = {}
        for _, row in ipairs(data.buckets) do
            topBuckets[#topBuckets + 1] = row
        end
        table.sort(topBuckets, function(a, b)
            local ta = math.floor(toNum(a and a.tokens, 0))
            local tb = math.floor(toNum(b and b.tokens, 0))
            if ta ~= tb then return ta > tb end
            return math.floor(toNum(a and a.count, 0)) > math.floor(toNum(b and b.count, 0))
        end)
        if #topBuckets > 25 then
            local slim = {}
            for i = 1, 25 do slim[i] = topBuckets[i] end
            topBuckets = slim
        end
    end

    local sellRows, buyRows = {}, {}
    for _, row in ipairs(topBuckets) do
        if type(row) == "table" then
            if trim(row.side or ""):upper() == "BUY" then
                buyRows[#buyRows + 1] = row
            else
                sellRows[#sellRows + 1] = row
            end
        end
    end

    local color = 0x94A3B8
    if netTokens > 0 then color = 0x22C55E
    elseif netTokens < 0 then color = 0xEF4444 end

    local netSign = netTokens >= 0 and "+" or ""
    local parts = {
        "👤 **" .. username .. "**",
        "⏱ **Runtime:** " .. formatPeriodRuntime(periodStart, periodEnd),
    }
    for _, line in ipairs(buildWalletLines(data)) do
        parts[#parts + 1] = line
    end

    parts[#parts + 1] = ""
    parts[#parts + 1] = "💰 **Token In (Sold)**"
    parts[#parts + 1] = "**" .. fmtInt(sellTokens) .. " tokens · " .. fmtInt(sellCount) .. "×**"
    parts[#parts + 1] = ""
    parts[#parts + 1] = "💸 **Token Out (Buy)**"
    parts[#parts + 1] = "**" .. fmtInt(buyTokens) .. " tokens · " .. fmtInt(buyCount) .. "×**"
    parts[#parts + 1] = ""
    parts[#parts + 1] = "📊 **Flow Net:** **" .. netSign .. fmtInt(netTokens) .. " tokens**"
    parts[#parts + 1] = ""
    parts[#parts + 1] = "💸 **Token Out**"
    for line in string.gmatch(formatMobileStackBuckets(buyRows, 8, "_(none)_") .. "\n", "([^\n]*)\n") do
        parts[#parts + 1] = line
    end
    parts[#parts + 1] = ""
    parts[#parts + 1] = "💰 **Token In**"
    for line in string.gmatch(formatMobileStackBuckets(sellRows, 8, "_(none)_") .. "\n", "([^\n]*)\n") do
        parts[#parts + 1] = line
    end

    local description = truncate(table.concat(parts, "\n"), 3900)
    return {
        title = "Token Market Summary",
        description = description,
        color = color,
        footer = { text = "NodeHub Market" },
        timestamp = isoTimestamp(periodEnd > 0 and periodEnd or tsUnix),
    }
end

local function buildSoldBuyEmbed(eventName, data, playerName, tsUnix)
    local dataTitle = trim(data.title or "")
    local isBuy = (dataTitle:lower() == "buy") or (eventName == "MARKET_BUY")

    local price = math.floor(toNum(data.price, 0))
    local finishTime = math.floor(toNum(data.finishTime, tsUnix))

    local buyerU = type(data.buyer) == "table" and data.buyer or {}
    local sellerU = type(data.seller) == "table" and data.seller or {}
    local buyer = trim(buyerU.username or "?")
    if buyer == "" then buyer = "?" end
    local seller = trim(sellerU.username or playerName)
    if seller == "" then seller = playerName end

    local item = type(data.item) == "table" and data.item or {}
    local itemName = trim(item.name or item.nameRaw or "Unknown")
    if itemName == "" then itemName = "Unknown" end

    local kg = toNum(item.kg, nil)
    local age = toNum(item.age, nil)
    local muts = item.muts
    local kgCurrent = toNum(item.kgCurrent or item.kg, nil)
    local kgBase = toNum(item.kgBase or item.baseKg, nil)
    local snipeKgMode = trim(item.snipeKgMode or "")

    local kgDisplay, baseKgDisplay, kgText = "-", "-", "-"
    if isBuy then
        local kgNow = kgCurrent or kg
        if kgNow ~= nil then kgDisplay = fmtFloat(kgNow, 2) end
        if kgBase ~= nil then baseKgDisplay = fmtFloat(kgBase, 2) end
    elseif kg ~= nil and kgBase ~= nil then
        kgText = fmtFloat(kg, 2) .. " current / " .. fmtFloat(kgBase, 2) .. " base (age1)"
    elseif kg ~= nil then
        kgText = fmtFloat(kg, 2) .. " KG"
    end

    local ageText = (age ~= nil) and ("Age " .. fmtInt(age)) or "-"
    local mutText = mutsText(muts)
    local timeText = fmtTimeWib(finishTime > 0 and finishTime or tsUnix, false)
    local priceText = fmtInt(price)

    local listTotal = nil
    if type(data.listing) == "table" then
        listTotal = toNum(data.listing.totalListed, nil)
    end
    if listTotal == nil then
        listTotal = toNum(data.totalListed, nil)
    end
    local listingsTxt = (listTotal ~= nil) and fmtInt(listTotal) or "-"

    local token = trim(data.token or "")
    local tokenTxt = (token ~= "") and token or "-"

    local sections = {}
    sections[#sections + 1] = panelSection("Profile", {
        { label = "Username", value = playerName },
        { label = "Token", value = tokenTxt },
        { label = "Listings", value = listingsTxt },
    })

    if isBuy then
        sections[#sections + 1] = panelSection("Pet Details", {
            { label = "Item Name", value = itemName },
            { label = "KG", value = kgDisplay },
            { label = "Base Kg", value = baseKgDisplay },
            { label = "Age", value = ageText },
            { label = "Mutations", value = mutText },
        })
        sections[#sections + 1] = panelSection("Buy Details", {
            { label = "Buyer", value = buyer },
            { label = "Seller", value = seller },
            { label = "Price", value = priceText },
            { label = "Time", value = timeText },
        })
    else
        sections[#sections + 1] = panelSection("Pet Details", {
            { label = "Item Name", value = itemName },
            { label = "KG", value = kgText },
            { label = "Age", value = ageText },
            { label = "Mutations", value = mutText },
        })
        sections[#sections + 1] = panelSection("Sold Details", {
            { label = "Seller", value = seller },
            { label = "Buyer", value = buyer },
            { label = "Price", value = priceText },
            { label = "Time", value = timeText },
        })
    end

    local title
    if isBuy then
        if snipeKgMode == "base_age1" then
            title = "NodeHub — Market Buy (base rule)"
        elseif snipeKgMode == "current" then
            title = "NodeHub — Market Buy (current rule)"
        elseif snipeKgMode == "skin" then
            title = "NodeHub — Market Buy (skin)"
        else
            title = "NodeHub — Market Buy"
        end
    else
        title = "NodeHub — Market Sold"
    end

    return {
        title = title,
        description = truncate(panelBlock(sections), 3800),
        color = 0xFACC15,
        footer = { text = "NodeHub Market" },
        timestamp = isoTimestamp(finishTime > 0 and finishTime or tsUnix),
    }
end

local function pickReasonLines(envelope, data)
    local extra = type(envelope.extra) == "table" and envelope.extra
        or (type(data.extra) == "table" and data.extra or {})

    local cands = {
        trim(data.reason or ""),
        trim(envelope.reason or ""),
        trim(data.reasonFull or ""),
        trim(data.reasonAll or ""),
        trim(data.message or ""),
        trim(data.text or ""),
    }

    local src = trim(extra.source or "")
    local node = trim(extra.node or "")
    if src ~= "" or node ~= "" then
        cands[#cands + 1] = "(" .. (src ~= "" and src or "prompt")
            .. (node ~= "" and (" / " .. node) or "") .. ")"
    end

    local lines, seen = {}, {}
    for _, c in ipairs(cands) do
        if c ~= "" then
            for ln in string.gmatch(c:gsub("\r\n", "\n"):gsub("\r", "\n") .. "\n", "([^\n]*)\n") do
                ln = trim(ln)
                if ln ~= "" then
                    local key = ln:lower()
                    if not seen[key] then
                        seen[key] = true
                        lines[#lines + 1] = ln
                        if #lines >= 8 then
                            return lines
                        end
                    end
                end
            end
        end
    end
    if #lines == 0 then lines[1] = "Disconnected" end
    return lines
end

local function buildDisconnectEmbed(envelope, data, playerName, tsUnix, pingEveryone)
    local timeText = fmtTimeWib(tsUnix, true)
    local token = trim(data.token or envelope.token or "")
    local tokenTxt = (token ~= "") and token or "-"
    local reasonLines = pickReasonLines(envelope, data)
    local showEnv = (data.showEnv == true)

    local sections = {}
    sections[#sections + 1] = panelSection("Profile", {
        { label = "Username", value = playerName },
        { label = "Token", value = tokenTxt },
        { label = "Time", value = timeText },
    })
    sections[#sections + 1] = panelSection("Reason", {
        { label = "Detail", value = reasonLines },
    })

    if showEnv then
        local e = type(envelope.env) == "table" and envelope.env or {}
        local ping = e.pingMs
        local pingTxt = (tonumber(ping) ~= nil) and (tostring(math.floor(ping)) .. " ms") or "-"
        sections[#sections + 1] = panelSection("Env", {
            { label = "Ping", value = pingTxt },
            { label = "Place", value = trim(e.placeId or "-") },
            { label = "Job", value = trim(e.jobId or "-") },
        })
    end

    local embed = {
        title = "NodeHub — Disconnect",
        description = panelBlock(sections),
        color = 0xEF4444,
        footer = { text = "NodeHub" },
        timestamp = isoTimestamp(tsUnix),
    }
    return embed, pingEveryone and "@everyone" or ""
end

local function buildDiscordBody(eventName, data, playerName, tsUnix, opts, envelope)
    opts = opts or {}
    eventName = tostring(eventName or "")
    data = type(data) == "table" and data or {}
    tsUnix = tonumber(tsUnix) or os.time()

    if eventName == "MARKET_RESULT"
        or trim(data.title or ""):lower() == "market result" then
        return discordPayload(buildMarketResultEmbed(data, playerName, tsUnix))
    end

    if eventName == "MARKET_PET_BAG"
        or trim(data.title or ""):lower() == "pet inventory" then
        return discordPayload(buildMarketPetBagEmbed(data, playerName, tsUnix))
    end

    if eventName == "DISCONNECT" then
        local embed, content = buildDisconnectEmbed(
            envelope or {},
            data,
            playerName,
            tsUnix,
            opts.pingEveryone == true
        )
        return discordPayload(embed, nil, content)
    end

    return discordPayload(buildSoldBuyEmbed(eventName, data, playerName, tsUnix))
end

--------------------------------------------------
-- DEDUPE / QUEUE
--------------------------------------------------
local function dedupeSig(eventName, data)
    local s = tostring(eventName or "UNKNOWN")
    if type(data) == "table" then
        if data.id then s = s .. "|id:" .. tostring(data.id) end
        if data.item and data.item.uuid then s = s .. "|u:" .. tostring(data.item.uuid) end
        if data.price then s = s .. "|p:" .. tostring(data.price) end
        if data.reason then s = s .. "|r:" .. tostring(data.reason) end
    end
    return s
end

local function enqueue(item)
    if #_queue >= MAX_QUEUE then
        table.remove(_queue, 1)
    end
    table.insert(_queue, item)
end

local function startWorker()
    if _worker then return end
    _worker = true

    task.spawn(function()
        while #_queue > 0 do
            local item = table.remove(_queue, 1)
            if not item then break end

            local ok, err = httpPost(item.url, item.body)
            if ok then
                DBG("sent:", item.event)
            else
                item.tries = (item.tries or 0) + 1
                WARN("http fail:", item.event, "tries", item.tries, "err", err)

                if item.tries <= (item.maxRetry or MAX_RETRY) then
                    local backoff = (item.baseDelay or BASE_DELAY) * (2 ^ (item.tries - 1))
                    if backoff > 6 then backoff = 6 end
                    task.wait(backoff)
                    enqueue(item)
                end
            end

            task.wait(0.05)
        end
        _worker = false
    end)
end

