-- API
--------------------------------------------------
function Webhook.Init(opts)
    opts = opts or {}
    _STATE = (type(opts.STATE) == "table") and opts.STATE or rawget(_G, "STATE") or {}
    _SaveState = opts.SaveState

    if opts.debug ~= nil then
        _debug = (opts.debug == true)
    elseif rawget(_G, "WEBHOOK_DEBUG") ~= nil then
        _debug = (_G.WEBHOOK_DEBUG == true)
    end

    local GG = (getgenv and getgenv()) or _G
    GG.Webhook = Webhook
    _G.Webhook = Webhook

    WARN("Init debug=", _debug, "mode=direct_discord")
    return Webhook
end

function Webhook.SetDebug(on)
    _debug = (on == true)
    WARN("DEBUG =", _debug)
end

function Webhook.Send(eventName, data, opts)
    opts = opts or {}
    eventName = tostring(eventName or "UNKNOWN")
    data = (type(data) == "table") and data or {}

    if eventName == "MARKET_BUY" or data.title == "Buy" then
        data = addBuyPetRAP(data)
    end

    if not isEventEnabled(eventName) then
        return false, "DISABLED"
    end

    local target = getTargetWebhook()
    if not target then
        return false, "NO_TARGET_WEBHOOK"
    end
    if not isDiscordWebhookUrl(target) then
        return false, "TARGET_NOT_DISCORD_WEBHOOK"
    end

    local sig = opts.dedupeKey or dedupeSig(eventName, data)
    local t = os.clock()
    if _lastSend[sig] and (t - _lastSend[sig]) < (opts.dedupeWindow or DEDUPE_WIN) then
        return false, "DEDUPED"
    end
    _lastSend[sig] = t

    local shareWanted  = (getShareToDC() == true)
    local shareToDC    = (shareWanted and opts.shareToDC == true) or false
    local pingEveryone = (opts.pingEveryone == true) or false

    local alias
    if shareToDC == true then
        alias = getOrCreateAlias()
    else
        alias = getAliasIfAny()
    end

    local playerName = (alias and alias ~= "") and alias or (LP and LP.Name or "Unknown")
    local tsUnix = os.time()

    local discordBody = buildDiscordBody(eventName, data, playerName, tsUnix, {
        pingEveryone = pingEveryone,
        mode = upperMode(opts.mode or getMode()),
    }, {
        event = eventName,
        reason = data.reason,
        extra = data.extra,
        env = envInfo(),
        token = data.token,
    })

    enqueue({
        event     = eventName,
        url       = target,
        body      = jsonEncode(discordBody),
        tries     = 0,
        maxRetry  = opts.maxRetry or MAX_RETRY,
        baseDelay = opts.baseDelay or BASE_DELAY,
    })

    startWorker()
    return true, "QUEUED"
end

function Webhook.SendMarketSold(soldPayload, opts)
    soldPayload = (type(soldPayload) == "table") and soldPayload or {}
    opts = opts or {}
    if soldPayload.id and not opts.dedupeKey then
        opts.dedupeKey = "MARKET_SOLD|id:" .. tostring(soldPayload.id)
        opts.dedupeWindow = opts.dedupeWindow or 30
    end
    return Webhook.Send("MARKET_SOLD", soldPayload, opts)
end

function Webhook.SendMarketResult(summary, opts)
    summary = (type(summary) == "table") and summary or {}
    opts = opts or {}
    if not opts.dedupeKey then
        opts.dedupeKey = "MARKET_RESULT|manual|" .. tostring(os.time())
        opts.dedupeWindow = opts.dedupeWindow or 10
    end
    return Webhook.Send("MARKET_RESULT", summary, opts)
end

function Webhook.ResetResultNow()
    local MR = rawget(_G, "MarketResult")
    if type(MR) == "table" and type(MR.ResetResultNow) == "function" then
        return MR.ResetResultNow()
    end
    if type(MR) == "table" and type(MR.Reset) == "function" then
        return MR.Reset(true)
    end
    return false
end

function Webhook.ResetResult()
    return Webhook.ResetResultNow()
end

