            -- auto_hop.lua (NodeHub Market)
-- ✅ Auto hop server when:
--    1) No sales for X minutes
--    2) Current players < minPlayerNow
--    3) Manual trigger _G.__MARKET_HOP_NOW == true
--
-- ✅ Target: hop to servers with players close to targetPlayer
-- ✅ Uses Roblox public servers API + TeleportService:TeleportToPlaceInstance

local M = {}

----------------------------------------------------------------
-- Services
----------------------------------------------------------------
local Players         = game:GetService("Players")
local TeleportService = game:GetService("TeleportService")
local HttpService     = game:GetService("HttpService")
local RunService      = game:GetService("RunService")

local LP = Players.LocalPlayer

----------------------------------------------------------------
-- Internal state
----------------------------------------------------------------
local _running = false
local _thread = nil

local _lastSoldAt = os.clock()       -- updated by NotifySold()
local _lastHopAt  = 0
local _cooldownHopSec = 25           -- anti-spam hop

-- hop attempt state
local _hopAttemptId = 0
local _hopInFlight = false
local _hopFromJobId = ""
local _hopTargetJobId = ""

-- avoid jobId yang gagal (TTL)
local _avoidUntil = {}  -- [jobId]=untilClock

-- cache kandidat hop (max 15) — 1x fetch API, retry pakai list tanpa spam API
local CANDIDATE_MAX     = 15
local CANDIDATE_TTL_SEC = 180
local SCAN_MAX_PAGES    = 5
local _candidateCache = {
    placeId = nil,
    targetPlayers = nil,
    builtAt = 0,
    list = {},
    index = 1,
}

-- limiter retry cepat biar gak infinite spam
local _burstWindowStart = 0
local _burstFailCount = 0
local BURST_WINDOW_SEC = 30
local BURST_MAX_FAILS = 10
local BURST_BACKOFF_SEC = 10

local _debug = false

local function dprint(...)
    if not _debug then return end
    warn("[auto_hop]", ...)
end

local function now()
    return os.clock()
end

----------------------------------------------------------------
-- Read config from STATE
----------------------------------------------------------------
local function getHopCfg()
    local STATE = rawget(_G, "STATE")
    local MK = STATE and STATE.main and STATE.main.auto_market
    local H = MK and MK.hop
    if type(H) ~= "table" then return nil end

    local cfg = {
        enabled       = (H.autohoop == true),
        waktuMin      = tonumber(H.waktu) or 15,
        minPlayerNow  = tonumber(H.minPlayerNow) or 0, -- 0 = ignore
        targetPlayer  = tonumber(H.targetPlayer) or 20,
    }

    if cfg.waktuMin < 1 then cfg.waktuMin = 1 end
    if cfg.targetPlayer < 1 then cfg.targetPlayer = 1 end
    if cfg.minPlayerNow < 0 then cfg.minPlayerNow = 0 end

    return cfg
end

local function getPlayerCount()
    local ok, n = pcall(function()
        return #Players:GetPlayers()
    end)
    return ok and n or 0
end

local function _isAvoided(jobId)
    jobId = tostring(jobId or "")
    if jobId == "" then return false end
    local untilT = _avoidUntil[jobId]
    if not untilT then return false end
    if os.clock() >= untilT then
        _avoidUntil[jobId] = nil
        return false
    end
    return true
end

local function _markAvoid(jobId, ttlSec)
    jobId = tostring(jobId or "")
    if jobId == "" then return end
    ttlSec = tonumber(ttlSec) or 120
    _avoidUntil[jobId] = os.clock() + ttlSec
end

local function _burstFail()
    local t = os.clock()
    if (t - _burstWindowStart) > BURST_WINDOW_SEC then
        _burstWindowStart = t
        _burstFailCount = 0
    end
    _burstFailCount += 1
    if _burstFailCount >= BURST_MAX_FAILS then
        dprint("BURST backoff", BURST_BACKOFF_SEC, "sec")
        task.wait(BURST_BACKOFF_SEC)
        _burstWindowStart = os.clock()
        _burstFailCount = 0
    end
end

----------------------------------------------------------------
-- Roblox server list API
----------------------------------------------------------------
local function httpGet(url)
    local req =
        (syn and syn.request) or
        (http and http.request) or
        http_request or
        request or
        (fluxus and fluxus.request)

    if type(req) == "function" then
        local res = req({ Url = url, Method = "GET" })
        local body = res and (res.Body or res.body)
        if type(body) == "string" and body ~= "" then
            return true, body
        end
        return false, "request failed"
    end

    local ok, body = pcall(function()
        return game:HttpGet(url)
    end)
    if not ok then
        return false, body
    end
    return true, body
end

local function fetchServers(placeId, cursor)
    local url =
        ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Desc&limit=100"):format(placeId)

    if cursor and cursor ~= "" then
        url = url .. "&cursor=" .. HttpService:UrlEncode(cursor)
    end

    local ok, body = httpGet(url)
    if not ok then
        return nil, nil, ("http_failed: " .. tostring(body))
    end

    local decoded
    local ok2 = pcall(function()
        decoded = HttpService:JSONDecode(body)
    end)
    if not ok2 or type(decoded) ~= "table" then
        return nil, nil, "json_decode_failed"
    end

    local data = decoded.data
    local nextCursor = decoded.nextPageCursor
    if type(data) ~= "table" then data = {} end

    return data, nextCursor, nil
end

local function scoreServer(playing, targetPlayers)
    playing = tonumber(playing) or 0
    targetPlayers = tonumber(targetPlayers) or 20
    local diff = math.abs(playing - targetPlayers)
    -- Di bawah target tetap OK — penalty kecil saja
    if playing < targetPlayers then
        return diff + 0.25
    end
    return diff
end

local function serverEligible(id, playing, maxPlayers, avoidJobId)
    id = tostring(id or "")
    avoidJobId = tostring(avoidJobId or "")
    if id == "" or id == avoidJobId then return false end
    if _isAvoided(id) then return false end
    playing = tonumber(playing) or 0
    maxPlayers = tonumber(maxPlayers) or 0
    if maxPlayers ~= 0 and playing >= maxPlayers then return false end
    return true
end

-- Isi list: server rendah / jauh dari target tetap masuk (GameFull nanti di-blacklist)
local function serverEligibleRelaxed(id, playing, maxPlayers, avoidJobId)
    id = tostring(id or "")
    avoidJobId = tostring(avoidJobId or "")
    if id == "" or id == avoidJobId then return false end
    if _isAvoided(id) then return false end
    return true
end

local function addCandidate(all, seen, id, playing, maxPlayers, targetPlayers)
    id = tostring(id or "")
    if id == "" or seen[id] then return end
    seen[id] = true
    all[#all + 1] = {
        id = id,
        playing = tonumber(playing) or 0,
        maxPlayers = tonumber(maxPlayers) or 0,
        score = scoreServer(playing, targetPlayers),
    }
end

local function clearCandidateCache()
    _candidateCache.list = {}
    _candidateCache.index = 1
    _candidateCache.builtAt = 0
    _candidateCache.placeId = nil
    _candidateCache.targetPlayers = nil
end

local function candidateCacheStale(placeId, targetPlayers)
    if #_candidateCache.list == 0 then return true end
    if _candidateCache.placeId ~= placeId then return true end
    if _candidateCache.targetPlayers ~= targetPlayers then return true end
    if (now() - (_candidateCache.builtAt or 0)) > CANDIDATE_TTL_SEC then return true end
    if _candidateCache.index > #_candidateCache.list then return true end
    return false
end

local function buildCandidateList(placeId, targetPlayers, avoidJobId)
    targetPlayers = tonumber(targetPlayers) or 20
    avoidJobId = tostring(avoidJobId or "")
    placeId = tonumber(placeId) or game.PlaceId

    local strictList = {}
    local relaxedList = {}
    local seenStrict = {}
    local seenAll = {}
    local scanned = 0
    local cursor = nil

    for page = 1, SCAN_MAX_PAGES do
        local servers, nextCursor, err = fetchServers(placeId, cursor)
        if not servers then
            return false, ("no_servers: " .. tostring(err)), scanned
        end

        for _, s in ipairs(servers) do
            scanned += 1
            local id = tostring(s.id or "")
            local playing = tonumber(s.playing) or 0
            local maxPlayers = tonumber(s.maxPlayers) or 0

            if serverEligible(id, playing, maxPlayers, avoidJobId) then
                addCandidate(strictList, seenStrict, id, playing, maxPlayers, targetPlayers)
                addCandidate(relaxedList, seenAll, id, playing, maxPlayers, targetPlayers)
            elseif serverEligibleRelaxed(id, playing, maxPlayers, avoidJobId) then
                addCandidate(relaxedList, seenAll, id, playing, maxPlayers, targetPlayers)
            end
        end

        if not nextCursor or nextCursor == "" then break end
        cursor = nextCursor
    end

    local pool = strictList
    if #pool < CANDIDATE_MAX and #relaxedList > #pool then
        table.sort(relaxedList, function(a, b)
            return a.score < b.score
        end)
        local have = {}
        for _, rec in ipairs(pool) do
            have[rec.id] = true
        end
        for _, rec in ipairs(relaxedList) do
            if not have[rec.id] then
                pool[#pool + 1] = rec
                have[rec.id] = true
            end
            if #pool >= CANDIDATE_MAX then break end
        end
    end

    if #pool == 0 then
        return false, ("no_match_scanned=" .. tostring(scanned)), scanned
    end

    table.sort(pool, function(a, b)
        return a.score < b.score
    end)

    if #pool > CANDIDATE_MAX then
        local trimmed = {}
        for i = 1, CANDIDATE_MAX do
            trimmed[i] = pool[i]
        end
        pool = trimmed
    end

    _candidateCache.placeId = placeId
    _candidateCache.targetPlayers = targetPlayers
    _candidateCache.builtAt = now()
    _candidateCache.list = pool
    _candidateCache.index = 1

    dprint("candidate cache built", #pool, "strict=", #strictList, "scanned", scanned)
    return true, nil, scanned
end

local function getNextCandidate(placeId, targetPlayers, avoidJobId, allowRebuild)
    placeId = tonumber(placeId) or game.PlaceId
    targetPlayers = tonumber(targetPlayers) or 20
    avoidJobId = tostring(avoidJobId or "")
    allowRebuild = (allowRebuild ~= false)

    if candidateCacheStale(placeId, targetPlayers) then
        if not allowRebuild then
            return nil, "cache_exhausted"
        end
        local ok, err = buildCandidateList(placeId, targetPlayers, avoidJobId)
        if not ok then
            return nil, err
        end
    end

    while _candidateCache.index <= #_candidateCache.list do
        local rec = _candidateCache.list[_candidateCache.index]
        _candidateCache.index += 1
        if serverEligibleRelaxed(rec.id, rec.playing, rec.maxPlayers, avoidJobId) then
            return rec, nil
        end
    end

    if allowRebuild then
        clearCandidateCache()
        local ok, err = buildCandidateList(placeId, targetPlayers, avoidJobId)
        if ok then
            return getNextCandidate(placeId, targetPlayers, avoidJobId, false)
        end
        return nil, err
    end

    return nil, "cache_exhausted"
end

----------------------------------------------------------------
-- Pick best server near target players (legacy helper)
----------------------------------------------------------------
local function pickServerNearTarget(placeId, targetPlayers, avoidJobId)
    local rec, err = getNextCandidate(placeId, targetPlayers, avoidJobId, true)
    if not rec then
        return nil, err
    end
    return { id = rec.id, playing = rec.playing, maxPlayers = rec.maxPlayers }, nil
end

local function hopToServer(placeId, jobId)
    local R = rawget(_G, "PSReconnect")
    if R and type(R.HopToServer) == "function" then
        return R.HopToServer(placeId, jobId)
    end

    local ok, err = pcall(function()
        TeleportService:TeleportToPlaceInstance(placeId, jobId, LP)
    end)
    return ok, err
end

----------------------------------------------------------------
-- Public signals
----------------------------------------------------------------
function M.NotifySold()
    _lastSoldAt = now()
    dprint("NotifySold -> lastSoldAt updated")
end

function M.SetDebug(on)
    _debug = (on == true)
end

----------------------------------------------------------------
-- Retry scheduling (anti-recursion)
----------------------------------------------------------------
local _pendingRetry = false
local _pendingRetryReason = nil

local function scheduleRetry(reason)
    if _pendingRetry then return end
    _pendingRetry = true
    _pendingRetryReason = tostring(reason or "retry")

    task.defer(function()
        _pendingRetry = false
        local r = _pendingRetryReason
        _pendingRetryReason = nil

        _hopInFlight = false
        local ok, err = M.HopNextFromCache(r)
        dprint("retry after fail:", r, "ok=", ok, "err=", tostring(err))
    end)
end

----------------------------------------------------------------
-- Teleport fail hook (FULL / FAILURE) -> schedule retry
----------------------------------------------------------------
local _tpFailConn = nil
local function ensureTeleportFailHook()
    if _tpFailConn then return end
    _tpFailConn = TeleportService.TeleportInitFailed:Connect(function(player, result, errMsg)
        if player ~= LP then return end
        if not _hopInFlight then return end

        local r = tostring(result)
        local m = string.lower(tostring(errMsg or ""))

        local isFail =
            (result == Enum.TeleportResult.GameFull) or m:find("full")
            or (result == Enum.TeleportResult.Failure)
            or (result == Enum.TeleportResult.Flooded)
            or (result == Enum.TeleportResult.Unauthorized)

        if not isFail then return end

        dprint("TeleportInitFailed:", r, errMsg)

        if _hopTargetJobId ~= "" then
            _markAvoid(_hopTargetJobId, 180)
        end

        _burstFail()
        scheduleRetry("teleport_failed:" .. r)
    end)
end

----------------------------------------------------------------
-- Watchdog: kalau 5 detik masih jobId sama -> retry
----------------------------------------------------------------
local function startHopWatchdog(attemptId, fromJobId, targetJobId)
    task.delay(5, function()
        if _hopAttemptId ~= attemptId then return end

        if tostring(game.JobId) == tostring(fromJobId) then
            dprint("WATCHDOG: still same server after 5s -> retry")
            if targetJobId and targetJobId ~= "" then
                _markAvoid(targetJobId, 180)
            end
            _burstFail()
            scheduleRetry("retry_timeout")
        else
            dprint("WATCHDOG: job changed -> hop success")
            _hopInFlight = false
            clearCandidateCache()
        end
    end)
end

----------------------------------------------------------------
-- Force hop
----------------------------------------------------------------
local function executeHopCandidate(best, placeId, fromJobId, reason, tryIndex, tryMax)
    _lastHopAt = now()
    _hopAttemptId += 1
    local myAttempt = _hopAttemptId

    _hopInFlight = true
    _hopFromJobId = fromJobId
    _hopTargetJobId = best.id

    dprint(string.format(
        "Hop try#%d/%d reason=%s -> job=%s playing=%d cacheLeft=%d",
        tryIndex, tryMax, reason, best.id, best.playing,
        math.max(0, #_candidateCache.list - _candidateCache.index + 1)
    ))

    local ok, e = hopToServer(placeId, best.id)
    if not ok then
        dprint("Hop failed immediate:", e)
        _hopInFlight = false
        _markAvoid(best.id, 180)
        _burstFail()
        return false, "immediate_fail", e
    end

    startHopWatchdog(myAttempt, fromJobId, best.id)
    return true, "teleport_called", nil
end

function M.HopNextFromCache(reason)
    ensureTeleportFailHook()

    reason = tostring(reason or "retry")
    if not LP then return false, "no_localplayer" end

    local placeId = game.PlaceId
    local fromJobId = tostring(game.JobId)
    local cfg = getHopCfg() or { targetPlayer = 20 }
    local targetPlayers = cfg.targetPlayer or 20

    local best, err = getNextCandidate(placeId, targetPlayers, fromJobId, true)
    if not best then
        dprint("HopNextFromCache no candidate:", err)
        return false, err
    end

    local ok, status = executeHopCandidate(best, placeId, fromJobId, reason, 1, 1)
    return ok, status
end

function M.ForceHopNow(reason, bypassCooldown)
    ensureTeleportFailHook()

    reason = tostring(reason or "manual")
    if not LP then return false, "no_localplayer" end

    local t = now()
    if bypassCooldown ~= true then
        if (t - (_lastHopAt or 0)) < _cooldownHopSec then
            return false, "hop_cooldown"
        end
    end

    local placeId = game.PlaceId
    local fromJobId = tostring(game.JobId)

    local cfg = getHopCfg() or { targetPlayer = 20 }
    local targetPlayers = cfg.targetPlayer or 20

    local MAX_TRIES = CANDIDATE_MAX

    for i = 1, MAX_TRIES do
        local best, err = getNextCandidate(placeId, targetPlayers, fromJobId, true)
        if not best then
            dprint("ForceHopNow pick failed:", err)
            _burstFail()
            clearCandidateCache()
            return false, err
        end

        local ok, status, hopErr = executeHopCandidate(
            best, placeId, fromJobId, reason, i, MAX_TRIES
        )
        if ok then
            return true, status
        end
        if status == "immediate_fail" then
            task.wait(0.2)
        else
            return false, status or hopErr
        end
    end

    clearCandidateCache()
    return false, "all_tries_failed"
end

----------------------------------------------------------------
-- Main loop logic
----------------------------------------------------------------
local function shouldHop(cfg)
    if not cfg or cfg.enabled ~= true then
        return false, "disabled"
    end

    local playersNow = getPlayerCount()

    if cfg.minPlayerNow and cfg.minPlayerNow > 0 then
        if playersNow < cfg.minPlayerNow then
            return true, ("players_below_min (" .. playersNow .. " < " .. cfg.minPlayerNow .. ")")
        end
    end

    local noSaleSec = now() - (_lastSoldAt or now())
    local thresholdSec = (tonumber(cfg.waktuMin) or 15) * 60
    if noSaleSec >= thresholdSec then
        return true, ("no_sale_timeout (" .. math.floor(noSaleSec) .. "s)")
    end

    return false, "ok"
end

local function loop()
    while _running do
        
        local cfg = getHopCfg()
local noSaleSec = now() - (_lastSoldAt or now())
dprint("enabled=", cfg and cfg.enabled, "waktuMin=", cfg and cfg.waktuMin, "noSaleSec=", math.floor(noSaleSec))

        local ok, err = pcall(function()
            local cfg = getHopCfg()
            local doHop, reason = shouldHop(cfg)
            if doHop then
                local success, hopErr = M.ForceHopNow(reason)
                dprint("doHop=", success, "reason=", reason, "err=", hopErr)
            end
        end)

        if not ok then
            dprint("loop error:", err)
        end

        task.wait(2.0)
    end
end

function M.ShouldHop()
    local cfg = getHopCfg()
    return shouldHop(cfg)
end

----------------------------------------------------------------
-- Start / Stop
----------------------------------------------------------------
function M.IsRunning()
    return _running == true
end

function M.Start()
    if _running then return end
    _running = true

    if _lastSoldAt == nil then _lastSoldAt = now() end

    ensureTeleportFailHook()
    _thread = task.spawn(loop)
    dprint("Start()")
end

function M.Stop()
    _running = false
    dprint("Stop()")
end

local G = (getgenv and getgenv()) or _G
G.AutoHop = M
_G.AutoHop = M
--_G.AutoHop.SetDebug(true)

return M

        end,
        required = false,
    },

    {
        key = "hopsnipeserver",
        name = "hopsnipeserver",
        factory = function()
            -- auto_snipe_hop.lua (NodeHub Market - SNIPE HOP) ✅ NO TELEPORT SPAM
-- ✅ 1 Hop Session (serial attempts, no storm)
-- ✅ Anti IsTeleporting spam (lock window)
-- ✅ If target dead/full -> mark & try next candidate
-- ✅ TeleportData confirm -> push visited (persist)
-- ✅ PRE-HOP: mark current server JobId to visited BEFORE building candidates (STATE + FILE)
-- ✅ Candidates filter uses visited from STATE + FILE cache
-- ✅ If visited reached diffServers -> clear visited (STATE + FILE) + invalidate cache ts
-- ✅ Cache candidates to FILE per (placeId,targetPlayers,diffServers) to reduce 429
-- ✅ 429 backoff -> stop scan and rely on cache
-- ✅ Works with PSReconnect:HopToServer (keeps QTP gating). Fallback to TeleportToPlaceInstance if needed.

local M = {}

----------------------------------------------------------------
-- Services
----------------------------------------------------------------
local Players         = game:GetService("Players")
local TeleportService = game:GetService("TeleportService")
local HttpService     = game:GetService("HttpService")

local LP = Players.LocalPlayer

----------------------------------------------------------------
-- Debug (production output)
----------------------------------------------------------------
local _debug = false
local function dprint(...)
    if not _debug then return end
    print("[auto_snipe_hop]", ...)
end

local function now() return os.clock() end
local function low(s) return string.lower(tostring(s or "")) end

----------------------------------------------------------------
-- Utils
----------------------------------------------------------------
local function clampNum(v, minv, maxv, fallback)
    local n = tonumber(v)
    if n == nil then return fallback end
    if minv ~= nil and n < minv then n = minv end
    if maxv ~= nil and n > maxv then n = maxv end
    return n
end

local function isArray(t)
    return type(t) == "table" and rawget(t, 1) ~= nil
end

local function ensureArray(t)
    if type(t) ~= "table" then return {} end
    if isArray(t) then return t end
    return {}
end

----------------------------------------------------------------
-- FILE CACHE (reduce 429)
----------------------------------------------------------------
local FS_OK = (type(readfile)=="function" and type(writefile)=="function" and type(isfile)=="function")

local function ensureFolder(path)
    if type(makefolder) ~= "function" then return end
    if type(isfolder) == "function" and isfolder(path) then return end
    local parts = {}
    for seg in tostring(path):gmatch("[^/]+") do
        parts[#parts+1] = seg
        local p = table.concat(parts, "/")
        if type(isfolder) ~= "function" or not isfolder(p) then
            pcall(function() makefolder(p) end)
        end
    end
end

local CACHE_DIR  = "nodehub"
local CACHE_FILE = CACHE_DIR .. "/snipehop_cache.json"

local function safeJsonDecode(s)
    local ok, t = pcall(function() return HttpService:JSONDecode(s) end)
    if ok and type(t) == "table" then return t end
    return nil
end

local function safeJsonEncode(t)
    local ok, s = pcall(function() return HttpService:JSONEncode(t) end)
    if ok and type(s) == "string" then return s end
    return nil
end

local function readCacheRoot()
    if not FS_OK then return {} end
    if not isfile(CACHE_FILE) then return {} end
    local ok, content = pcall(function() return readfile(CACHE_FILE) end)
    if not ok or type(content) ~= "string" then return {} end
    return safeJsonDecode(content) or {}
end

local function writeCacheRoot(root)
    if not FS_OK then return end
    ensureFolder(CACHE_DIR)
    local s = safeJsonEncode(root)
    if not s then return end
    pcall(function() writefile(CACHE_FILE, s) end)
end

local function makeCacheKey(placeId, targetPlayers, diffServers)
    return tostring(placeId) .. "|tp=" .. tostring(targetPlayers) .. "|diff=" .. tostring(diffServers)
end

-- root[key] = { ts=os.time(), candidates={...}, visited={...} }
local function cacheLoad(placeId, targetPlayers, diffServers)
    local root = readCacheRoot()
    local key  = makeCacheKey(placeId, targetPlayers, diffServers)
    local rec  = (type(root[key])=="table") and root[key] or {}
    return root, key, rec
end

local function cacheSave(placeId, targetPlayers, diffServers, patch)
    local root, key, rec = cacheLoad(placeId, targetPlayers, diffServers)
    rec = (type(rec)=="table") and rec or {}
    patch = (type(patch)=="table") and patch or {}
    for k,v in pairs(patch) do rec[k] = v end
    root[key] = rec
    writeCacheRoot(root)
end

local function cacheGetCandidates(placeId, targetPlayers, diffServers, maxAgeSec)
    maxAgeSec = tonumber(maxAgeSec) or 900
    local _, _, rec = cacheLoad(placeId, targetPlayers, diffServers)
    local ts  = tonumber(rec.ts) or 0
    local arr = rec.candidates
    if type(arr) ~= "table" then return nil, "no_cache" end
    local age = os.time() - ts
    if age > maxAgeSec then
        return ensureArray(arr), "stale_cache"
    end
    return ensureArray(arr), "fresh_cache"
end

local function cacheSetCandidates(placeId, targetPlayers, diffServers, candidates)
    candidates = ensureArray(candidates)
    cacheSave(placeId, targetPlayers, diffServers, {
        ts = os.time(),
        candidates = candidates,
    })
end

local function cacheGetVisited(placeId, targetPlayers, diffServers)
    local _, _, rec = cacheLoad(placeId, targetPlayers, diffServers)
    local v = rec.visited
    if type(v) ~= "table" then return {} end
    return ensureArray(v)
end

local function cacheSetVisited(placeId, targetPlayers, diffServers, visitedArr)
    visitedArr = ensureArray(visitedArr)
    cacheSave(placeId, targetPlayers, diffServers, {
        visited = visitedArr,
    })
end

----------------------------------------------------------------
-- State read
----------------------------------------------------------------
local function _getState()
    local S = rawget(_G, "STATE")
    if type(S) ~= "table" then
        S = {}
        _G.STATE = S
    end

    S.main = (type(S.main) == "table") and S.main or {}
    S.main.auto_market = (type(S.main.auto_market) == "table") and S.main.auto_market or {}
    local MK = S.main.auto_market

    MK.snipeHop = (type(MK.snipeHop) == "table") and MK.snipeHop or {}
    local SH = MK.snipeHop

    if SH.enabled == nil then SH.enabled = false end
    if tonumber(SH.minutes) == nil then SH.minutes = 8 end
    if tonumber(SH.diffServers) == nil then SH.diffServers = 5 end
    SH.visited = ensureArray(SH.visited)

    SH.minutes     = clampNum(SH.minutes, 1, 1440, 8)
    SH.diffServers = clampNum(SH.diffServers, 1, 200, 5)

    if SH.targetPlayer ~= nil then
        SH.targetPlayer = clampNum(SH.targetPlayer, 1, 100, 20)
    end

    MK.hop = (type(MK.hop) == "table") and MK.hop or {}
    return S, MK, SH
end

local function getCfg()
    local S, MK, SH = _getState()

    local target =
        (SH.targetPlayer ~= nil and tonumber(SH.targetPlayer))
        or (MK.hop and tonumber(MK.hop.targetPlayer))
        or 20
    target = clampNum(target, 1, 100, 20)

    return {
        enabled       = (SH.enabled == true),
        minutes       = clampNum(SH.minutes, 1, 1440, 8),
        diffServers   = clampNum(SH.diffServers, 1, 200, 5),
        targetPlayers = target,
        SH = SH,
        MK = MK,
        STATE = S,
    }
end

----------------------------------------------------------------
-- visited helpers (STATE + FILE)
----------------------------------------------------------------
local function buildSetFromArray(arr)
    local set = {}
    arr = ensureArray(arr)
    for _, v in ipairs(arr) do
        local s = tostring(v or "")
        if s ~= "" then set[s] = true end
    end
    return set
end

local function resetVisitedIfNeeded(placeId, targetPlayers, diffServers, SH)
    local limit = tonumber(SH and SH.diffServers) or diffServers or 5
    SH.visited = ensureArray(SH and SH.visited)

    if #SH.visited >= limit then
        SH.visited = {}
        dprint("visited reset limit", limit)

        cacheSetVisited(placeId, targetPlayers, diffServers, SH.visited)

        -- ✅ invalidate candidates cache so next build refreshes (optional but requested)
        cacheSave(placeId, targetPlayers, diffServers, { ts = 0 })

        local MAIN = rawget(_G, "MAIN")
        if MAIN and type(MAIN.save) == "function" then
            task.defer(function() pcall(function() MAIN.save() end) end)
        end
        return true
    end
    return false
end

-- ✅ PRE-HOP: always mark current server to visited (STATE + FILE)
local function pushVisitedPreHop(jobId)
    local cfg = getCfg()
    local placeId = game.PlaceId

    jobId = tostring(jobId or "")
    if jobId == "" then return false end

    local SH = cfg.SH
    SH.visited = ensureArray(SH.visited)

    for _, v in ipairs(SH.visited) do
        if tostring(v) == jobId then
            return false
        end
    end

    table.insert(SH.visited, jobId)
    dprint("visited prehop +1", jobId, "count", #SH.visited)

    cacheSetVisited(placeId, cfg.targetPlayers, cfg.diffServers, SH.visited)
    resetVisitedIfNeeded(placeId, cfg.targetPlayers, cfg.diffServers, SH)

    local MAIN = rawget(_G, "MAIN")
    if MAIN and type(MAIN.save) == "function" then
        task.defer(function() pcall(function() MAIN.save() end) end)
    end

    return true
end

local function pushVisitedConfirmed(jobId)
    local cfg = getCfg()
    local placeId = game.PlaceId

    jobId = tostring(jobId or "")
    if jobId == "" then return end

    local SH = cfg.SH
    SH.visited = ensureArray(SH.visited)
    for _, v in ipairs(SH.visited) do
        if tostring(v) == jobId then return end
    end

    table.insert(SH.visited, jobId)
    dprint("visited confirmed +1", jobId, "count", #SH.visited)

    cacheSetVisited(placeId, cfg.targetPlayers, cfg.diffServers, SH.visited)
    resetVisitedIfNeeded(placeId, cfg.targetPlayers, cfg.diffServers, SH)

    local MAIN = rawget(_G, "MAIN")
    if MAIN and type(MAIN.save) == "function" then
        task.defer(function() pcall(function() MAIN.save() end) end)
    end
end

----------------------------------------------------------------
-- Local avoid/recent/dead trackers
----------------------------------------------------------------
local AVOID_TTL_SEC    = 240
local AVOID_TTL_DEAD   = 900
local AVOID_TTL_FULL   = 240
local RECENT_TRIED_TTL = 240

local _avoidUntil  = {}
local _recentTried = {}
local _deadUntil   = {}

local function ttlAlive(map, jobId)
    jobId = tostring(jobId or "")
    if jobId == "" then return false end
    local untilT = map[jobId]
    if not untilT then return false end
    if now() >= untilT then
        map[jobId] = nil
        return false
    end
    return true
end

local function isAvoided(jobId) return ttlAlive(_avoidUntil, jobId) end
local function isRecent(jobId)  return ttlAlive(_recentTried, jobId) end
local function isDead(jobId)    return ttlAlive(_deadUntil, jobId) end

local function markAvoid(jobId, sec)
    jobId = tostring(jobId or "")
    if jobId == "" then return end
    sec = tonumber(sec) or AVOID_TTL_SEC
    _avoidUntil[jobId] = now() + sec
end

local function markRecent(jobId, sec)
    jobId = tostring(jobId or "")
    if jobId == "" then return end
    sec = tonumber(sec) or RECENT_TRIED_TTL
    _recentTried[jobId] = now() + sec
end

local function markDead(jobId, sec)
    jobId = tostring(jobId or "")
    if jobId == "" then return end
    sec = tonumber(sec) or AVOID_TTL_DEAD
    _deadUntil[jobId] = now() + sec
end

----------------------------------------------------------------
-- Roblox API backoff (429)
----------------------------------------------------------------
local _apiBlockedUntil = 0
local _api429WinStart  = 0
local _api429Count     = 0

local function apiBackoff(sec, why)
    sec = tonumber(sec) or 30
    local jitter = math.random(0, 8)
    _apiBlockedUntil = now() + sec + jitter
    dprint("API_BACKOFF", math.floor(sec + jitter), "sec", tostring(why or ""))
end

local function httpGet(url)
    if now() < (_apiBlockedUntil or 0) then
        return false, "rate_limited_local", 429
    end

    local req =
        (syn and syn.request) or
        (http and http.request) or
        http_request or
        request or
        (fluxus and fluxus.request)

    if type(req) == "function" then
        local res = req({ Url = url, Method = "GET" })
        local body = res and (res.Body or res.body)
        local code = tonumber(res and (res.StatusCode or res.status_code)) or 0

        if _debug then dprint("http", code, url) end

        if code == 429 then
            local t = now()
            if (t - _api429WinStart) > 60 then
                _api429WinStart = t
                _api429Count = 0
            end
            _api429Count += 1

            local base = 30
            if _api429Count >= 2 then base = 45 end
            if _api429Count >= 4 then base = 75 end
            apiBackoff(base, "http_429")
            return false, "http_429", 429
        end

        if type(body) == "string" and body ~= "" then
            return true, body, code
        end
        return false, "request_failed", code
    end

    local ok, body = pcall(function()
        return game:HttpGet(url)
    end)
    if not ok then
        return false, body, 0
    end
    return true, body, 200
end

local function fetchServers(placeId, cursor)
    local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Desc&limit=100"):format(placeId)
    if cursor and cursor ~= "" then
        url = url .. "&cursor=" .. HttpService:UrlEncode(cursor)
    end

    local ok, body, code = httpGet(url)
    if not ok then
        return nil, nil, ("http_failed:" .. tostring(body) .. "|code=" .. tostring(code))
    end

    local decoded
    local ok2 = pcall(function()
        decoded = HttpService:JSONDecode(body)
    end)
    if not ok2 or type(decoded) ~= "table" then
        return nil, nil, "json_decode_failed"
    end

    local data = decoded.data
    local nextCursor = decoded.nextPageCursor
    if type(data) ~= "table" then data = {} end

    return data, nextCursor, nil
end

local function filterCandidates(list, visitedSet, avoidJobId)
    local out = {}
    list = ensureArray(list)
    visitedSet = visitedSet or {}
    avoidJobId = tostring(avoidJobId or "")

    for _, rec in ipairs(list) do
        local id = tostring(rec.id or "")
        local playing = tonumber(rec.playing) or 0
        local maxPlayers = tonumber(rec.maxPlayers) or 0

        if id ~= ""
            and id ~= avoidJobId
            and not visitedSet[id]
            and not isDead(id)
            and not isAvoided(id)
            and not isRecent(id)
        then
            if (maxPlayers == 0) or (playing < maxPlayers) then
                out[#out+1] = { id=id, playing=playing, maxPlayers=maxPlayers }
            end
        end
    end

    return out
end

----------------------------------------------------------------
-- Build candidates (cache-first, scan-later)
----------------------------------------------------------------
local function buildCandidates(placeId, targetPlayers, diffServers, visitedSet, avoidJobId)
    visitedSet = visitedSet or {}
    avoidJobId = tostring(avoidJobId or "")

    -- ✅ merge visited from file (persist)
    do
        local vfile = cacheGetVisited(placeId, targetPlayers, diffServers)
        for _, jid in ipairs(ensureArray(vfile)) do
            visitedSet[tostring(jid)] = true
        end
    end

    -- 1) cache first (fresh)
    local cached, cacheState = cacheGetCandidates(placeId, targetPlayers, diffServers, 900)
    if type(cached) == "table" and #cached > 0 and cacheState == "fresh_cache" then
        local filtered = filterCandidates(cached, visitedSet, avoidJobId)
        if #filtered > 0 then
            dprint("use cache candidates (fresh)", #filtered, "from", #cached)
            return filtered, nil, 0, cacheState
        end
        dprint("cache fresh exhausted by filters -> scan")
    end

    -- 2) if blocked -> stale cache only
    if now() < (_apiBlockedUntil or 0) then
        if type(cached) == "table" and #cached > 0 then
            local filtered = filterCandidates(cached, visitedSet, avoidJobId)
            if #filtered > 0 then
                dprint("use cache candidates (blocked)", #filtered, cacheState)
                return filtered, nil, 0, cacheState
            end
            dprint("blocked + cache exhausted by filters")
        end
        return nil, "api_blocked_no_cache", 0, cacheState
    end

    -- 3) scan (limited pages)
    local cursor = nil
    local scanned = 0
    local poolAbove, poolBelow = {}, {}

    local function pushPool(pool, rec, maxN)
        pool[#pool+1] = rec
        if #pool > maxN then
            local worstI, worstS = 1, pool[1].score
            for i = 2, #pool do
                if pool[i].score > worstS then
                    worstS = pool[i].score
                    worstI = i
                end
            end
            table.remove(pool, worstI)
        end
    end

    for page = 1, 3 do
        local servers, nextCursor, err = fetchServers(placeId, cursor)
        if not servers then
            -- if scan hits 429 -> fallback cache if exists
            if tostring(err):find("code=429") then
                if type(cached) == "table" and #cached > 0 then
                    local filtered = filterCandidates(cached, visitedSet, avoidJobId)
                    if #filtered > 0 then
                        dprint("scan hit 429 -> fallback cache(filtered)", #filtered, cacheState)
                        return filtered, nil, scanned, cacheState
                    end
                    dprint("scan hit 429 but cache exhausted by filters")
                    return nil, "http_429_cache_exhausted", scanned, cacheState
                end
            end
            return nil, err, scanned, cacheState
        end

        for _, s in ipairs(servers) do
            scanned += 1
            local id = tostring(s.id or "")
            local playing = tonumber(s.playing) or 0
            local maxPlayers = tonumber(s.maxPlayers) or 0

            if id ~= ""
                and id ~= avoidJobId
                and not visitedSet[id]
                and not isDead(id)
                and not isAvoided(id)
                and not isRecent(id)
                and not ((maxPlayers ~= 0) and (playing >= maxPlayers))
            then
                local score = math.abs(playing - targetPlayers)
                local rec = { id=id, playing=playing, maxPlayers=maxPlayers, score=score }
                if playing >= targetPlayers then
                    pushPool(poolAbove, rec, 14)
                else
                    pushPool(poolBelow, rec, 14)
                end
            end
        end

        if not nextCursor or nextCursor == "" then break end
        cursor = nextCursor
    end

    local candidates = {}
    if #poolAbove > 0 then
        table.sort(poolAbove, function(a,b) return a.score < b.score end)
        for _, rec in ipairs(poolAbove) do
            candidates[#candidates+1] = { id=rec.id, playing=rec.playing, maxPlayers=rec.maxPlayers }
        end
    end
    if #poolBelow > 0 then
        table.sort(poolBelow, function(a,b) return a.score < b.score end)
        for _, rec in ipairs(poolBelow) do
            candidates[#candidates+1] = { id=rec.id, playing=rec.playing, maxPlayers=rec.maxPlayers }
        end
    end

    if #candidates > 0 then
        cacheSetCandidates(placeId, targetPlayers, diffServers, candidates)
    end

    dprint("SCAN done scanned=", scanned, "candidates=", #candidates, "target=", targetPlayers)
    return candidates, nil, scanned, cacheState
end

----------------------------------------------------------------
-- Teleport wrappers
----------------------------------------------------------------
local function teleportToJob(placeId, jobId, teleportData)
    placeId = tonumber(placeId) or game.PlaceId
    jobId = tostring(jobId or "")
    if jobId == "" then return false, "jobId_empty" end

    local opts = Instance.new("TeleportOptions")
    if type(teleportData) == "table" then
        pcall(function() opts:SetTeleportData(teleportData) end)
    end

    local ok, err = pcall(function()
        TeleportService:TeleportToPlaceInstance(placeId, jobId, LP, opts)
    end)
    if not ok then
        return false, tostring(err)
    end
    return true, "teleport_to_place_instance"
end

local function hopToServer(placeId, jobId, fromJobId)
    placeId = tonumber(placeId) or game.PlaceId
    jobId = tostring(jobId or "")
    fromJobId = tostring(fromJobId or game.JobId or "")

    if jobId == "" then return false, "jobId_empty" end

    local td = {
        __nodehub_snipehop = true,
        fromJobId = fromJobId,
        targetJobId = jobId,
        nonce = tostring(os.time()) .. "_" .. tostring(math.random(100000, 999999)),
    }

    local PR = rawget(_G, "PSReconnect") or rawget((getgenv and getgenv()) or _G, "PSReconnect")
    if type(PR) == "table" and type(PR.HopToServer) == "function" then
        local ok, res = PR.HopToServer(placeId, jobId, td)
        if ok then return true, res end
        dprint("psreconnect hop failed -> fallback", tostring(res))
    end

    return teleportToJob(placeId, jobId, td)
end

----------------------------------------------------------------
-- TeleportData confirm (visited only when really moved)
----------------------------------------------------------------
local _teleDataApplied = false
local function applyTeleportDataOnce()
    if _teleDataApplied then return end
    _teleDataApplied = true

    local data = nil
    pcall(function()
        data = TeleportService:GetLocalPlayerTeleportData()
    end)

    dprint("TPDATA type", typeof(data))
    if type(data) == "table" then
        dprint("TPDATA keys",
            tostring(data.__nodehub_snipehop),
            tostring(data.fromJobId),
            tostring(data.targetJobId),
            "here="..tostring(game.JobId)
        )
    end

    if type(data) ~= "table" then return end
    if data.__nodehub_snipehop ~= true then return end

    local targetJob = tostring(data.targetJobId or "")
    local fromJob   = tostring(data.fromJobId or "")
    local hereJob   = tostring(game.JobId or "")

    if targetJob ~= "" and hereJob == targetJob and hereJob ~= fromJob then
        pushVisitedConfirmed(hereJob)
        dprint("teleport confirmed from", fromJob, "to", hereJob)
    else
        dprint("teleportData ignored target", targetJob, "here", hereJob, "from", fromJob)
    end
end

----------------------------------------------------------------
-- Hop Scheduler (no spam)
----------------------------------------------------------------
local _running = false
local _thread  = nil

local _lastHopSuccessAt = 0
local _lastHopTryAt     = 0
local _cooldownHopSec   = 25
local SESSION_FAIL_COOLDOWN = 18

local _lockUntil = 0

local _session = nil
local WATCHDOG_SEC = 12

local function sessionReset()
    _session = nil
end

local function sessionActive()
    return type(_session) == "table" and _session.active == true
end

local function shouldHop(cfg)
    if not cfg or cfg.enabled ~= true then
        return false, "disabled"
    end

    if rawget(_G, "__SNIPE_HOP_NOW") == true then
        return true, "manual_flag"
    end

    local base = math.max(tonumber(_lastHopSuccessAt) or 0, tonumber(_lastHopTryAt) or 0)
    if base <= 0 then
        _lastHopTryAt = now()
        base = _lastHopTryAt
    end

    local elapsed = now() - base
    local threshold = (tonumber(cfg.minutes) or 8) * 60
    if elapsed >= threshold then
        return true, ("interval_timeout (" .. math.floor(elapsed) .. "s)")
    end

    return false, "ok"
end

local function sessionStart(reason)
    local cfg = getCfg()
    if cfg.enabled ~= true then
        return false, "disabled"
    end
    if not LP then
        return false, "no_localplayer"
    end
    if sessionActive() then
        return false, "session_already_active"
    end

    local t = now()
    if (t - (_lastHopTryAt or 0)) < _cooldownHopSec then
        return false, "hop_cooldown"
    end

    _lastHopTryAt = t

    local placeId   = game.PlaceId
    local fromJobId = tostring(game.JobId)

    -- ✅ PRE-HOP: always mark current server visited BEFORE building candidates
    pushVisitedPreHop(fromJobId)

    -- visited set from STATE + FILE
    local visitedSet = buildSetFromArray(cfg.SH.visited)
    do
        local vfile = cacheGetVisited(placeId, cfg.targetPlayers, cfg.diffServers)
        for _, jid in ipairs(vfile) do
            visitedSet[tostring(jid)] = true
        end
    end
    visitedSet[fromJobId] = true

    local candidates, err = buildCandidates(placeId, cfg.targetPlayers, cfg.diffServers, visitedSet, fromJobId)
    if type(candidates) ~= "table" or #candidates == 0 then
        if tostring(err or ""):find("429") then
            apiBackoff(35, "no_candidates_429")
        end
        return false, err or "no_candidates"
    end

    _session = {
        active = true,
        reason = tostring(reason or ""),
        placeId = placeId,
        fromJobId = fromJobId,
        targetPlayers = cfg.targetPlayers,
        diffServers = cfg.diffServers,
        candidates = ensureArray(candidates),
        idx = 1,
        attemptedSet = {},
        inFlight = false,
        currentJobId = "",
        startedAt = now(),
        nextActionAt = now(),
    }

    dprint("sessionStart", "reason=", _session.reason, "candidates=", #_session.candidates)
    return true, "session_started"
end

local function sessionFinish(ok, why)
    if rawget(_G, "__SNIPE_HOP_NOW") == true then
        _G.__SNIPE_HOP_NOW = false
    end

    if ok then
        _lastHopSuccessAt = now()
    else
        _lockUntil = math.max(_lockUntil, now() + SESSION_FAIL_COOLDOWN)
    end

    dprint("sessionFinish", ok, tostring(why or ""))
    sessionReset()
end

local function pickNextCandidate()
    if not sessionActive() then return nil end
    local s = _session

    for i = s.idx, #s.candidates do
        local rec = s.candidates[i] or {}
        local jobId = tostring(rec.id or "")
        s.idx = i + 1

        if jobId ~= ""
            and jobId ~= s.fromJobId
            and not s.attemptedSet[jobId]
            and not isDead(jobId)
            and not isAvoided(jobId)
            and not isRecent(jobId)
        then
            s.attemptedSet[jobId] = true
            return rec, jobId
        end
    end

    return nil
end

local function startWatchdog(attemptJobId, fromJobId)
    task.delay(WATCHDOG_SEC, function()
        if not sessionActive() then return end
        local s = _session
        if s.inFlight ~= true then return end
        if s.currentJobId ~= tostring(attemptJobId) then return end

        if tostring(game.JobId) == tostring(fromJobId) then
            dprint("WATCHDOG timeout -> treat as stuck, try next")
            markAvoid(attemptJobId, AVOID_TTL_SEC)
            markRecent(attemptJobId, RECENT_TRIED_TTL)
            s.inFlight = false
            s.currentJobId = ""
            s.nextActionAt = now() + 1.0
        end
    end)
end

----------------------------------------------------------------
-- TeleportInitFailed hook (core anti spam)
----------------------------------------------------------------
local _tpFailConn = nil
local function ensureTeleportFailHook()
    if _tpFailConn then return end

    _tpFailConn = TeleportService.TeleportInitFailed:Connect(function(player, result, errMsg)
        if player ~= LP then return end
        if not sessionActive() then return end

        local s = _session
        if s.inFlight ~= true then return end

        local msg = tostring(errMsg or "")
        local lm  = low(msg)
        local r   = tostring(result)

        dprint("TeleportInitFailed", r, msg)

        local jobId = tostring(s.currentJobId or "")
        if jobId ~= "" then
            if lm:find("gameended")
                or lm:find("could not find requested game instance")
                or lm:find("requested game instance")
            then
                markDead(jobId, AVOID_TTL_DEAD)
                markAvoid(jobId, AVOID_TTL_DEAD)
                markRecent(jobId, math.max(RECENT_TRIED_TTL, AVOID_TTL_DEAD))
                s.nextActionAt = now() + 0.8

            elseif r:find("IsTeleporting") or lm:find("previous teleport") or lm:find("in processing") then
                _lockUntil = math.max(_lockUntil, now() + 12)
                s.nextActionAt = _lockUntil + 0.2

            else
                markAvoid(jobId, AVOID_TTL_FULL)
                markRecent(jobId, RECENT_TRIED_TTL)
                s.nextActionAt = now() + 0.6
            end
        end

        s.inFlight = false
        s.currentJobId = ""
    end)
end

----------------------------------------------------------------
-- Session Tick (state machine)
----------------------------------------------------------------
local function sessionTick()
    if not sessionActive() then return end
    local s = _session

    if now() < (_lockUntil or 0) then
        return
    end

    if now() < (s.nextActionAt or 0) then
        return
    end

    if s.inFlight == true then
        return
    end

    local rec, jobId = pickNextCandidate()
    if not rec then
        sessionFinish(false, "candidates_exhausted")
        return
    end

    markRecent(jobId, RECENT_TRIED_TTL)

    s.currentJobId = jobId
    s.inFlight = true

    dprint(("Hop -> job=%s playing=%s target=%s from=%s"):format(
        jobId, tostring(rec.playing or "?"), tostring(s.targetPlayers), tostring(s.fromJobId)
    ))

    local ok, res = hopToServer(s.placeId, jobId, s.fromJobId)
    if not ok then
        dprint("teleport call failed (pcall)", tostring(res))
        s.inFlight = false
        s.currentJobId = ""
        markAvoid(jobId, AVOID_TTL_SEC)
        s.nextActionAt = now() + 0.6
        return
    end

    startWatchdog(jobId, s.fromJobId)
end

----------------------------------------------------------------
-- Apply TeleportData once per server join
----------------------------------------------------------------
local function tryApplyTeleportDataAndSyncVisited()
    applyTeleportDataOnce()

    -- also sync visited file -> STATE (so UI consistent)
    local cfg = getCfg()
    local placeId = game.PlaceId

    local vfile = cacheGetVisited(placeId, cfg.targetPlayers, cfg.diffServers)
    if #vfile > 0 and type(cfg.SH.visited) == "table" then
        local set = buildSetFromArray(cfg.SH.visited)
        local changed = false
        for _, jid in ipairs(vfile) do
            jid = tostring(jid or "")
            if jid ~= "" and not set[jid] then
                table.insert(cfg.SH.visited, jid)
                set[jid] = true
                changed = true
            end
        end
        if changed then
            local MAIN = rawget(_G, "MAIN")
            if MAIN and type(MAIN.save) == "function" then
                task.defer(function() pcall(function() MAIN.save() end) end)
            end
        end
    end
end

----------------------------------------------------------------
-- Main loop
----------------------------------------------------------------
local function loop()
    while _running do
        local ok, err = pcall(function()
            tryApplyTeleportDataAndSyncVisited()

            local cfg = getCfg()
            local doHop, why = shouldHop(cfg)

            if doHop and not sessionActive() then
                local okS, rs = sessionStart(why)
                dprint("startHop", okS, rs)
            end

            if sessionActive() then
                sessionTick()
            end
        end)

        if not ok then
            dprint("loop error", err)
        end

        task.wait(0.6)
    end
end

----------------------------------------------------------------
-- Public API
----------------------------------------------------------------
function M.IsRunning()
    return _running == true
end

function M.SetDebug(on)
    _debug = (on == true)
end

function M.ShouldHop()
    return shouldHop(getCfg())
end

function M.ForceHopNow(reason)
    if sessionActive() then
        return false, "session_active"
    end
    local okS, rs = sessionStart(reason or "manual_force")
    return okS, rs
end

function M.Start()
    if _running then return end
    _running = true
    ensureTeleportFailHook()
    tryApplyTeleportDataAndSyncVisited()
    _thread = task.spawn(loop)
    dprint("Start()")
end

function M.Stop()
    _running = false
    sessionReset()
    dprint("Stop()")
end

