-- Export
----------------------------------------------------------------
local G = (getgenv and getgenv()) or _G
G.AutoSnipeHop = M
_G.AutoSnipeHop = M

return M

        end,
        required = false,
    },

    {
        key = "snipeSellerHop",
        name = "Snipe Seller Hop",
        factory = function()
            -- auto_snipe_seller_hop.lua
-- Snipe Hop By Seller (Pet + TradeBoothSkin)
-- Reads:
-- STATE.main.auto_market.snipeHopBySeller
--   enabled
--   syncFromSnipeList
--   delaySeconds
--   selectedPetTypes
--   selectedSkinTypes
--
-- If sync ON, targets diambil dari STATE.main.auto_market.snipe.rules (+ rulesBase)

local M = {}

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local TeleportService = game:GetService("TeleportService")

local LP = Players.LocalPlayer

local function waitChild(parent, name, timeout)
    if typeof(parent) ~= "Instance" then
        return nil
    end
    timeout = tonumber(timeout) or 8
    local existing = parent:FindFirstChild(name)
    if existing then
        return existing
    end
    return parent:WaitForChild(name, timeout)
end

local TokenRAPUtil = nil
pcall(function()
    local mods = ReplicatedStorage:FindFirstChild("Modules")
    local tokens = mods and mods:FindFirstChild("TradeTokens")
    local util = tokens and tokens:FindFirstChild("TokenRAPUtil")
    if util then
        TokenRAPUtil = require(util)
    end
end)

local TokenRAPs = waitChild(
    waitChild(waitChild(ReplicatedStorage, "GameEvents", 8), "TradeEvents", 8),
    "TokenRAPs",
    8
)

local FindSellers = TokenRAPs and waitChild(TokenRAPs, "FindSellers", 5)
local TeleportToListing = TokenRAPs and waitChild(TokenRAPs, "TeleportToListing", 5)

local ITEM_TYPE_PET = "Pet"
local ITEM_TYPE_SKIN = "TradeBoothSkin"

local running = false
local busy = false
local DEBUG = false
local statusText = "Idle"

local TELEPORT_CONFIRM_SEC = 8
-- Batas tunggu buy snipe sebelum tetap hop (detik), override: SHS.waitBuyMaxSec
local WAIT_BUY_MAX_SEC = 300
local pendingSince = nil

local function log(...)
    if DEBUG then
        print("[SnipeSellerHop]", ...)
    end
end

local function warnlog(...)
    warn("[SnipeSellerHop]", ...)
end

local function getStateSafe()
    local G = (getgenv and getgenv()) or _G
    local STATE = rawget(G, "STATE") or rawget(_G, "STATE") or {}
    STATE.main = STATE.main or {}
    STATE.main.auto_market = STATE.main.auto_market or {}
    local MK = STATE.main.auto_market
    MK.snipeHopBySeller = MK.snipeHopBySeller or {}
    return STATE, MK, MK.snipeHopBySeller
end

local function setStatus(msg)
    statusText = tostring(msg or "Idle")
    local ok, _, SHS = pcall(getStateSafe)
    if ok and SHS then
        SHS.status = statusText
    end
end

local function getState()
    local STATE, MK, SHS = getStateSafe()

    if type(SHS.enabled) ~= "boolean" then
        SHS.enabled = false
    end

    if type(SHS.syncFromSnipeList) ~= "boolean" then
        SHS.syncFromSnipeList = false
    end

    -- migrate delayMinutes (lama) -> delaySeconds
    if SHS.delaySeconds == nil and SHS.delayMinutes ~= nil then
        local oldMin = tonumber(SHS.delayMinutes)
        if oldMin and oldMin > 0 then
            SHS.delaySeconds = math.floor(oldMin * 60)
        end
    end

    SHS.delaySeconds = tonumber(SHS.delaySeconds) or 30
    if SHS.delaySeconds < 1 then SHS.delaySeconds = 1 end
    if SHS.delaySeconds > 86400 then SHS.delaySeconds = 86400 end

    SHS.selectedPetTypes = type(SHS.selectedPetTypes) == "table"
        and SHS.selectedPetTypes
        or {}
    SHS.selectedSkinTypes = type(SHS.selectedSkinTypes) == "table"
        and SHS.selectedSkinTypes
        or {}

    if type(SHS.status) ~= "string" then
        SHS.status = statusText
    end

    MK.snipe = type(MK.snipe) == "table" and MK.snipe or {}
    MK.snipe.rules = type(MK.snipe.rules) == "table" and MK.snipe.rules or {}
    MK.snipe.rulesBase = type(MK.snipe.rulesBase) == "table" and MK.snipe.rulesBase or {}

    return STATE, MK, SHS
end

local function cleanName(s)
    s = tostring(s or "")
    s = s:gsub("^%s+", ""):gsub("%s+$", "")
    return s
end

local function mapToList(map)
    local out = {}

    if type(map) == "table" then
        for key, on in pairs(map) do
            if on == true then
                local name = cleanName(key)
                if name ~= "" then
                    table.insert(out, name)
                end
            end
        end
    end

    table.sort(out)
    return out
end

local function collectSnipeRules(MK)
    local rules = {}
    if MK and MK.snipe then
        if type(MK.snipe.rules) == "table" then
            for k, v in pairs(MK.snipe.rules) do rules[k] = v end
        end
        if type(MK.snipe.rulesBase) == "table" then
            for k, v in pairs(MK.snipe.rulesBase) do rules[k] = v end
        end
    end
    return rules
end

local function getPetTypesFromSnipeRules(MK)
    local out = {}
    local seen = {}
    local rules = collectSnipeRules(MK)

    for _, rec in pairs(rules) do
        if type(rec) == "table" then
            local kind = tostring(rec.kind or "pet"):lower()
            if kind == "pet" then
                local petType = cleanName(rec.petType)
                if petType ~= "" and not seen[petType] then
                    seen[petType] = true
                    table.insert(out, petType)
                end
            end
        end
    end

    table.sort(out)
    return out
end

local function getSkinTypesFromSnipeRules(MK)
    local out = {}
    local seen = {}
    local rules = collectSnipeRules(MK)

    for _, rec in pairs(rules) do
        if type(rec) == "table" then
            local kind = tostring(rec.kind or "pet"):lower()
            if kind == "skin" then
                local skinType = cleanName(rec.skinType)
                if skinType ~= "" and not seen[skinType] then
                    seen[skinType] = true
                    table.insert(out, skinType)
                end
            end
        end
    end

    table.sort(out)
    return out
end

-- returns array of { itemType, itemName, label }
local function getTargetItems()
    local _, MK, SHS = getState()
    local out = {}

    local pets, skins
    if SHS.syncFromSnipeList == true then
        pets = getPetTypesFromSnipeRules(MK)
        skins = getSkinTypesFromSnipeRules(MK)
    else
        pets = mapToList(SHS.selectedPetTypes)
        skins = mapToList(SHS.selectedSkinTypes)
    end

    for _, name in ipairs(pets) do
        out[#out + 1] = {
            itemType = ITEM_TYPE_PET,
            itemName = name,
            label = "Pet:" .. name,
        }
    end
    -- Batas pet / booth skin (Config Snipe) sudah tercapai → jangan cari seller kategori itu
    local snipe = rawget(_G, "snipe_loop")
    if type(snipe) == "table" then
        if type(snipe.PetLimitReached) == "function" then
            local okLim, reached = pcall(snipe.PetLimitReached)
            if okLim and reached == true then
                pets = {}
            end
        end
        if type(snipe.SkinLimitReached) == "function" then
            local okLim, reached = pcall(snipe.SkinLimitReached)
            if okLim and reached == true then
                skins = {}
            end
        end
    end

    for _, name in ipairs(skins) do
        out[#out + 1] = {
            itemType = ITEM_TYPE_SKIN,
            itemName = name,
            label = "Skin:" .. name,
        }
    end

    return out
end

local function getSnipeModule()
    local G = (getgenv and getgenv()) or _G
    return rawget(_G, "snipe_loop") or rawget(G, "snipe_loop")
end

-- true = masih ada pet sesuai Snipe tab di server ini → jangan hop dulu
local function shouldWaitForSnipeBuy()
    local snipe = getSnipeModule()
    if type(snipe) ~= "table" or type(snipe.HasPendingBuy) ~= "function" then
        pendingSince = nil
        return false
    end

    local ok, pending, count = pcall(snipe.HasPendingBuy)
    if not ok or pending ~= true then
        pendingSince = nil
        return false
    end

    pendingSince = pendingSince or os.clock()

    local _, _, SHS = getStateSafe()
    local maxWait = tonumber(SHS.waitBuyMaxSec) or WAIT_BUY_MAX_SEC
    local waited = os.clock() - pendingSince
    if maxWait > 0 and waited >= maxWait then
        log("Tunggu buy snipe melewati batas, tetap hop:", math.floor(waited))
        return false
    end

    setStatus(string.format("Tunggu buy snipe: %d pet (%ds)", tonumber(count) or 0, math.floor(waited)))
    return true
end

local function waitTeleportResult(jobBefore)
    local failed = false
    local conn

    pcall(function()
        conn = TeleportService.TeleportInitFailed:Connect(function()
            failed = true
        end)
    end)

    local t0 = os.clock()
    while running and (os.clock() - t0) < TELEPORT_CONFIRM_SEC do
        if failed then
            break
        end

        local jobNow = tostring(game.JobId or "")
        if jobNow ~= "" and jobNow ~= jobBefore then
            if conn then pcall(function() conn:Disconnect() end) end
            return true
        end

        local leaving = false
        pcall(function()
            leaving = LP and LP.Parent == nil
        end)
        if leaving then
            if conn then pcall(function() conn:Disconnect() end) end
            return true
        end

        task.wait(0.25)
    end

    if conn then
        pcall(function() conn:Disconnect() end)
    end

    if failed then
        return false
    end

    -- masih di server yang sama = teleport gagal / tidak jadi
    local jobNow = tostring(game.JobId or "")
    if jobNow == jobBefore then
        return false
    end

    return true
end

-- returns: "teleported" | "no_seller" | "tp_fail" | "error"
local function findSellerOnce(itemType, itemName)
    itemType = tostring(itemType or ITEM_TYPE_PET)
    itemName = cleanName(itemName)
    if itemName == "" then
        return "error"
    end

    if not TokenRAPUtil or type(TokenRAPUtil.GetDefaultItemData) ~= "function" then
        warnlog("TokenRAPUtil belum ready")
        setStatus("TokenRAPUtil missing")
        return "error"
    end

    if not FindSellers or not TeleportToListing then
        warnlog("TokenRAPs remote belum ready")
        setStatus("TokenRAPs missing")
        return "error"
    end

    local itemData = nil

    local okData, errData = pcall(function()
        itemData = TokenRAPUtil.GetDefaultItemData(itemType, itemName)
    end)

    if not okData or not itemData then
        warnlog("Item data tidak ketemu:", itemType, itemName, errData)
        setStatus("Item data missing: " .. itemType .. "/" .. itemName)
        return "error"
    end

    setStatus("Cari seller: " .. itemType .. "/" .. itemName)
    log("Cari seller:", itemType, itemName)

    local ok, hasSeller, listingData = pcall(function()
        return FindSellers:InvokeServer(itemType, itemData)
    end)

    if not ok then
        warnlog("FindSellers error:", itemType, itemName, hasSeller)
        setStatus("FindSellers error: " .. itemName)
        return "error"
    end

    if not (hasSeller and listingData) then
        log("Tidak ada seller online:", itemType, itemName)
        setStatus("Tidak ada seller: " .. itemName)
        return "no_seller"
    end

    -- Cek lagi tepat sebelum teleport (listing baru bisa muncul saat scan)
    if shouldWaitForSnipeBuy() then
        return "pending_buy"
    end

    local jobBefore = tostring(game.JobId or "")

    setStatus("Teleport: " .. itemName)
    log("Seller ketemu:", itemType, itemName, "teleport...")

    local okTp, errTp = pcall(function()
        return TeleportToListing:InvokeServer(listingData)
    end)

    if not okTp then
        warnlog("TeleportToListing error:", itemName, errTp)
        setStatus("Teleport gagal: " .. itemName)
        return "tp_fail"
    end

    setStatus("Menunggu teleport: " .. itemName)
    local confirmed = waitTeleportResult(jobBefore)

    if confirmed then
        setStatus("Teleport OK: " .. itemName)
        return "teleported"
    end

    warnlog("Teleport tidak terkonfirmasi, lanjut cari seller:", itemName)
    setStatus("Teleport gagal (retry): " .. itemName)
    return "tp_fail"
end

function M.Tick()
    if busy then
        return false
    end

    busy = true

    local ok, found = pcall(function()
        local _, _, SHS = getState()

        if SHS.enabled ~= true then
            setStatus("Disabled")
            return false
        end

        local targets = getTargetItems()

        if #targets <= 0 then
            warnlog("Target kosong (pet/skin)")
            setStatus("Target kosong (pet/skin)")
            return false
        end

        log("Target count:", #targets, "sync:", SHS.syncFromSnipeList)
        setStatus(string.format("Scan %d target...", #targets))

        for i, t in ipairs(targets) do
            if not running or SHS.enabled ~= true then
                break
            end

            local label = t.label or (t.itemType .. "/" .. t.itemName)
            setStatus(string.format("Scan %d/%d: %s", i, #targets, label))

            local result = findSellerOnce(t.itemType, t.itemName)

            if result == "teleported" then
                return true
            end

            if result == "pending_buy" then
                return false
            end

            -- tp_fail / no_seller / error -> lanjut target berikutnya
            task.wait(0.8)
        end

        setStatus("Tidak ketemu, scan ulang...")
        return false
    end)

    busy = false

    if not ok then
        warnlog("Tick error:", found)
        setStatus("Tick error")
        return false
    end

    return found == true
end

function M.Start()
    if running then
        return
    end

    running = true
    log("START")
    setStatus("Starting...")

    task.spawn(function()
        ------------------------------------------------
        -- DELAY AWAL SAJA (detik)
        ------------------------------------------------
        local _, _, SHS = getState()

        local delaySec = tonumber(SHS.delaySeconds) or 30
        if delaySec < 1 then
            delaySec = 1
        end

        log("Initial wait:", delaySec)

        local t0 = os.clock()
        while running and (os.clock() - t0) < delaySec do
            local left = math.max(0, math.ceil(delaySec - (os.clock() - t0)))
            setStatus(string.format("Delay %ds...", left))
            task.wait(1)
        end

        ------------------------------------------------
        -- LOOP CEPAT — tetap jalan walau teleport gagal
        ------------------------------------------------
        while running do
            local _, _, cur = getState()

            if cur.enabled ~= true then
                setStatus("Disabled")
                task.wait(1)
            elseif shouldWaitForSnipeBuy() then
                task.wait(1)
            else
                local found = M.Tick()

                if found then
                    -- teleport terkonfirmasi; biasanya place unload.
                    -- jika masih di sini, jangan stop permanen — lanjut cari.
                    setStatus("Teleport OK, cek ulang...")
                    task.wait(2)

                    local stillHere = true
                    pcall(function()
                        stillHere = LP ~= nil and LP.Parent ~= nil
                    end)

                    if not stillHere then
                        setStatus("Left server")
                        break
                    end

                    setStatus("Masih di server, lanjut cari seller...")
                end

                task.wait(1)
            end
        end

        if not running then
            setStatus("Stopped")
        end
        log("STOPPED")
    end)
end

function M.Stop()
    running = false
    busy = false
    setStatus("Stopped")
    log("STOP")
end

function M.IsRunning()
    return running == true
end

function M.SetDebug(v)
    DEBUG = v == true
end

function M.GetTargets()
    return getTargetItems()
end

function M.GetStatus()
    return statusText
end

function M.GetStatusText()
    return statusText
end

_G.auto_snipe_seller_hop = M
_G.AutoSnipeSellerHop = M

return M

        end,
        required = false,
    },

    {
        key = "market_result",
        name = "market_result",
        factory = function()
            -- market_result.lua
-- Agregasi hasil market: SELL (booth sold) + BUY (snipe sukses)
-- Bucket: SELL|BUY | PET | {PetType} | {kgBucket} | {LT100|GE100}
-- File: nodehub/market/market_result_{username}.json

local MarketResult = {}

local HttpService = game:GetService("HttpService")
local Players     = game:GetService("Players")
local RS          = game:GetService("ReplicatedStorage")

local LP = Players.LocalPlayer
local USERNAME = (LP and LP.Name) or "Unknown"

