local ARCHIVE_DIR = SAVE_DIR .. "/archive"
local DATA_FILE = string.format("%s/market_result_%s.json", SAVE_DIR, USERNAME)

local DATA_VERSION = 2
local MAX_SEEN_IDS = 1200
local MAX_RECENT = 80
local TICK_SEC = 30

local _STATE = nil
local _SaveState = nil
local _data = nil
local _dirty = false
local _workerStarted = false
local _sending = false
local _scalePerLvl = nil
local _debug = false
-- Trade baru menunggu kirim ke NodeMonitor (1x saja, bukan resend list).
local _pendingMonitor = {}

if rawget(_G, "MARKET_RESULT_DEBUG") == nil then
    _G.MARKET_RESULT_DEBUG = false
end

