local function trim(s)
    s = tostring(s or "")
    return (s:match("^%s*(.-)%s*$"))
end

local function getWB()
    local S = rawget(_G, "STATE") or _STATE
    if type(S) == "table" and type(S.webhook) == "table" then
        return S.webhook
    end
    return {}
end

local function getSendIntervalMinutes()
    local W = getWB()
    local mins = tonumber(W.resultSendMinutes or W.resultSendHours) or 60
    if mins < 1 then mins = 60 end
    return mins
end

local function getPetInventorySendIntervalMinutes()
    local W = getWB()
    local mins = tonumber(W.petInventorySendMinutes) or 60
    if mins < 1 then mins = 60 end
    return mins
end

local function isPetInventoryEnabled()
