local function canRead()
    return (type(readfile) == "function") and (type(isfile) == "function")
end

local function canWrite()
    return (type(writefile) == "function")
end

local function ensureDirs()
    if not makefolder then return end
    pcall(function()
        if isfolder and not isfolder(SAVE_DIR) then makefolder(SAVE_DIR) end
        if isfolder and not isfolder(ARCHIVE_DIR) then makefolder(ARCHIVE_DIR) end
    end)
end

local function getScalePerLvl()
    if _scalePerLvl ~= nil then return _scalePerLvl end
    local scale = 0
    pcall(function()
        local PetRegistry = require(RS.Data.PetRegistry)
        scale = PetRegistry
            and PetRegistry.PetConfig
            and PetRegistry.PetConfig.WEIGHT_CONFIG
            and PetRegistry.PetConfig.WEIGHT_CONFIG.SCALE_PERCENTAGE_OF_BASE_WEIGHT_PER_LEVEL
            or 0
    end)
    _scalePerLvl = tonumber(scale) or 0
    return _scalePerLvl
end

local function resolveBaseKg(baseKg, kg, age, baseWeight)
    local bk = tonumber(baseKg)
    if bk and bk > 0 then return bk end

    local bw = tonumber(baseWeight)
    if bw and bw > 0 then
        local scale = getScalePerLvl()
        return bw * (1 + scale * 1)
    end

    local k = tonumber(kg)
    local a = tonumber(age)
    if k and k > 0 and a and a > 0 then
        local scale = getScalePerLvl()
        local denom = 1 + scale * a
        if denom > 0 then
            local base = k / denom
            return base * (1 + scale * 1)
        end
    end

    return k
end

local function kgBucketFromBaseKg(baseKg)
    local n = tonumber(baseKg)
    if not n or n <= 0 then return "NA" end
    return tostring(math.floor(n))
end

local function ageBand(age)
    local a = tonumber(age)
    if not a then return "LT100" end
    if a >= 100 then return "GE100" end
    return "LT100"
end

local function itemKindFromPayload(payload, item)
    item = item or (type(payload) == "table" and payload.item) or {}
    local t = item.type or item.itemType or payload.itemType
    if t ~= nil then
        local s = tostring(t):lower()
        if s:find("pet") then return "PET" end
        return "ITEM"
    end
    if item.ptype or item.name or item.petType then return "PET" end
    return "ITEM"
end

local function petTypeName(item, payload)
    item = item or {}
    return tostring(item.ptype or item.name or item.petType or item.nameRaw or payload.petType or "Unknown")
end

local function makeBucketKey(side, kind, petType, kgBucket, band)
    return table.concat({ side, kind, petType, kgBucket, band }, "|")
end

-- Trade Token Reader (DataService only — profile.TradeData.Tokens)
local function formatTokenComma(n)
    n = math.floor(tonumber(n) or 0)
    local s = tostring(n)
    local out = s:reverse():gsub("(%d%d%d)", "%1,"):reverse()
    if out:sub(1, 1) == "," then out = out:sub(2) end
    return out
end

local function getPlayerProfile()
    local ok, profile = pcall(function()
        local mods = RS:FindFirstChild("Modules")
        local dsMod = mods and mods:FindFirstChild("DataService")
        if not dsMod then return nil end
        local DS = require(dsMod)
        if DS and type(DS.GetData) == "function" then
            return DS:GetData()
        end
        return nil
    end)
    if ok and type(profile) == "table" then return profile end
    return nil
end

local function pickTokenFromProfile(profile)
    if type(profile) ~= "table" then return nil end
    local td = profile.TradeData
    if type(td) == "table" then
        local n = tonumber(td.Tokens) or tonumber(td.TradeTokens)
        if n and n >= 0 then return n end
    end
    for _, c in ipairs({
        profile.TradeTokens,
        profile.TradeToken,
        profile.Tokens,
        profile.tokens,
    }) do
        local n = tonumber(c)
        if n and n >= 0 then return n end
    end
    return nil
end

local function getTradeTokenBalance()
    local n = pickTokenFromProfile(getPlayerProfile())
    if n ~= nil then return n, tostring(n) end
    return nil, nil
end

local function getTradeTokenText()
    local n, t = getTradeTokenBalance()
    if t then return t end
    if n then return formatTokenComma(n) end
    return nil
end

local function getTrackedNet()
    local sellT = tonumber(_data.totals.sellTokens) or 0
    local buyT  = tonumber(_data.totals.buyTokens) or 0
    return sellT - buyT
end

local function noteTokenSnap(balance, sourceText)
    balance = tonumber(balance)
    if balance == nil then return end
    _data.lastTokenSnap = {
        balance    = math.floor(balance),
        trackedNet = getTrackedNet(),
        at         = os.time(),
        text       = sourceText,
    }
    _dirty = true
end

local function snapTokenBalance()
    local n, t = getTradeTokenBalance()
    if n ~= nil then
        noteTokenSnap(n, t)
    end
    return n
end

local function ensureTokenStart()
    local trackedNet = getTrackedNet()
    local n = snapTokenBalance()
    if n ~= nil then
        if _data.tokenStart == nil then
            _data.tokenStart = math.floor(n - trackedNet)
            _data.tokenStartText = formatTokenComma(_data.tokenStart)
            _dirty = true
        end
        return
    end

    if _data.tokenStart ~= nil then return end

    if type(_data.lastTokenSnap) == "table" then
        local snapBal = tonumber(_data.lastTokenSnap.balance)
        local snapNet = tonumber(_data.lastTokenSnap.trackedNet) or 0
        if snapBal ~= nil then
            local estNow = snapBal + (trackedNet - snapNet)
            _data.tokenStart = math.floor(estNow - trackedNet)
            _data.tokenStartText = formatTokenComma(_data.tokenStart)
            _dirty = true
        end
    end
end

local function resolveWalletValues(trackedNet)
    ensureTokenStart()

    local tokenStart = tonumber(_data.tokenStart)
    local tokenStartText = _data.tokenStartText
    local tokenNow, tokenNowText = getTradeTokenBalance()
    local source = "live"

    if tokenNow == nil and type(_data.lastTokenSnap) == "table" then
        local snap = _data.lastTokenSnap
        local snapBal = tonumber(snap.balance)
        local snapNet = tonumber(snap.trackedNet) or 0
        if snapBal ~= nil then
            tokenNow = math.floor(snapBal + (trackedNet - snapNet))
            tokenNowText = snap.text or formatTokenComma(tokenNow)
            source = "snap"
        end
    end

    if tokenNow == nil and tokenStart ~= nil then
        tokenNow = math.floor(tokenStart + trackedNet)
        tokenNowText = formatTokenComma(tokenNow)
        source = "calc"
    end

    if tokenStart == nil and tokenNow ~= nil then
        tokenStart = math.floor(tokenNow - trackedNet)
        tokenStartText = formatTokenComma(tokenStart)
        source = "calc"
    end

    if tokenStartText == nil and tokenStart ~= nil then
        tokenStartText = formatTokenComma(tokenStart)
    end
    if tokenNowText == nil and tokenNow ~= nil then
        tokenNowText = formatTokenComma(tokenNow)
    end

    return tokenStart, tokenNow, tokenStartText, tokenNowText, source
end

local function buildWalletSnapshot()
    local sellT = tonumber(_data.totals.sellTokens) or 0
    local buyT  = tonumber(_data.totals.buyTokens) or 0
    local trackedNet = sellT - buyT

    local tokenStart, tokenNow, tokenStartText, tokenNowText, source =
        resolveWalletValues(trackedNet)

    local walletDelta = nil
    local expectedNow = nil
    local balanceMatch = nil

    if tokenStart ~= nil and tokenNow ~= nil then
        walletDelta = tokenNow - tokenStart
        expectedNow = tokenStart + trackedNet
        balanceMatch = (walletDelta == trackedNet)
    end

    return {
        tokenStart     = tokenStart,
        tokenStartText = tokenStartText,
        tokenNow       = tokenNow,
        tokenNowText   = tokenNowText,
        tokenSource    = source,
        trackedIn      = sellT,
        trackedOut     = buyT,
        trackedNet     = trackedNet,
        walletDelta    = walletDelta,
        expectedNow    = expectedNow,
        balanceMatch   = balanceMatch,
    }
end

local function captureTokenAfterTrade(_tokenText)
    task.defer(function()
        for _ = 1, 6 do
            task.wait(0.35)
            local n, t = getTradeTokenBalance()
            if n ~= nil then
                noteTokenSnap(n, t)
                ensureTokenStart()
                saveData(false)
                return
            end
        end
    end)
end

local function freshData()
    local t = os.time()
    local tokenStart, tokenStartText, lastTokenSnap = nil, nil, nil
    local n, ttxt = getTradeTokenBalance()
    if n ~= nil then
        tokenStart = math.floor(n)
        tokenStartText = ttxt or formatTokenComma(n)
        lastTokenSnap = {
            balance    = tokenStart,
            trackedNet = 0,
            at         = t,
            text       = tokenStartText,
        }
    end
    return {
        version       = DATA_VERSION,
        username      = USERNAME,
        periodStart   = t,
        lastResetAt   = t,
        tokenStart    = tokenStart,
        tokenStartText = tokenStartText,
        lastTokenSnap = lastTokenSnap,
        seenIds       = {},
        buckets       = {},
        recent        = {},
        totals        = {
            sellTokens = 0,
            buyTokens  = 0,
            sellCount  = 0,
            buyCount   = 0,
        },
    }
end

local function pruneSeenIds(seen)
    if type(seen) ~= "table" then return {} end
    local n = 0
    for _ in pairs(seen) do n += 1 end
    if n <= MAX_SEEN_IDS then return seen end

    local arr = {}
    for id, at in pairs(seen) do
        arr[#arr + 1] = { id = id, at = tonumber(at) or 0 }
    end
    table.sort(arr, function(a, b) return a.at < b.at end)

    local keep = {}
    local start = math.max(1, #arr - math.floor(MAX_SEEN_IDS * 0.7) + 1)
    for i = start, #arr do
        keep[arr[i].id] = arr[i].at
    end
    return keep
end

local function loadData()
    ensureDirs()
    if not canRead() or not isfile(DATA_FILE) then
        return freshData()
    end

    local ok, raw = pcall(readfile, DATA_FILE)
    if not ok or type(raw) ~= "string" or raw == "" then
        return freshData()
    end

    local ok2, dec = pcall(function()
        return HttpService:JSONDecode(raw)
    end)
    if not ok2 or type(dec) ~= "table" then
        return freshData()
    end

    dec.seenIds = type(dec.seenIds) == "table" and dec.seenIds or {}
    dec.buckets = type(dec.buckets) == "table" and dec.buckets or {}
    dec.recent  = type(dec.recent) == "table" and dec.recent or {}
    dec.totals  = type(dec.totals) == "table" and dec.totals or {}
    dec.totals.sellTokens = tonumber(dec.totals.sellTokens) or 0
    dec.totals.buyTokens  = tonumber(dec.totals.buyTokens) or 0
    dec.totals.sellCount  = tonumber(dec.totals.sellCount) or 0
    dec.totals.buyCount   = tonumber(dec.totals.buyCount) or 0
    dec.periodStart = tonumber(dec.periodStart) or os.time()
    dec.lastResetAt = tonumber(dec.lastResetAt) or dec.periodStart
    dec.tokenStart = tonumber(dec.tokenStart)
    dec.tokenStartText = type(dec.tokenStartText) == "string" and dec.tokenStartText or nil
    if type(dec.lastTokenSnap) == "table" then
        dec.lastTokenSnap.balance = tonumber(dec.lastTokenSnap.balance)
        dec.lastTokenSnap.trackedNet = tonumber(dec.lastTokenSnap.trackedNet) or 0
        dec.lastTokenSnap.at = tonumber(dec.lastTokenSnap.at) or 0
    else
        dec.lastTokenSnap = nil
    end
    dec.version = tonumber(dec.version) or DATA_VERSION
    dec.username = USERNAME
    return dec
end

local function saveData(force)
    if not _dirty and not force then return end
    if not canWrite() then return end
    ensureDirs()

    _data.seenIds = pruneSeenIds(_data.seenIds)

    local ok, body = pcall(function()
        return HttpService:JSONEncode(_data)
    end)
    if not ok or type(body) ~= "string" then return end

    pcall(function()
        writefile(DATA_FILE, body)
    end)
    _dirty = false
end

local function touchBucket(side, kind, petType, kgBucket, band, price)
    local key = makeBucketKey(side, kind, petType, kgBucket, band)
    local b = _data.buckets[key]
    if type(b) ~= "table" then
        b = {
            side     = side,
            kind     = kind,
            petType  = petType,
            kgBucket = kgBucket,
            ageBand  = band,
            count    = 0,
            tokens   = 0,
            lastAt   = 0,
        }
        _data.buckets[key] = b
    end

    b.count  = (tonumber(b.count) or 0) + 1
    b.tokens = (tonumber(b.tokens) or 0) + price
    b.lastAt = os.time()
    _dirty = true
end

local function slimRecentRow(row)
    if type(row) ~= "table" then return nil end
    return {
        id = tostring(row.id or ""),
        side = tostring(row.side or "sold"),
        kind = tostring(row.kind or ""),
        name = tostring(row.name or "Item"),
        price = tonumber(row.price) or 0,
        fee = tonumber(row.fee) or 0,
        at = tonumber(row.at) or 0,
        kg = tonumber(row.kg) or 0,
        base_kg = tonumber(row.base_kg or row.baseKg) or 0,
        baseKg = tonumber(row.base_kg or row.baseKg) or 0,
        age = tonumber(row.age) or 0,
        muts = tostring(row.muts or "None"),
        peer = tostring(row.peer or ""),
    }
end

local function queuePendingMonitor(row)
    local slim = slimRecentRow(row)
    if not slim then return end
    local id = tostring(slim.id or "")
    if id ~= "" then
        for i = 1, #_pendingMonitor do
            local p = _pendingMonitor[i]
            if type(p) == "table" and tostring(p.id or "") == id then
                return
            end
        end
    end
    table.insert(_pendingMonitor, 1, slim)
    while #_pendingMonitor > MAX_RECENT do
        table.remove(_pendingMonitor)
    end
end

local function drainPendingMonitorHistory()
    if type(_pendingMonitor) ~= "table" or #_pendingMonitor == 0 then
        return {}
    end
    local out = _pendingMonitor
    _pendingMonitor = {}
    return out
end

local function pushRecent(row)
    if type(_data) ~= "table" or type(row) ~= "table" then return end
    if type(_data.recent) ~= "table" then _data.recent = {} end
    table.insert(_data.recent, 1, row)
    while #_data.recent > MAX_RECENT do
        table.remove(_data.recent)
    end
    queuePendingMonitor(row)
    _dirty = true
end

local function slimRecent(list)
    local out = {}
    if type(list) ~= "table" then return out end
    local n = math.min(#list, MAX_RECENT)
    for i = 1, n do
        local row = slimRecentRow(list[i])
        if row then
            out[#out + 1] = row
        end
    end
    return out
end

-- Monitor web: max 10 sold + 10 buy (newest first)
local function slimRecentForMonitor(list, maxEach)
    maxEach = math.max(1, math.floor(tonumber(maxEach) or 10))
    local sold, buy = {}, {}
    if type(list) ~= "table" then
        return {}
    end
    for i = 1, #list do
        local raw = list[i]
        if type(raw) == "table" then
            local side = tostring(raw.side or "sold"):lower()
            local row = slimRecentRow(raw)
            if row then
                if side == "buy" then
                    if #buy < maxEach then
                        buy[#buy + 1] = row
                    end
                else
                    if #sold < maxEach then
                        sold[#sold + 1] = row
                    end
                end
            end
        end
        if #sold >= maxEach and #buy >= maxEach then
            break
        end
    end
    local out = {}
    for i = 1, #sold do out[#out + 1] = sold[i] end
    for i = 1, #buy do out[#out + 1] = buy[i] end
    table.sort(out, function(a, b)
        return (tonumber(a.at) or 0) > (tonumber(b.at) or 0)
    end)
    return out
end

local function mutsText(muts)
    if type(muts) == "string" then
        local t = trim(muts)
        if t == "" or t == "Normal" or t == "None" then
            return "None"
        end
        return t
    end
    if type(muts) ~= "table" then
        return "None"
    end
    local clean = {}
    local seen = {}
    for k, v in pairs(muts) do
        local m = (type(k) == "string" and tonumber(k) == nil) and k or v
        m = trim(m)
        if m ~= "" and m ~= "Normal" and m ~= "None" then
            local key = string.lower(m)
            if not seen[key] then
                seen[key] = true
                clean[#clean + 1] = m
            end
        end
    end
    if #clean == 0 then
        return "None"
    end
    table.sort(clean, function(a, b)
        return string.lower(a) < string.lower(b)
    end)
    return table.concat(clean, ", ")
end

local function recordSide(side, opts)
    opts = opts or {}
    local id = trim(opts.id)
    if id == "" then return false, "NO_ID" end

    if _data.seenIds[id] then
        return false, "DEDUPED"
    end

    local price = tonumber(opts.price) or 0
    if price <= 0 then return false, "NO_PRICE" end

    local item = opts.item or {}
    local kind = tostring(opts.kind or itemKindFromPayload(opts, item)):upper()
    if kind == "" then kind = "PET" end

    local ptype = petTypeName(item, opts)
    local band = ageBand(opts.age or item.age)
    local baseKg = resolveBaseKg(opts.baseKg or item.baseKg, opts.kg or item.kg, opts.age or item.age, opts.baseWeight or item.baseWeight)
    local bucket = kgBucketFromBaseKg(baseKg)
    if kind ~= "PET" then
        bucket = "NA"
        if ptype == "" or ptype == "Unknown" then
            ptype = tostring(item.name or item.nameRaw or "Item")
        end
    end

    _data.seenIds[id] = os.time()
    ensureTokenStart()

    if side == "SELL" then
        _data.totals.sellTokens = (tonumber(_data.totals.sellTokens) or 0) + price
        _data.totals.sellCount  = (tonumber(_data.totals.sellCount) or 0) + 1
    else
        _data.totals.buyTokens = (tonumber(_data.totals.buyTokens) or 0) + price
        _data.totals.buyCount  = (tonumber(_data.totals.buyCount) or 0) + 1
    end

    touchBucket(side, kind, ptype, bucket, band, price)
    local peer = ""
    if side == "SELL" then
        local buyer = opts.buyer
        if type(buyer) == "table" then
            peer = trim(buyer.username or buyer.Name)
        else
            peer = trim(buyer)
        end
    else
        local seller = opts.seller
        if type(seller) == "table" then
            peer = trim(seller.username or seller.Name)
        else
            peer = trim(seller)
        end
    end
    pushRecent({
        id = id,
        side = side == "BUY" and "buy" or "sold",
        kind = kind,
        name = ptype,
        price = price,
        fee = tonumber(opts.fee) or 0,
        at = os.time(),
        kg = tonumber(opts.kg or item.kg) or 0,
        base_kg = tonumber(baseKg) or 0,
        baseKg = tonumber(baseKg) or 0,
        age = tonumber(opts.age or item.age) or 0,
        muts = mutsText(opts.muts or item.muts),
        peer = peer,
    })
    saveData(false)
    captureTokenAfterTrade(opts.tokenText)

    local mon = rawget(_G, "MarketMonitor")
    if type(mon) == "table" and type(mon.Push) == "function" then
        task.defer(function()
            pcall(mon.Push, mon, "market_" .. string.lower(side))
        end)
    end

    return true, "OK"
end

function MarketResult.GetMonitorSnapshot()
    if type(_data) ~= "table" then
        return {
            tokenStart = 0,
            tokenNow = 0,
            sellCount = 0,
            sellTokens = 0,
            buyCount = 0,
            buyTokens = 0,
            netTokens = 0,
            history = {},
        }
    end

    local sellT = tonumber(_data.totals.sellTokens) or 0
    local buyT = tonumber(_data.totals.buyTokens) or 0
    local sellC = tonumber(_data.totals.sellCount) or 0
    local buyC = tonumber(_data.totals.buyCount) or 0
    local trackedNet = sellT - buyT
    local tokenStart, tokenNow = resolveWalletValues(trackedNet)

    return {
        tokenStart = tonumber(tokenStart) or 0,
        tokenNow = tonumber(tokenNow) or 0,
        sellCount = sellC,
        sellTokens = sellT,
        buyCount = buyC,
        buyTokens = buyT,
        netTokens = trackedNet,
        history = drainPendingMonitorHistory(),
    }
end

function MarketResult.BuildSummary()
    local sellT = tonumber(_data.totals.sellTokens) or 0
    local buyT  = tonumber(_data.totals.buyTokens) or 0

    local rows = {}
    for _, b in pairs(_data.buckets or {}) do
        if type(b) == "table" then
            rows[#rows + 1] = {
                key      = makeBucketKey(b.side, b.kind, b.petType, b.kgBucket, b.ageBand),
                side     = b.side,
                kind     = b.kind,
                petType  = b.petType,
                kgBucket = b.kgBucket,
                ageBand  = b.ageBand,
                count    = tonumber(b.count) or 0,
                tokens   = tonumber(b.tokens) or 0,
                lastAt   = tonumber(b.lastAt) or 0,
            }
        end
    end

    table.sort(rows, function(a, b)
        if a.tokens ~= b.tokens then return a.tokens > b.tokens end
        return a.count > b.count
    end)

    local top = {}
    for i = 1, math.min(25, #rows) do
        top[i] = rows[i]
    end

    return {
        title        = "Market Result",
        periodStart  = tonumber(_data.periodStart) or os.time(),
        periodEnd    = os.time(),
        username     = USERNAME,
        totals = {
            sellTokens = sellT,
            buyTokens  = buyT,
            netTokens  = sellT - buyT,
            sellCount  = tonumber(_data.totals.sellCount) or 0,
            buyCount   = tonumber(_data.totals.buyCount) or 0,
        },
        wallet = buildWalletSnapshot(),
        bucketCount = #rows,
        topBuckets  = top,
        buckets     = rows,
    }
end

local function collectDatastorePets()
    local PLV = rawget(_G, "PetListView")
    if type(PLV) == "table" and type(PLV.listPetsAll) == "function" then
        local ok, res = pcall(function() return PLV.listPetsAll() end)
        if ok and type(res) == "table" then return res end
    end
    if type(PLV) == "table" and type(PLV.listPetsNotFav) == "function" then
        local ok, res = pcall(function() return PLV.listPetsNotFav() end)
        if ok and type(res) == "table" then return res end
    end
    return {}
end

function MarketResult.BuildPetInventory()
    local pets = collectDatastorePets()
    local byType = {}

    for _, p in ipairs(pets) do
        if type(p) == "table" then
            local typeName = tostring(p.petType or p.ptype or "Unknown")
            local bucket = byType[typeName]
            if type(bucket) ~= "table" then
                bucket = { pets = {} }
                byType[typeName] = bucket
            end
            bucket.pets[#bucket.pets + 1] = p
        end
    end

    local groups = {}
    for typeName, bucket in pairs(byType) do
        local clusters = {}
        for _, p in ipairs(bucket.pets) do
            local kg = tonumber(p.kg) or 0
            local age = math.floor(tonumber(p.age) or 1)
            if age < 1 then age = 1 end

            local kgKey = tostring(math.floor(kg))
            local c = clusters[kgKey]
            if type(c) ~= "table" then
                c = {
                    minKg  = kg,
                    maxKg  = kg,
                    minAge = age,
                    maxAge = age,
                    count  = 0,
                }
                clusters[kgKey] = c
            end

            if kg < c.minKg then c.minKg = kg end
            if kg > c.maxKg then c.maxKg = kg end
            if age < c.minAge then c.minAge = age end
            if age > c.maxAge then c.maxAge = age end
            c.count += 1
        end

        local lines = {}
        for _, c in pairs(clusters) do
            lines[#lines + 1] = {
                minKg  = c.minKg,
                maxKg  = c.maxKg,
                minAge = c.minAge,
                maxAge = c.maxAge,
                count  = c.count,
            }
        end

        table.sort(lines, function(a, b)
            if a.minKg ~= b.minKg then return a.minKg < b.minKg end
            return a.minAge < b.minAge
        end)

        groups[#groups + 1] = {
            petType = typeName,
            total   = #bucket.pets,
            lines   = lines,
        }
    end

    table.sort(groups, function(a, b)
        if a.total ~= b.total then return a.total > b.total end
        return tostring(a.petType) < tostring(b.petType)
    end)

    return {
        title     = "Pet Inventory",
        username  = USERNAME,
        totalPets = #pets,
        groups    = groups,
    }
end

function MarketResult.SendPetInventoryWebhook(periodKey, dedupeSec, dedupeKey)
    if not isPetInventoryEnabled() then
        return false, "INVENTORY_DISABLED"
    end

    local W = getWB()
    local Webhook = rawget(_G, "Webhook")
    if not Webhook or type(Webhook.Send) ~= "function" then
        return false, "NO_WEBHOOK"
    end

    periodKey = tostring(periodKey or (_data and _data.periodStart) or 0)
    dedupeSec = tonumber(dedupeSec) or (getPetInventorySendIntervalMinutes() * 60)
    dedupeKey = dedupeKey or ("MARKET_PET_BAG|" .. periodKey)

    local payload = MarketResult.BuildPetInventory()
    local ok, reason = Webhook.Send("MARKET_PET_BAG", payload, {
        shareToDC    = false,
        dedupeWindow = dedupeSec,
        dedupeKey    = dedupeKey,
    })

    log("SendPetInventoryWebhook ok=", ok, "reason=", reason, "total=", payload.totalPets)

    if not ok then
        log("MARKET_PET_BAG not sent:", tostring(reason),
            "| webhook enabled?", tostring(W.enabled),
            "| url set?", (type(W.targetUrl) == "string" and W.targetUrl ~= ""))
    end

    return ok, reason
end

function MarketResult.SendSummaryWebhook(opts)
    opts = opts or {}

    if not isResultEnabled() then
        return false, "RESULT_DISABLED"
    end

    if _sending then
        return false, "BUSY"
    end
    _sending = true

    local W = getWB()
    local Webhook = rawget(_G, "Webhook")
    if not Webhook or type(Webhook.Send) ~= "function" then
        _sending = false
        log("SendSummaryWebhook: NO_WEBHOOK module")
        return false, "NO_WEBHOOK"
    end

    local mins = getSendIntervalMinutes()
    local dedupeSec = mins * 60

    if opts.force ~= true and opts.periodic == true then
        if secondsSinceLastSent() < dedupeSec then
            _sending = false
            return false, "COOLDOWN"
        end
    end

    local sellC = tonumber(_data.totals.sellCount) or 0
    local buyC  = tonumber(_data.totals.buyCount) or 0
    local periodKey = tostring(_data.periodStart or 0)
    local okResult, reasonResult = false, "NO_DATA"

    -- Periodic: dedupe per period. Manual (force): key unik supaya tidak DEDUPED.
    local dedupeKeyResult = "MARKET_RESULT|" .. periodKey
    if opts.force == true then
        local stamp = tostring(os.time())
        dedupeKeyResult = "MARKET_RESULT|" .. periodKey .. "|force|" .. stamp
        dedupeSec = 10
    end

    if (sellC + buyC) > 0 then
        local summary = MarketResult.BuildSummary()
        okResult, reasonResult = Webhook.Send("MARKET_RESULT", summary, {
            shareToDC    = false,
            dedupeWindow = dedupeSec,
            dedupeKey    = dedupeKeyResult,
        })

        log("SendSummaryWebhook result ok=", okResult, "reason=", reasonResult, "sell=", sellC, "buy=", buyC)

        if not okResult then
            log("MARKET_RESULT not sent:", tostring(reasonResult),
                "| webhook enabled?", tostring(W.enabled),
                "| url set?", (type(W.targetUrl) == "string" and W.targetUrl ~= ""))
        end
    else
        log("skip MARKET_RESULT (no transactions)")
        reasonResult = "NO_DATA"
    end

    if okResult then
        markResultSentNow()
    elseif opts.periodic == true or opts.markAttempt == true then
        if reasonResult == "DEDUPED" or reasonResult == "QUEUED" then
            markResultSentNow()
        end
    end

    _sending = false

    if okResult then
        return true, "OK_RESULT"
    end
    return false, reasonResult or "FAILED"
end

function MarketResult.SendInventoryNow()
    if not isPetInventoryEnabled() then
        return false, "INVENTORY_DISABLED"
    end

    local periodKey = tostring(_data and _data.periodStart or 0)
    local stamp = tostring(os.time())
    local dedupeKey = "MARKET_PET_BAG|" .. periodKey .. "|force|" .. stamp
    local ok, reason = MarketResult.SendPetInventoryWebhook(periodKey, 10, dedupeKey)

    if ok then
        markPetInventorySentNow()
    elseif reason == "DEDUPED" or reason == "QUEUED" then
        markPetInventorySentNow()
    end

    return ok, reason
end

function MarketResult.SendResultNow()
    return MarketResult.SendSummaryWebhook({ force = true })
end

function MarketResult.Reset(archive)
    if archive ~= false and canWrite() and canRead() and isfile(DATA_FILE) then
        ensureDirs()
        local stamp = os.date("%Y%m%d_%H%M%S")
        local dest = string.format("%s/market_result_%s_%s.json", ARCHIVE_DIR, USERNAME, stamp)
        pcall(function()
            writefile(dest, readfile(DATA_FILE))
        end)
    end

    _data = freshData()
    _dirty = true
    saveData(true)

    local W = getWB()
    W.resultLastResetAt = os.time()
    if type(_SaveState) == "function" then
        pcall(_SaveState)
    end

    return true
end

function MarketResult.ResetResultNow()
    local sellC = tonumber(_data.totals.sellCount) or 0
    local buyC  = tonumber(_data.totals.buyCount) or 0
    if (sellC + buyC) > 0 then
        MarketResult.SendSummaryWebhook({ force = true })
    end
    return MarketResult.Reset(true)
end

function MarketResult.ResetResult()
    return MarketResult.Reset(true)
end

function MarketResult.RecordSell(payload)
    if type(payload) ~= "table" then return false, "BAD_PAYLOAD" end
    local item = payload.item or {}
    return recordSide("SELL", {
        id        = payload.id and ("SELL:" .. tostring(payload.id)) or nil,
        price     = payload.price,
        fee       = payload.fee,
        item      = item,
        kind      = itemKindFromPayload(payload, item),
        petType   = petTypeName(item, payload),
        baseKg    = item.baseKg or item.kgBase,
        kg        = item.kg or item.kgCurrent,
        age       = item.age,
        muts      = item.muts,
        tokenText = payload.token,
        buyer     = payload.buyer,
    })
end

function MarketResult.RecordBuy(opts)
    if type(opts) ~= "table" then return false, "BAD_OPTS" end
    local id = opts.id
    if not id then
        id = "BUY:" .. tostring(opts.listingUUID or opts.uuid or "?") .. ":" .. tostring(os.time())
    else
        id = "BUY:" .. tostring(id)
    end

    local item = type(opts.item) == "table" and opts.item or {}
    return recordSide("BUY", {
        id         = id,
        price      = opts.price,
        fee        = opts.fee,
        petType    = opts.petType,
        baseKg     = opts.baseKg or item.baseKg or item.kgBase,
        kg         = opts.kg or item.kg or item.kgCurrent,
        age        = opts.age or item.age,
        baseWeight = opts.baseWeight,
        muts       = opts.muts or item.muts,
        kind       = opts.kind or "PET",
        tokenText  = opts.token,
        seller     = opts.seller,
        item       = {
            ptype  = opts.petType,
            baseKg = opts.baseKg or item.baseKg or item.kgBase,
            kg     = opts.kg or item.kg or item.kgCurrent,
            age    = opts.age or item.age,
            muts   = opts.muts or item.muts,
        },
    })
end

local function maybeAutoReset()
    local W = getWB()
    local hours = tonumber(W.resultResetHours) or 24
    if hours < 1 then hours = 24 end

    local last = tonumber(W.resultLastResetAt) or tonumber(_data.lastResetAt) or _data.periodStart or 0
    local elapsed = os.time() - last
    if elapsed >= (hours * 3600) then
        MarketResult.SendSummaryWebhook({ force = true })
        MarketResult.Reset(true)
        return true
    end
    return false
end

local function maybePeriodicSend()
    if not isResultEnabled() then
        return
    end

    local mins = getSendIntervalMinutes()
    local elapsed = secondsSinceLastSent()

    if elapsed < (mins * 60) then
        return
    end

    local sellC = tonumber(_data.totals.sellCount) or 0
    local buyC  = tonumber(_data.totals.buyCount) or 0
    if (sellC + buyC) > 0 then
        MarketResult.SendSummaryWebhook({ periodic = true, markAttempt = true })
    end
end

local function maybePeriodicInventorySend()
    if not isPetInventoryEnabled() then
        return
    end

    local mins = getPetInventorySendIntervalMinutes()
    if secondsSinceLastInventorySent() < (mins * 60) then
        return
    end

    local periodKey = tostring(_data.periodStart or 0)
    local ok, reason = MarketResult.SendPetInventoryWebhook(periodKey, mins * 60, "MARKET_PET_BAG|" .. periodKey)

    if ok then
        markPetInventorySentNow()
    elseif reason == "DEDUPED" or reason == "QUEUED" then
        markPetInventorySentNow()
    end
end

local function startWorker()
    if _workerStarted then return end
    _workerStarted = true

    task.spawn(function()
        while true do
            task.wait(TICK_SEC)
            pcall(function()
                local wb = getWB()
                if wb.resultResetNow == true then
                    wb.resultResetNow = false
                    MarketResult.ResetResultNow()
                else
                    maybeAutoReset()
                    maybePeriodicSend()
                end
                maybePeriodicInventorySend()
                ensureTokenStart()
            end)
            if _dirty then
                saveData(false)
            end
        end
    end)
end

function MarketResult.Init(opts)
    opts = opts or {}
    _STATE = (type(opts.STATE) == "table") and opts.STATE or rawget(_G, "STATE") or {}
    _SaveState = opts.SaveState
    if opts.debug ~= nil then
        MarketResult.SetDebug(opts.debug == true)
    elseif _G.MARKET_RESULT_DEBUG == true then
        _debug = true
    end

    _data = loadData()
    _dirty = false
    ensureTokenStart()

    local W = getWB()
    W.resultResetHours   = tonumber(W.resultResetHours) or 24
    W.resultSendMinutes  = tonumber(W.resultSendMinutes or W.resultSendHours) or 60
    W.resultLastResetAt  = tonumber(W.resultLastResetAt) or _data.lastResetAt
    W.resultLastSentAt   = tonumber(W.resultLastSentAt) or 0
    if W.petInventoryEnabled == nil then
        W.petInventoryEnabled = true
    else
        W.petInventoryEnabled = (W.petInventoryEnabled == true)
    end
    W.petInventorySendMinutes = tonumber(W.petInventorySendMinutes) or 60
    if W.petInventorySendMinutes < 1 then W.petInventorySendMinutes = 60 end
    W.petInventoryLastSentAt  = tonumber(W.petInventoryLastSentAt) or 0
    if W.resultEnabled == nil then
        W.resultEnabled = true
    else
        W.resultEnabled = (W.resultEnabled == true)
    end

    local G = (getgenv and getgenv()) or _G
    G.MarketResult = MarketResult
    _G.MarketResult = MarketResult

    startWorker()

    task.spawn(function()
        for _ = 1, 15 do
            pcall(ensureTokenStart)
            if _data.tokenStart ~= nil then break end
            local n = getTradeTokenBalance()
            if n ~= nil then break end
            task.wait(2)
        end
    end)

    return MarketResult
end

