local function shortNum(n)
    n = num(n)
    local sign = n < 0 and "-" or ""
    n = math.abs(n)
    local units = {
        { 1e27, "Oc" },
        { 1e24, "Sp" },
        { 1e21, "Sx" },
        { 1e18, "Qi" },
        { 1e15, "Qa" },
        { 1e12, "T" },
        { 1e9, "B" },
        { 1e6, "M" },
        { 1e3, "k" },
    }
    for _, u in ipairs(units) do
        if n >= u[1] then
            return sign .. string.format("%.1f%s", n / u[1], u[2])
        end
    end
    if n >= 10 or n == math.floor(n) then
        return sign .. string.format("%.0f", n)
    end
    return sign .. string.format("%.1f", n)
end

local function dotNum(n)
    n = num(n)
    local sign = n < 0 and "-" or ""
    local s = string.format("%.0f", math.floor(math.abs(n) + 0.5))
    local parts = {}
    while #s > 3 do
        table.insert(parts, 1, s:sub(-3))
        s = s:sub(1, -4)
    end
    if s ~= "" then
        table.insert(parts, 1, s)
    end
    if #parts == 0 then
        return sign .. "0"
    end
    return sign .. table.concat(parts, ".")
end

local function getPlayerProfile()
    local ok, profile = pcall(function()
        local rs = game:GetService("ReplicatedStorage")
        local mods = rs:FindFirstChild("Modules")
        local dsMod = mods and mods:FindFirstChild("DataService")
        if not dsMod then return nil end
        local DS = require(dsMod)
        if DS and type(DS.GetData) == "function" then
            return DS:GetData()
        end
        return nil
    end)
    if ok and type(profile) == "table" then
        return profile
    end
    return nil
end

local function getShecklesBalance(profile)
    if type(profile) ~= "table" then
        profile = getPlayerProfile()
    end
    if type(profile) ~= "table" then
        return 0
    end
    local n = tonumber(profile.Sheckles)
    if n then return n end
    if type(profile.CurrencyData) == "table" then
        n = tonumber(profile.CurrencyData.Sheckles)
        if n then return n end
    end
    if type(profile.Stats) == "table" then
        n = tonumber(profile.Stats.Sheckles)
        if n then return n end
    end
    return 0
end

