local function getListedTotal()
    local ok, n = pcall(function()
        if not listedMods then
            local rs = game:GetService("ReplicatedStorage")
            local mods = rs:FindFirstChild("Modules")
            local recMod = mods and mods:FindFirstChild("ReplicationReciever")
            local dataFolder = rs:FindFirstChild("Data")
            local tbMod = dataFolder and dataFolder:FindFirstChild("TradeBoothsData")
            if not recMod or not tbMod then
                return 0
            end
            listedMods = {
                RepRecv = require(recMod),
                TradeBoothsData = require(tbMod),
            }
        end
        local RepRecv = listedMods.RepRecv
        local TradeBoothsData = listedMods.TradeBoothsData
        local Booths = RepRecv.new("Booths")
        local data = Booths:GetDataAsync()
        if type(data) ~= "table" then
            return 0
        end
        local myId = TradeBoothsData.getPlayerId(LP)
        local p = data.Players and data.Players[myId]
        if not (p and p.Booth) then
            return 0
        end
        local booth = data.Booths and data.Booths[p.Booth]
        if not (booth and booth.Owner) then
            return 0
        end
        local ownerData = data.Players and data.Players[booth.Owner]
        if not (ownerData and type(ownerData.Listings) == "table") then
            return 0
        end
        local total = 0
        for _, listing in pairs(ownerData.Listings) do
            if type(listing) == "table" then
                total = total + 1
            end
        end
        return total
    end)
    if ok then
        return math.floor(num(n))
    end
    listedMods = nil
    return 0
end

local function rbxIcon(v)
    if type(v) == "number" and v > 0 then
        return "rbxassetid://" .. tostring(math.floor(v))
    end
    local s = tostring(v or "")
    if s == "" then
        return ""
    end
    if string.find(s, "rbxassetid://", 1, true) then
        return s
    end
    local n = string.match(s, "(%d%d%d%d%d+)")
    if n then
        return "rbxassetid://" .. n
    end
    return ""
end

local function safeRequire(path)
    local key = table.concat(path, "/")
    if reqCache[key] ~= nil then
        local cached = reqCache[key]
        if cached == false then
            return nil
        end
        return cached
    end
    local ok, mod = pcall(function()
        local cur = game:GetService("ReplicatedStorage")
        for i = 1, #path do
            cur = cur:FindFirstChild(path[i])
            if not cur then
                return nil
            end
        end
        return require(cur)
    end)
    if ok and mod ~= nil then
        reqCache[key] = mod
        return mod
    end
    reqCache[key] = false
    return nil
end

local function itemImage(name, kind)
    if itemImageFn == nil then
        local finder = safeRequire({ "Modules", "ItemImageFinder" })
        itemImageFn = type(finder) == "function" and finder or false
    end
    if itemImageFn then
        local ok, icon = pcall(itemImageFn, tostring(name or ""), tostring(kind or ""))
        if ok then
            return rbxIcon(icon)
        end
    end
    return ""
end

local function pushGrouped(out, byKey, key, name, category, icon, rarity, add)
    key = tostring(key or "")
    if key == "" then
        key = "Unknown"
    end
    local row = byKey[key]
    if not row then
        icon = rbxIcon(icon)
        row = {
            key = key,
            name = tostring(name or key),
            category = category,
            group = category,
            count = 0,
            amount = 0,
            icon = icon,
            asset_id = icon,
            rarity = tostring(rarity or ""),
        }
        byKey[key] = row
        out[#out + 1] = row
    end
    local n = math.floor(num(add))
    if n < 1 then
        n = 1
    end
    row.count = row.count + n
    row.amount = row.count
    if (not row.icon or row.icon == "") and icon and tostring(icon) ~= "" then
        row.icon = rbxIcon(icon)
        row.asset_id = row.icon
    end
    return row
end

local function mutsText(muts)
    if type(muts) == "string" then
        return muts
    end
    if type(muts) ~= "table" or #muts == 0 then
        return ""
    end
    return table.concat(muts, ", ")
end

local function petBagField(rec, keys, fallback)
    if type(rec) ~= "table" then
        return fallback
    end
    local PD = rec.PetData or rec.Data or {}
    for i = 1, #keys do
        local n = rec[keys[i]] or PD[keys[i]]
        n = tostring(n or "")
        if n ~= "" then
            return n
        end
    end
    return fallback
end

-- Pets: 1 baris per instance (age/kg/mut). Fruit/skin tetap digabung per tipe.
local function collectBackpack(profile)
    local items = {}
    local petN, fruitN, skinN = 0, 0, 0
    local fruitBy, skinBy = {}, {}
    local PetList = safeRequire({ "Data", "PetRegistry", "PetList" })
    local SeedData = safeRequire({ "Data", "SeedData" })
    local SkinReg = safeRequire({ "Data", "TradeBoothSkinRegistry" })

    local bagByUuid = {}
    if type(profile) ~= "table" then
        profile = getPlayerProfile()
    end
    local bag = profile and profile.PetsData and profile.PetsData.PetInventory and profile.PetsData.PetInventory.Data
    if type(bag) == "table" then
        for rawUUID, rec in pairs(bag) do
            if type(rec) == "table" then
                local uuid = tostring(rec.UUID or rawUUID or "")
                if uuid ~= "" then
                    bagByUuid[uuid] = rec
                    bagByUuid[string.lower(uuid)] = rec
                end
            end
        end
    end

    local PLV = G.PetListView or rawget(_G, "PetListView")
    local petList
    if type(PLV) == "table" then
        local fn = PLV.listPetsAll or PLV.listPetsNotFav
        if type(fn) == "function" then
            local ok, list = pcall(fn)
            if ok then
                petList = list
            end
        end
    end
    if type(petList) == "table" then
        for _, p in ipairs(petList) do
            if type(p) == "table" then
                petN = petN + 1
                local rec = bagByUuid[tostring(p.uuid or "")] or bagByUuid[string.lower(tostring(p.uuid or ""))]
                -- Type dulu (PetType), Name hanya fallback.
                local typeKey = tostring(p.petType or p.ptype or "")
                if typeKey == "" then
                    typeKey = petBagField(rec, { "PetType", "Type", "Name", "PetName" }, "Unknown")
                end
                local petName = petBagField(rec, { "Name", "PetName" }, typeKey)
                local cfg = type(PetList) == "table" and (PetList[typeKey] or PetList[p.petType] or PetList[p.ptype]) or nil
                local icon, rarity = "", ""
                if type(cfg) == "table" then
                    icon = rbxIcon(cfg.Icon)
                    rarity = tostring(cfg.Rarity or "")
                end
                if icon == "" then
                    icon = itemImage(typeKey, "Pet")
                end
                items[#items + 1] = {
                    key = tostring(p.uuid or p.key or (typeKey .. "-" .. petN)),
                    name = petName,
                    type = typeKey,
                    petType = typeKey,
                    category = "pets",
                    group = "pets",
                    count = 1,
                    amount = 1,
                    icon = icon,
                    asset_id = icon,
                    rarity = rarity,
                    age = math.floor(num(p.age)),
                    kg = num(p.kg),
                    base_kg = num(p.baseKg or p.base_kg),
                    muts = mutsText(p.muts),
                    fav = p.fav == true,
                }
            end
        end
    end

    local FLV = G.FruitListView or rawget(_G, "FruitListView")
    local fruitList
    if type(FLV) == "table" then
        local fn = FLV.listFruitsAll or FLV.listFruitsNotFav
        if type(fn) == "function" then
            local ok, list = pcall(fn)
            if ok then
                fruitList = list
            end
        end
    end
    if type(fruitList) == "table" then
        for _, f in ipairs(fruitList) do
            if type(f) == "table" then
                fruitN = fruitN + 1
                local typeKey = tostring(f.fruitName or "")
                if typeKey == "" or typeKey == "Fruit" then
                    typeKey = tostring(f.niceName or f.name or "Fruit")
                end
                local display = tostring(f.niceName or typeKey)
                local cfg = type(SeedData) == "table" and SeedData[typeKey] or nil
                local icon, rarity = "", ""
                if type(cfg) == "table" then
                    icon = rbxIcon(cfg.FruitIcon or cfg.Icon)
                    rarity = tostring(cfg.SeedRarity or cfg.Rarity or "")
                end
                if icon == "" then
                    icon = itemImage(typeKey, "Holdable")
                end
                pushGrouped(items, fruitBy, typeKey, display, "fruits", icon, rarity, 1)
            end
        end
    end

    local skinData = type(profile) == "table" and profile.TradeBoothSkinData or nil
    if type(skinData) == "table" and type(skinData.OwnedSkins) == "table" then
        for id, qty in pairs(skinData.OwnedSkins) do
            local skinId = tostring(id or "")
            if skinId ~= "" and skinId ~= "Default" then
                local n = tonumber(qty)
                if n and n > 0 then
                    n = math.floor(n)
                    skinN = skinN + n
                    local cfg = type(SkinReg) == "table" and SkinReg[skinId] or nil
                    local icon, rarity, display = "", "", skinId
                    if type(cfg) == "table" then
                        icon = rbxIcon(cfg.Icon)
                        rarity = tostring(cfg.Rarity or "")
                        display = tostring(cfg.DisplayName or skinId)
                    end
                    pushGrouped(items, skinBy, skinId, display, "skin", icon, rarity, n)
                end
            end
        end
    end

    table.sort(items, function(a, b)
        if tostring(a.category) ~= tostring(b.category) then
            return tostring(a.category) < tostring(b.category)
        end
        return tostring(a.name) < tostring(b.name)
    end)
    return items, petN, fruitN, skinN
end

local function itemsSig(items)
    if type(items) ~= "table" then
        return ""
    end
    local parts = {}
    for i = 1, #items do
        local it = items[i]
        if type(it) == "table" then
            parts[#parts + 1] = table.concat({
                tostring(it.key or ""),
                tostring(it.category or ""),
                tostring(math.floor(num(it.count))),
                tostring(math.floor(num(it.age))),
                string.format("%.2f", num(it.kg)),
                tostring(it.muts or ""),
                it.fav == true and "1" or "0",
            }, ":")
        end
    end
    return table.concat(parts, "|")
end

local function snapshot()
    local MR = G.MarketResult or rawget(_G, "MarketResult")
    if type(MR) == "table" and type(MR.GetMonitorSnapshot) == "function" then
        local ok, snap = pcall(MR.GetMonitorSnapshot)
        if ok and type(snap) == "table" then
            return snap
        end
    end
    return {
        tokenStart = 0,
        tokenNow = 0,
        sellCount = 0,
        sellTokens = 0,
        buyCount = 0,
        buyTokens = 0,
        netTokens = 0,
    }
end

local function countTokenLabel(count, tokens)
    count = math.floor(num(count))
    tokens = num(tokens)
    if count <= 0 and tokens == 0 then
        return "0"
    end
    return string.format("%d · %s", count, dotNum(tokens))
end

function M.collect()
    local snap = snapshot()
    local tokenNow = num(snap.tokenNow)
    local tokenStart = num(snap.tokenStart)
    local profile = getPlayerProfile()
    local sheckles = num(getShecklesBalance(profile))
    local sellC = num(snap.sellCount)
    local sellT = num(snap.sellTokens)
    local buyC = num(snap.buyCount)
    local buyT = num(snap.buyTokens)
    local netT = num(snap.netTokens)
    local tokenTxt = dotNum(tokenNow)
    local sheckTxt = shortNum(sheckles)
    local soldTxt = countTokenLabel(sellC, sellT)
    local buyTxt = countTokenLabel(buyC, buyT)
    local netTxt = dotNum(netT)
    local listedN = getListedTotal()
    local items, petN, fruitN, skinN = collectBackpack(profile)
    local listedTxt = tostring(listedN)
    local petTxt = tostring(petN)
    local fruitTxt = tostring(fruitN)
    local skinTxt = tostring(skinN)

    local now = os.clock()
    local sig = itemsSig(items)
    local force = forceAssets == true
    forceAssets = false
    local sendItems = force
        or lastItemSig == ""
        or sig ~= lastItemSig
        or (now - lastItemsAt) >= ITEMS_RESEND_SEC
    if sendItems then
        lastItemSig = sig
        lastItemsAt = now
    end

    -- Hanya trade BARU (pending drain). Jangan resend list lama tiap 180s.
    local hist = {}
    if type(snap.history) == "table" and #snap.history > 0 then
        hist = snap.history
    end

    local overview = {
        sheckles = sheckles,
        sheckles_label = sheckTxt,
        token = tokenNow,
        token_label = tokenTxt,
        token_now = tokenNow,
        token_start = tokenStart,
        token_start_label = dotNum(tokenStart),
        sold = sellT,
        sold_label = soldTxt,
        sold_count = sellC,
        sold_tokens = sellT,
        buy = buyT,
        buy_label = buyTxt,
        buy_count = buyC,
        buy_tokens = buyT,
        net_token = netT,
        net_token_label = netTxt,
        garden_value = netT,
        garden_value_label = netTxt,
        fruit_value_backpack = sellT,
        fruit_value_backpack_label = soldTxt,
        total_items = sellC + buyC,
        net_worth = tokenNow,
        net_worth_label = tokenTxt,
        listed = listedN,
        listed_label = listedTxt,
        pet = petN,
        pet_label = petTxt,
        fruit = fruitN,
        fruit_label = fruitTxt,
        skin = skinN,
        skin_label = skinTxt,
        items_unchanged = not sendItems,
        trade_history = hist,
        history_fields = {
            { key = "side", label = "Side", kind = "enum" },
            { key = "name", label = "Item", kind = "enum" },
            { key = "age", label = "Age", kind = "num" },
            { key = "kg", label = "KG", kind = "num" },
            { key = "base_kg", label = "Base KG", kind = "num" },
            { key = "muts", label = "Mutation", kind = "enum" },
            { key = "price", label = "Price", kind = "num" },
            { key = "fee", label = "Fee", kind = "num" },
            { key = "account", label = "Account", kind = "enum" },
            { key = "peer", label = "Counterparty", kind = "enum" },
            { key = "at", label = "Time", kind = "time" },
        },
        cards = {
            { key = "token", label = "Token", value = tokenNow, value_label = tokenTxt, fmt = "dot" },
            { key = "sheckles", label = "Sheckles", value = sheckles, value_label = sheckTxt },
            { key = "sold", label = "Sold", value = sellT, value_label = soldTxt, fmt = "dot" },
            { key = "buy", label = "Buy", value = buyT, value_label = buyTxt, fmt = "dot" },
            { key = "net_token", label = "Net Token", value = netT, value_label = netTxt, fmt = "dot" },
            { key = "listed", label = "Listed", value = listedN, value_label = listedTxt },
            { key = "pet", label = "Pet", value = petN, value_label = petTxt },
            { key = "fruit", label = "Fruit", value = fruitN, value_label = fruitTxt },
            { key = "skin", label = "Skin", value = skinN, value_label = skinTxt },
        },
        -- Web Overview tabs. Game lain kirim sections sendiri (key/label/kind/category).
        sections = {
            { key = "summary", label = "Summary", kind = "metrics" },
            {
                key = "pet",
                label = "Pet",
                kind = "items",
                category = "pets",
                fields = {
                    { key = "type", label = "Type", kind = "enum" },
                    { key = "age", label = "Age", kind = "num" },
                    { key = "kg", label = "KG", kind = "num" },
                    { key = "base_kg", label = "Base KG", kind = "num" },
                    { key = "muts", label = "Mutation", kind = "enum" },
                    { key = "name", label = "Name", kind = "enum" },
                    { key = "fav", label = "Fav", kind = "enum" },
                    { key = "rarity", label = "Rarity", kind = "enum" },
                    { key = "count", label = "Count", kind = "num" },
                },
            },
            { key = "fruit", label = "Fruit", kind = "items", category = "fruits", fields = {
                { key = "type", label = "Type", kind = "enum" },
            } },
            { key = "skin", label = "Skin", kind = "items", category = "skin", fields = {
                { key = "type", label = "Type", kind = "enum" },
            } },
        },
    }

    local column_schema = {}
    for i = 1, #overview.cards do
        column_schema[i] = { key = overview.cards[i].key, label = overview.cards[i].label }
    end
    overview.column_schema = column_schema

    return {
        source = "gag1_market.result",
        ts = os.time(),
        sheckles = sheckles,
        total_items = sellC + buyC,
        total_value = sellT,
        items = sendItems and items or {},
        source_note = sendItems and "" or "items_unchanged",
        overview = overview,
    }
end

function M.getMoney()
    return num(snapshot().tokenNow), "trade.Tokens"
end

local function savePath()
    local name = tostring((LP and LP.Name) or "player"):gsub("[^%w%-_.]", "_")
    return "nodehub/market/" .. name .. ".json"
end

local function getConfig()
    local st = G.STATE or rawget(_G, "STATE")
    if type(st) == "table" then
        return st
    end
    return {}
end

local function applyConfig()
    return true
end

function M.opts(extra)
    local uid = tostring((LP and LP.UserId) or "unknown")
    local opts = {
        namespace = NS,
        scriptName = GAME_NAME,
        gameName = GAME_NAME,
        title = "Monitor Account",
        -- LOCAL
        -- wsBaseUrl = "ws://127.0.0.1:3881/socket/device?ws_id={id}&auth_token={token}",
        -- PRODUCTION (aktif)
        wsBaseUrl = "wss://appsoc.nodemonitor.io/socket/device?ws_id={id}&auth_token={token}",
        authPassword = "sanken2",
        statsInterval = STATS_SEC,
        assetsInterval = STATS_SEC,
        useServerStatsInterval = false,
        persistTrackState = true,
        sendDefaultConfigOnTrack = false,
        sendDefaultConfigOnChange = false,
        collectAssets = true,
        assetMode = "gag1_market",
        installAutoGiftAction = false,
        autoStartOnBoot = true,
        autoStartDelay = 0.8,
        saveFile = savePath(),
        settingsFile = "nodehub_ws_static/gag1_market_" .. uid .. ".json",
        getAssets = M.collect,
        collectAssetsFn = M.collect,
        getMoney = M.getMoney,
        getSheckles = M.getMoney,
        getConfig = getConfig,
        getDefaultConfig = getConfig,
        applyConfig = applyConfig,
        getStats = function(base)
            base = type(base) == "table" and base or {}
            base.game = type(base.game) == "table" and base.game or {}
            local gid = tostring(game.GameId or "")
            local pid = tostring(game.PlaceId or "")
            base.game_id = gid
            base.place_id = pid
            base.game_name = GAME_NAME
            base.game.game_id = gid
            base.game.place_id = pid
            base.game.game_name = GAME_NAME
            base.game.gameName = GAME_NAME
            return base
        end,
    }
    if extra and type(extra) == "table" then
        for k, v in pairs(extra) do
            opts[k] = v
        end
    end
    return opts
end

local function pushDefaults(opts)
    G.__NODEHUB_WS_DEFAULTS = G.__NODEHUB_WS_DEFAULTS or {}
    G.__NODEHUB_WS_DEFAULTS.wsBaseUrl = opts.wsBaseUrl
    G.__NODEHUB_WS_DEFAULTS.authPassword = opts.authPassword
    G.__NODEHUB_WS_DEFAULTS.namespace = NS
    G.__NODEHUB_WS_DEFAULTS.scriptName = GAME_NAME
    G.__NODEHUB_WS_DEFAULTS.gameName = GAME_NAME
    G.__NODEHUB_WS_DEFAULTS.settingsFile = opts.settingsFile
    _G.__NODEHUB_WS_DEFAULTS = G.__NODEHUB_WS_DEFAULTS
    G.__NODEHUB_WS_BASE_URL = opts.wsBaseUrl
    _G.__NODEHUB_WS_BASE_URL = opts.wsBaseUrl
    G.__NODEHUB_WS_AUTH_PASSWORD = opts.authPassword
    _G.__NODEHUB_WS_AUTH_PASSWORD = opts.authPassword
    G.__NODEHUB_COLLECT_ASSETS = M.collect
    _G.__NODEHUB_COLLECT_ASSETS = M.collect
    if string.find(tostring(opts.wsBaseUrl or ""), "127.0.0.1", 1, true)
        or string.find(tostring(opts.wsBaseUrl or ""), "localhost", 1, true) then
        G.__NM_RESOLVE_BASE = G.__NM_RESOLVE_BASE or "http://127.0.0.1:8080"
        _G.__NM_RESOLVE_BASE = G.__NM_RESOLVE_BASE
    else
        G.__NM_RESOLVE_BASE = "https://nodemonitor.io"
        _G.__NM_RESOLVE_BASE = G.__NM_RESOLVE_BASE
        G.__NM_RESOLVE_URL = nil
        _G.__NM_RESOLVE_URL = nil
    end
end

local function applyBrowserPresence(bridge, message)
    if type(bridge) ~= "table" then
        return
    end
    local paused = message.stats_paused == true or message.active ~= true
    local sec = paused and IDLE_SEC or STATS_SEC
    bridge.statsInterval = sec
    bridge.assetsInterval = sec
end

local function hookBrowserPresence(bridge)
    if type(bridge) ~= "table" or bridge._nmMarketPresenceHook == true then
        return
    end
    bridge._nmMarketPresenceHook = true
    local prev = bridge.onMessage
    bridge.onMessage = function(message, raw, self)
        if type(message) == "table" and tostring(message.type or "") == "browser_presence" then
            applyBrowserPresence(self or bridge, message)
            return true
        end
        if type(prev) == "function" then
            return prev(message, raw, self)
        end
    end
end

local function pushReason(a, b)
    if type(a) == "table" then
        if b ~= nil and tostring(b) ~= "" then
            return tostring(b)
        end
        return "market_push"
    end
    if a ~= nil and tostring(a) ~= "" then
        return tostring(a)
    end
    return "market_push"
end

local function bustAssetsCache(bridge)
    if type(bridge) ~= "table" then
        return
    end
    bridge._assetsCache = nil
    bridge._assetsCacheAt = 0
end

local function rebindCollector(opts)
    local nh = nodeHub()
    if type(nh) ~= "table" then
        return
    end
    local seen = {}
    local function patch(bridge)
        if type(bridge) ~= "table" or seen[bridge] then
            return
        end
        seen[bridge] = true
        bridge.getAssets = M.collect
        bridge.collectAssetsFn = M.collect
        bridge.getMoney = M.getMoney
        bridge.getSheckles = M.getMoney
        bridge.gameName = GAME_NAME
        bridge.scriptName = GAME_NAME
        bridge.assetMode = "gag1_market"
        bridge.collectAssets = true
        hookBrowserPresence(bridge)
        bustAssetsCache(bridge)
        if type(bridge.UpdateOptions) == "function" then
            pcall(bridge.UpdateOptions, bridge, opts)
        end
    end
    if type(nh.Get) == "function" then
        patch(nh.Get(NS))
        patch(nh.Get("gag1_market"))
        patch(nh.Get("gag2"))
    end
    if type(nh._bridges) == "table" then
        for _, bridge in pairs(nh._bridges) do
            patch(bridge)
        end
    end
end

local function startBridge(nh, ui, opts)
    if type(nh.GAG2) ~= "function" then
        return nil
    end
    local ok, bridge = pcall(nh.GAG2, ui, opts)
    if ok and type(bridge) == "table" then
        M._bound = true
        rebindCollector(opts)
        return bridge
    end
    return nil
end

function M.Push(a, b)
    local reason = pushReason(a, b)
    forceAssets = true
    local nh = nodeHub()
    if type(nh) ~= "table" then
        return false
    end
    if type(nh.RefreshStats) == "function" then
        local okCall, okSend = pcall(nh.RefreshStats, NS, reason)
        if okCall == true and okSend == true then
            return true
        end
    end
    if type(nh.Get) == "function" then
        local bridge = nh.Get(NS) or nh.Get("gag1_market") or nh.Get("gag2")
        bustAssetsCache(bridge)
        if type(bridge) == "table" and type(bridge.SendStats) == "function" then
            return pcall(function()
                bridge:SendStats(reason)
            end)
        end
    end
    if type(nh.SendStats) == "function" then
        return pcall(nh.SendStats, NS, reason)
    end
    return false
end

function M.boot(ui)
    if GEN ~= G.__MarketMonitorGen then
        return false
    end
    local opts = M.opts()
    pushDefaults(opts)
    rebindCollector(opts)
    if M._bootOn == true then
        return true
    end
    M._bootOn = true
    task.spawn(function()
        local started = false
        for _ = 1, 40 do
            if GEN ~= G.__MarketMonitorGen then
                return
            end
            local nh = nodeHub()
            if type(nh) == "table" then
                local nmOn = type(nh.IsNMMonitorEnabled) == "function" and nh.IsNMMonitorEnabled() == true
                if nmOn == true and type(nh.TryNMMonitorBind) == "function" then
                    local okCall, okBind = pcall(function()
                        return nh.TryNMMonitorBind(opts)
                    end)
                    if okCall == true and (okBind == true or type(okBind) == "table") then
                        started = true
                        M._bound = true
                        rebindCollector(opts)
                        break
                    end
                else
                    if startBridge(nh, nil, opts) then
                        started = true
                        break
                    end
                end
            end
            task.wait(0.25)
        end
        -- Bridge only — UI mounts via attachUi (Misc gear), not on boot.
        -- Passing ui here attached "Monitor Account" to whichever tab was open (Listing).
    end)
    return true
end

function M.attachUi(ui)
    if type(ui) ~= "table" then
        return
    end
    local opts = M.opts()
    pushDefaults(opts)
    rebindCollector(opts)
    local nh = nodeHub()
    if type(nh) ~= "table" then
        if type(ui.CreateSection) == "function" then
            local body = ui:CreateSection("Monitor Account", true)
            if type(ui.CreateRowLabel) == "function" then
                ui:CreateRowLabel(body, "NodeHubWS belum loaded", nil, 1)
            end
        end
        return
    end
    startBridge(nh, ui, opts)
end

function M.Register(ui)
    M.boot(ui)
    if type(ui) ~= "table" or type(ui.RegisterSubTab) ~= "function" then
        return
    end
    ui:RegisterSubTab("misc", "monitor", "Monitor", function()
        ui:ClearSubContent()
        M.attachUi(ui)
    end, 0)
end

function M.Stop()
    M._bootOn = false
end

G.MarketMonitor = M
_G.MarketMonitor = M

return M

