local Players = game:GetService("Players")
local LP = Players.LocalPlayer
local PG = LP:WaitForChild("PlayerGui")

local M = {}

local GUI_NAME = "NodeHubMarketAgeBreakHUD"

local CARD_W = 200
local PAD = 6
local GAP = 2
local LINE_H = 11
local PET_TEXT_SIZE = 8
local PET_LINE_H = 10

local THEME = {
    bg      = Color3.fromRGB(10, 10, 12),
    border  = Color3.fromRGB(255, 217, 0),
    title   = Color3.fromRGB(255, 217, 0),
    text    = Color3.fromRGB(228, 228, 232),
    sub     = Color3.fromRGB(145, 145, 150),
    idle    = Color3.fromRGB(115, 115, 120),
    running = Color3.fromRGB(255, 217, 0),
    ready   = Color3.fromRGB(95, 255, 145),
    on      = Color3.fromRGB(95, 255, 145),
    off     = Color3.fromRGB(150, 150, 155),
    warn    = Color3.fromRGB(255, 175, 75),
    waiting = Color3.fromRGB(255, 175, 75),
    pet     = Color3.fromRGB(235, 235, 240),
}

