local _refs = {}
local _pollToken = 0
local _started = false

local function getMK()
    local STATE = rawget(_G, "STATE")
    if type(STATE) ~= "table" then return nil end
    local mk = STATE.main and STATE.main.auto_market
    return type(mk) == "table" and mk or nil
end

local function isInMarketWorld()
    return workspace:FindFirstChild("TradeWorld") ~= nil
end

local function getRejoinModule()
    return rawget(_G, "AgeBreakRejoinReduce")
end

local function fetchMachineStatus()
    local mod = getRejoinModule()
    if mod and type(mod.GetMachineStatus) == "function" then
        local ok, st = pcall(function()
            return mod.GetMachineStatus()
        end)
        if ok and type(st) == "table" then
            return st
        end
    end
    return { text = "—", kind = "idle" }
end

local function colorForKind(kind)
    return THEME[kind] or THEME.idle
end

local function shouldShowHud()
    if not isInMarketWorld() then
        return false
    end
    local mk = getMK()
    if mk and mk.ageBreakRejoinReduce == true then
        return true
    end
    if mk and mk.ageBreakSessionPending == true then
        return true
    end
    local st = fetchMachineStatus()
    if st and st.kind and st.kind ~= "idle" then
        return true
    end
    if st and type(st.runtimeText) == "string" and st.runtimeText ~= "" then
        return true
    end
    return false
end

local function makeLine(parent, name, order, textSize, color, bold, opts)
    opts = opts or {}
    local lbl = Instance.new("TextLabel")
    lbl.Name = name
    lbl.BackgroundTransparency = 1
    lbl.Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham
    lbl.TextSize = textSize
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.TextYAlignment = opts.wrap and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center
    lbl.TextColor3 = color or THEME.text
    lbl.Text = ""
    lbl.LayoutOrder = order
    lbl.Parent = parent

    if opts.wrap then
        lbl.Size = UDim2.new(1, 0, 0, 0)
        lbl.AutomaticSize = Enum.AutomaticSize.Y
        lbl.TextWrapped = true
        lbl.TextTruncate = Enum.TextTruncate.None
        lbl.LineHeight = 1.05
    else
        lbl.Size = UDim2.new(1, 0, 0, opts.height or LINE_H)
        lbl.TextTruncate = Enum.TextTruncate.AtEnd
    end
    return lbl
end

local function resizeCard()
    local card = _refs.card
    local layout = _refs.layout
    if not card or not layout then return end
    task.defer(function()
        if not _refs.card or not _refs.layout then return end
        local contentH = _refs.layout.AbsoluteContentSize.Y
        local contentW = _refs.layout.AbsoluteContentSize.X
        local w = math.clamp(math.max(CARD_W, contentW + PAD * 2), 140, 240)
        local h = contentH + PAD * 2
        _refs.card.Size = UDim2.fromOffset(w, h)
    end)
end

local function buildHud()
    local old = PG:FindFirstChild(GUI_NAME)
    if old then old:Destroy() end

    local sg = Instance.new("ScreenGui")
    sg.Name = GUI_NAME
    sg.ResetOnSpawn = false
    sg.IgnoreGuiInset = true
    sg.DisplayOrder = 880
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    sg.Parent = PG

    local card = Instance.new("Frame")
    card.Name = "Card"
    card.AnchorPoint = Vector2.new(1, 1)
    card.Position = UDim2.new(1, -10, 1, -10)
    card.Size = UDim2.fromOffset(CARD_W, 40)
    card.BackgroundColor3 = THEME.bg
    card.BackgroundTransparency = 0.08
    card.BorderSizePixel = 0
    card.Parent = sg

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 6)
    corner.Parent = card

    local stroke = Instance.new("UIStroke")
    stroke.Color = THEME.border
    stroke.Thickness = 1
    stroke.Transparency = 0.2
    stroke.Parent = card

    local pad = Instance.new("UIPadding")
    pad.PaddingTop = UDim.new(0, PAD)
    pad.PaddingBottom = UDim.new(0, PAD)
    pad.PaddingLeft = UDim.new(0, PAD)
    pad.PaddingRight = UDim.new(0, PAD)
    pad.Parent = card

    local layout = Instance.new("UIListLayout")
    layout.FillDirection = Enum.FillDirection.Vertical
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, GAP)
    layout.Parent = card

    _refs.card = card
    _refs.layout = layout
    _refs.title = makeLine(card, "Title", 1, 9, THEME.title, true)
    _refs.title.Text = "Age Break"
    _refs.pet = makeLine(card, "Pet", 2, PET_TEXT_SIZE, THEME.pet, false, {
        wrap = true,
        height = PET_LINE_H,
    })
    _refs.machine = makeLine(card, "Machine", 3, 9, THEME.text, false)
    _refs.runtime = makeLine(card, "Runtime", 4, 8, THEME.sub, false)

    layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
        pcall(resizeCard)
    end)

    _gui = sg
    return sg
end

local function applyStatus()
    if not _gui or not _refs.machine then return end

    local visible = shouldShowHud()
    _gui.Enabled = visible
    if not visible then return end

    local mk = getMK()
    local rejoinOn = mk and mk.ageBreakRejoinReduce == true
    local mod = getRejoinModule()
    local modRun = mod and mod.IsRunning and mod.IsRunning() == true

    local st = fetchMachineStatus()
    local kind = tostring(st.kind or "idle")
    local petLine = st.petLine

    if type(petLine) ~= "string" or petLine == "" then
        _refs.pet.Visible = false
        _refs.pet.Text = ""
    else
        _refs.pet.Visible = true
        _refs.pet.Text = petLine
    end

    _refs.machine.Text = tostring(st.text or "—")
    _refs.machine.TextColor3 = colorForKind(kind)

    local runtimeText = st.runtimeText
    if type(runtimeText) == "string" and runtimeText ~= "" and runtimeText ~= "0s" then
        local startLeft = tonumber(st.startTimeLeft)
        local fmt = mod and mod.FormatTimeLeft
        _refs.runtime.Visible = true
        if startLeft and startLeft > 0 and type(fmt) == "function" then
            _refs.runtime.Text = string.format("Runtime · %s · start %s", runtimeText, fmt(startLeft))
        else
            _refs.runtime.Text = "Runtime · " .. runtimeText
        end
    else
        _refs.runtime.Visible = false
        _refs.runtime.Text = ""
    end

    resizeCard()
end

local function startPoll()
    _pollToken += 1
    local token = _pollToken
    task.spawn(function()
        while _started and _pollToken == token do
            pcall(applyStatus)
            task.wait(1)
        end
    end)
end

function M.Init()
    if _started then
        pcall(applyStatus)
        return
    end
    _started = true
    buildHud()
    applyStatus()
    startPoll()
end

function M.Destroy()
    _started = false
    _pollToken += 1
    if _gui then
        pcall(function() _gui:Destroy() end)
        _gui = nil
    end
    _refs = {}
end

function M.Refresh()
    pcall(applyStatus)
end

_G.NodeHubMarketAgeBreakHUD = M

