local function makeCacheKey(listingUUID, itemId, price, mode)
    return tostring(listingUUID)
        .. ":"
        .. tostring(itemId)
        .. ":"
        .. tostring(price)
        .. ":mode"
        .. tostring(mode)
end

-------------------------------------------------
-- HTTP
-------------------------------------------------

local function requestPost(url, body)
    local req =
        (syn and syn.request)
        or (http and http.request)
        or http_request
        or request

    if req then
        return req({
            Url = url,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json"
            },
            Body = body
        })
    end

    if HttpService.RequestAsync then
        return HttpService:RequestAsync({
            Url = url,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json"
            },
            Body = body
        })
    end

    error("No HTTP request function available")
end

local function sendWebhook(payload, cacheKey)
    task.spawn(function()
        local ok, err = pcall(function()
            local body = HttpService:JSONEncode(payload)
            requestPost(WEBHOOK_URL, body)
            sentCache[cacheKey] = os.clock()
        end)

        if not ok then
            sentCache[cacheKey] = nil
            warn("[MarketWebhook] failed:", err)
        end
    end)
end

