local function getPetRarity(petType)
    local info = PetList[petType]
    if not info then
        return nil
    end

    return tostring(
        info.Rarity
        or info.PetRarity
        or info.Tier
        or ""
    )
end

local function isTargetRarity(petType)
    local rarity = getPetRarity(petType)
    if not rarity or rarity == "" then
        return false
    end

    return TARGET_RARITIES[rarity] == true
end

