-- PET INFO
-------------------------------------------------

local function ownerName(ownerKey)
    local userId = tonumber(
        tostring(ownerKey):match("(%d+)")
    )

    if userId then
        local plr = Players:GetPlayerByUserId(userId)

        if plr then
            return plr.Name
        end

        local ok, name = pcall(function()
            return Players:GetNameFromUserIdAsync(userId)
        end)

        if ok and name then
            return name
        end
    end

    return tostring(ownerKey)
end

local function calcPetWeightByLevel(item, level)
    local pd = item and item.PetData
    if not pd or pd.BaseWeight == nil then
        return nil
    end

    local baseWeight = tonumber(pd.BaseWeight)
    if not baseWeight then
        return nil
    end

    local ok, kg = pcall(function()
        return PetUtilities:CalculateWeight(baseWeight, level)
    end)

    return ok and tonumber(kg) or nil
end

local function calcPetKG(item)
    local pd = item and item.PetData
    local level = tonumber(pd and pd.Level) or 1
    return calcPetWeightByLevel(item, level)
end

local function calcBaseKGAge1(item)
    return calcPetWeightByLevel(item, 1)
end

local function calcKGAt100(item)
    return calcPetWeightByLevel(item, 100)
end

local function getMutationName(item)
    local pd = item and item.PetData
    local mutEnum = pd and pd.MutationType

    if not mutEnum then
        return "None"
    end

    local name =
        PetMutRegistry.EnumToPetMutation
        and PetMutRegistry.EnumToPetMutation[mutEnum]

    return name and tostring(name) or tostring(mutEnum)
end

local function getPetRAP(item)
    if not item then
        return nil
    end

    local ok, rap = pcall(function()
        return TokenRAPController:GetRAPAsync("Pet", item)
    end)

    if ok and tonumber(rap) then
        return tonumber(rap)
    end

    local okId, itemId = pcall(function()
        return TokenRAPUtil.GetItemId("Pet", item)
    end)

    if okId and itemId then
        local okRap, rap2 = pcall(function()
            return TokenRAPController:GetRAPByIdAsync("Pet", itemId)
        end)

        if okRap and tonumber(rap2) then
            return tonumber(rap2)
        end
    end

    return nil
end

local function buildActiveOwners(data)
    local active = {}

    for _, booth in pairs(data.Booths or {}) do
        local owner = booth and booth.Owner
        if owner ~= nil then
            active[owner] = true
            active[tostring(owner)] = true
        end
    end

    return active
end

local function scanListings(reason)
    if scanning then return end
    scanning = true

    local ok, err = pcall(function()
        local data = Booths:GetDataAsync()
        if not data or not data.Players then
            warn("[MarketScanner] no booth data")
            return
        end

        local activeOwners = buildActiveOwners(data)

        for playerKey, playerData in pairs(data.Players or {}) do
            local isActive =
                activeOwners[playerKey] == true
                or activeOwners[tostring(playerKey)] == true

            if isActive then
                for listingUUID, listing in pairs(playerData.Listings or {}) do
                    local itemId = listing and listing.ItemId
                    local price = tonumber(listing and listing.Price) or math.huge
                    local item = playerData.Items and playerData.Items[itemId]

                    if item and listing.ItemType == "Pet" then
                        local petType = tostring(item.PetType or "")

                        if PetList[petType] then
                            local rap = getPetRAP(item)

                            if rap and rap > 0 then
                                local modesToSend = {}

                                local pd = item.PetData or {}
                                local age = tonumber(pd.Level) or 0

                                local kg = calcPetKG(item)
                                local baseKG = calcBaseKGAge1(item)
                                local kgAt100 = calcKGAt100(item)

                                local requiredBaseKG = TARGET_PETS[petType]

                                if requiredBaseKG and baseKG then
                                    requiredBaseKG = tonumber(requiredBaseKG)

                                    if requiredBaseKG and baseKG >= requiredBaseKG then
                                        local maxPrice = rap * (1 + MODE1_MAX_OVER_RAP_PERCENT / 100)

                                        if price <= maxPrice then
                                            table.insert(modesToSend, 1)
                                        end
                                    end
                                end

                                if isTargetRarity(petType) then
                                    local percentOfRap = (price / rap) * 100
                                    local profit = rap - price
                                    local allowLowRapByBaseKG = baseKG and baseKG > MODE2_BASEKG_OVERRIDE

                                    if percentOfRap <= MODE2_MAX_PRICE_PERCENT_OF_RAP
                                        and (
                                            rap >= MODE2_MIN_RAP
                                            or allowLowRapByBaseKG
                                        )
                                        and profit > 0
                                    then
                                        table.insert(modesToSend, 2)
                                    end
                                end

                                -- mode 3: semua pet titan (baseKG age1 >= 11)
                                if baseKG and baseKG >= MODE3_TITAN_BASEKG then
                                    local maxPrice = rap * (1 + MODE1_MAX_OVER_RAP_PERCENT / 100)
                                    if price <= maxPrice then
                                        table.insert(modesToSend, 3)
                                    end
                                end

                                if #modesToSend > 0 then
                                    local mutName = getMutationName(item)
                                    local rarity = getPetRarity(petType)

                                    local profit = rap - price
                                    local underPct = ((profit / rap) * 100)
                                    local pricePercentOfRap = ((price / rap) * 100)
                                    local owner = ownerName(playerKey)

                                    for _, mode in ipairs(modesToSend) do
                                        local cacheKey = makeCacheKey(listingUUID, itemId, price, mode)

                                        if not sentCache[cacheKey] then
                                            sentCache[cacheKey] = os.clock()

                                            sendWebhook({
                                                mode = mode,

                                                event = "MARKET_UNDER_RAP",
                                                source = "market_global_snipe",
                                                reason = tostring(reason or "scan"),
                                                ts = os.time(),

                                                player = {
                                                    name = LP and LP.Name or "Unknown",
                                                    userId = LP and LP.UserId or 0,
                                                },

                                                server = {
                                                    placeId = game.PlaceId,
                                                    jobId = game.JobId,
                                                },

                                                listing = {
                                                    listingUUID = tostring(listingUUID),
                                                    itemId = tostring(itemId),
                                                    ownerKey = tostring(playerKey),
                                                    ownerName = owner,
                                                    itemType = tostring(listing.ItemType),

                                                    price = price,
                                                    rap = rap,
                                                    profit = profit,
                                                    underPercent = underPct,
                                                    pricePercentOfRap = pricePercentOfRap,
                                                },

                                                pet = {
                                                    petType = petType,
                                                    rarity = rarity,
                                                    mutation = mutName,

                                                    age = age,

                                                    kg = kg,
                                                    kgText = kg and string.format("%.2f", kg) or "N/A",

                                                    baseKG = baseKG,
                                                    baseKGText = baseKG and string.format("%.2f", baseKG) or "N/A",

                                                    kgAt100 = kgAt100,
                                                    kg100Text = kgAt100 and string.format("%.2f", kgAt100) or "N/A",

                                                    targetBaseKG = TARGET_PETS[petType],
                                                },
                                            }, cacheKey)

                                           -- print("========== MARKET DETECT ==========")
                                           --   print("MODE            :", mode)
                                          --    print("PET             :", petType)
                                           --   print("RARITY          :", rarity)
                                          --    print("MUTATION        :", mutName)
                                           --   print("AGE             :", age)
                                          --    print("KG CURRENT      :", kg)
                                          --    print("KG AGE100       :", kgAt100)
                                          --    print("BASE KG AGE1    :", baseKG)
                                          --    print("TARGET BASE KG  :", requiredBaseKG)
                                          --    print("PRICE           :", price)
                                           --   print("RAP             :", rap)
                                           --   print("PRICE % RAP     :", string.format("%.2f%%", pricePercentOfRap))
                                          --    print("UNDER %         :", string.format("%.2f%%", underPct))
                                          --    print("OWNER           :", owner)
                                          --    print("LISTING UUID    :", listingUUID)
                                           --   print("===================================")
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end)

    scanning = false

    if not ok then
      --  warn("[MarketScanner] scan error:", err)
    end
end

