----------------------------------------------------------------

local function httpRequest(url, timeoutSec)
    timeoutSec = tonumber(timeoutSec) or 30

    local req =
        (syn and syn.request)
        or (http and http.request)
        or http_request
        or (fluxus and fluxus.request)
        or request

    local done = false
    local body
    local err

    task.spawn(function()
        local ok, resOrErr = pcall(function()
            if req then
                local res = req({
                    Url = url,
                    Method = "GET",
                })

                if not res then
                    error("no response")
                end

                return res.Body or res.body or ""
            end

            return game:HttpGet(url)
        end)

        if ok then
            body = resOrErr
        else
            err = resOrErr
        end

        done = true
    end)

    local t0 = os.clock()

    while not done do
        if os.clock() - t0 > timeoutSec then
            error("http timeout")
        end

        task.wait()
    end

    if err then
        error(err)
    end

    return body or ""
end

local function getLoadString()
    if type(loadstring) == "function" then
        return loadstring
    end

    if ENV and type(ENV.loadstring) == "function" then
        return ENV.loadstring
    end

    if syn and type(syn.loadstring) == "function" then
        return syn.loadstring
    end

    if getrenv and type(getrenv().loadstring) == "function" then
        return getrenv().loadstring
    end

    return nil
end

local LS = getLoadString()

if type(LS) ~= "function" then
    failBoot("loadstring tidak tersedia")
end

local function callMethod(mod, names, ...)
    if type(mod) ~= "table" then
        return false, "module not table"
    end

    for _, name in ipairs(names) do
        local fn = mod[name]

        if type(fn) == "function" then
            local ok, res = pcall(fn, mod, ...)

            if ok then
                return true, res
            end

            ok, res = pcall(fn, ...)

            if ok then
                return true, res
            end

            return false, res
        end
    end

    return false, "method not found"
end

local function moduleIsRunning(mod)
    if type(mod) ~= "table" then
        return false
    end

    if type(mod.IsRunning) == "function" then
        local ok, v = pcall(mod.IsRunning, mod)

        if ok then
            return v == true
        end

        ok, v = pcall(mod.IsRunning)

        if ok then
            return v == true
        end
    end

    return mod.running == true
end

local function moduleStart(mod, ...)
    if type(mod) ~= "table" then
        return false
    end

    if moduleIsRunning(mod) then
        return true
    end

    local ok = callMethod(mod, { "Start", "start" }, ...)

    return ok == true
end

local function syncStateGlobals(st)
    if type(st) ~= "table" then
        st = {}
    end

    ENV.STATE = st
    _G.STATE = st

    if type(st.trade_cfg) == "table" then
        ENV.TRADE_CFG = st.trade_cfg
        _G.TRADE_CFG = st.trade_cfg
    end

    return st
end

----------------------------------------------------------------
-- LOAD STATE EARLY WITH RETRY
----------------------------------------------------------------

local StateModule = nil
local STATE = nil

local function ensureStateModule()
    if type(StateModule) == "table" and type(StateModule.Load) == "function" then
        return StateModule
    end

    local cached = rawget(ENV, "__NODEHUB_MARKET_STATE_MOD") or rawget(_G, "__NODEHUB_MARKET_STATE_MOD")
    if type(cached) == "table" and type(cached.Load) == "function" then
        StateModule = cached
        return StateModule
    end

    local src = httpRequest(STATE_URL, 30)
    if type(src) ~= "string" or src == "" then
        return nil, "state empty"
    end

    local chunk = LS(src)
    if type(chunk) ~= "function" then
        return nil, "state loadstring failed"
    end

    local mod = chunk()
    if type(mod) ~= "table" then
        return nil, "state result bukan table"
    end

    StateModule = mod
    ENV.__NODEHUB_MARKET_STATE_MOD = mod
    return mod
end

local function loadStateOnce()
    local mod, err = ensureStateModule()
    if type(mod) ~= "table" then
        return false, err or "state module missing"
    end

    local loadFn = mod.Load or mod.load
    local loadSource = nil

    if type(loadFn) == "function" then
        local okLoad, result, source = pcall(function()
            return loadFn(mod)
        end)

        if not okLoad then
            return false, "state load failed: " .. tostring(result)
        end

        loadSource = source or (mod.GetLoadSource and mod.GetLoadSource()) or nil
        if result == false and source ~= "keep_prev" then
            local st0 = rawget(_G, "STATE") or (mod.market and mod.market.state)
            STATE = syncStateGlobals(st0 or {})
            ENV.__NODEHUB_STATE_LOAD_SOURCE = loadSource or "?"
            return false, "state file not ready:" .. tostring(source)
        end
    end

    local st = rawget(_G, "STATE") or rawget(ENV, "STATE") or (mod.market and mod.market.state) or mod.STATE or mod.state or {}

    STATE = syncStateGlobals(st)
    ENV.__NODEHUB_STATE_LOAD_SOURCE = loadSource or (mod.GetLoadSource and mod.GetLoadSource()) or "?"

    return true
end

LOADER.SetProgress(0.05, "Loading market state...")

local stateLoaded = false
for attempt = 1, STATE_RETRY do
    LOADER.SetInfo(("Loading state.lua (%d/%d)..."):format(attempt, STATE_RETRY))

    local okCall, okLoad, err = pcall(function()
        return loadStateOnce()
    end)

    if okCall and okLoad == true then
        stateLoaded = true
        dprint("STATE OK", tostring(ENV.__NODEHUB_STATE_LOAD_SOURCE))
        break
    end

    local why = okCall and tostring(err) or tostring(okLoad)
    warnlog("State load gagal:", attempt, why)
    task.wait(STATE_RETRY_DELAY)
end

if type(STATE) ~= "table" then
    STATE = syncStateGlobals({})
    warnlog("State fallback dipakai")
end

-- Kalau boot pertama cuma dapat default (FS / username belum siap), coba reload lagi
-- sebelum UI dibangun — pola: setting "hilang" lalu rejoin baru muncul.
do
    local src = tostring(ENV.__NODEHUB_STATE_LOAD_SOURCE or "")
    if src == "default" or src == "keep_prev" or src == "error" or src == "" then
        LOADER.SetInfo("Retry state file...")
        for _ = 1, 8 do
            task.wait(0.35)
            local mod = StateModule
            if type(mod) == "table" and type(mod.ReloadIfNeeded) == "function" then
                local okR, src2 = pcall(function()
                    return mod.ReloadIfNeeded()
                end)
                if okR then
                    local st2 = rawget(_G, "STATE") or (mod.market and mod.market.state)
                    if type(st2) == "table" then
                        STATE = syncStateGlobals(st2)
                    end
                    local got = (mod.GetLoadSource and mod.GetLoadSource()) or src2
                    ENV.__NODEHUB_STATE_LOAD_SOURCE = got
                    if got == "file" or got == "bak" then
                        dprint("STATE RELOAD OK", tostring(got))
                        break
                    end
                end
            elseif type(mod) == "table" and type(mod.Load) == "function" then
                pcall(function() mod.Load(mod) end)
                local st2 = rawget(_G, "STATE") or (mod.market and mod.market.state)
                if type(st2) == "table" then
                    STATE = syncStateGlobals(st2)
                end
                local got = mod.GetLoadSource and mod.GetLoadSource()
                ENV.__NODEHUB_STATE_LOAD_SOURCE = got
                if got == "file" or got == "bak" then
                    break
                end
            else
                break
            end
        end
    end
end

local function normalizeBootRuntime()
    local MK = STATE and STATE.main and STATE.main.auto_market
    if type(MK) ~= "table" then return end
    MK.runtime = MK.runtime or {}
    if MK.auto_start ~= true then
        MK.runtime.enabled = false
    end
    _G.__AUTO_MARKET_RUNNING = false
    _G.__AUTO_SNIPE_RUNNING = false
end

normalizeBootRuntime()

