local function waitGameData()
    local RS = game:GetService("ReplicatedStorage")

    LOADER.SetProgress(0.12, "Waiting game data...")
    LOADER.SetInfo("Menunggu ReplicatedStorage...")

    waitChild(RS, "GameEvents", GAME_DATA_WAIT)
    waitChild(RS, "Modules", GAME_DATA_WAIT)
    waitChild(RS, "Data", GAME_DATA_WAIT)

    local ge = RS:FindFirstChild("GameEvents")
    if ge then
        waitChild(ge, "TradeEvents", 12)
        local te = ge:FindFirstChild("TradeEvents")
        if te then
            waitChild(te, "Booths", 8)
        end
    end

    local mods = RS:FindFirstChild("Modules")
    if mods then
        waitChild(mods, "ReplicationReciever", 12)
    end
end

waitGameData()

----------------------------------------------------------------
-- LOAD MODULE WITH RETRY
----------------------------------------------------------------

local Loaded = {}

local function runWithTimeout(fn, timeoutSec, timeoutMsg)
    local done = false
    local ok, res

    task.spawn(function()
        ok, res = pcall(fn)
        done = true
    end)

    local t0 = os.clock()
    while not done do
        if os.clock() - t0 > timeoutSec then
            return false, timeoutMsg or "timeout"
        end
        task.wait()
    end

    if not ok then
        return false, res
    end

    return true, res
end

local function runFactory(def)
    local timeoutSec = tonumber(def.timeout) or FACTORY_TIMEOUT
    local ok, res = runWithTimeout(
        def.factory,
        timeoutSec,
        "factory timeout (WaitForChild/require hung)"
    )

    if not ok then
        return false, "factory error: " .. tostring(res)
    end

    return true, res
end

local function runUrl(def)
    local body = httpRequest(def.url, 30)

    if type(body) ~= "string" or body == "" then
        return false, "empty body"
    end

    local chunk = LS(body)

    if type(chunk) ~= "function" then
        return false, "loadstring failed"
    end

    local ok, res = runWithTimeout(chunk, FACTORY_TIMEOUT, "runtime timeout (WaitForChild/require hung)")

    if not ok then
        return false, "runtime error: " .. tostring(res)
    end

    return true, res
end

local function loadOneModule(def)
    local lastErr = "unknown"

    for attempt = 1, BOOT_RETRY do
        LOADER.SetInfo(("Loading %s (%d/%d)..."):format(
            tostring(def.name),
            attempt,
            BOOT_RETRY
        ))

        local ok, result

        if type(def.factory) == "function" then
            ok, result = runFactory(def)
        elseif type(def.url) == "string" and def.url ~= "" then
            ok, result = runUrl(def)
        else
            ok = false
            result = "module tidak punya factory/url"
        end

        if ok then
            dprint("MODULE OK", def.key, def.name, "attempt", attempt)
            return true, result
        end

        lastErr = tostring(result)

        warnlog(("Load gagal %s attempt %d/%d: %s"):format(
            tostring(def.name),
            attempt,
            BOOT_RETRY,
            lastErr
        ))

        -- Hang WaitForChild tidak akan muncul nanti; jangan buang 5x timeout.
        if lastErr:find("timeout", 1, true) then
            break
        end

        task.wait(RETRY_DELAY)
    end

    return false, lastErr
end

local function loadModuleSet(label, filterFn, progressStart, progressSpan)
    local list = {}

    for _, def in ipairs(MODULE_DEFS) do
        if filterFn(def) then
            list[#list + 1] = def
        end
    end

    for i, def in ipairs(list) do
        local p = progressStart + (progressSpan * (i - 1) / math.max(#list, 1))

        LOADER.SetProgress(p, label .. ": " .. tostring(def.name) .. "...")

        local ok, modOrErr = loadOneModule(def)

        if ok then
            Loaded[def.key] = modOrErr
        else
            -- Hanya MainUI yang boleh mematikan seluruh boot.
            -- required lain yang gagal (WaitForChild/game belum ready)
            -- tidak boleh menggagalkan module berikutnya + UI.
            if def.required == true and def.key == "MainUI" then
                failBoot(("required module failed: %s | %s"):format(
                    tostring(def.name),
                    tostring(modOrErr)
                ))
            else
                warnlog(("%s module failed, boot lanjut: %s | %s"):format(
                    def.required == true and "required" or "optional",
                    tostring(def.name),
                    tostring(modOrErr)
                ))
            end
        end
    end
end

