    if type(tabs_main_snipe.Register) == "function" then
        pcall(function()
            tabs_main_snipe.Register(ui, STATE, PetListView)
        end)
    end
end

if type(ListsnipeTabs) == "table" and type(ListsnipeTabs.Register) == "function" then
    local ok, err = pcall(function()
        ListsnipeTabs.Register(ui, STATE, PetListView)
    end)

    if not ok then
        warnlog("ListsnipeTabs.Register error:", err)
    end
end

if type(MiscTabsMod) == "table" and type(MiscTabsMod.Register) == "function" then
    pcall(function()
        MiscTabsMod.Register(ui, STATE, PetListView)
    end)
end

----------------------------------------------------------------
-- INITIAL TAB
----------------------------------------------------------------

pcall(function()
    ui:SetActiveMainTab("auto_market")
end)

----------------------------------------------------------------
-- AUTO START AFTER UI READY
----------------------------------------------------------------

local function waitMarketWorld(timeout)
    timeout = tonumber(timeout) or 20

    local t0 = os.clock()

    while os.clock() - t0 < timeout do
        local tw = workspace:FindFirstChild("TradeWorld")
        local booths = tw and tw:FindFirstChild("Booths")

        if tw and booths then
            return true
        end

        task.wait(0.25)
    end

    return false
end

local function clearLoopRunningFlags(loop, globalKey)
    if type(loop) ~= "table" then return end
    if moduleIsRunning(loop) then return end
    loop.running = false
    if globalKey then
        rawset(_G, globalKey, false)
    end
end

local function startEnabledLoops()
    local st = syncStateGlobals(rawget(_G, "STATE") or rawget(ENV, "STATE") or STATE or {})
    local MK = st.main and st.main.auto_market

    if type(MK) ~= "table" then
        return
    end

    normalizeBootRuntime()

    local marketLoop = rawget(_G, "market_loop") or MarketLoop
    local snipeLoop = rawget(_G, "snipe_loop") or SnipeLoop

    if MK.auto_start ~= true then
        clearLoopRunningFlags(marketLoop, "__AUTO_MARKET_RUNNING")
        clearLoopRunningFlags(snipeLoop, "__AUTO_SNIPE_RUNNING")
    end

    if MK.ageBreakRejoinReduce == true then
        task.spawn(function()
            waitMarketWorld(20)

            local ab = rawget(_G, "AgeBreakRejoinReduce") or AgeBreakRejoin

            if type(ab) == "table" then
                if type(ab.Start) == "function" then
                    pcall(function() ab.Start("auto_load") end)
                else
                    moduleStart(ab, "auto_load")
                end
            end

            local hud = rawget(_G, "NodeHubMarketAgeBreakHUD") or MarketAgeBreakHUD
            if type(hud) == "table" and type(hud.Refresh) == "function" then
                pcall(function() hud.Refresh() end)
            end
        end)
    end

    if MK.auto_start == true then
        task.spawn(function()
            waitMarketWorld(20)

            if type(marketLoop) == "table" then
                moduleStart(marketLoop)

                marketLoop.running = true
                _G.__AUTO_MARKET_RUNNING = true
                _G.__auto_market_DIRTY = true

                MK.runtime = MK.runtime or {}
                MK.runtime.enabled = true
            end
        end)

        task.spawn(function()
            waitMarketWorld(20)

            if type(snipeLoop) == "table" then
                moduleStart(snipeLoop)

                snipeLoop.running = true
                _G.__AUTO_SNIPE_RUNNING = true
            else
                warnlog("auto-start snipe gagal: snipe_loop nil")
            end
        end)
    end

    local SH = MK.snipeHop

    if SH and SH.enabled == true then
        task.spawn(function()
            local hop = rawget(_G, "AutoSnipeHop") or AutoSnipeHop

            if type(hop) == "table" then
                moduleStart(hop)
            end
        end)
    end

    local SHS = MK.snipeHopBySeller

    if SHS and SHS.enabled == true then
        task.spawn(function()
            waitMarketWorld(20)

            local hop = rawget(_G, "AutoSnipeSellerHop") or AutoSnipeSellerHop

            if type(hop) == "table" then
                moduleStart(hop)
            else
                warnlog("auto-start seller hop gagal: module nil")
            end
        end)
    end
end

ENV.__NODEHUB_MARKET_READY = true
_G.__NODEHUB_MARKET_READY = true

task.defer(startEnabledLoops)

LOADER.SetInfo("Market loaded.")
LOADER.Destroy() -- idempotent; biasanya sudah ditutup saat UI create

return true
